window.BANK={"exams": [{"code": "20SA", "label": "קיץ תש\"פ מועד א'", "date": "23.09.2020", "n": 10}, {"code": "20SB", "label": "קיץ תש\"פ מועד ב'", "date": "26.10.2020", "n": 10}, {"code": "22AA", "label": "סמסטר א' תשפ\"ב מועד א'", "date": "11.01.2022", "n": 8}, {"code": "22AB", "label": "סמסטר א' תשפ\"ב מועד ב'", "date": "01.02.2022", "n": 8}, {"code": "22AC", "label": "סמסטר א' תשפ\"ב מועד ג'", "date": "2022", "n": 8}, {"code": "22BA", "label": "סמסטר ב' תשפ\"ב מועד א'", "date": "13.06.2022", "n": 8}, {"code": "22BB", "label": "סמסטר ב' תשפ\"ב מועד ב'", "date": "18.07.2022", "n": 8}, {"code": "22BC", "label": "סמסטר ב' תשפ\"ב מועד ג'", "date": "18.08.2022", "n": 3}, {"code": "23AA", "label": "סמסטר א' תשפ\"ג מועד א'", "date": "30.01.2023", "n": 8}, {"code": "23AB", "label": "סמסטר א' תשפ\"ג מועד ב'", "date": "20.02.2023", "n": 8}, {"code": "23AC", "label": "סמסטר א' תשפ\"ג מועד ג'", "date": "28.03.2023", "n": 3}, {"code": "23BA", "label": "סמסטר ב' תשפ\"ג מועד א'", "date": "25.06.2023", "n": 8}, {"code": "23BB", "label": "סמסטר ב' תשפ\"ג מועד ב'", "date": "16.07.2023", "n": 8}, {"code": "23SA", "label": "סמסטר קיץ תשפ\"ג מועד א'", "date": "07.12.2023", "n": 8}, {"code": "23SB", "label": "סמסטר קיץ תשפ\"ג מועד ב'", "date": "28.12.2023", "n": 8}, {"code": "24AA", "label": "סמסטר א' תשפ\"ד מועד א'", "date": "04.03.2024", "n": 10}, {"code": "24AB", "label": "סמסטר א' תשפ\"ד מועד ב'", "date": "22.03.2024", "n": 9}, {"code": "24AC", "label": "סמסטר א' תשפ\"ד מועד ג'", "date": "30.04.2024", "n": 4}, {"code": "24BA", "label": "סמסטר ב' תשפ\"ד מועד א'", "date": "07.07.2024", "n": 9}, {"code": "24BB", "label": "סמסטר ב' תשפ\"ד מועד ב'", "date": "30.07.2024", "n": 9}, {"code": "24SA", "label": "סמסטר קיץ תשפ\"ד מועד א'", "date": "10.10.2024", "n": 9}, {"code": "24SB", "label": "סמסטר קיץ תשפ\"ד מועד ב'", "date": "04.11.2024", "n": 9}, {"code": "24SC", "label": "סמסטר קיץ תשפ\"ד מועד ג'", "date": "02.12.2024", "n": 8}, {"code": "25AA", "label": "סמסטר א' תשפ\"ה מועד א'", "date": "04.02.2025", "n": 8}, {"code": "25AB", "label": "סמסטר א' תשפ\"ה מועד ב'", "date": "25.02.2025", "n": 8}, {"code": "25AC", "label": "סמסטר א' תשפ\"ה מועד ג'", "date": "26.03.2025", "n": 8}, {"code": "25BA", "label": "סמסטר ב' תשפ\"ה מועד א'", "date": "15.07.2025", "n": 8}, {"code": "25BB", "label": "סמסטר ב' תשפ\"ה מועד ב'", "date": "04.08.2025", "n": 8}, {"code": "25BC", "label": "סמסטר ב' תשפ\"ה מועד ג'", "date": "04.09.2025", "n": 5}, {"code": "26AA", "label": "סמסטר א' תשפ\"ו מועד א'", "date": "27.01.2026", "n": 8}, {"code": "26AB", "label": "סמסטר א' תשפ\"ו מועד ב'", "date": "17.02.2026", "n": 8}], "questions": [{"num": "1", "type": "tf", "topic": "deadlock", "sub": "הרעבה וקיפאון", "q": "הוכח או הפרך: אם יש הרעבה, בהכרח יש גם קיפאון.", "correct": false, "official": "לא נכון. תיתכן הרעבה ללא קיפאון, לדוגמה במנעול TAS תיתכן הרעבה אבל לא קיפאון.", "expl": "קיפאון (deadlock) הוא מצב שבו אף חוט בקבוצה לא יכול להתקדם לעולם. הרעבה (starvation) היא מצב שבו חוט מסוים לא מתקדם, בזמן שאחרים כן מתקדמים.\n\nבמנעול Test-And-Set פשוט אין קיפאון: תמיד מישהו מצליח לתפוס את המנעול. אבל אין הבטחה שחוט מסוים יצליח אי פעם – חוט \"חסר מזל\" יכול להפסיד בכל פעם. זו הרעבה בלי קיפאון, ולכן הטענה לא נכונה.\n\nשימו לב: גם הכיוון ההפוך לא נכון לפי הקורס – ראו שאלה 5 במבחן 22AA.", "check": "נבדק מול הגדרות הקורס", "exam": "20SA", "examLabel": "קיץ תש\"פ מועד א'", "date": "23.09.2020", "id": "20SA-1"}, {"num": "2", "type": "tf", "topic": "sched", "sub": "Round Robin", "q": "הוכח או הפרך: באלגוריתם תזמון Round Robin, זמן המחזור (turnaround time) הוא אופטימלי.", "correct": false, "official": "לא נכון. זמן המחזור של RR הוא גרוע, כפי שראינו בשיעור.", "expl": "RR טוב לזמן התגובה (response time) וגרוע לזמן המחזור, כי הוא \"מורח\" את כל העבודות עד הסוף.\n\nדוגמה מההרצאה: שלוש עבודות של 5 שניות שמגיעות ב-0, quantum של שנייה.\nRR: זמני סיום 13, 14, 15, ממוצע 14.\nSJF על אותן עבודות: זמני סיום 5, 10, 15, ממוצע 10.\n\nהאופטימלי לזמן מחזור הוא SRTF (STCF), לא RR.", "check": "חושב בסימולטור התזמון", "exam": "20SA", "examLabel": "קיץ תש\"פ מועד א'", "date": "23.09.2020", "id": "20SA-2"}, {"num": "3", "type": "tf", "topic": "memory", "sub": "TLB", "q": "הוכח או הפרך: הגדלת ה-TLB יכולה להקטין את ה-hit ratio.", "correct": true, "official": "נכון. לדוגמה עבור אלגוריתם FIFO זה אפשרי.", "expl": "ה-TLB הוא מטמון, ואם מדיניות ההחלפה שלו היא FIFO הוא חשוף ל-Belady's anomaly: מטמון גדול יותר יכול לתת פחות פגיעות.\n\nהדוגמה מההרצאה, על הרצף 1 2 3 4 1 2 5 1 2 3 4 5:\nFIFO עם 3 כניסות: 3 פגיעות מתוך 12 (25%).\nFIFO עם 4 כניסות: 2 פגיעות מתוך 12 (16.7%).\n\nהמילה \"יכולה\" חשובה: עם מדיניות בעלת stack property (כמו LRU) הגדלה לא יכולה להזיק – אבל הטענה דורשת רק דוגמה אחת.", "check": "הרצף חושב בסימולטור החלפת הדפים", "exam": "20SA", "examLabel": "קיץ תש\"פ מועד א'", "date": "23.09.2020", "id": "20SA-3"}, {"num": "4", "type": "tf", "topic": "threads", "sub": "מנעולים ו-spinning", "q": "הוכח או הפרך: במחשב עם מעבד יחיד, תמיד נעדיף מנעול שלא מבצע spinning.", "correct": true, "official": "נכון. אם חוט נכשל בתפיסת המנעול, אין טעם לבצע spinning כי אף חוט אחר לא רץ במקביל (מעבד יחיד). כלומר המנעול לא ישוחרר וה-spinning מבזבז זמן מעבד.", "expl": "במעבד יחיד, בזמן שחוט מסתובב בלולאה (spin) אף חוט אחר לא רץ – כולל החוט שמחזיק במנעול. לכן המנעול בוודאות לא ישתחרר עד שתהיה החלפת הקשר, וכל ה-quantum של החוט המסתובב מבוזבז.\n\nעדיף מנעול שמוותר על המעבד (yield או שינה בתור) – כך החוט שמחזיק את המנעול יכול לרוץ ולשחרר אותו.", "check": "נבדק מול הגדרות הקורס", "exam": "20SA", "examLabel": "קיץ תש\"פ מועד א'", "date": "23.09.2020", "id": "20SA-4"}, {"num": "5", "type": "tf", "topic": "fs", "sub": "Crash consistency", "q": "הוכח או הפרך: בעיית ה-crash consistency כאשר מוסיפים בלוק נתונים חדש לקובץ קיים (הדוגמה שניתנה בשיעור) תיפתר אם נוכל לבצע 2 כתיבות לדיסק בבת אחת.", "correct": true, "official": "נכון. היכולת לבצע 2 כתיבות במקביל לא אומרת שאלו חייבות להיות 2 הכתיבות הראשונות. ראשית נכתוב רק את ה-DATA, מאחר ואין בעיה לקרוס אחרי כתיבת ה-DATA בלבד. לאחר מכן ננצל את היכולת החדשה כדי לעדכן את ה-inode וגם את ה-data bitmap יחד, כך שאם נקרוס לפני אז לא קרה כלום (עודכן רק ה-DATA), ואם נקרוס אחרי אז הפעולה בוצעה במלואה. כך לא יתכן שנקרוס אחרי 2 כתיבות – אלא רק אחרי אחת או 3.", "expl": "בדוגמה מהשיעור צריך לכתוב 3 בלוקים: את בלוק הנתונים (Db), את ה-inode המעודכן, ואת ה-data bitmap.\n\nקריסה אחרי כתיבת Db בלבד לא מזיקה: הבלוק לא מסומן כתפוס ואף inode לא מצביע עליו – פשוט כאילו הכתיבה לא קרתה.\n\nהבעיה היא כשנכתב רק אחד מבין ה-inode וה-bitmap: אז הם לא עקביים זה עם זה. אם אפשר לכתוב 2 בלוקים אטומית:\n1) כותבים קודם את Db לבד.\n2) כותבים את ה-inode ואת ה-bitmap יחד.\n\nכך המצבים האפשריים אחרי קריסה הם רק \"שום דבר משמעותי\" או \"הכל\" – ולכן הבעיה נפתרת.", "check": "נבדק מול הדוגמה בשיעור", "exam": "20SA", "examLabel": "קיץ תש\"פ מועד א'", "date": "23.09.2020", "id": "20SA-5"}, {"num": "6", "type": "open", "topic": "deadlock", "sub": "ארבעת התנאים", "parts": [{"label": null, "q": "מהם ארבעת התנאים לקיום קיפאון? הסבירו כל אחד מהם.", "answer": "Mutual exclusion – משאב יכול להיות מוחזק בידי חוט אחד בלבד בכל רגע (למשל מנעול).\nHold-and-wait – חוט מחזיק משאב אחד ובאותו זמן ממתין למשאב נוסף.\nNo preemption – אי אפשר לקחת בכוח משאב מחוט שמחזיק בו; הוא משתחרר רק כשהחוט משחרר אותו.\nCircular wait – קיימת שרשרת מעגלית של חוטים, שכל אחד ממתין למשאב שמוחזק בידי הבא בשרשרת.\n\nקיפאון אפשרי רק כשכל ארבעת התנאים מתקיימים יחד – ולכן כדי למנוע קיפאון מספיק לשבור תנאי אחד."}], "official": "בהתאם לשקפים.", "expl": "הפתרון הרשמי מפנה לשקפים. התשובה כאן היא ההגדרות הסטנדרטיות מהספר (OSTEP, פרק 32).", "check": "לפי OSTEP", "exam": "20SA", "examLabel": "קיץ תש\"פ מועד א'", "date": "23.09.2020", "id": "20SA-6"}, {"num": "7", "type": "open", "topic": "process", "sub": "fork ו-wait", "parts": [{"label": null, "q": "מריצים את קטע הקוד הבא. ציירו את עץ התהליכים שנוצר, וציינו עבור כל תהליך בעץ את הפלט שלו. מהם כל הפלטים האפשריים של הקוד?", "code": "fork();\nif (fork() == 0) {\n    printf(\"B\");\n} else {\n    wait(NULL);\n    printf(\"A\");\n}", "answer": "עץ התהליכים: לשורש יש שני ילדים – הבן מה-fork הראשון (השמאלי) והבן מה-fork השני (הימני). לבן השמאלי יש ילד אחד – הנכד, מה-fork השני שלו.\n\n[[TREE]]\n\nהשורש והבן השמאלי מקבלים מה-fork השני ערך חיובי, ולכן מחכים ומדפיסים A. הבן הימני והנכד מקבלים 0 ומדפיסים B.\n\nהפלטים האפשריים: BABA, BBAA, BAAB.\n\nהמלכודת היא BAAB: לשורש יש שני ילדים, ו-wait חוזר כשילד כלשהו מסתיים. אם הבן השמאלי מסתיים ראשון (אחרי שהנכד הדפיס B והוא עצמו הדפיס A), השורש מדפיס A עוד לפני שהבן הימני הדפיס B.\n\nפלט שמתחיל ב-A בלתי אפשרי: כל A בא אחרי wait שחוזר רק אחרי שילד הסתיים, וכל ילד שמסתיים הוא כזה שהדפיס B או שהוא עצמו המתין ל-B.", "tree": ["שורש", "A", [["בן שמאלי", "A", [["נכד", "B", []]]], ["בן ימני", "B", []]]]}], "official": "הפלט של התהליך הראשי (שורש העץ) ושל הבן השמאלי הוא A, של הבן הימני ושל הנכד הוא B. הפלטים האפשריים הם: BABA, BBAA, BAAB. פלט נפוץ שפוספס הוא BAAB, במקרה שבו ה-wait של השורש חוזר בעקבות סיום הבן השמאלי שלו, לפני שהבן הימני מדפיס B.", "expl": "", "check": "הורץ 500 פעמים: התקבלו BBAA, BABA ו-BAAB, ושום פלט אחר", "exam": "20SA", "examLabel": "קיץ תש\"פ מועד א'", "date": "23.09.2020", "id": "20SA-7"}, {"num": "8", "type": "open", "topic": "threads", "sub": "מימוש מנעול", "parts": [{"label": null, "q": "נתון קטע הקוד הבא למימוש מנעול עבור 2 חוטים, כאשר לכל חוט מזהה (0 או 1) המועבר כפרמטר i. האם המנעול מקיים מניעה הדדית? חופש מקיפאון? הוגנות?", "code": "int turn;\nvoid lock(int i) {\n    turn = i;\n    while (turn != i);\n}\nvoid unlock(int i) {\n    turn = 1-i;\n}", "answer": "מניעה הדדית – לא מתקיימת. דוגמה נגדית: חוט 0 קורא ל-lock, רץ לבד ונכנס לקטע הקריטי. אחר כך חוט 1 קורא ל-lock, כותב turn = 1, יוצא מיד מהלולאה ונכנס גם הוא.\n\nחופש מקיפאון – מתקיים. נניח בשלילה שיש קיפאון. אם רק חוט אחד תקוע בלולאה, הוא עצמו כתב את המזהה שלו ל-turn, והחוט השני או לא רץ או סיים בכתיבת turn למזהה של הראשון – סתירה. אם שני החוטים תקועים, turn צריך להיות שונה גם מ-0 וגם מ-1, אבל רק הערכים האלה נכתבים אליו – סתירה.\n\nהוגנות – לא מתקיימת. דוגמה נגדית: חוט 0 כותב turn = 0, ולפני שהוא בודק את הלולאה חוט 1 כותב turn = 1 ונכנס לקטע הקריטי. חוט 0 תקוע. כשחוט 1 יוצא הוא כותב turn = 0, אבל מיד מנסה שוב לתפוס, כותב turn = 1 ונכנס שוב – לפני שחוט 0 ראה את השינוי. וכך שוב ושוב.\n\nשימו לב: \"אין מניעה הדדית ולכן בהכרח יש חופש מקיפאון\" הוא נימוק שגוי, למרות שהמסקנה כאן נכונה."}], "official": "מניעה הדדית – לא מתקיימת. חופש מקיפאון – מתקיים. הוגנות – לא מתקיימת.", "expl": "", "check": "model checking על כל השזירות של 2 החוטים", "exam": "20SA", "examLabel": "קיץ תש\"פ מועד א'", "date": "23.09.2020", "id": "20SA-8"}, {"num": "9", "type": "open", "topic": "memory", "sub": "גודל טבלת דפים", "parts": [{"label": null, "q": "נתונה מערכת עם זיכרון וירטואלי של 1MB, גודל דף של 2KB, וזיכרון פיזי של 4MB. מהם הגדלים של ה-VPN וה-PFN, וכמה זיכרון פיזי תתפוס טבלת דפים (לינארית) של תהליך, במינימום?", "answer": "כתובת וירטואלית:\n1MB = 2^20, ולכן 20 ביטים.\n\nהיסט:\n2KB = 2^11, ולכן 11 ביטים.\n\nVPN:\n20 − 11 = 9 ביטים\n\nכתובת פיזית:\n4MB = 2^22, ולכן 22 ביטים.\n\nPFN:\n22 − 11 = 11 ביטים\n\nגודל הטבלה:\nיש 2^9 = 512 דפים, ולכן 512 רשומות. כל רשומה צריכה לפחות 11 ביטים, ומעגלים לחזקה של 2 בבתים: 2 בתים.\n512 × 2B = 1KB"}], "official": "VPN = 9, PFN = 11, הטבלה תתפוס 1KB.", "expl": "", "check": "חושב", "exam": "20SA", "examLabel": "קיץ תש\"פ מועד א'", "date": "23.09.2020", "id": "20SA-9"}, {"num": "10", "type": "open", "topic": "disk", "sub": "ביצועי דיסק", "parts": [{"label": null, "q": "נתונים שני דיסקים קשיחים:\nA: RPM 7500, seek time 10ms, transfer rate 250 MB/s\nB: RPM 15000, seek time 4ms, transfer rate 125 MB/s\nבהינתן workload אקראי של 4KB וסדרתי של 100MB, איזה דיסק קשיח נעדיף לכל אחד?", "answer": "זמן סיבוב:\nA: 60000 / 7500 = 8ms לסיבוב, בממוצע חצי סיבוב = 4ms\nB: 60000 / 15000 = 4ms לסיבוב, בממוצע חצי סיבוב = 2ms\n\nאקראי, 4KB:\nA: 10 + 4 + 0.016 ≈ 14ms\nB: 4 + 2 + 0.032 ≈ 6ms\nנעדיף את B.\n\nסדרתי, 100MB:\nA: 10 + 4 + 100/250·1000 = 14 + 400 = 414ms\nB: 4 + 2 + 100/125·1000 = 6 + 800 = 806ms\nנעדיף את A.\n\nבפעולה קטנה הזמן נשלט על ידי seek וסיבוב (B טוב יותר), ובפעולה גדולה על ידי קצב ההעברה (A טוב יותר)."}], "official": "דיסק A מהיר יותר בתרחיש הסדרתי, ודיסק B מהיר יותר בתרחיש האקראי.", "expl": "", "check": "חושב", "exam": "20SA", "examLabel": "קיץ תש\"פ מועד א'", "date": "23.09.2020", "id": "20SA-10"}, {"num": "1", "type": "tf", "topic": "deadlock", "sub": "הפילוסופים הסועדים", "q": "הוכח או הפרך: בבעיית הפילוסופים הסועדים (dining philosophers) ניתן למנוע הרעבה.", "correct": true, "official": "לא נכון. ניתן למנוע הרעבה, לדוגמה בשימוש במנעול הוגן.", "note": "בפתרון הרשמי כתוב \"לא נכון\", אבל ההסבר שבא אחריו (\"ניתן למנוע הרעבה\") אומר בדיוק שהטענה נכונה. זו טעות הקלדה בפתרון: הטענה נכונה.", "expl": "הטענה נכונה: אפשר לבנות פתרון לפילוסופים הסועדים שאין בו גם קיפאון וגם הרעבה – למשל עם מנעולים הוגנים (שנותנים את המזלג לפי סדר הבקשה), יחד עם שבירת המעגל (פילוסוף אחד לוקח את המזלגות בסדר הפוך) כדי למנוע קיפאון.\n\nשימו לב: בפתרון הרשמי כתוב \"לא נכון\", אבל ההסבר שלו (\"ניתן למנוע הרעבה\") תומך בתשובה \"נכון\". במבחן – ענו \"נכון\" עם ההסבר הזה.", "check": "נבדק מול הפתרון הרשמי – נמצאה סתירה פנימית בו", "exam": "20SB", "examLabel": "קיץ תש\"פ מועד ב'", "date": "26.10.2020", "id": "20SB-1"}, {"num": "2", "type": "tf", "topic": "sched", "sub": "SRTF/STCF", "q": "הוכח או הפרך: באלגוריתם תזמון STCF עם overlap, זמן התגובה (response time) הוא אופטימלי.", "correct": false, "official": "לא נכון. בתזמון STCF זמן התגובה גרוע. השימוש ב-overlap לא משנה את זה.", "expl": "STCF (שנקרא גם SRTF) אופטימלי לזמן המחזור, לא לזמן התגובה: עבודה ארוכה מחכה עד שכל הקצרות מסתיימות.\n\nדוגמה מההרצאה: A, B, C מגיעות ב-0, כל אחת 10 שניות. STCF מריץ אותן ברצף, וזמני התגובה הם 0, 10, 20. RR עם quantum קטן היה נותן זמני תגובה קרובים ל-0 לכולן.\n\nה-overlap (הרצת עבודה אחרת בזמן ש-A מחכה ל-I/O) משפר את ניצול המעבד, אבל לא משנה את הבעיה הזו.", "check": "חושב בסימולטור התזמון", "exam": "20SB", "examLabel": "קיץ תש\"פ מועד ב'", "date": "26.10.2020", "id": "20SB-2"}, {"num": "3", "type": "tf", "topic": "memory", "sub": "Buddy allocation", "q": "הוכח או הפרך: באלגוריתם ההקצאה buddy allocation יש בעיית internal fragmentation.", "correct": true, "official": "נכון. כפי שמופיע בשקפים – ההקצאה היא בחזקות של 2 ולכן כל דרישה להקצאה שאינה חזקה של 2 תגרום לפרגמנטציה.", "expl": "ב-buddy allocation הזיכרון מחולק שוב ושוב לחצאים, וכל בקשה מקבלת בלוק בגודל של חזקה של 2 שמספיק לה.\n\nלדוגמה: בקשה ל-7KB מקבלת בלוק של 8KB. ה-1KB שנשאר בתוך הבלוק לא ישמש אף אחד – זו בדיוק internal fragmentation (בזבוז בתוך יחידה שהוקצתה).\n\nהערה: buddy allocation לא מופיע במצגות הזיכרון שבחומר שהועלה – הוא מהספר (OSTEP, פרק 17).", "check": "לפי OSTEP", "exam": "20SB", "examLabel": "קיץ תש\"פ מועד ב'", "date": "26.10.2020", "id": "20SB-3"}, {"num": "4", "type": "tf", "topic": "threads", "sub": "מנעולים", "q": "הוכח או הפרך: מנעול מונע החלפת הקשר (context switch) בקטע הקריטי.", "correct": false, "official": "לא נכון. מנעול בפני עצמו לא מונע החלפת הקשר, אלא רק מונע ממספר חוטים להריץ קטע קוד מסוים במקביל (גם אם מתבצעת החלפת הקשר).", "expl": "החוט שמחזיק את המנעול יכול בהחלט לקבל פסיקת שעון באמצע הקטע הקריטי ולהיות מוחלף. המנעול רק מבטיח שחוט אחר שינסה להיכנס לאותו קטע ייחסם, כך שגם אם יש החלפת הקשר – אף חוט אחר לא יבצע את הקטע במקביל.\n\nמה שכן מונע החלפת הקשר הוא כיבוי פסיקות – פתרון שמתאים רק לקרנל ובמעבד יחיד.", "check": "נבדק מול הגדרות הקורס", "exam": "20SB", "examLabel": "קיץ תש\"פ מועד ב'", "date": "26.10.2020", "id": "20SB-4"}, {"num": "5", "type": "tf", "topic": "disk", "sub": "RAID-4", "q": "הוכח או הפרך: שימוש ב-RAID-4 משפר את כל ביצועי הכתיבה לדיסק.", "correct": false, "official": "לא נכון. בתרחיש של כתיבות אקראיות, שימוש ב-RAID-4 פוגע בביצועי הדיסק לעומת שימוש בדיסק יחיד. בתרחישי כתיבות סדרתיות או קריאות – הביצועים משתפרים.", "expl": "ב-RAID-4 יש דיסק parity אחד שמשותף לכל הפסים. כל כתיבה קטנה ואקראית צריכה לעדכן את בלוק ה-parity, ולכן כל הכתיבות האקראיות עוברות דרך אותו דיסק – הוא צוואר בקבוק. בנוסף כל כתיבה כזו דורשת קריאה וכתיבה של הנתונים ושל ה-parity (4 פעולות).\n\nקצב כתיבות אקראיות ב-RAID-4 הוא בערך R/2 – חצי מדיסק יחיד. לכן הטענה \"משפר את כל ביצועי הכתיבה\" לא נכונה. כתיבות סדרתיות (פס מלא בבת אחת) כן משתפרות.", "check": "לפי OSTEP, פרק 38", "exam": "20SB", "examLabel": "קיץ תש\"פ מועד ב'", "date": "26.10.2020", "id": "20SB-5"}, {"num": "6", "type": "open", "topic": "deadlock", "sub": "מניעת קיפאון", "parts": [{"label": null, "q": "מה הפתרון לכל אחד מארבעת התנאים לקיום קיפאון (deadlock)? התנאים הם: Mutual exclusion, Hold-and-wait, No preemption, Circular wait.", "answer": "Mutual exclusion – להימנע ממשאבים בלעדיים, למשל מבני נתונים lock-free שמשתמשים בפעולות אטומיות (כמו compare-and-swap) במקום מנעולים.\n\nHold-and-wait – לתפוס את כל המנעולים בבת אחת, באופן אטומי (למשל מנעול \"גלובלי\" שמוחזק בזמן תפיסת כל השאר).\n\nNo preemption – לא להמתין כשמחזיקים משאב: להשתמש ב-trylock, ואם נכשלים – לשחרר את כל מה שתפסנו ולנסות מחדש.\n\nCircular wait – לקבוע סדר קבוע (סדר מלא או חלקי) לתפיסת המנעולים, וכל החוטים תופסים לפיו. זו השיטה הנפוצה ביותר."}], "official": "בהתאם לשקפים.", "expl": "הפתרון הרשמי מפנה לשקפים. התשובה כאן היא ארבע הטכניקות מהספר (OSTEP, פרק 32). שימו לב שעם trylock יכול להיווצר livelock, ומוסיפים השהיה אקראית כדי למנוע אותו.", "check": "לפי OSTEP", "exam": "20SB", "examLabel": "קיץ תש\"פ מועד ב'", "date": "26.10.2020", "id": "20SB-6"}, {"num": "7", "type": "open", "topic": "process", "sub": "fork", "parts": [{"label": null, "q": "מריצים את קטע הקוד הבא. ציירו את עץ התהליכים שנוצר, וציינו עבור כל תהליך בעץ את הפלט שלו. מהם כל הפלטים האפשריים של הקוד?", "code": "int i = 0;\nif (fork()) {\n    ++i;\n    fork();\n}\nelse if (fork())\n    ++i;\nprintf(\"%d\", i);", "answer": "נוצרים 4 תהליכים. ההורה מגדיל את i ל-1 ומבצע fork – הוא והבן החדש שלו מדפיסים 1. הבן הראשון (i = 0) נכנס ל-else ומבצע fork: הוא עצמו מקבל ערך חיובי ומגדיל ל-1, והנכד שנוצר נשאר עם 0.\n\nלכן שלושה תהליכים מדפיסים 1 ואחד (הנכד) מדפיס 0, בכל סדר: 0111, 1011, 1101, 1110."}], "official": "הפלט של תהליך אחד (תהליך הנכד משמאל) הוא 0 ושל כל השאר 1, בכל סדר אפשרי. לכן הפלטים האפשריים הם: 0111, 1011, 1101, 1110.", "expl": "", "check": "הורץ 200 פעמים: התקבלו 1110, 1101, 1011. גם 0111 אפשרי – פשוט נדיר", "exam": "20SB", "examLabel": "קיץ תש\"פ מועד ב'", "date": "26.10.2020", "id": "20SB-7"}, {"num": "8", "type": "open", "topic": "threads", "sub": "מימוש מנעול", "parts": [{"label": null, "q": "נתון קטע הקוד הבא למימוש מנעול עבור 2 חוטים, כאשר לכל חוט מזהה (0 או 1) המועבר כפרמטר i. האם המנעול מקיים מניעה הדדית? חופש מקיפאון? הוגנות?", "code": "int turn;\nvoid lock(int i) {\n    turn = 1-i;\n    while (turn != i);\n}\nvoid unlock(int i) {\n    turn = 1-i;\n}", "answer": "מניעה הדדית – מתקיימת. אם שני החוטים בקטע הקריטי בבת אחת, שניהם יצאו מהלולאה, כלומר turn == 0 וגם turn == 1 – סתירה.\n\nחופש מקיפאון – לא מתקיים. אם רק חוט אחד מנסה לתפוס את המנעול, למשל חוט 0, הוא כותב turn = 1 ותקוע לנצח – למרות שהמנעול פנוי.\n\nהוגנות – מתקיימת. חוט שתקוע בלולאה לא משנה את turn. כל חוט כותב ל-turn רק את המזהה של החוט האחר, ולכן החוט השני לא יכול לתפוס ולשחרר שוב ושוב: ברגע שהוא מנסה לתפוס שוב, הוא נותן את התור לחוט הממתין."}], "official": "מניעה הדדית – מתקיימת. חופש מקיפאון – לא מתקיים. הוגנות – מתקיימת.", "expl": "השוו לשאלה 8 במועד א' (20SA): שינוי אחד – turn = i לעומת turn = 1-i – הופך את כל שלוש התשובות.", "check": "model checking על כל השזירות של 2 החוטים", "exam": "20SB", "examLabel": "קיץ תש\"פ מועד ב'", "date": "26.10.2020", "id": "20SB-8"}, {"num": "9", "type": "open", "topic": "memory", "sub": "גודל טבלת דפים", "parts": [{"label": null, "q": "נתונה מערכת עם זיכרון וירטואלי של 4MB, גודל דף של 1KB, וזיכרון פיזי של 8MB. מהם הגדלים של ה-VPN וה-PFN, וכמה זיכרון פיזי תתפוס טבלת דפים (לינארית) של תהליך, במינימום?", "answer": "כתובת וירטואלית:\n4MB = 2^22, ולכן 22 ביטים.\n\nהיסט:\n1KB = 2^10, ולכן 10 ביטים.\n\nVPN:\n22 − 10 = 12 ביטים\n\nכתובת פיזית:\n8MB = 2^23, ולכן 23 ביטים.\n\nPFN:\n23 − 10 = 13 ביטים\n\nגודל הטבלה:\nיש 2^12 = 4K דפים, ולכן 4K רשומות. כל רשומה צריכה לפחות 13 ביטים, ומעגלים ל-2 בתים.\n4K × 2B = 8KB"}], "official": "VPN = 12, PFN = 13, הטבלה תתפוס 8KB.", "expl": "", "check": "חושב", "exam": "20SB", "examLabel": "קיץ תש\"פ מועד ב'", "date": "26.10.2020", "id": "20SB-9"}, {"num": "10", "type": "open", "topic": "disk", "sub": "ביצועי דיסק", "parts": [{"label": null, "q": "נתונים שני דיסקים קשיחים:\nA: RPM 7500, seek time 10ms, transfer rate 250 MB/s\nB: RPM 15000, seek time 4ms, transfer rate 125 MB/s\nמה גודל הפעולה המינימלי שנדרש כדי להבטיח קצב שהוא לפחות 90% מקצב ההעברה המקסימלי של הדיסק? ועבור 50%?", "answer": "נסמן ב-X את גודל הפעולה ב-MB. הקצב בפועל הוא X חלקי הזמן הכולל, ורוצים שיהיה אחוז מסוים מקצב ההעברה.\n\nדיסק A:\nזמן סיבוב 8ms, ולכן המתנה ממוצעת 4ms. seek של 10ms. העברת 1MB לוקחת 1000/250 = 4ms.\nזמן פעולה: 14 + 4X\n\n90% מ-250MB/s הוא 225MB/s, כלומר 1000/225 ms לכל MB:\n14 + 4X = 1000X/225\nX = 31.5MB\n\n50% הוא 125MB/s, כלומר 8ms לכל MB:\n14 + 4X = 8X\nX = 3.5MB\n\nדיסק B:\nזמן סיבוב 4ms, ולכן המתנה ממוצעת 2ms. seek של 4ms. העברת 1MB לוקחת 8ms.\nזמן פעולה: 6 + 8X\n\n90%:\n6 + 8X = 1000X/112.5\nX = 6.75MB\n\n50%:\n6 + 8X = 16X\nX = 0.75MB"}], "official": "A: 31.5MB עבור 90%, 3.5MB עבור 50%. B: 6.75MB עבור 90%, 0.75MB עבור 50%.", "expl": "", "check": "חושב ונבדק בסקריפט", "exam": "20SB", "examLabel": "קיץ תש\"פ מועד ב'", "date": "26.10.2020", "id": "20SB-10"}, {"num": "1", "type": "tf", "topic": "memory", "sub": "Clock", "q": "הוכח או הפרך: אלגוריתם השעון בוחר לפנות את הדף הכי ותיק (שניגשו אליו הכי בעבר).", "correct": false, "official": "לא נכון. אלגוריתם השעון (עם או בלי שדרוגים) מפנה את הדף הראשון שנמצא שלא ניגשו אליו מאז הסיבוב הקודם, לא בהכרח הדף הכי ותיק.", "expl": "Clock הוא רק קירוב ל-LRU. המחוג עובר על הדפים במעגל ומפנה את הדף הראשון שה-use bit שלו 0 – כלומר דף שלא ניגשו אליו מאז שהמחוג עבר עליו בפעם הקודמת.\n\nייתכן שיש דף אחר, ישן יותר, שנמצא רחוק יותר מהמחוג – Clock לא יגיע אליו. מה שמובטח הוא רק \"לא בשימוש לאחרונה\", לא \"הכי ותיק\".", "check": "נבדק מול האלגוריתם", "exam": "22AA", "examLabel": "סמסטר א' תשפ\"ב מועד א'", "date": "11.01.2022", "id": "22AA-1"}, {"num": "2", "type": "tf", "topic": "intro", "sub": "פסיקות", "q": "הוכח או הפרך: במקרים מסוימים, תהליכי משתמש יכולים לבטל פסיקות.", "correct": false, "official": "לא נכון. רק לקרנל יש הרשאות לבטל פסיקות (לא מדובר בסיגנלים).", "expl": "ביטול פסיקות היא פקודה מורשית (privileged) שאפשר לבצע רק ב-kernel mode. אם תהליך משתמש היה יכול לבטל פסיקות, הוא היה יכול לבטל גם את פסיקת השעון ולהשתלט על המעבד לנצח – בדיוק מה ש-Limited Direct Execution נועד למנוע.\n\nאל תתבלבלו עם סיגנלים: תהליך כן יכול לחסום או להתעלם מסיגנלים מסוימים, אבל סיגנל הוא הודעה לתהליך – לא פסיקה למעבד.", "check": "נבדק מול ההרצאה", "exam": "22AA", "examLabel": "סמסטר א' תשפ\"ב מועד א'", "date": "11.01.2022", "id": "22AA-2"}, {"num": "3", "type": "tf", "topic": "threads", "sub": "חוטים וזיכרון", "q": "הוכח או הפרך: חוטים של אותו תהליך יכולים לגשת למחסנית אחד של השני.", "correct": true, "official": "נכון. לכל חוט יש מחסנית נפרדת משלו, אך חוטים של אותו תהליך חולקים את מרחב הכתובות כולו – ולכן יכולים לגשת למחסנית של חוט אחר באמצעות מצביע מתאים לזיכרון.", "expl": "לכל חוט יש מחסנית משלו – אבל כל המחסניות יושבות באותו מרחב כתובות. אין שום הגנת חומרה בין חוטים של אותו תהליך, ולכן חוט שמחזיק מצביע למשתנה מקומי של חוט אחר יכול לקרוא ולכתוב אותו.\n\n\"נפרדת\" כאן אומר שכל חוט משתמש באזור אחר, לא שהאזור מוגן.", "check": "נבדק מול ההגדרות", "exam": "22AA", "examLabel": "סמסטר א' תשפ\"ב מועד א'", "date": "11.01.2022", "id": "22AA-3"}, {"num": "4", "type": "tf", "topic": "memory", "sub": "פרגמנטציה", "q": "הוכח או הפרך: בדפדוף יש בעיה של פרגמנטציה חיצונית (external fragmentation).", "correct": false, "official": "לא נכון. דפדוף זו הקצאה בגודל קבוע, תמיד ניתן להשתמש בכל מסגרת ולכן אין פרגמנטציה חיצונית (אך כן יש פנימית).", "expl": "פרגמנטציה חיצונית היא \"חורים\" בין יחידות בגדלים משתנים שקטנים מכדי לשמש בקשה חדשה. בדפדוף כל המסגרות באותו גודל וכל דף יכול לשבת בכל מסגרת פנויה – אז כל מסגרת פנויה ניתנת לשימוש.\n\nמה שכן יש בדפדוף הוא פרגמנטציה פנימית: תהליך שצריך קצת זיכרון מקבל דף שלם.", "check": "נבדק מול ההרצאה", "exam": "22AA", "examLabel": "סמסטר א' תשפ\"ב מועד א'", "date": "11.01.2022", "id": "22AA-4"}, {"num": "5", "type": "tf", "topic": "deadlock", "sub": "הרעבה וקיפאון", "q": "הוכח או הפרך: אם יש קיפאון, בהכרח יש גם הרעבה.", "correct": false, "official": "לא נכון. יתכן קיפאון ללא הרעבה, לדוגמה מנעול הוגן אשר מגריל כל פעם אם להיכנס ללולאה אינסופית (קיימות גם דוגמאות מציאותיות יותר).", "note": "שאלה עדינה. לפי הפתרון הרשמי התשובה \"לא נכון\". אפשר לטעון אחרת לפי הגדרה אינטואיטיבית (\"החוטים התקועים מורעבים\"), אבל זה המפתח שנבדק – ענו לפיו עם הדוגמה.", "expl": "הפתרון הרשמי עונה \"לא נכון\": הוא רואה בהרעבה ובקיפאון שתי תכונות נפרדות שלא גוררות זו את זו.\n\nהדוגמה הרשמית: מנעול הוגן שבכל פעם מגריל אם להיכנס ללולאה אינסופית. הוא הוגן – אף חוט לא מקופח לטובת חוטים אחרים – אבל ייתכן מצב שבו אף אחד לא מתקדם.\n\nשימו לב: אינטואיטיבית אפשר לחשוב ש\"חוטים שתקועים בקיפאון מורעבים\", ולכן הטענה נראית נכונה. אבל המפתח הרשמי סימן \"לא נכון\" – אם השאלה חוזרת, ענו \"לא נכון\" עם דוגמה כזו. השוו גם ל-20SA שאלה 1, שם הכיוון ההפוך (הרעבה גוררת קיפאון) גם הוא \"לא נכון\".", "check": "לפי הפתרון הרשמי, עם הסתייגות", "exam": "22AA", "examLabel": "סמסטר א' תשפ\"ב מועד א'", "date": "11.01.2022", "id": "22AA-5"}, {"num": "6", "type": "open", "topic": "memory", "sub": "גודל טבלת דפים", "intro": "נתונה מערכת עם זיכרון וירטואלי של 32GB וגודל דף של 4KB.", "parts": [{"label": "6.1", "q": "נתון שטבלת דפים לינארית תופסת 24MB בזיכרון, וכל כניסה בטבלת הדפים (PTE) מכילה מספר מסגרת ועוד שלושה ביטים בלבד (ללא תוספות או ריפוד): ביט valid, ביט access, ביט dirty. מה גודל הזיכרון הפיזי המקסימלי במערכת זו?", "answer": "מספר הדפים:\n32GB = 2^35, דף 4KB = 2^12\nVPN = 35 − 12 = 23 ביטים, כלומר 2^23 = 8M דפים ו-8M רשומות.\n\nגודל רשומה:\n24MB / 8M = 3 בתים = 24 ביטים\n\nגודל PFN:\n24 − 3 = 21 ביטים, כלומר עד 2^21 מסגרות.\n\nזיכרון פיזי מקסימלי:\n2^21 × 4KB = 2^33 = 8GB"}, {"label": "6.2", "q": "נתון שכל כניסה בטבלת הדפים (PTE) מכילה 32 ביטים בכל רמה, ונדרש שכל טבלה תאוחסן בדף אחד בדיוק. כמה רמות של טבלאות דרושות כדי למפות את מרחב הכתובות הווירטואלי?", "answer": "כניסות בדף:\n4KB / 4B = 1024 = 2^10, ולכן כל רמה מקבלת 10 ביטים של אינדקס.\n\nה-VPN הוא 23 ביטים (מסעיף 6.1):\n23 = 3 + 10 + 10\n\nצריך 3 רמות (3 ביטים לרמה העליונה, ו-10 לכל אחת משתי האחרות)."}, {"label": "6.3", "q": "מה מספר הגישות המקסימלי שעלול להתבצע לזיכרון הראשי, לזיכרון המשני (הדיסק) ול-TLB, בעקבות גישה של תהליך לכתובת וירטואלית כלשהי?", "answer": "המקסימום הוא כש-TLB miss מוביל ל-page fault, וצריך לפנות דף כדי לפנות מקום.\n\nהשלבים (עם טבלה בת 3 רמות מסעיף 6.2):\n1) גישה ל-TLB – miss.\n2) הליכה בטבלת הדפים: 3 גישות לזיכרון, אחת לכל רמה – ונמצא page fault.\n3) פינוי דף (page out): גישה לזיכרון וגישה לדיסק.\n4) טעינת הדף המבוקש (page in): גישה לדיסק וגישה לזיכרון.\n5) עדכון טבלת הדפים: גישה לזיכרון.\n6) עדכון ה-TLB, והרצה חוזרת של הפקודה (עוד גישה ל-TLB – לא חובה לציין).\n7) גישה לזיכרון עבור הנתון עצמו.\n\nסך הכל לפי הפירוט הזה:\nזיכרון ראשי: 3 + 1 + 1 + 1 + 1 = 7\nדיסק: 2\nTLB: 2 (חיפוש ועדכון), או 3 אם סופרים גם את החיפוש בהרצה החוזרת"}], "official": "6.1: זיכרון פיזי מקסימלי 8GB. 6.2: 3 רמות. 6.3: הפתרון הרשמי מפרט את השלבים (TLB miss, 3 גישות לטבלה, page out ו-page in – כל אחד זיכרון ודיסק, עדכון הטבלה, עדכון TLB, הרצה חוזרת וגישה לנתון) בלי לסכם מספרים.", "expl": "בסעיף 6.3 הפתרון הרשמי מונה את השלבים אבל לא כותב את המספרים הסופיים. הספירה כאן נגזרת ישירות מהפירוט הרשמי.", "check": "חושב", "exam": "22AA", "examLabel": "סמסטר א' תשפ\"ב מועד א'", "date": "11.01.2022", "id": "22AA-6"}, {"num": "7", "type": "open", "topic": "threads", "sub": "מימוש מנעול עם פעולה אטומית", "intro": "מנעול חד-פעמי הוא מנעול שאפשר לנעול פעם אחת בלבד: ברגע שחוט תופס את המנעול בהצלחה, אף חוט אחר לא יכול לתפוס אותו יותר לכל אורך התוכנית. פונקציית הנעילה מחזירה 0 לחוטים שנכשלו – בלי לחסום אותם (בדומה ל-trylock) – ו-1 לחוט שהצליח. ברגע שחוט קיבל 1, כל קריאה עתידית בכל חוט תחזיר 0, גם אם המנעול פנוי.\n\nבמנעול חד-פעמי ל-N חוטים מובטח שפונקציית הנעילה לא נקראת יותר מ-N פעמים בכל ריצה.\n\nלרשותנו פקודת חומרה אטומית Check&Add, שמקדמת מונה באחד ומחזירה האם ערכו החדש שווה לפרמטר C (הקוד הוא לצורך הסבר בלבד – המעבד מבצע את כל זה באופן אטומי). אסור להשתמש באובייקטי סנכרון או בפעולות אטומיות אחרות, ויש לדאוג למניעה הדדית ולחופש מקיפאון.", "code": "int check_add(int *p, int C) {\n    assert(*p < C);   // check invalid op (crashes if FALSE)\n    return (++*p == C);\n}", "parts": [{"label": "7.1", "q": "ממשו מנעול חד-פעמי ל-2 חוטים שמשתמש בתא זיכרון יחיד (משתנה x שמתקבל כפרמטר): void init2(int* x) ו-int lock2(int* x).", "answer": "משתמשים ב-C = 2 כדי להבדיל בין החוט הראשון שקורא ל-lock2 לבין השני:\n\nvoid init2(int *x) {\n    *x = 0;\n}\nint lock2(int *x) {\n    return !check_add(x, 2);\n}\n\nהראשון מקדם ל-1 (לא שווה ל-2) ומקבל 1. השני מקדם ל-2 ומקבל 0.\n\nחשוב להחזיר את ההפך מ-check_add. מובטח שיהיו לכל היותר 2 קריאות – אבל לא מובטח שיהיו בדיוק 2. אם רק חוט אחד מנסה ו\"הצלחה\" היא לקבל אמת, הוא ייכשל ואף אחד לא יתפוס את המנעול."}, {"label": "7.2", "q": "ממשו מנעול חד-פעמי ל-3 חוטים שמשתמש ב-2 תאי זיכרון (משתנים x ו-y שמתקבלים כפרמטר): void init3(int* x, int* y) ו-int lock3(int* x, int* y).", "answer": "הפעולה יודעת להפריד רק את החוט האחרון שביצע אותה. עם 3 חוטים משתמשים ב-x כדי להוציא את השלישי, ובין שני הראשונים מכריעים עם הפתרון של 7.1:\n\nvoid init3(int *x, int *y) {\n    *x = *y = 0;\n}\nint lock3(int *x, int *y) {\n    if (check_add(x, 3))\n        return 0;\n    return lock2(y);\n}"}, {"label": "7.3", "q": "ממשו מנעול חד-פעמי ל-N חוטים (N פרמטר בפונקציית האתחול). הגדירו את המבנה CALock וממשו init(CALock *lock, int N), int lock(CALock *lock) ו-void destroy(CALock *lock).", "answer": "אותו רעיון, בשלבים: N − 1 משתנים, וכל אחד הוא \"תחרות\" שבה החוט האחרון שמגיע אליה נפסל. בשלב i מגיעים לכל היותר N − i חוטים, ולכן C = N − i. בשלב האחרון C = 2, אז לכל היותר חוט אחד עובר את כולם.\n\ntypedef struct __calock {\n    int *carr;\n    int N;\n} CALock;\n\nvoid init(CALock *lock, int N) {\n    lock->carr = (int*) calloc(N - 1, sizeof(int));\n    lock->N = N;\n}\nint lock(CALock *lock) {\n    for (int i = 0; i < lock->N - 1; ++i)\n        if (check_add(&lock->carr[i], lock->N - i))\n            return 0;\n    return 1;\n}\nvoid destroy(CALock *lock) {\n    free(lock->carr);\n}\n\nהחוט שזוכה אינו בהכרח הראשון שניסה – הוא הראשון שהגיע לשלב האחרון, בלי שהיה אחרון באף שלב."}], "official": "כמו בפתרון כאן, אבל בקוד הרשמי של 7.3 יש שלוש טעויות קטנות.", "note": "בקוד הרשמי של 7.3: מעבירים את carr[i] במקום את הכתובת שלו (&carr[i]), משתמשים ב-N במקום lock->N, וחסרה השורה return 1 בסוף הפונקציה (וגם destroy לא מומשה). הקוד כאן מתוקן.", "expl": "הקוד המתוקן נבדק בהרצה אמיתית: Check&Add מומש עם פעולה אטומית של המעבד, והרצתי 80,000 ריצות עם חוטים אמיתיים – 2 ו-3 חוטים לסעיפים 7.1–7.2, ו-N בין 2 ל-8 עם כל מספר של חוטים מתחרים בסעיף 7.3. בכל ריצה זכה בדיוק חוט אחד, וה-assert לא נכשל אף פעם.", "check": "הורץ עם חוטים אמיתיים", "exam": "22AA", "examLabel": "סמסטר א' תשפ\"ב מועד א'", "date": "11.01.2022", "id": "22AA-7"}, {"num": "8", "type": "open", "topic": "fs", "sub": "VSFS", "intro": "נתונה מערכת קבצים VSFS עם גודל בלוק של 4KB. מספר בלוקי ה-DATA במערכת הוא 20,000,000, ומספר ה-inodes הוא 40,000. גודל כל inode הוא 128 בתים.\nהסופר-בלוק מכיל את השדות: BSIZE – גודל הבלוק (4096 בתים), Nblocks – מספר הבלוקים הכולל, Ninodes – מספר ה-inodes, I_BMAP_Start – הבלוק הראשון של ה-inode bitmap, D_BMAP_Start – הבלוק הראשון של ה-data bitmap.\nבכל inode יש 10 מצביעים ישירים, מצביע עקיף אחד ומצביע עקיף כפול אחד.\nבנוסף מוגדרים בקרנל 2 מערכים שמתארים כמה ביטים פנויים (כמה אפסים) יש בכל בלוק של bitmap:", "code": "int inode_bmap_stat[ <value_1> ];\nint data_bmap_stat[ <value_2> ];", "parts": [{"label": "8.1", "q": "האם אפשר לדעת מה הגדלים של המערכים? אם כן – פרטו את הגדלים, אחרת – פרטו איזה מידע חסר.", "answer": "אפשר לדעת: כל תא במערך מתאר בלוק אחד של ה-bitmap המתאים, ולכן גודל כל מערך הוא מספר הבלוקים ב-bitmap.\n\nביטים בבלוק:\n4KB = 4096 × 8 = 32,768 ביטים\n\nvalue_1 (inode bitmap):\n40,000 / 32,768 = 1.22, ולכן 2 בלוקים.\n\nvalue_2 (data bitmap):\n20,000,000 / 32,768 = 610.4, ולכן 611 בלוקים."}, {"label": "8.2", "q": "משתמש ביצע בטרמינל את הפעולה mkdir d1. הניחו שהפעולה מצליחה. כמה בלוקים צריך לקרוא ולכתוב לדיסק בכדי לבצע את הפעולה?", "answer": "מניחים שתיקיית העבודה הנוכחית כבר בזיכרון הקרנל, כולל ה-DATA שלה.\n\n1) בלוק inode bitmap עם ביט פנוי (נמצא מיד בזכות המערך): קריאה וכתיבה.\n2) בלוק ה-inodes שבו ה-inode החדש: קריאה וכתיבה (משנים inode אחד בלי לפגוע בשאר הבלוק).\n3) בלוק data bitmap עם ביט פנוי: קריאה וכתיבה.\n4) בלוק ה-DATA של התיקייה הנוכחית, להוספת הרשומה d1: כתיבה בלבד (כבר בזיכרון; מניחים שלא צריך בלוק חדש).\n5) בלוק ה-DATA החדש של d1, עם הרשומות . ו-..: כתיבה בלבד.\n\nסך הכל: 3 קריאות ו-5 כתיבות."}, {"label": "8.3", "q": "בתיקיית העבודה הנוכחית קיים קובץ רגיל שגודלו 45,050 בתים. תוכנית משתמש פתחה את הקובץ בסופו (O_APPEND) וכתבה 10 בתים. כמה בלוקים צריך לקרוא מהדיסק בכדי לבצע את פעולת הכתיבה? (אין צורך להתייחס לכתיבות לדיסק.)", "answer": "נתוני ה-inode כבר בזיכרון אחרי פתיחת הקובץ.\n\nאיפה הכתיבה:\n45,050 / 4,096 = 10.998, כלומר הקובץ תופס את בלוקים 0 עד 10 (לפי הסדר בקובץ).\nבבלוק 10 נשארו 6 בתים פנויים, ולכן 6 בתים נכתבים לבלוק 10 ו-4 לבלוק חדש – בלוק 11.\n\nבלוקים 10 ו-11 הם מעבר ל-10 המצביעים הישירים (0 עד 9), ולכן מגיעים אליהם דרך המצביע העקיף.\n\nקריאות:\n1) בלוק המצביעים העקיף.\n2) בלוק 10 עצמו – כותבים רק חלק ממנו, אז צריך לקרוא אותו קודם.\n3) בלוק data bitmap – כדי להקצות את בלוק 11.\nאת בלוק 11 החדש לא צריך לקרוא, רק לכתוב.\n\nסך הכל: 3 קריאות (התקבלה גם תשובה שסופרת קריאה נוספת של בלוק ה-inode)."}], "official": "8.1: value_1 = 2, value_2 = 611. 8.2: צעדים 1–3 קריאה וכתיבה, צעדים 4–5 כתיבה בלבד. 8.3: קריאת בלוק המצביעים העקיף, הבלוק עצמו, ובלוק data bitmap.", "note": "בפתרון הרשמי של 8.1 כתוב \"יש 2,000,000 בלוקים של DATA\", אבל בשאלה הנתון הוא 20,000,000 – והתשובה 611 נכונה רק עבור 20,000,000 (עבור 2,000,000 היו יוצאים 62). גם \"32,678 ביטים\" הוא שגיאת הקלדה של 32,768.", "expl": "", "check": "חושב", "exam": "22AA", "examLabel": "סמסטר א' תשפ\"ב מועד א'", "date": "11.01.2022", "id": "22AA-8"}, {"num": "1", "type": "tf", "topic": "disk", "sub": "SSD", "q": "הוכח או הפרך: בכונן SSD, נתוני קובץ שניגשים אליו לעיתים רחוקות נשארים באותו מיקום פיזי על הדיסק.", "correct": false, "official": "לא נכון. בלוק שלא משתנה במשך זמן רב נכתב מחדש כדי לחלוק במעמסת הכתיבה עם שאר הבלוקים בדיסק.", "expl": "ב-SSD כל בלוק פיזי עומד רק במספר מוגבל של מחיקות. כדי שהבלוקים יישחקו באופן אחיד, ה-FTL מבצע wear leveling: גם נתונים \"קרים\" שלא משתנים מועברים מדי פעם למקום אחר, כדי שהבלוקים שהם תפסו ישמשו לכתיבות חדשות.\n\nלכן גם קובץ שכמעט לא ניגשים אליו לא נשאר בהכרח באותו מיקום פיזי.", "check": "לפי OSTEP, פרק 44", "exam": "22AB", "examLabel": "סמסטר א' תשפ\"ב מועד ב'", "date": "01.02.2022", "id": "22AB-1"}, {"num": "2", "type": "tf", "topic": "sched", "sub": "SRTF", "q": "הוכח או הפרך: אלגוריתם התזמון SRTF פותר את בעיית ההרעבה של תהליכים.", "correct": false, "official": "לא נכון. תהליך ארוך יורעב אם מגיעים הרבה תהליכים קצרים למערכת, כך שהם כל הזמן מתוזמנים לפניו והתהליך הארוך לא מסיים לעולם.", "expl": "SRTF תמיד מריץ את העבודה עם הכי מעט זמן שנותר. אם כל הזמן מגיעות עבודות קצרות חדשות, הן תמיד \"מנצחות\" את העבודה הארוכה – והיא לא תרוץ לעולם. זו בדיוק הרעבה.\n\nהפתרון שראינו להרעבה הוא ב-MLFQ: priority boost, שמעלה מדי פעם את כל העבודות לתור העליון.", "check": "נבדק מול ההרצאה", "exam": "22AB", "examLabel": "סמסטר א' תשפ\"ב מועד ב'", "date": "01.02.2022", "id": "22AB-2"}, {"num": "3", "type": "tf", "topic": "threads", "sub": "מקביליות", "q": "הוכח או הפרך: במערכת עם מעבד יחיד, שימוש בחוטים יכול לשפר את ביצועי התוכנית.", "correct": true, "official": "נכון. במעבד יחיד לא ניתן להריץ קוד באופן מקבילי באמת, אך שימוש בחוטים מאפשר לשפר את הביצועים במקרה של חפיפה – להמשיך להריץ קוד בזמן ביצוע קלט/פלט.", "expl": "גם בלי מקביליות אמיתית, חוטים מאפשרים חפיפה (overlap): כשחוט אחד חסום ומחכה לקלט/פלט (דיסק, רשת), חוט אחר של אותה תוכנית יכול להשתמש במעבד. בתוכנית עם חוט יחיד המעבד היה פשוט מחכה.\n\nזה אותו רעיון כמו \"שילוב I/O\" בתזמון: לא לבזבז את המעבד בזמן שעבודה חסומה.", "check": "נבדק מול ההגדרות", "exam": "22AB", "examLabel": "סמסטר א' תשפ\"ב מועד ב'", "date": "01.02.2022", "id": "22AB-3"}, {"num": "4", "type": "tf", "topic": "threads", "sub": "Hand-over-hand", "q": "הוכח או הפרך: ברשימה מקושרת hand-over-hand עם מנעולים הוגנים, תיתכן הרעבה.", "correct": false, "official": "לא נכון. מאחר שמתקדמים על המנעולים ברשימה המקושרת אחד אחרי השני וכל מנעול הוא הוגן, הרי שכל חוט ממתין רק לחוטים ש\"לפניו\". לא ניתן לעקוף חוטים אחרים ברשימה בגלל אופן תפיסת המנעול והשימוש במנעולים הוגנים, ולכן לא תיתכן הרעבה.", "expl": "ב-hand-over-hand לכל צומת יש מנעול, וחוט שעובר על הרשימה תופס את המנעול של הצומת הבא לפני שהוא משחרר את הנוכחי. כך החוטים \"זוחלים\" ברשימה בסדר קבוע, ואי אפשר לעקוף חוט שנמצא לפניך.\n\nכשכל מנעול הוגן (למשל ticket lock), חוט שממתין למנעול יקבל אותו אחרי מספר סופי של חוטים שהגיעו לפניו. אין דרך שחוטים חדשים \"יעקפו\" אותו שוב ושוב – ולכן אין הרעבה.", "check": "נבדק מול ההגדרות", "exam": "22AB", "examLabel": "סמסטר א' תשפ\"ב מועד ב'", "date": "01.02.2022", "id": "22AB-4"}, {"num": "5", "type": "tf", "topic": "disk", "sub": "DMA", "q": "הוכח או הפרך: שימוש ב-DMA מאפשר לתהליכים לקבל יותר זמן מעבד.", "correct": true, "official": "נכון. ה-DMA הוא התקן שמטפל בהעברת המידע מ/אל התקני קלט/פלט במקום מערכת ההפעלה והמעבד, וכך המעבד פנוי להריץ תהליכים אחרים במשך יותר זמן.", "expl": "בלי DMA, המעבד צריך להעתיק בעצמו כל מילה בין הזיכרון להתקן (Programmed I/O) – זמן מעבד שהולך לאיבוד. עם DMA מערכת ההפעלה רק מורה לבקר ה-DMA מה להעתיק, ומקבלת פסיקה כשההעתקה הסתיימה. בינתיים המעבד מריץ תהליכים אחרים.", "check": "לפי OSTEP, פרק 36", "exam": "22AB", "examLabel": "סמסטר א' תשפ\"ב מועד ב'", "date": "01.02.2022", "id": "22AB-5"}, {"num": "6", "type": "open", "topic": "redir", "sub": "pipe בין תהליכים", "intro": "נתונה התוכנית הבאה. אפשר להניח שכל קריאות המערכת מצליחות.", "code": " 1 void foo(int p_read[2], int p_write[2]) {\n 2     unsigned int num;\n 3     int ret;\n 4     close(p_read[1]);\n 5     close(p_write[0]);\n 6\n 7     while (1) {\n 8         ret = read(p_read[0], &num, sizeof(int));\n 9         if (ret == 0)\n10             exit(0);\n11         printf(\"%d \", num);\n12         if (num == 1)\n13             exit(0);\n14         usleep(50 * 1000);\n15         num = (num%2 == 0) ? num/2 : num*3+1;\n16         write(p_write[1], &num, sizeof(int));\n17     }\n18 }\n19 int main() {\n20     setbuf(stdout, NULL); // cancel buffering\n21     int pipe1[2], pipe2[2];\n22     const int NUM = 3;\n23     pipe(pipe1);\n24     pipe(pipe2);\n25     if (!fork())\n26         foo(pipe1, pipe2);\n27     if (!fork())\n28         foo(pipe2, pipe1);\n29     write(pipe1[1], &NUM, sizeof(int));\n30     // while (wait(NULL) > 0); // commented out!\n31     exit(0);\n32 }", "parts": [{"label": "6.1", "q": "מה הפלט של התוכנית?", "answer": "3 10 5 16 8 4 2 1\n\nהאב כותב 3 ל-pipe1. הבן הראשון קורא מ-pipe1 וכותב ל-pipe2, והבן השני קורא מ-pipe2 וכותב ל-pipe1 – כך הם מעבירים את המספר הלוך ושוב. כל אחד מדפיס את המספר שקיבל ומחשב את הבא: אם זוגי – חצי, אחרת 3n + 1 (סדרת קולץ). כשמגיעים ל-1, מי שקיבל אותו יוצא."}, {"label": "6.2", "q": "בהנחה שהרצנו את התוכנית מתוך הטרמינל, האם ה-prompt של הטרמינל עשוי להתערבב עם הפלט של התוכנית?", "answer": "כן. ה-shell ממתין רק לתהליך האב, והאב מסתיים מיד אחרי שכתב את 3 – הרבה לפני שהבנים סיימו להדפיס. לכן ה-prompt יופיע באמצע הפלט של הבנים."}, {"label": "6.3", "q": "אם נכניס את שורה 14 להערה, האם עלול להיווצר מרוץ (race condition)?", "answer": "לא. הבנים מסונכרנים על ידי ה-pipe עצמו: כל אחד חסום ב-read עד שהשני כותב, כך שבכל רגע רק אחד מהם \"פעיל\". ההדפסות בלי buffer, וכל תהליך עובד בזיכרון הפרטי שלו. ה-usleep רק מאט – הוא לא זה שמסנכרן."}, {"label": "6.4", "q": "אם נוציא את שורה 30 מהערה, מה תהיה ההשפעה על ריצת התוכנית?", "answer": "התוכנית תיתקע. הבן שמקבל את 1 יוצא, אבל הבן השני חסום ב-read ומחכה למספר הבא. הוא היה מקבל EOF רק אם כל הצדדים הכותבים של ה-pipe שלו היו סגורים – אבל האב עדיין מחזיק אותם פתוחים, והאב עצמו תקוע ב-wait ומחכה לאותו בן. זה מעגל המתנה.\n\nכדי שזה יעבוד, האב צריך לסגור את קצוות ה-pipe שלו – בפרט את הצדדים הכותבים – לפני ה-wait."}], "official": "6.1: 3 10 5 16 8 4 2 1. 6.2: כן – ה-prompt ממתין לאב בלבד, שמסתיים לפני הבנים. 6.3: לא נוצר מרוץ – הקריאות והכתיבות ל-pipe מסנכרנות. 6.4: התוכנית תיתקע, כי האב לא סוגר את קצוות ה-pipe.", "expl": "", "check": "הורץ: הפלט 3 10 5 16 8 4 2 1, ועם שורה 30 התוכנית נתקעה ונעצרה רק ב-timeout", "exam": "22AB", "examLabel": "סמסטר א' תשפ\"ב מועד ב'", "date": "01.02.2022", "id": "22AB-6"}, {"num": "7", "type": "open", "topic": "sync", "sub": "Barrier", "intro": "Barrier הוא אובייקט סנכרון ל-N חוטים (N פרמטר אתחול) עם פעולה אחת, checkin, שנועדה לסנכרן את שלב הביצוע של N החוטים. חוט שקורא ל-checkin חסום עד ש-N חוטים (כולל הוא) קראו ל-checkin. החוט ה-N (\"האחרון\") משחרר את כולם, וכולם ממשיכים לפקודה הבאה.\nהפעולה אינה חד-פעמית: אחרי שהקריאה חוזרת אפשר לקרוא שוב ולחכות שוב – עד שכל החוטים יקראו שוב, וכן הלאה.\nבשאלה זו אפשר להתעלם מגבולות int (אין overflow), ואפשר להשתמש ב-spinning.", "parts": [{"label": "7.1", "q": "לכל חוט יש מזהה i בין 0 ל-N − 1 שמועבר כפרמטר ל-checkin. השלימו את המימוש החלקי הבא ע\"י כתיבת checkin, בלי פעולות אטומיות או אובייקטי סנכרון. אין להוסיף שדות או לשנות את הקוד הנתון.", "code": "typedef struct {\n    int N;\n    int *arr;\n} Barrier;\nvoid init(Barrier *bar, int N) {\n    bar->N = N;\n    bar->arr = (int*) calloc(sizeof(int), N);\n}\nvoid destroy(Barrier *bar) {\n    free(bar->arr);\n}\nvoid checkin(Barrier *bar, int i) {\n    // ???\n}", "answer": "כל חוט סופר בתא שלו במערך כמה פעמים קרא ל-checkin. רק הוא כותב לתא שלו, ולכן אפשר לקדם אותו בלי פעולה אטומית. אחר כך הוא עובר על כל המערך ומחכה שכל חוט יגיע לפחות לאותו מספר קריאות:\n\nvoid checkin(Barrier *bar, int i) {\n    ++bar->arr[i];\n    for (int t = 0; t < bar->N; ++t)\n        while (bar->arr[t] < bar->arr[i]);   // wait for t\n}\n\nלמה זה עובד גם בשימוש חוזר: חוט שכבר יצא וקרא שוב ל-checkin רק מגדיל את התא שלו, וחוט שעדיין מחכה בסבב הקודם בודק \"לפחות\" – כך שזה לא מפריע לו."}, {"label": "7.2", "q": "ממשו Barrier עם שימוש כרצונכם באובייקטי סנכרון ופעולות אטומיות שנלמדו, בזיכרון מינימלי. הגדירו את המבנה וממשו init, destroy ו-checkin. שימו לב: כאן checkin לא מקבל את i.", "answer": "מונה אחד שסופר את כל הקריאות ל-checkin מכל החוטים. בכל פעם שהמונה מגיע לכפולה של N, כל החוטים קראו לפחות פעם נוספת.\n\nכל חוט מקדם את המונה אטומית עם Fetch-And-Add, ומחכה שהמונה יעבור לכפולה הבאה של N:\n\ntypedef struct __Barrier {\n    int N;\n    int checked;\n} Barrier;\n\nvoid init(Barrier *bar, int N) {\n    bar->N = N;\n    bar->checked = 0;\n}\nvoid checkin(Barrier *bar) {\n    int val = fetch_and_add(&bar->checked, 1);\n    while ((bar->checked / bar->N) == (val / bar->N));\n}\nvoid destroy(Barrier *bar) {\n    // empty\n}"}], "official": "כמו בפתרון כאן.", "note": "בקוד הרשמי של 7.1 כתוב arr[t] ו-arr[i] במקום bar->arr[t] ו-bar->arr[i]. הקוד כאן מתוקן.", "expl": "שני המימושים נבדקו בהרצה עם 4 חוטים אמיתיים ו-2,000 סבבים, כשבכל סבב כל חוט בודק שאף חוט אחר לא נשאר מאחור אחרי ה-checkin: 0 הפרות בשני המימושים.", "check": "הורץ עם חוטים אמיתיים", "exam": "22AB", "examLabel": "סמסטר א' תשפ\"ב מועד ב'", "date": "01.02.2022", "id": "22AB-7"}, {"num": "8", "type": "open", "topic": "disk", "sub": "ביצועי דיסק ו-RAID", "intro": "נתונה מערכת עם workload אקראי של 1MB וסדרתי של 50MB. נתונים שלושה דיסקים קשיחים. יש לפרט ולנמק את כל החישובים.", "table": {"headers": ["דיסק", "RPM", "SEEK TIME", "TRANSFER RATE"], "rows": [["NEXUS", "1200", "10ms", "200 MB/s"], ["PYLON", "5400", "50ms", "100 MB/s"], ["PHOTON", "5400", "10ms", "150 MB/s"]]}, "parts": [{"label": "8.1", "q": "איזה דיסק קשיח נעדיף עבור ה-workload האקראי, ואיזה עבור הסדרתי?", "answer": "המתנה לסיבוב (חצי סיבוב בממוצע):\n1200 RPM: סיבוב של 50ms, ולכן 25ms\n5400 RPM: סיבוב של 11.1ms, ולכן 5.56ms (בפתרון הרשמי עוגל ל-5ms)\n\nזמן מיקום (seek + המתנה):\nNEXUS: 10 + 25 = 35ms\nPYLON: 50 + 5.56 = 55.56ms\nPHOTON: 10 + 5.56 = 15.56ms\n\nזמן העברה של 1MB (1000 חלקי הקצב):\nNEXUS: 5ms, PYLON: 10ms, PHOTON: 6.67ms\n\nאקראי, 1MB:\nNEXUS: 35 + 5 = 40ms\nPYLON: 55.56 + 10 = 65.56ms\nPHOTON: 15.56 + 6.67 = 22.22ms\nנעדיף את PHOTON.\n\nסדרתי, 50MB:\nNEXUS: 35 + 250 = 285ms\nPYLON: 55.56 + 500 = 555.6ms\nPHOTON: 15.56 + 333.3 = 348.9ms\nנעדיף את NEXUS."}, {"label": "8.2", "q": "עבור ה-workload הסדרתי, מה היחס (באחוזים) בין המהירות בפועל לבין המהירות המקסימלית של כל דיסק?", "answer": "הקצב בפועל הוא 50MB חלקי הזמן מ-8.1:\nNEXUS: 50 / 0.285 = 175.4 MB/s\nPYLON: 50 / 0.5556 = 90.0 MB/s\nPHOTON: 50 / 0.3489 = 143.3 MB/s\n\nבאחוזים מהקצב המקסימלי:\nNEXUS: 175.4 / 200 = 87.7%\nPYLON: 90.0 / 100 = 90.0%\nPHOTON: 143.3 / 150 = 95.5%\n\n(עם העיגול של הפתרון הרשמי יוצא 87.5%, 90% ו-96%.)"}, {"label": "8.3", "q": "לשיפור ביצועים ב-workload האקראי, הוחלט להשתמש במערך RAID-4 של דיסקים מסוג PYLON. מה המספר המינימלי של דיסקים שנצטרך כדי לשפר את הביצועים על פני שימוש בדיסק אחד ללא RAID? תנו תשובה נפרדת לכל תרחיש (קריאות אקראיות וכתיבות אקראיות).", "answer": "הקצב בתרחיש האקראי לכל דיסק (1MB חלקי זמן הפעולה מ-8.1):\nNEXUS: 25 MB/s, PYLON: R = 15.25 MB/s, PHOTON: 45 MB/s\n\nכדי לשפר צריך לעבור את הדיסק הטוב ביותר – PHOTON.\n\nקריאות אקראיות:\nב-RAID-4 עם N דיסקים הקצב הוא (N − 1)·R.\nN = 3: 2 × 15.25 = 30.5 – לא מספיק\nN = 4: 3 × 15.25 = 45.8 – יותר מ-45, משפר\nתשובה: 4 דיסקים.\n\nכתיבות אקראיות:\nב-RAID-4 הקצב הוא R/2 בלי קשר למספר הדיסקים (דיסק ה-parity הוא צוואר בקבוק). לכן אי אפשר לשפר בכלל, בשום מספר דיסקים."}], "official": "8.1: PHOTON לאקראי, NEXUS לסדרתי. 8.2: NEXUS 87.5%, PYLON 90%, PHOTON 96%. 8.3: קריאות – 4 דיסקים; כתיבות – אי אפשר לשפר.", "note": "הפתרון הרשמי עיגל את ההמתנה לסיבוב ב-5400 RPM ל-5ms (הערך המדויק 5.56ms), וברשימת הזמנים הסדרתיים שלו (250, 500, 333) חסר זמן המיקום – אבל הקצבים שהוא מחשב אחריהם כן כוללים אותו. עם העיגול של הפתרון הרשמי, ב-8.3 עם 4 דיסקים יוצא שוויון מדויק (3 × 15.38 = 46.15, בדיוק כמו PHOTON). עם הערכים המדויקים 4 דיסקים כן משפרים (45.8 לעומת 45). התשובה הרשמית – 4 – נכונה.", "expl": "", "check": "חושב בסקריפט, גם עם העיגול הרשמי וגם עם הערכים המדויקים", "exam": "22AB", "examLabel": "סמסטר א' תשפ\"ב מועד ב'", "date": "01.02.2022", "id": "22AB-8", "image": "img/22AB-8.png"}, {"num": "1", "type": "open", "topic": "deadlock", "sub": "סמפורים וקיפאון", "parts": [{"label": null, "q": "האם ייתכן קיפאון בתוכנית שמשתמשת רק בסמפורים שאינם בינאריים? אם כן – הדגימו תרחיש שיוביל לקיפאון, אחרת – הסבירו בפירוט מדוע לא.", "answer": "ייתכן.\n\nתרחיש: שני סמפורים S1 ו-S2, כל אחד מאותחל ל-2 (מייצג 2 יחידות של משאב). כל חוט צריך 2 יחידות מכל משאב:\nחוט A: wait(S1), wait(S1), wait(S2), wait(S2)\nחוט B: wait(S2), wait(S2), wait(S1), wait(S1)\n\nאם A לוקח יחידה אחת מ-S1 ו-B לוקח יחידה אחת מ-S2, ואז A לוקח את השנייה מ-S1 ו-B את השנייה מ-S2 – שני הסמפורים על 0. A ממתין ל-S2 ו-B ממתין ל-S1, ואף אחד לא ישחרר. זה בדיוק הקיפאון הבסיסי מהשיעור (שני חוטים, שני מנעולים בסדר הפוך) – רק עם יחידות משאב במקום מנעולים.\n\nגם תרחיש פשוט יותר עובד: כל חוט מבקש יחידה אחת מכל סמפור, אבל יש 3 חוטים ו-2 יחידות, בסדר מעגלי."}], "official": "ייתכן. עם 2 סמפורים שמאותחלים ל-2, אפשר להגיע לאותה בעיה בסיסית שהוצגה בשיעור של קיפאון, אם כל חוט מנסה להקצות לעצמו 2 משאבים מכל סמפור.", "expl": "", "check": "נבדק מול הפתרון הרשמי", "exam": "22AC", "examLabel": "סמסטר א' תשפ\"ב מועד ג'", "date": "2022", "id": "22AC-1"}, {"num": "2", "type": "open", "topic": "sched", "sub": "Lottery ו-Stride", "parts": [{"label": null, "q": "מתי נעדיף להשתמש בתזמון lottery על פני תזמון stride ומדוע? ומתי נעדיף stride על פני lottery ומדוע?", "answer": "Stride – כשרוצים חלוקה מדויקת ודטרמיניסטית: כל עבודה מקבלת בדיוק את החלק היחסי שלה בכל פרק זמן, גם בטווח קצר. ב-lottery החלוקה נכונה רק בממוצע, ובטווח קצר עבודה יכולה \"להפסיד\" כמה פעמים ברצף.\n\nLottery – כשעבודות מגיעות ועוזבות הרבה, או כשרוצים מימוש פשוט: אין לו מצב גלובלי לכל תהליך. עבודה חדשה פשוט מקבלת כרטיסים ומשתתפת בהגרלה הבאה. ב-stride צריך להחליט מה ה-pass של עבודה חדשה – אם נאתחל אותו ל-0, היא תשתלט על המעבד עד שתשיג את כולם."}], "official": null, "note": "אין פתרון רשמי לשאלה זו. התשובה נכתבה לפי הספר (OSTEP).", "expl": "", "check": "לפי OSTEP, פרק 9", "exam": "22AC", "examLabel": "סמסטר א' תשפ\"ב מועד ג'", "date": "2022", "id": "22AC-2"}, {"num": "3", "type": "open", "topic": "disk", "sub": "רמות RAID", "parts": [{"label": null, "q": "מתי נעדיף להשתמש בכל אחת מרמות ה-RAID שנלמדו (0, 1, 4, 5)? פרטו ונמקו את הסיבות לשימוש בכל רמה.", "answer": "RAID-0 (striping) – כשרוצים את המקסימום בקיבולת ובביצועים ולא אכפת מאמינות: כל N הדיסקים משמשים לנתונים וכל הפעולות מתחלקות ביניהם, אבל כשל של דיסק אחד מאבד נתונים.\n\nRAID-1 (mirroring) – כשאמינות חשובה ויש הרבה קריאות וכתיבות אקראיות קטנות: כל בלוק שמור פעמיים, אז אפשר לשרוד כשל דיסק, וקריאות אקראיות מתחלקות בין העותקים. המחיר: חצי מהקיבולת.\n\nRAID-4 (parity בדיסק נפרד) – כשרוצים אמינות עם קיבולת טובה (N − 1 דיסקים לנתונים), והעומס בעיקר קריאות וכתיבות סדרתיות. כתיבות אקראיות איטיות מאוד, כי כולן מעדכנות את אותו דיסק parity. כמעט תמיד RAID-5 עדיף עליו.\n\nRAID-5 (parity מפוזר) – כמו RAID-4 מבחינת קיבולת ואמינות, אבל ה-parity מסתובב בין הדיסקים, כך שכתיבות אקראיות מתחלקות ביניהם (קצב בערך N·R/4 במקום R/2). זו הבחירה הטובה כשרוצים אמינות וקיבולת וגם יש כתיבות אקראיות."}], "official": null, "note": "אין פתרון רשמי לשאלה זו. התשובה נכתבה לפי הספר (OSTEP).", "expl": "", "check": "לפי OSTEP, פרק 38", "exam": "22AC", "examLabel": "סמסטר א' תשפ\"ב מועד ג'", "date": "2022", "id": "22AC-3"}, {"num": "4", "type": "open", "topic": "sched", "sub": "תזמון מרובה מעבדים", "parts": [{"label": null, "q": "תזמון SQMS (single-queue multiprocessor scheduling) כפי שנלמד הוא בעייתי. הציעו דרך לשפר אותו באופן משמעותי, בלי להשתמש בתורים נוספים. פרטו את השינויים ונמקו מדוע ישפרו את הביצועים.", "answer": "שתי הבעיות של SQMS:\n1) נעילה – כל המעבדים ניגשים לאותו תור, ולכן צריך מנעול אחד ומשותף. ככל שיש יותר מעבדים, הם מבזבזים יותר זמן בהמתנה למנעול.\n2) Cache affinity – עבודה קופצת בין מעבדים, ובכל פעם ה-cache של המעבד החדש \"קר\" בשבילה.\n\nשיפור בלי תורים נוספים – מנגנון affinity: לכל עבודה שומרים על איזה מעבד היא רצה לאחרונה. כשמעבד בוחר את העבודה הבאה, הוא מעדיף עבודה שרצה עליו לאחרונה (אפשר לקחת אותה גם אם היא לא ראשונה בתור), ורק אם אין כזו – לוקח עבודה אחרת. ככה רוב העבודות נשארות על אותו מעבד ונהנות מ-cache חם, ורק חלק קטן \"מאזן עומס\" בין המעבדים.\n\nכדי להקטין את בעיית הנעילה אפשר להחליף את המנעול הגס במבנה תור שמאפשר גישה מקבילית (מנעולים עדינים יותר או מימוש lock-free), או לקחת כמה עבודות בכל גישה."}], "official": null, "note": "אין פתרון רשמי לשאלה זו. התשובה נכתבה לפי הספר (OSTEP).", "expl": "", "check": "לפי OSTEP, פרק 10", "exam": "22AC", "examLabel": "סמסטר א' תשפ\"ב מועד ג'", "date": "2022", "id": "22AC-4"}, {"num": "5", "type": "open", "topic": "fs", "sub": "LFS", "parts": [{"label": null, "q": "למה משמש ה-imap במערכת הקבצים LFS? מתי וכיצד נשתמש בו? מתי נקרא אותו מהדיסק?", "answer": "למה: ב-LFS הכל נכתב ליומן (log) במקום חדש בכל פעם – גם ה-inodes. לכן ה-inodes לא יושבים במקום קבוע, ואי אפשר לחשב את המיקום של inode לפי המספר שלו כמו ב-VSFS. ה-imap (inode map) ממפה מספר inode למיקום העדכני של ה-inode בדיסק.\n\nאיך משתמשים: כדי לקרוא קובץ, מחפשים את מספר ה-inode ב-imap, קוראים את ה-inode מהמיקום שמופיע שם, ומשם ממשיכים לבלוקי הנתונים כרגיל. כשנכתב inode חדש, מעדכנים את ה-imap, וחלקי ה-imap שהשתנו נכתבים ליומן יחד עם הנתונים וה-inode (באותו segment).\n\nמתי קוראים מהדיסק: גם ה-imap מפוזר ביומן, אז יש checkpoint region במקום קבוע בדיסק שמצביע לחלקים העדכניים שלו. בעליית המערכת (mount) קוראים את ה-checkpoint region, ממנו את כל ה-imap, ושומרים אותו בזיכרון. מאז כל החיפושים ב-imap נעשים בזיכרון, בלי גישה לדיסק."}], "official": null, "note": "אין פתרון רשמי לשאלה זו. התשובה נכתבה לפי הספר (OSTEP).", "expl": "", "check": "לפי OSTEP, פרק 43", "exam": "22AC", "examLabel": "סמסטר א' תשפ\"ב מועד ג'", "date": "2022", "id": "22AC-5"}, {"num": "6", "type": "open", "topic": "memory", "sub": "TLB miss", "parts": [{"label": null, "q": "מתי מתרחש TLB miss? מה התהליך המלא שקורה בעקבות TLB miss?", "answer": "מתי: כשתהליך ניגש לכתובת וירטואלית שהתרגום של הדף שלה (ה-VPN, יחד עם ה-ASID של התהליך) לא נמצא ב-TLB. למשל בגישה הראשונה לדף, אחרי שהרשומה פונתה כי ה-TLB התמלא, או אחרי החלפת הקשר כשה-TLB רוקן.\n\nהתהליך (TLB שמנוהל בחומרה):\n1) ה-MMU מוצא את ה-PTE בטבלת הדפים שבזיכרון (לפי האוגר שמצביע לטבלה של התהליך; בטבלה רב-שלבית – גישה לכל רמה).\n2) אם ה-PTE לא valid – זו גישה לא חוקית: trap למערכת ההפעלה, שבדרך כלל מסיימת את התהליך.\n3) אם valid אבל present = 0 – page fault: מערכת ההפעלה מביאה את הדף מה-swap (ואם צריך – מפנה דף אחר), מעדכנת את ה-PTE, והפקודה מורצת שוב.\n4) אם ה-PTE תקין ואין הפרת הרשאות – מכניסים את התרגום ל-TLB (ואם הוא מלא – מפנים רשומה).\n5) מריצים שוב את הפקודה, ועכשיו יש TLB hit.\n\nב-TLB שמנוהל בתוכנה: ה-miss גורם ל-exception, ה-trap handler של מערכת ההפעלה מוצא את התרגום בטבלה ומכניס אותו ל-TLB בפקודה מורשית, ו-return-from-trap מריץ את הפקודה שוב."}], "official": null, "note": "אין פתרון רשמי לשאלה זו. התשובה נכתבה לפי הספר (OSTEP).", "expl": "", "check": "לפי ההרצאה ו-OSTEP, פרק 19", "exam": "22AC", "examLabel": "סמסטר א' תשפ\"ב מועד ג'", "date": "2022", "id": "22AC-6"}, {"num": "7", "type": "open", "topic": "threads", "sub": "מימוש מנעול", "parts": [{"label": null, "q": "נתון קטע הקוד הבא למימוש מנעול עבור N חוטים, כאשר לכל חוט מזהה ייחודי (בין 0 ל-N − 1) המועבר כפרמטר me לפונקציית lock. האם המנעול מקיים מניעה הדדית? חופש מקיפאון? הוגנות?", "code": "typedef struct {\n    int turn;\n    int busy;\n} FlakyLock;\nvoid init(FlakyLock *lock) {\n    lock->busy = 0;\n}\nvoid lock(FlakyLock *lock, int me) {\n    do {\n        do {\n            lock->turn = me;\n        } while (lock->busy);\n        lock->busy = 1;\n    } while (lock->turn != me);\n}\nvoid unlock(FlakyLock *lock) {\n    lock->busy = 0;\n}", "answer": "מניעה הדדית – מתקיימת. נניח בשלילה ששני חוטים בקטע הקריטי. כל אחד יצא מהלולאה החיצונית כשראה turn שווה למזהה שלו – ורק הוא עצמו כותב את המזהה שלו ל-turn. נסתכל על החוט שיצא שני: הוא כתב turn אחרי שהראשון יצא (אחרת הראשון היה רואה turn לא שלו). אבל הראשון כתב busy = 1 לפני שיצא, ולכן כשהשני בודק את busy אחרי שכתב turn, הוא רואה 1 ותקוע בלולאה הפנימית – סתירה.\n\nחופש מקיפאון – לא מתקיים. דוגמה נגדית: חוט 0 כותב turn = 0 ו-busy = 1. לפני שהוא בודק את התנאי החיצוני, חוט 1 כותב turn = 1 ונתקע בלולאה הפנימית (busy = 1). חוט 0 רואה ש-turn לא שלו, חוזר ללולאה הפנימית, כותב turn = 0 – ונתקע גם הוא, כי busy = 1. אף חוט לא בקטע הקריטי, אף אחד לא יאפס את busy – שני החוטים תקועים לנצח.\n\nהוגנות – לא מתקיימת. דוגמה נגדית: חוט 0 כותב turn = 0 ונעצר לפני busy = 1. חוט 1 כותב turn = 1, עובר ונכנס לקטע הקריטי. חוט 0 ממשיך, רואה שזה לא התור שלו ונתקע בלולאה הפנימית. חוט 1 משחרר (busy = 0), ולפני שחוט 0 רואה את זה – חוט 1 תופס שוב: turn = 1, busy = 1, ונכנס. וכך שוב ושוב."}], "official": "מניעה הדדית – מתקיימת. חופש מקיפאון – לא מתקיים. הוגנות – לא מתקיימת.", "expl": "בדיקה ממוחשבת: הרצתי חיפוש ממצה על כל השזירות האפשריות (עם 2 ו-3 חוטים). לא נמצא אף מצב עם שני חוטים בקטע הקריטי, ונמצאו מצבים ישיגים שמהם אף חוט לא יכול להיכנס לעולם – כלומר קיפאון.", "check": "model checking על כל השזירות", "exam": "22AC", "examLabel": "סמסטר א' תשפ\"ב מועד ג'", "date": "2022", "id": "22AC-7"}, {"num": "8", "type": "open", "topic": "memory", "sub": "גודל טבלת דפים", "intro": "נתונה מערכת עם זיכרון פיזי של 64KB וגודל דף של 512B. כל טבלת דפים תופסת דף יחיד, ותרגום כתובת וירטואלית לפיזית מתבצע ברמה אחת בלבד. כל כניסה בטבלת הדפים (PTE) מכילה מספר מסגרת, ריפוד, ועוד שלושה ביטים: valid, access, dirty.", "parts": [{"label": "8.1", "q": "מה גודל הזיכרון הווירטואלי של תהליך?", "answer": "כתובת פיזית:\n64KB = 2^16, ולכן 16 ביטים.\n\nהיסט:\n512B = 2^9, ולכן 9 ביטים.\n\nPFN:\n16 − 9 = 7 ביטים\n\nגודל PTE:\n7 + 3 = 10 ביטים, ומרפדים לחזקה של 2: 16 ביטים = 2 בתים.\n\nמספר רשומות:\nהטבלה תופסת דף אחד: 512B / 2B = 256 רשומות, כלומר 256 דפים.\n\nזיכרון וירטואלי:\n256 × 512B = 128KB"}, {"label": "8.2", "q": "נתון שחצי מהזיכרון הפיזי משוריין עבור מערכת ההפעלה, והמערכת אינה תומכת ב-swapping או ב-copy-on-write. תהליך יחיד (לא רץ אף תהליך אחר) מבצע fork בלולאה עד שנגמר הזיכרון הפיזי. התהליך המקורי וכל תהליך בן משתמש ב-10 דפים של קוד ו-5 דפים של מחסנית. כמה תהליכי משתמש יכולים להיווצר סך הכל, כולל התהליך הראשי?", "answer": "מסגרות:\n64KB / 512B = 128 מסגרות: 64 לקרנל ו-64 לתהליכים.\n\nבמרחב הקרנל:\nכל תהליך צריך מסגרת אחת לטבלת הדפים שלו.\n\nבמרחב המשתמש:\nהקוד משותף לכל התהליכים (זה קוד לקריאה בלבד, אז אין צורך ב-copy-on-write כדי לשתף אותו): 10 מסגרות פעם אחת. מחסנית: 5 מסגרות לכל תהליך.\n\nחישוב:\n10 + 5k ≤ 64\nk ≤ 10.8, ולכן k = 10\n\nבקרנל: 10 טבלאות ≤ 64 – מספיק.\n\nתשובה: 10 תהליכים, כולל הראשי."}], "official": "8.1: 128KB. 8.2: 10 תהליכים.", "expl": "", "check": "חושב", "exam": "22AC", "examLabel": "סמסטר א' תשפ\"ב מועד ג'", "date": "2022", "id": "22AC-8"}, {"num": "1", "type": "tf", "topic": "disk", "sub": "SSD", "q": "הוכח או הפרך: בכונן SSD, קריאות מרובות מאותו קובץ אינן מאיצות את שחיקת הדיסק.", "correct": true, "official": "נכון. קריאות אמנם מגבירות את הסיכוי להפרעות (disturbance) אבל לא שוחקות את הדיסק (זיכרון flash נשחק ממחזורי מחיקה + כתיבה).", "expl": "שחיקה (wear out) של תאי flash נגרמת ממחזורי program/erase – כלומר מכתיבות ומחיקות. קריאה לא מוחקת ולא כותבת, ולכן לא שוחקת.\n\nקריאות רבות יכולות לגרום ל-read disturbance (שינוי קטן במטען של תאים שכנים), אבל זו לא שחיקה של הדיסק.", "check": "לפי OSTEP, פרק 44", "exam": "22BA", "examLabel": "סמסטר ב' תשפ\"ב מועד א'", "date": "13.06.2022", "id": "22BA-1"}, {"num": "2", "type": "tf", "topic": "sched", "sub": "FIFO ו-RR", "q": "הוכח או הפרך: זמן המחזור הממוצע של תזמון FIFO תמיד עדיף או שווה ל-RR.", "correct": false, "official": "לא נכון. לדוגמה עבור תהליך ארוך שמיד אחריו מגיע תהליך קצר, זמן המחזור הממוצע של FIFO גרוע יותר.", "expl": "דוגמה נגדית: A באורך 100 מגיע ב-0, ו-B באורך 1 מגיע ב-0 (מיד אחריו בתור). quantum של 1.\n\nFIFO: A מסתיים ב-100, B ב-101.\nממוצע: (100 + 101) / 2 = 100.5\n\nRR: B רץ בשנייה השנייה ומסתיים ב-2, A מסתיים ב-101.\nממוצע: (101 + 2) / 2 = 51.5\n\nכש-FIFO נתקע מאחורי עבודה ארוכה (convoy effect), RR יכול להיות הרבה יותר טוב.", "check": "חושב בסימולטור התזמון", "exam": "22BA", "examLabel": "סמסטר ב' תשפ\"ב מועד א'", "date": "13.06.2022", "id": "22BA-2"}, {"num": "3", "type": "tf", "topic": "sync", "sub": "משתני תנאי", "q": "הוכח או הפרך: במשתני תנאי (condition variable), אם נבטל את תפיסת המנעול המובנית ב-wait ובמקום זאת נבצע אותה באופן ידני מיד אחרי כל קריאה ל-wait, זה לא ישפיע על הנכונות ולא יוסיף בעיות חדשות.", "correct": true, "official": "נכון. ב-wait שחרור המנעול והכניסה להמתנה מתבצעות באופן אטומי, אבל לאחר התעוררות (קבלת הסיגנל) מתבצעת תפיסת מנעול כרגיל, ואין הבדל אם תפיסת המנעול מחדש מתבצעת בתוך ה-wait או באופן ידני מיד לאחר ה-wait, כל עוד היא מתבצעת.", "expl": "החלק ב-wait שחייב להיות אטומי הוא שחרור המנעול יחד עם הכניסה לשינה – אחרת סיגנל יכול ללכת לאיבוד בין השחרור להירדמות.\n\nתפיסת המנעול מחדש אחרי ההתעוררות היא פשוט lock רגיל. גם בתוך wait החוט המתעורר מתחרה על המנעול כמו כל חוט אחר, ולכן אם עושים את זה ידנית מיד אחרי wait, אין שום שינוי בהתנהגות.\n\nשימו לב: מה שכן היה שובר את הנכונות הוא לשנות את החלק הראשון – לשחרר את המנעול ידנית לפני wait.", "check": "נבדק מול הגדרת wait", "exam": "22BA", "examLabel": "סמסטר ב' תשפ\"ב מועד א'", "date": "13.06.2022", "id": "22BA-3"}, {"num": "4", "type": "tf", "topic": "threads", "sub": "חוטי משתמש", "q": "הוכח או הפרך: חוטים במרחב המשתמש (user threads) יכולים לשפר את ביצועי התוכנית.", "correct": true, "official": "נכון. בשימוש בחוטים במרחב המשתמש עדיין ניתן לשפר את ביצועי התוכנית ע\"י חפיפה (overlap) – הרצת קוד בחוט אחד בזמן שחוט אחר ממתין לקלט/פלט.", "expl": "חוטים במרחב המשתמש מנוהלים על ידי ספרייה ולא על ידי הקרנל. הם לא יכולים לרוץ באמת במקביל על כמה מעבדים, אבל הפתרון הרשמי מציין שהם עדיין מאפשרים חפיפה: בזמן שחוט אחד ממתין לקלט/פלט, הספרייה מריצה חוט אחר.\n\nזה עובד כשהספרייה משתמשת בקלט/פלט לא-חוסם (בקריאת מערכת חוסמת רגילה הקרנל היה חוסם את כל התהליך, כי הוא לא מכיר את החוטים). הטענה רק אומרת \"יכולים\", ולכן מספיק להראות מקרה אחד.", "check": "לפי הפתרון הרשמי", "exam": "22BA", "examLabel": "סמסטר ב' תשפ\"ב מועד א'", "date": "13.06.2022", "id": "22BA-4"}, {"num": "5", "type": "tf", "topic": "disk", "sub": "DMA", "q": "הוכח או הפרך: שימוש ב-DMA חוסך את זמן העברת הנתונים מ/אל ההתקן בלבד.", "correct": false, "official": "לא נכון. שימוש ב-DMA חוסך לא רק את העברת הנתונים, אלא גם את הטיפול בפסיקות ושליחת פקודות מחדש במקרה של פעולות קריאה/כתיבה גדולות.", "expl": "בלי DMA, בהעברה גדולה המעבד צריך לטפל בכל פסיקה ולשלוח להתקן את הפקודה הבאה שוב ושוב. עם DMA המעבד נותן פקודה אחת לבקר ה-DMA, שמבצע את כל ההעברה, ומקבל פסיקה אחת בסוף.\n\nלכן החיסכון הוא לא רק בהעתקת הנתונים עצמה – אלא גם בפסיקות ובשליחת הפקודות.", "check": "לפי הפתרון הרשמי", "exam": "22BA", "examLabel": "סמסטר ב' תשפ\"ב מועד א'", "date": "13.06.2022", "id": "22BA-5"}, {"num": "6", "type": "open", "topic": "memory", "sub": "טבלה היררכית", "intro": "נתונה מערכת עם גודל דף של 4KB וטבלת דפים היררכית. כל כניסה בטבלת הדפים (PTE) מכילה מספר מסגרת ועוד ביט present בלבד. נתון שהגודל של PTE ו-PDE זהה, וכל טבלה/חלק מאוחסנים בדף אחד בדיוק (לא יותר ולא פחות). יש לפרט ולנמק את החישובים בכל סעיף.", "parts": [{"label": "6.1", "q": "נתון שעבור תהליך המשתמש בכל הדפים במרחב הכתובות שלו, טבלת דפים ב-3 רמות תופסת 1 + 2048 + 2048² מסגרות בזיכרון הפיזי. מה מרחב הכתובות של תהליך, ומה גודל הזיכרון הפיזי המקסימלי?", "answer": "קריאת המספר:\nכשכל הטבלה מלאה, ברמה העליונה יש חלק אחד, בשנייה 2048, ובשלישית 2048². כלומר כל חלק מחזיק 2048 = 2^11 כניסות.\n\nגודל כניסה:\n4KB / 2048 = 2B = 16 ביטים\n\nPFN:\n16 − 1 = 15 ביטים (ביט אחד הוא present)\n\nזיכרון פיזי מקסימלי:\n2^15 × 2^12 = 2^27 = 128MB\n\nמרחב הכתובות:\n3 רמות של 11 ביטים: VPN = 33 ביטים\n2^33 × 2^12 = 2^45 = 32TB"}, {"label": "6.2", "q": "כיצד תשתנה התשובה לסעיף הקודם אם, עבור תהליך שמשתמש בכל הדפים במרחב הכתובות שלו, טבלת דפים ב-2 רמות תופסת 1 + 1024 מסגרות?", "answer": "כל חלק מחזיק 1024 = 2^10 כניסות.\n\nגודל כניסה:\n4KB / 1024 = 4B = 32 ביטים\n\nPFN:\n32 − 1 = 31 ביטים\n\nזיכרון פיזי מקסימלי:\n2^31 × 2^12 = 2^43 = 8TB\n\nמרחב הכתובות:\n2 רמות של 10 ביטים: VPN = 20 ביטים\n2^20 × 2^12 = 2^32 = 4GB"}, {"label": "6.3", "q": "נתון תהליך שמשתמש ב-5 דפים של זיכרון, כאשר 2 מהדפים רצופים בזיכרון התהליך. מה הגודל המינימלי והמקסימלי של הזיכרון הפיזי שתתפוס טבלת הדפים של התהליך, לפי נתוני כל אחד מהסעיפים הקודמים? (4 תשובות)", "answer": "מינימום: כל 5 הדפים ממופים באותו חלק ברמה התחתונה, ולכן יש חלק אחד בכל רמה.\n6.1: 3 מסגרות\n6.2: 2 מסגרות\n\nמקסימום: כל דף ממופה בחלק אחר ברמה התחתונה – גם 2 הדפים הרצופים: אחד הוא הכניסה האחרונה בחלק שלו, והשני הראשונה בחלק הבא. ברמה העליונה תמיד יש מסגרת אחת.\n6.1: 1 + 5 (רמה שנייה) + 5 (רמה שלישית) = 11 מסגרות\n6.2: 1 + 5 = 6 מסגרות"}], "official": "6.1: מרחב כתובות 32TB, זיכרון פיזי 128MB. 6.2: מרחב כתובות 4GB, זיכרון פיזי 8TB. 6.3: מינימום 3 ו-2 מסגרות, מקסימום 11 ו-6 מסגרות.", "note": "בפתרון הרשמי של 6.2 כתוב \"2^11 כניסות בכל רמה, VPN של 22 ביטים, 2^22 דפים\" – זה לא מתאים לנתון (1024 = 2^10 כניסות, VPN של 20 ביטים, 2^20 דפים). התשובה הסופית שם – 4GB – כן נכונה (2^22 דפים היו נותנים 16GB).", "expl": "", "check": "חושב", "exam": "22BA", "examLabel": "סמסטר ב' תשפ\"ב מועד א'", "date": "13.06.2022", "id": "22BA-6"}, {"num": "7", "type": "open", "topic": "sync", "sub": "מנעול קוראים-כותבים", "intro": "בשאלה זו יש לממש מנעול קוראים-כותבים (Reader-Writer Lock) שמקיים את שלוש התכונות: מניעה הדדית, חופש מקיפאון והוגנות. ראשית יש להגדיר מחדש את התכונות כך שיתאימו למנעול קוראים-כותבים, ואחר כך לספק מימוש.", "parts": [{"label": "7.1", "q": "הגדירו מחדש את שלוש התכונות (מניעה הדדית, חופש מקיפאון, הוגנות) כך שיאפיינו במדויק את אופן הפעולה של מנעול קוראים-כותבים. שימו לב: ההגדרות אינן בהכרח זהות לאלו של מנעול רגיל (למשל, כי מתאפשר יותר מחוט אחד בקטע הקריטי).", "answer": "מניעה הדדית: בקטע הקריטי יש לכל היותר חוט כותב אחד, או כל מספר של חוטים קוראים – אבל אף פעם לא כותב וקורא בו-זמנית.\n\nחופש מקיפאון: אם אף חוט לא נמצא בקטע הקריטי, חוט כלשהו ייכנס אליו בסופו של דבר. ואם יש בקטע הקריטי רק קוראים, חוט קורא שמנסה להיכנס ייכנס בסופו של דבר.\n\nהוגנות: כמו במנעול רגיל – אם החוטים נכנסים ויוצאים מהקטע הקריטי, כל חוט שמנסה להיכנס ייכנס בסופו של דבר (בפרט, כותבים לא יורעבו על ידי זרם של קוראים)."}, {"label": "7.2", "q": "ממשו מנעול קוראים-כותבים שמקיים את שלוש התכונות, עם סמפורים בלבד (ללא פעולות אטומיות או אובייקטי סנכרון אחרים): המבנה RWLock והפונקציות init, destroy, acquire_writelock, release_writelock, acquire_readlock, release_readlock.", "answer": "המימוש מבוסס על הפתרון מהשיעור, עם סמפורים בינאריים במקום מנעולים. כדי שקוראים לא ירעיבו את הכותבים, מוסיפים סמפור בינארי שלישי (enterlock) שכל חוט – קורא או כותב – עובר דרכו כדי להתחיל לתפוס. כך אי אפשר לעקוף כותב שממתין.\n\ntypedef struct __rw_lock {\n    int numReaders;\n    sem_t writelock;   // binary semaphore (init to 1)\n    sem_t readlock;    // binary semaphore (init to 1)\n    sem_t enterlock;   // binary semaphore (init to 1)\n} RWLock;\n\nvoid init(RWLock *lock) {\n    lock->numReaders = 0;\n    sem_init(&lock->writelock, 0, 1);\n    sem_init(&lock->readlock, 0, 1);\n    sem_init(&lock->enterlock, 0, 1);\n}\nvoid destroy(RWLock *lock) {\n    sem_destroy(&lock->writelock);\n    sem_destroy(&lock->readlock);\n    sem_destroy(&lock->enterlock);\n}\nvoid acquire_writelock(RWLock *lock) {\n    sem_wait(&lock->enterlock);   // no one else may start acquiring\n    sem_wait(&lock->writelock);\n    sem_post(&lock->enterlock);   // now others can try\n}\nvoid release_writelock(RWLock *lock) {\n    sem_post(&lock->writelock);\n}\nvoid acquire_readlock(RWLock *lock) {\n    sem_wait(&lock->enterlock);\n    sem_wait(&lock->readlock);\n    if (++lock->numReaders == 1)\n        sem_wait(&lock->writelock);   // first reader blocks writers\n    sem_post(&lock->readlock);\n    sem_post(&lock->enterlock);\n}\nvoid release_readlock(RWLock *lock) {\n    sem_wait(&lock->readlock);\n    if (--lock->numReaders == 0)\n        sem_post(&lock->writelock);   // last reader lets writers in\n    sem_post(&lock->readlock);\n}"}, {"label": "7.3", "q": "הוכיחו בקצרה שהמימוש בסעיף הקודם מקיים את שלוש התכונות.", "answer": "מניעה הדדית: כותב בקטע הקריטי מחזיק את writelock. כל עוד יש קוראים, הראשון מביניהם מחזיק את writelock, והאחרון משחרר אותו רק כשהמונה חוזר ל-0. writelock הוא בינארי, ולכן אי אפשר שכותב וקוראים (או שני כותבים) יחזיקו אותו יחד. המונה numReaders מוגן על ידי readlock.\n\nחופש מקיפאון: כל חוט מחזיק את enterlock רק לזמן קצר. כותב שתופס את enterlock ממתין רק ל-writelock, שישתחרר כשהכותב הנוכחי או הקורא האחרון ייצאו (וקוראים חדשים לא יכולים להיכנס בינתיים, כי enterlock תפוס). אין מעגל המתנה, ולכן כשהקטע הקריטי פנוי – מישהו ייכנס.\n\nהוגנות: בהנחה ש-enterlock הוגן (משחרר את הממתינים לפי סדר), כל חוט מגיע תוך מספר סופי של חוטים שלפניו לראש התור. כותב שתפס את enterlock חוסם קוראים חדשים מלהתחיל, ולכן הקוראים שבפנים מסיימים והוא נכנס. כך אף חוט לא נעקף מספר לא מוגבל של פעמים."}], "official": "7.1 – כמו כאן. 7.2 – הפתרון הרשמי מראה רק את המבנה ואת שתי פעולות התפיסה, ואומר שפעולות השחרור זהות לפתרון מהשיעור.", "note": "הפתרון הרשמי של 7.2 לא כולל את init, destroy ופעולות השחרור – הן הושלמו כאן לפי הפתרון מהשיעור. הוגנות מחייבת הנחה ש-enterlock הוא סמפור הוגן.", "expl": "הקוד המלא נבדק בהרצה: 5 חוטים קוראים ו-3 כותבים, 160,000 פעולות. אף פעם לא היו כותב וקורא יחד או שני כותבים יחד, היו מצבים עם כמה קוראים בפנים בבת אחת, והריצה הסתיימה בלי להיתקע.", "check": "הורץ עם חוטים אמיתיים", "exam": "22BA", "examLabel": "סמסטר ב' תשפ\"ב מועד א'", "date": "13.06.2022", "id": "22BA-7"}, {"num": "8", "type": "open", "topic": "fs", "sub": "VSFS", "intro": "נתונה מערכת קבצים VSFS עם סופר-בלוק בבלוק 1, ושאר מערכת הקבצים מבלוק 2 והלאה. תוכן הסופר-בלוק מיוצג על ידי המבנה הבא. כל inode מכיל 9 מצביעים ישירים, 2 מצביעים עקיפים ו-1 מצביע עקיף כפול. גודל מצביע הוא 4 בתים. נתון:\nbsize = 4096\ninode_size = 128\nnblocks = 200 * 1000 * 1000\nninodes = 12 * 1000 * 1000\nיש לפרט ולנמק את החישובים בכל סעיף.", "code": "struct superblock {\n    int bsize;          // block size\n    int inode_size;     // sizeof(struct inode)\n    int nblocks;        // number of data blocks on the disk\n    int ninodes;        // number of inodes\n    int inode_start;    // start of inodes area\n    int data_start;     // start of data block area\n    int i_bmap_start;   // start of inode bit map\n    int d_bmap_start;   // start of data bit map\n    int max_file_size;  // maximum size of file\n    ...\n};", "parts": [{"label": "8.1", "q": "לגבי כל אחד מהשדות הבאים ציינו האם אפשר לדעת את ערכו. אם כן – מה הערך, אחרת – מה הנתון החסר: inode_start, data_start, i_bmap_start, d_bmap_start, max_file_size.", "answer": "כל השדות ניתנים לחישוב.\n\nביטים בבלוק:\n4096 × 8 = 32,768\n\ninode bitmap:\n12,000,000 / 32,768 = 366.2, ולכן 367 בלוקים.\n\ndata bitmap:\n200,000,000 / 32,768 = 6,103.5, ולכן 6,104 בלוקים.\n\nאזור ה-inodes:\n12,000,000 × 128 / 4,096 = 375,000 בלוקים.\n\nלפי הסדר של VSFS (inode bitmap, data bitmap, inodes, data):\ni_bmap_start = 2\nd_bmap_start = 2 + 367 = 369\ninode_start = 369 + 6,104 = 6,473\ndata_start = 6,473 + 375,000 = 381,473\n\nגודל קובץ מקסימלי:\nבבלוק נכנסים 4096 / 4 = 1024 מצביעים.\n(9 + 2·1024 + 1024²) × 4KB = 1,050,633 × 4,096 = 4,303,392,768 בתים (בערך 4GB)"}, {"label": "8.2", "q": "נתון קובץ בגודל המקסימלי האפשרי. המשתמש מחק את הקובץ לחלוטין (לא נותרו hard links אליו). לפני הפעולה ידוע רק מספר ה-inode של הקובץ ושל התיקייה שמכילה אותו, ואף cache אינו מכיל מידע רלוונטי. זה הקובץ היחיד בתיקייה. מה מספר הבלוקים המקסימלי שנצטרך לקרוא ולכתוב תוך כדי המחיקה? פרטו את כל הבלוקים.", "answer": "כדי למחוק קובץ לא צריך לקרוא את בלוקי הנתונים שלו – אבל צריך לסמן כפנויים ב-data bitmap את כל הבלוקים שלו, כולל בלוקי המצביעים.\n\nקריאות:\n1) ה-inode של הקובץ: 1\n2) בלוקי המצביעים, כדי לדעת אילו בלוקים לשחרר: 2 (עקיפים) + 1 (עקיף כפול) + 1,024 (הרמה השנייה שלו) = 1,027\n3) data bitmap – במקרה המקסימלי הבלוקים מפוזרים על כל ה-bitmap: 6,104\n4) ה-inode של התיקייה וה-DATA שלה, למחיקת הרשומה: 2\n5) בלוק inode bitmap: 1\nסך הכל: 1 + 1,027 + 6,104 + 2 + 1 = 7,135\n\nכתיבות:\ndata bitmap 6,104 + inode ו-DATA של התיקייה 2 + inode bitmap 1 = 6,107\n\nאת ה-inode של הקובץ לא צריך לכתוב: מספיק לסמן אותו כפנוי ב-inode bitmap."}, {"label": "8.3", "q": "נתונה מערכת קבצים חדשה וריקה, מלבד תיקייה אחת ובה קובץ יחיד בשם a.txt בגודל 40,000 בתים. בתיקייה זו המשתמש ביצע:\nmkdir d1\ncp a.txt d1/x.txt\nln a.txt d1/y.txt\nln -s a.txt d1/z.txt\nומיד אחר כך: rm -r d1 (מחיקת כל הקבצים ב-d1 ואת d1 עצמה). תארו את כל הפעולות במערכת הקבצים בעקבות rm, לפי סדר הביצוע ובמקרה המינימלי. פרטו כמה בלוקים צריך לקרוא ולכתוב, ומאיזה סוג.", "answer": "גודל הקובץ: 40,000 בתים = 10 בלוקים. 9 הראשונים דרך מצביעים ישירים, והעשירי דרך מצביע עקיף.\n\n1) קריאת ה-inode של התיקייה הנוכחית ואז ה-DATA שלה, כדי למצוא את d1.\n2) קריאת ה-inode של d1 ואז ה-DATA שלה, כדי למצוא את x, y, z.\n3) מחיקת x (עותק עצמאי): קריאת ה-inode שלו, קריאת בלוק המצביעים העקיף, קריאה וכתיבה של data bitmap (שחרור 10 בלוקי נתונים + בלוק המצביעים), וקריאה וכתיבה של inode bitmap.\n4) מחיקת y (hard link ל-a.txt): קריאת ה-inode ועדכון מונה הקישורים – כתיבה של בלוק ה-inode. הקובץ לא נמחק, כי a.txt עדיין מצביע אליו.\n5) מחיקת z (קישור סימבולי): כמו x, אבל יש לו רק בלוק DATA אחד עם הנתיב – אין בלוק מצביעים.\n6) את הרשומות בתוך d1 לא צריך לעדכן, כי d1 נמחקת כולה.\n7) מחיקת d1: עדכון (קריאה וכתיבה) של data bitmap ושל inode bitmap.\n8) עדכון התיקייה הנוכחית: קריאה ועדכון של ה-DATA שלה, כדי להוריד את הרשומה של d1.\n\nבמקרה המינימלי כל ה-inodes באותו בלוק, כל הביטים באותו בלוק inode bitmap, וכל הביטים באותו בלוק data bitmap – ולכן כל אחד מהם נקרא ונכתב פעם אחת בלבד.\n\nסך הכל לפי הפתרון הרשמי: 7 קריאות ו-4 כתיבות."}], "official": "8.1: i_bmap_start = 2, d_bmap_start = 369, inode_start = 6473, data_start = 381473, max_file_size = (9 + 2·1024 + 1024²)·4KB. 8.2: קריאה של 7135 בלוקים, כתיבה של 6107. 8.3: 7 קריאות ו-4 כתיבות.", "note": "ב-8.1 בפתרון הרשמי כתוב \"1028 מצביעים בבלוק\" – שגיאת הקלדה: 4096 / 4 = 1024 (והנוסחה שם כן משתמשת ב-1024). ב-8.3, כשסופרים בלוקים שונים לפי הפירוט הרשמי (בלוק ה-inodes, DATA של התיקייה הנוכחית, DATA של d1, בלוק המצביעים של x, data bitmap, inode bitmap) מגיעים ל-6 קריאות. הפתרון הרשמי כותב 7 – כנראה הוא סופר קריאה אחת פעמיים (למשל קריאה חוזרת של ה-DATA של התיקייה הנוכחית בשלב 8). הכתיבות – 4 (בלוק ה-inodes, data bitmap, inode bitmap ו-DATA של התיקייה הנוכחית) – מתאימות.", "expl": "", "check": "חושב בסקריפט", "exam": "22BA", "examLabel": "סמסטר ב' תשפ\"ב מועד א'", "date": "13.06.2022", "id": "22BA-8"}, {"num": "1", "type": "tf", "topic": "disk", "sub": "תזמון דיסק", "q": "הוכח או הפרך: בתזמון SCAN לעומת C-SCAN, הראש הקורא-כותב עובר את אותו מרחק בסקטורים, וההבדל מתבטא רק בסדר הטיפול בבקשות/סקטורים.", "correct": false, "official": "לא נכון. דוגמה נגדית: הראש הקורא-כותב היה בסקטור 40 והגיעו בקשות ל-10 ול-20. בתזמון SCAN נטפל קודם ב-20 ואז ב-10 (מרחק כולל של 30), אך ב-C-SCAN נטפל קודם ב-10 ואז ב-20 (מרחק כולל של 40).", "expl": "SCAN (אלגוריתם המעלית) נע לכיוון אחד, ואז הופך כיוון ומטפל בבקשות גם בדרך חזרה. C-SCAN מטפל בבקשות רק בכיוון אחד: בסוף הוא קופץ חזרה להתחלה בלי לטפל בבקשות בדרך.\n\nבדוגמה הרשמית הראש ב-40 ונע כלפי מטה, והבקשות ב-10 וב-20:\nSCAN: 40 ← 20 ← 10, מרחק 30.\nC-SCAN (שמטפל רק כשהוא עולה): קודם מגיע ל-10 ואז עולה ל-20, מרחק 30 + 10 = 40.\n\nהמרחקים שונים, ולכן הטענה לא נכונה.", "check": "חושב", "exam": "22BB", "examLabel": "סמסטר ב' תשפ\"ב מועד ב'", "date": "18.07.2022", "id": "22BB-1"}, {"num": "2", "type": "tf", "topic": "threads", "sub": "Cache coherence", "q": "הוכח או הפרך: בגישה לזיכרון משותף יש הבדל בביצועים בין פעולות קריאה לפעולות כתיבה.", "correct": true, "official": "נכון. פעולות כתיבה דורשות אקסקלוסיביות ושליחת הודעת invalidate על גבי ה-bus, ולכן פוגעות יותר בביצועים לעומת קריאות שיכולות להתבצע באופן מקומי גם כאשר למעבדים אחרים יש את אותו ערך. הסבר נוסף: עבור זיכרון משותף בין תהליכים עם מנגנון copy-on-write, פעולות כתיבה יכולות לגרור שכפול של הזיכרון.", "expl": "בפרוטוקול cache coherence, כמה מעבדים יכולים להחזיק עותק של אותה שורה ולקרוא ממנה במקביל, כל אחד מה-cache שלו. כדי לכתוב, מעבד צריך עותק בלעדי: הוא שולח invalidate על ה-bus, וכל שאר המעבדים זורקים את העותק שלהם. לכן כתיבות לזיכרון משותף יקרות יותר מקריאות.\n\nובזיכרון משותף בין תהליכים עם copy-on-write, כתיבה ראשונה לדף גורמת להעתקה שלו.", "check": "לפי הפתרון הרשמי", "exam": "22BB", "examLabel": "סמסטר ב' תשפ\"ב מועד ב'", "date": "18.07.2022", "id": "22BB-2"}, {"num": "3", "type": "tf", "topic": "memory", "sub": "Swapping", "q": "הוכח או הפרך: אם כל המסגרות בזיכרון תפוסות, לא ניתן להקצות זיכרון חדש לתהליכים.", "correct": false, "official": "לא נכון. באמצעות מנגנון ההחלפה אנו לא מוגבלים לכמות המסגרות בזיכרון הפיזי ויכולים לאחסן דפים בדיסק.", "expl": "בעזרת swapping מערכת ההפעלה יכולה לפנות דף קיים ל-swap space בדיסק (לפי מדיניות ההחלפה), ולהשתמש במסגרת שהתפנתה עבור הזיכרון החדש. הדף שפונה יחזור לזיכרון ב-page fault אם ניגשו אליו שוב.", "check": "נבדק מול ההרצאה", "exam": "22BB", "examLabel": "סמסטר ב' תשפ\"ב מועד ב'", "date": "18.07.2022", "id": "22BB-3"}, {"num": "4", "type": "tf", "topic": "process", "sub": "מצבי תהליך", "q": "הוכח או הפרך: תהליך במצב Ready יכול להסתיים.", "correct": true, "official": "נכון. ע\"י קריאות חיצוניות כמו kill ניתן לעצור תהליך גם כשהוא לא במצב Running. (התקבל גם: לא נכון, כאשר מתייחסים לריצה תקינה וסיום יזום ע\"י התהליך.)", "expl": "בדיאגרמת המצבים, המעבר הרגיל ל-Terminated הוא מ-Running (התהליך קורא ל-exit). אבל תהליך אחר יכול לשלוח לתהליך שנמצא ב-Ready את הסיגנל SIGKILL – והקרנל מסיים אותו בלי שהוא ירוץ בכלל.\n\nהפתרון הרשמי קיבל גם \"לא נכון\", כשמתייחסים רק לסיום רגיל שהתהליך עצמו יוזם. הכי בטוח לענות \"נכון\" עם הדוגמה של kill.", "check": "לפי הפתרון הרשמי", "exam": "22BB", "examLabel": "סמסטר ב' תשפ\"ב מועד ב'", "date": "18.07.2022", "id": "22BB-4"}, {"num": "5", "type": "tf", "topic": "deadlock", "sub": "חופש מקיפאון", "q": "הוכח או הפרך: בשימוש במנעולים המקיימים חופש מקיפאון ניתן להגיע לקיפאון.", "correct": true, "official": "נכון. הדוגמה הקלאסית של קיפאון (2 חוטים שתופסים 2 מנעולים בסדר הפוך) יכולה להוביל לקיפאון גם אם 2 המנעולים מקיימים חופש מקיפאון.", "expl": "\"חופש מקיפאון\" הוא תכונה של מנעול בודד: אם המנעול פנוי ויש חוטים שמנסים לתפוס אותו, אחד מהם יצליח. התכונה לא מדברת על כמה מנעולים יחד.\n\nחוט A תופס את L1 ואז מנסה את L2, וחוט B תופס את L2 ואז מנסה את L1. כל מנעול לבדו תקין לגמרי – אבל שני החוטים ממתינים זה לזה לנצח.", "check": "נבדק מול ההגדרות", "exam": "22BB", "examLabel": "סמסטר ב' תשפ\"ב מועד ב'", "date": "18.07.2022", "id": "22BB-5"}, {"num": "6", "type": "open", "topic": "redir", "sub": "exec", "intro": "נתונה התוכנית הבאה. אפשר להניח שכל הקריאות ל-fork הצליחו.", "code": " 1 int main() {\n 2     int r1 = fork() || fork();\n 3     if (r1) {\n 4         char* args[3] = {\"echo\", \"r1: TRUE\", NULL};\n 5         execvp(args[0], args);\n 6         printf(\"r1: TRUE\\n\");\n 7     } else {\n 8         printf(\"r1: FALSE\\n\");\n 9     }\n10     wait(NULL);\n11\n12     int r2 = fork() && fork();\n13     if (r2) {\n14         char* args[3] = {\"echo\", \"r2: TRUE\", NULL};\n15         execvp(args[0], args);\n16     }\n17     else {\n18         printf(\"r2: FALSE\\n\");\n19     }\n20     if (r1 || r2)\n21         printf(\"END\\n\");\n22 }", "parts": [{"label": "6.1", "q": "כתבו פלט אפשרי של התוכנית, בהנחה שכל קריאות המערכת הצליחו, ולאחריו הסבר.", "answer": "r1: TRUE\nr1: TRUE\nr1: FALSE\nr2: TRUE\nr2: FALSE\nr2: FALSE\n\nבשורה 2 ה-fork הראשון יוצר בן. אצל האב הוא מחזיר ערך חיובי, ולכן || לא מחשב את ה-fork השני: r1 = 1. אצל הבן הראשון ה-fork החזיר 0, ולכן הבן מבצע את ה-fork השני ויוצר נכד: הבן מקבל r1 = 1 והנכד r1 = 0.\n\nהאב והבן מגיעים ל-execvp בשורה 5, שמריץ echo ולא חוזר – הם מדפיסים \"r1: TRUE\" ונגמרים.\n\nהנכד מדפיס \"r1: FALSE\". ב-wait אין לו ילדים, אז הוא ממשיך מיד. בשורה 12 הוא יוצר שני בנים: אצלו r2 = 1 (שני ה-fork החזירו ערך חיובי), ואצל שני הבנים r2 = 0 (הראשון בגלל הקיצור של &&, השני כי ה-fork החזיר לו 0).\n\nהנכד מריץ echo ומדפיס \"r2: TRUE\". שני הבנים מדפיסים \"r2: FALSE\". אצל שניהם r1 = 0 ו-r2 = 0, ולכן אף אחד לא מדפיס END."}, {"label": "6.2", "q": "כמה תהליכים נוצרו במהלך ריצה תקינה של התוכנית, כולל התהליך הראשי?", "answer": "5: הראשי, הבן והנכד מהשורה של ||, ועוד שני בני הנכד מהשורה של &&.\n\nעץ התהליכים:\n\n[[TREE]]", "tree": ["ראשי", "r1: TRUE", [["בן", "r1: TRUE", [["נכד", "r1: FALSE · r2: TRUE", [["בן א", "r2: FALSE", []], ["בן ב", "r2: FALSE", []]]]]]]]}, {"label": "6.3", "q": "האם ייתכנו זומבים בשלב כלשהו במהלך הריצה? אם כן – ציינו את כל תהליכי הזומבים האפשריים בכל שלב, אחרת – הסבירו מדוע לא.", "answer": "ייתכנו. כל תהליך יכול להיות זומבי, מלבד התהליך הראשי (עליו לא ידוע – ההורה שלו הוא ה-shell).\n\nאין שום מנגנון שקובע סדר בין התהליכים, ואף אחד לא מחכה לילדים שלו (ה-wait היחיד הוא של הנכד, שאין לו ילדים באותו רגע). כל תהליך בן שמסתיים לפני ההורה שלו נשאר זומבי עד שההורה מסתיים, ואז init מאמץ אותו ואוסף אותו."}, {"label": "6.4", "q": "אם הקובץ echo לא קיים במערכת, האם התשובה לסעיף 6.2 תשתנה? אם כן – מה התשובה החדשה, אחרת – הסבירו מדוע לא.", "answer": "התשובה תשתנה: 9 תהליכים.\n\nאם echo לא קיים, כל הקריאות ל-execvp נכשלות וחוזרות, והתהליכים ממשיכים לשורה הבאה. שני התהליכים שהגיעו לשורה 5 (הראשי והבן) ממשיכים עכשיו לשורה 12, וכל אחד מהם יוצר עוד 2 בנים. נוספים 4 תהליכים: 5 + 4 = 9."}], "official": "6.1: הפלט כמו כאן. 6.2: 5 תהליכים. 6.3: כל תהליך יכול להיות זומבי מלבד התהליך הראשי. 6.4: 9 תהליכים.", "expl": "הסעיפים 6.1 ו-6.2 מופיעים גם בעמוד \"הפניות וצינורות\" באתר הלמידה, עם הרצה יבשה צעד אחר צעד.", "check": "הורץ: 6 השורות בלי END ו-5 תהליכים; ובגרסה שבה echo לא קיים – 9 תהליכים בדיוק", "exam": "22BB", "examLabel": "סמסטר ב' תשפ\"ב מועד ב'", "date": "18.07.2022", "id": "22BB-6"}, {"num": "7", "type": "open", "topic": "threads", "sub": "מנעול ניתן לביטול", "intro": "מנעול ניתן לביטול (Abortable Lock) הוא מנעול שמלבד פעולת הנעילה הרגילה, יש לו פעולה נוספת שיכולה לחזור בלי לתפוס את המנעול. לדוגמה, המנעול המובנה של לינוקס הוא מנעול ניתן לביטול, עם trylock ו-timedlock.\nהפעולה הנוספת מחזירה 0 אם תפסה את המנעול, ומספר אחר אם לא. החוט בודק את ערך ההחזרה ולא נכנס לקטע הקריטי אם הנעילה נכשלה.\nלשאלה מצורפים המימושים הרגילים (בלי ביטול) של מנעול TTAS ושל ALock (Anderson Queue Lock), בלי פונקציות אתחול והריסה. N הוא מספר החוטים המקסימלי, ו-mine הוא משתנה עזר ייחודי לכל חוט (שערכו נשמר בין קריאות של אותו חוט).\nבכל סעיף יש לעדכן גם את lock אם צריך. אפשר להניח שחוט שקרא ל-trylock ונכשל לא יקרא שוב ל-trylock לפני שתפס את המנעול – הקריאה הבאה שלו (אם תהיה) היא lock. יש לשמור על כל התכונות של המימוש הקיים (מניעה הדדית, חופש מקיפאון, הוגנות). מותר להשתמש בפעולות אטומיות, אבל לא באובייקטי סנכרון אחרים.", "code": "typedef struct {\n    int state;\n} TTASLock;\nvoid lock(TTASLock *lock) {\n    while (1) {\n        while (lock->state);\n        if (!testAndSet(&lock->state, 1))\n            return;\n    }\n}\nvoid unlock(TTASLock *lock) {\n    lock->state = 0;\n}\n\ntypedef struct {\n    int next;\n    int flags[N];\n} ALock;   // Anderson queue lock\nvoid lock(ALock *lock, int *mine) {\n    *mine = fetchAndAdd(&lock->next);\n    while (!lock->flags[(*mine) % N]);\n}\nvoid unlock(ALock *lock, int *mine) {\n    lock->flags[(*mine) % N] = 0;\n    lock->flags[(*mine+1) % N] = 1;\n}", "parts": [{"label": "7.1", "q": "ממשו מנעול TTAS ניתן לביטול: init, destroy, lock, trylock, unlock.", "answer": "ב-TTAS אין תור, ולכן אפשר פשוט לנסות פעם אחת ולוותר. הוספת trylock לא משנה אף פעולה אחרת:\n\nint trylock(TTASLock *lock) {\n    if ((lock->state) || (testAndSet(&lock->state, 1)))\n        return 1;   // failed\n    else\n        return 0;   // acquired\n}\n\nבודקים קודם בקריאה רגילה (כמו ב-TTAS – כדי לא לשלוח TAS מיותר על ה-bus), ורק אם נראה פנוי מנסים TAS אחד."}, {"label": "7.2", "q": "ממשו מנעול אנדרסון (ALock) ניתן לביטול: init, destroy, lock, trylock, unlock.", "answer": "ב-ALock אי אפשר פשוט לחזור מ-trylock: לכל חוט יש מקום בתור, והוא אחראי להעביר את התור הלאה כשהוא יוצא. אם נעביר מוקדם מדי – תיפגע המניעה ההדדית; אם לא נעביר בכלל – החוט הבא יחכה לנצח.\n\nהפתרון: חוט שנכשל משאיר בתא שלו סימון מיוחד – 1 – שאומר לחוט שלפניו \"דלג עליי והעבר את התור הלאה\". עדכון התא נעשה עם TAS כדי שיהיה אטומי. המערך גדל ל-2N, כי חוט שנכשל ב-trylock משאיר תא \"נטוש\" ואז תופס תא נוסף ב-lock.\n\ntypedef struct {\n    int next;\n    int flags[2*N];\n} ALock;\n\nvoid init(ALock *lock) {\n    for (int i = 1; i < 2*N; ++i)\n        lock->flags[i] = 0;\n    lock->flags[0] = 1;\n    lock->next = 0;\n}\nvoid lock(ALock *lock, int *mine) {\n    *mine = fetchAndAdd(&lock->next);\n    while (!lock->flags[(*mine) % (2*N)]);\n}\nint trylock(ALock *lock, int *mine) {\n    *mine = fetchAndAdd(&lock->next);\n    return !testAndSet(&lock->flags[(*mine) % (2*N)], 1);\n}\nvoid unlock(ALock *lock, int *mine) {\n    lock->flags[(*mine) % (2*N)] = 0;\n    int i = 1;\n    while (testAndSet(&lock->flags[(*mine + i) % (2*N)], 1)) {\n        lock->flags[(*mine + i) % (2*N)] = 0;   // abandoned slot: skip it\n        ++i;\n    }\n}\n\nב-trylock: אם התא כבר 1 – התור הגיע אלינו, TAS מחזיר 1 ו-trylock מחזיר 0 (הצלחה). אם התא 0 – התור עוד לא הגיע; TAS כותב 1 (סימון \"נטוש\") ו-trylock מחזיר 1 (כישלון).\n\nב-unlock: מנסים להעביר את התור לתא הבא עם TAS. אם הוא החזיר 0 – העברנו. אם החזיר 1 – התא נטוש על ידי trylock שנכשל, אז מאפסים אותו וממשיכים לתא שאחריו."}], "official": "כמו בפתרון כאן.", "note": "בקוד הרשמי של 7.2 כתוב void trylock (צריך int), next = 0 במקום lock->next = 0, ו-lock עם N במקום 2N לא עודכן במפורש. הקוד כאן מתוקן.", "expl": "הקוד המתוקן של 7.2 נבדק בהרצה עם חוטים אמיתיים: 80,000 כניסות לקטע הקריטי, כמחציתן אחרי trylock שנכשל (כלומר עם הרבה תאים נטושים) – 0 הפרות של מניעה הדדית, והריצה הסתיימה בלי להיתקע. (בהרצה עם יותר חוטים ממעבדים צריך להוסיף sched_yield בהמתנה כדי שהבדיקה תסתיים בזמן סביר – זו תכונה ידועה של מנעולי תור.)", "check": "הורץ עם חוטים אמיתיים", "exam": "22BB", "examLabel": "סמסטר ב' תשפ\"ב מועד ב'", "date": "18.07.2022", "id": "22BB-7"}, {"num": "8", "type": "open", "topic": "fs", "sub": "חורים בקבצים ודיסקים", "parts": [{"label": "8.1", "q": "קריאת המערכת lseek מאפשרת למקם את סמן המיקום גם מעבר לסוף הקובץ, וכך ליצור \"חור\" בנתוני הקובץ. קריאה מתוך החור מחזירה בתים שכולם אפס. יש שתי אפשרויות למימוש: הראשונה – ב-lseek מקצים את כל הבלוקים החסרים ומאפסים אותם כחלק מקריאת המערכת. השנייה – לא מקצים מראש, אלא רק כשמתבצעת פעולה (קריאה או כתיבה) במיקום שהוא חלק מהחור. תארו את היתרונות והחסרונות של כל אפשרות.", "answer": "הקצאה מראש:\nחסרון – lseek עצמו איטי (צריך להקצות ולכתוב אפסים לכל הבלוקים), והחור תופס מקום בדיסק גם אם אף אחד לא ישתמש בו.\nיתרון – פעולות עתידיות על הקובץ מהירות בכל מיקום, ולא צריך לשמור שום מידע נוסף.\n\nבלי הקצאה מראש:\nיתרון – lseek מהיר, והחור לא תופס מקום בדיסק.\nחסרון – פעולות עתידיות עלולות להיות איטיות (הקצאה ברגע הגישה), וצריך לשמור ב-inode מידע נוסף על מיקום החורים – למשל מצביע \"ריק\" שאומר \"הבלוק הזה הוא אפסים\"."}, {"label": "8.2", "q": "נתונה מערכת שצריכה לייצר קבצים בגודל משתנה שאינו ידוע מראש, שכל התוכן שלהם הוא אפסים. הגודל המקסימלי של קובץ הוא 100MB, והממוצע 10MB.\nסטודנט א' הציע להתעלם מהגודל הנדרש ותמיד לייצר קבצים של 100MB. סטודנט ב' הציע ליצור קובץ ריק ולכתוב אליו 1MB שוב ושוב, עד שהגודל מגיע לגודל הנדרש או עובר אותו.\nמלאו טבלה עם נתונים (RPM, SEEK TIME, TRANSFER RATE) של שני דיסקים, כך שהפתרון של סטודנט א' יהיה מהיר יותר עם הדיסק הראשון, והפתרון של סטודנט ב' יהיה מהיר יותר עם הדיסק השני. התעלמו מפעולות אחרות במערכת הקבצים (גישה ל-inode, חיפוש ב-bitmap וכו'). כל הקצאה מוצאת בלוקים רציפים, אבל הקצאות נפרדות לא בהכרח רציפות.", "answer": "הרעיון: סטודנט א' כותב הרבה נתונים (100MB) – אבל ברצף אחד, אז הוא נהנה מדיסק עם קצב העברה גבוה גם אם זמן המיקום ארוך. סטודנט ב' כותב מעט נתונים (10MB בממוצע) – אבל ב-10 כתיבות נפרדות, כמו פעולות אקראיות, אז הוא נהנה מדיסק עם זמן מיקום קצר גם אם הקצב נמוך.\n\nדוגמה (מהפתרון הרשמי):\nדיסק ראשון: RPM 30 (סיבוב של 2 שניות, כלומר המתנה של שנייה), seek של שנייה, 100 MB/s\nדיסק שני: RPM 30,000 (סיבוב של 2ms, כלומר המתנה של 1ms), seek של 1ms, 10 MB/s\n\nסטודנט א' (קובץ של 100MB):\nדיסק ראשון: 1 + 1 + 1 = 3 שניות\nדיסק שני: 0.001 + 0.001 + 10 = יותר מ-10 שניות\nמהיר יותר בדיסק הראשון.\n\nסטודנט ב' (10 כתיבות של 1MB):\nדיסק ראשון: כל כתיבה 1 + 1 + 0.01 = 2.01 שניות, כלומר 20.1 שניות\nדיסק שני: כל כתיבה 0.001 + 0.001 + 0.1 = 0.102 שניות, כלומר 1.02 שניות\nמהיר יותר בדיסק השני."}], "official": "8.1 ו-8.2 – כמו כאן, כולל טבלת הדוגמה.", "expl": "", "check": "חושב", "exam": "22BB", "examLabel": "סמסטר ב' תשפ\"ב מועד ב'", "date": "18.07.2022", "id": "22BB-8"}, {"num": "1", "type": "open", "topic": "memory", "sub": "תרגום כתובות", "q": "נתונה מערכת עם מנגנון חדש של זיכרון וירטואלי, המבוסס על דפדוף והחלפה, אבל מספק לתהליכים זיכרון וירטואלי לא מוגבל: לכל תהליך יש מספר אינסופי של דפים, והוא יכול לפנות לכל כתובת (כל מספר טבעי). הזיכרון הפיזי עדיין סופי, אבל אפשר להניח שיש נפח לא מוגבל של זיכרון משני (דיסק).\nתארו בכלליות מימוש של תהליך התרגום, שמקבל מספר דף ומחזיר מספר מסגרת, ופרטו את כל השינויים הנדרשים: בקוד ובמבני הנתונים של מערכת ההפעלה, ברכיבי החומרה וכו' (טבלת הדפים, page fault, שימוש ב-TLB).\nשימו לב: גודל הקלט לא מוגבל, ואפשר להניח שהוא רצף ביטים (מערך ביטים וגודלו). מותר לשנות את אופן הפעולה של רכיבי החומרה אבל לא את המבנה הבסיסי שלהם (למשל מותר לשנות את גודל הרשומה או את אופן החיפוש ב-TLB, אבל לא את כמות הזיכרון שבו, ולא להגדיר רכיב חדש לגמרי).", "answer": "הבעיה: מספר הדף לא חסום, ולכן אי אפשר להחזיק טבלת דפים כמערך שהאינדקס שלו הוא מספר הדף – לא ליניארית ולא היררכית עם מספר רמות קבוע.\n\nהתובנה: הזיכרון הפיזי סופי, ולכן בכל רגע רק מספר סופי של דפים נמצא בזיכרון. מספיק טבלה שהגודל שלה תלוי במספר המסגרות, לא במספר הדפים.\n\nטבלת דפים הפוכה (inverted page table):\nרשומה אחת לכל מסגרת פיזית, עם: מזהה תהליך, מספר הדף המלא (מערך ביטים ואורכו, או מצביע אליו), וביטי סטטוס (valid, dirty, reference). כדי לא לסרוק את כל הטבלה, מוסיפים טבלת גיבוב: hash(pid, מספר דף) ← רשימת מסגרות מועמדות. על כל מועמד משווים את מספר הדף המלא.\n\nדפים שלא בזיכרון:\nמערכת ההפעלה שומרת לכל תהליך מבנה נתונים דינמי בדיסק (טבלת גיבוב או עץ חיפוש) ממספר דף למיקום ב-swap. דף שלא נמצא שם מעולם לא נגעו בו.\n\nאלגוריתם התרגום:\n1. מחשבים hash של מספר הדף ומחפשים ב-TLB.\n2. אם יש פגיעה (וההשוואה המלאה מצליחה) – מחזירים את המסגרת.\n3. אחרת מחפשים בטבלה ההפוכה דרך טבלת הגיבוב. אם נמצא – מעדכנים את ה-TLB ומחזירים את המסגרת.\n4. אחרת – page fault. מערכת ההפעלה מחפשת את הדף במבנה של ה-swap: אם הוא שם – בוחרת מסגרת (פנויה, או מפנה דף לפי מדיניות ההחלפה ושומרת אותו ב-swap אם הוא dirty), טוענת אליה את הדף ומעדכנת את הטבלה ההפוכה. אם הדף לא קיים בכלל – מקצה מסגרת מאופסת (הקצאה עצלה). חוזרים על הפקודה.\n\nשינויים בחומרה:\nה-MMU צריך לחשב hash של מספר דף באורך משתנה, ולבצע חיפוש בטבלת הגיבוב ובטבלה ההפוכה (או להעביר את זה למערכת ההפעלה כ-TLB miss שמטופל בתוכנה).\nבכל רשומת TLB שומרים במקום מספר הדף את ה-hash שלו (גודל קבוע) ואת מספר המסגרת. בגלל התנגשויות אפשריות, אחרי פגיעה ב-TLB משווים את מספר הדף המלא מול הרשומה של המסגרת בטבלה ההפוכה.\n\nהכתובת עצמה:\nההיסט (offset) הוא מספר קבוע של ביטים בסוף רצף הביטים, וכל השאר הוא מספר הדף – גם הוא באורך משתנה.", "note": "למבחן הזה אין הצעת פתרון רשמית. הפתרון כאן נכתב ונבדק בנפרד.", "expl": "זו שאלת תכנון פתוחה, ויש כמה פתרונות סבירים. מה שחשוב לציין: מבנה שהגודל שלו תלוי בזיכרון הפיזי (טבלה הפוכה עם גיבוב) ולא במרחב הווירטואלי; מבנה דינמי למיקום הדפים בדיסק; ואיך ה-TLB עובד עם מפתח שאינו באורך קבוע.\n\nפתרון חלופי סביר: עץ טבלאות היררכי שהעומק שלו גדל עם אורך מספר הדף (כמו טבלה רב-רמתית, אבל בלי מספר רמות קבוע).", "check": "פתרון תכנון – נבדק מול חומר ההרצאות", "exam": "22BC", "examLabel": "סמסטר ב' תשפ\"ב מועד ג'", "date": "18.08.2022", "id": "22BC-1"}, {"num": "2", "type": "open", "topic": "redir", "sub": "מימוש shell", "q": "באופן כללי, כל shell מריץ לולאה בסגנון הבא (פסאודו-קוד).\nבשאלה זו יש לממש את execute_cmd עם תמיכה בהרצה ברקע (&) ובהפניה (redirection) של הקלט והפלט הסטנדרטיים (< ו->). אין תמיכה בהפניה של stderr.\n\nהארגומנטים:\nprog_name – שם התוכנית להרצה.\nprog_args – מערך הארגומנטים לתוכנית. תא 0 מכיל את שם התוכנית, התא האחרון מכיל NULL, ואין במערך סימני הפניה או הרצה ברקע.\nin_file / out_file – שמות הקבצים להפניה, או NULL אם אין הפניה. ייתכן שיסופק אחד מהם, שניהם, או אף אחד.\nrun_bg – בוליאני שמציין האם להריץ ברקע. מותר להתעלם מזומבים.", "code": "while (1) {                 // SHELL main loop\n    printf(\"==> \");         // shell prompt\n    parse_cmd(...);         // read & parse input\n    execute_cmd(...);       // fork & exec\n}\n\nvoid execute_cmd(char* prog_name, char** prog_args,\n                 char* in_file, char* out_file, int run_bg) {\n    // ???\n}", "answer": "void execute_cmd(char* prog_name, char** prog_args,\n                 char* in_file, char* out_file, int run_bg) {\n    pid_t pid = fork();\n    if (pid < 0) { perror(\"fork\"); return; }\n    if (pid == 0) {                       // child\n        if (in_file) {\n            int fd = open(in_file, O_RDONLY);\n            if (fd < 0) { perror(\"open\"); _exit(1); }\n            dup2(fd, 0);\n            close(fd);\n        }\n        if (out_file) {\n            int fd = open(out_file, O_WRONLY | O_CREAT | O_TRUNC, 0644);\n            if (fd < 0) { perror(\"open\"); _exit(1); }\n            dup2(fd, 1);\n            close(fd);\n        }\n        execvp(prog_name, prog_args);\n        perror(\"execvp\");                 // only if exec failed\n        _exit(1);\n    }\n    if (!run_bg)                          // parent\n        waitpid(pid, NULL, 0);\n}\n\nההפניה נעשית רק בבן, אחרי fork ולפני exec – כך ה-shell עצמו ממשיך לקרוא מהמקלדת ולכתוב למסך, והתוכנית החדשה יורשת את טבלת ה-FD המעודכנת.\n\nבהרצה ברקע האב לא מחכה וחוזר מיד ללולאה. בהרצה רגילה הוא מחכה לבן הספציפי עם waitpid (ולא wait, שעלול לאסוף בן אחר שרץ ברקע).\n\nאם exec נכשל, הבן חייב לצאת – אחרת יהיו שני shell-ים שקוראים מאותה מקלדת.", "note": "למבחן הזה אין הצעת פתרון רשמית. הפתרון כאן נכתב ונבדק בנפרד.", "expl": "למה _exit ולא exit בבן? ה-prompt מודפס בלי ירידת שורה, ולכן הוא עדיין יושב ב-buffer של stdio כשמבצעים fork. אם exec נכשל והבן קורא ל-exit, ה-buffer מתרוקן עוד פעם והטקסט מודפס פעמיים. (גם exit(1) מתקבל בדרך כלל במבחן.)", "check": "הורץ: הפניה של קלט, של פלט ושל שניהם, הרצה ברקע, ותוכנית שלא קיימת", "exam": "22BC", "examLabel": "סמסטר ב' תשפ\"ב מועד ג'", "date": "18.08.2022", "id": "22BC-2"}, {"num": "3", "type": "open", "topic": "threads", "sub": "מימוש מנעול", "q": "מנעול N הוא מנעול שמאפשר ל-N חוטים להיכנס לקטע הקריטי בו-זמנית. הוא צריך לקיים:\nמניעה הדדית – לכל היותר N חוטים בקטע הקריטי בו-זמנית.\nחופש מקיפאון – אם חוטים מנסים לתפוס את המנעול ויש פחות מ-N חוטים בקטע הקריטי, חוט כלשהו יצליח להיכנס בזמן סופי.\nהוגנות – כמו ההגדרה שנלמדה בכיתה.\nקל לממש מנעול N עם סמפור שמאותחל ל-N. בשאלה זו יש לממש אותו בלי פעולות אטומיות ובלי אובייקטי סנכרון, מלבד 2 הפעולות האטומיות int fetchAndAdd(int *ptr) ו-int fetchAndSub(int *ptr).\nממשו את NLock ואת init, destroy, lock, unlock.", "answer": "הרעיון: הכללה של מנעול כרטיסים (ticket lock). כל חוט לוקח כרטיס, ונכנס כשהכרטיס שלו בין N הכרטיסים הבאים בתור.\n\ntypedef struct {\n    int next;     // next ticket to hand out\n    int served;   // how many threads have left the CS\n    int n;\n} NLock;\n\nvoid init(NLock *lock, int n) {\n    lock->next = 0;\n    lock->served = 0;\n    lock->n = n;\n}\nvoid destroy(NLock *lock) { }\n\nvoid lock(NLock *lock) {\n    int my = fetchAndAdd(&lock->next);\n    while (my >= lock->served + lock->n);\n}\nvoid unlock(NLock *lock) {\n    fetchAndAdd(&lock->served);\n}\n\nמניעה הדדית:\nאם served = s, כל חוט שנכנס קיבל כרטיס קטן מ-s + N. הכרטיסים שונים זה מזה, ולכן נכנסו לכל היותר s + N חוטים, ומתוכם s כבר יצאו. נשארים לכל היותר N בפנים.\n\nחופש מקיפאון:\nאם יש פחות מ-N בפנים, הכרטיס הקטן ביותר שמחכה קטן מ-served + N, והחוט שלו ייכנס.\n\nהוגנות:\nהחוטים נכנסים בסדר הכרטיסים (FIFO), כמו במנעול כרטיסים רגיל. אף חוט לא יכול לעקוף חוט שלקח כרטיס לפניו.", "note": "למבחן הזה אין הצעת פתרון רשמית. הפתרון כאן נכתב ונבדק בנפרד. (fetchAndSub לא נחוץ בפתרון הזה.)", "expl": "אפשר גם לחשוב על זה כך: מנעול כרטיסים רגיל הוא המקרה N = 1 – החוט נכנס כש-my == served, כלומר my < served + 1.\n\nפתרון שגוי נפוץ: מונה אחד שעושים עליו fetchAndAdd, ואם עברנו את N – fetchAndSub ומנסים שוב. זה שומר על מניעה הדדית, אבל לא על הוגנות – חוט יכול להפסיד שוב ושוב.", "check": "הורץ עם חוטים אמיתיים: 8 חוטים, N = 3, ‏160,000 כניסות – לכל היותר 3 בפנים, 0 הפרות", "exam": "22BC", "examLabel": "סמסטר ב' תשפ\"ב מועד ג'", "date": "18.08.2022", "id": "22BC-3"}, {"num": "1", "type": "tf", "topic": "sync", "sub": "משתני תנאי וסמפורים", "q": "הוכח או הפרך: כל שימוש במשתנה תנאי (condition variable) אפשר להחליף בשימוש בסמפור.", "correct": false, "official": "לא נכון. כפי שנלמד, לא ניתן לממש משתנה תנאי באמצעות סמפור.", "expl": "ההבדל המהותי: לסמפור יש זיכרון (ערך), ולמשתנה תנאי אין. signal על משתנה תנאי כשאף אחד לא ממתין פשוט הולך לאיבוד, בעוד post על סמפור נשמר ומעיר את מי שיגיע אחר כך.\n\nבנוסף, wait על משתנה תנאי משחרר את המנעול ונכנס להמתנה באופן אטומי, ו-broadcast מעיר את כל הממתינים – לסמפור אין פעולה כזו (צריך לדעת כמה ממתינים יש).\n\nבקורס נלמד שלא ניתן לממש משתנה תנאי בעזרת סמפור בצורה פשוטה וישירה.", "check": "לפי הפתרון הרשמי וההרצאה", "exam": "23AA", "examLabel": "סמסטר א' תשפ\"ג מועד א'", "date": "30.01.2023", "id": "23AA-1"}, {"num": "2", "type": "tf", "topic": "threads", "sub": "Cache coherence", "q": "הוכח או הפרך: בגישה לזיכרון משותף במעבדים עם write-through cache, אין הבדל בביצועים בין פעולות קריאה לפעולות כתיבה.", "correct": false, "official": "לא נכון. בכתיבה תמיד נשלח עדכון על גבי ה-bus, אך בקריאה ייתכן שהפעולה תתבצע מקומית ב-cache של המעבד.", "expl": "ב-write-through כל כתיבה עוברת מיד לזיכרון הראשי דרך ה-bus (ובפרוטוקול snooping גם מעדכנת או מבטלת את העותקים אצל שאר המעבדים). קריאה של ערך שכבר נמצא ב-cache לא צריכה את ה-bus בכלל. לכן כתיבות יקרות יותר.", "check": "לפי הפתרון הרשמי", "exam": "23AA", "examLabel": "סמסטר א' תשפ\"ג מועד א'", "date": "30.01.2023", "id": "23AA-2"}, {"num": "3", "type": "tf", "topic": "memory", "sub": "Swapping", "q": "הוכח או הפרך: אם הזיכרון המשני מלא לחלוטין, ייתכן שעדיין נוכל לטפל במקרה של page fault.", "correct": true, "official": "נכון. אם יש מסגרת פנויה לא נדרש page out (ומקום בדיסק), וגם אם יש מסגרת לפינוי שכבר קיימת בדיסק (dirty=0).", "expl": "טיפול ב-page fault דורש מקום בדיסק רק אם צריך לכתוב לשם דף שמפנים. זה לא קורה ב-2 מקרים:\n\n1. יש מסגרת פנויה בזיכרון – טוענים אליה את הדף ולא מפנים שום דבר.\n2. הדף שנבחר לפינוי הוא נקי (dirty = 0) ויש לו כבר עותק עדכני בדיסק – פשוט זורקים אותו מהזיכרון בלי לכתוב.", "check": "לפי הפתרון הרשמי", "exam": "23AA", "examLabel": "סמסטר א' תשפ\"ג מועד א'", "date": "30.01.2023", "id": "23AA-3"}, {"num": "4", "type": "tf", "topic": "signals", "sub": "זומבים ו-SIGCHLD", "q": "הוכח או הפרך: תהליך שהסתיים נמחק מעץ התהליכים רק כאשר תהליך האב שלו (לפי העץ) מבצע קריאה ל-wait.", "correct": false, "official": "לא נכון. אם תהליך האב מתעלם מסיגנל SIGCHLD, תהליך הבן נמחק מיד כשהוא מסתיים, בלי wait. (הסבר שגוי: \"אם תהליך האב מסתיים, הבן נמחק\" – זה קורה בגלל wait של init, שהוא האב החדש.)", "expl": "אם האב מגדיר במפורש signal(SIGCHLD, SIG_IGN), הקרנל לא משאיר את הבנים שלו כזומבים: הם נמחקים מיד כשהם מסתיימים, ואף אחד לא צריך לקרוא ל-wait.\n\nשימו לב להסבר השגוי: כשהאב מת, הבן היתום מאומץ על ידי init, ו-init הוא שקורא ל-wait. כלומר שם עדיין יש wait של האב (החדש) – זה לא מפריך את הטענה.", "check": "לפי הפתרון הרשמי ו-man 2 wait", "exam": "23AA", "examLabel": "סמסטר א' תשפ\"ג מועד א'", "date": "30.01.2023", "id": "23AA-4"}, {"num": "5", "type": "tf", "topic": "disk", "sub": "SSD", "q": "הוכח או הפרך: בכונן SSD, פעולות כתיבה מהירות יותר מפעולות קריאה.", "correct": false, "official": "לא נכון. כתיבה אקראית מהירה יותר מקריאה אקראית בגלל מבנה הלוג שהופך כתיבות אקראיות לסדרתיות, אך כתיבה סדרתית עדיין איטית יותר מקריאה סדרתית.", "expl": "ב-SSD עם FTL מבוסס לוג, כתיבות אקראיות הופכות לכתיבות סדרתיות לבלוק הפתוח, ולכן כתיבה אקראית יכולה להיות מהירה מקריאה אקראית. אבל כתיבה של דף בפלאש איטית יותר מקריאה שלו, ולכן בגישה סדרתית הקריאה מהירה יותר. כיוון שהטענה כללית (\"פעולות כתיבה מהירות יותר\"), היא לא נכונה.", "note": "בטקסט של הפתרון הרשמי כתוב \"כתיבה אקראית מהירה יותר מקריאה סדרתית\" – כנראה הכוונה לקריאה אקראית (כמו בטבלת הביצועים בהרצאה).", "check": "לפי הפתרון הרשמי וטבלת הביצועים מההרצאה", "exam": "23AA", "examLabel": "סמסטר א' תשפ\"ג מועד א'", "date": "30.01.2023", "id": "23AA-5"}, {"num": "6", "type": "open", "topic": "sched", "sub": "הרעבה ואפקט השיירה", "intro": "בתזמון תהליכים, הרעבה מוגדרת כמצב שבו ייתכן שתהליך מסוים לעולם לא יסתיים. אפקט השיירה מוגדר כמצב שבו ייתכן שתהליכים קצרים יתעכבו זמן רב בגלל תהליך ארוך שתופס את המעבד.\nבתזמון Stride אפשר להניח שתהליך חדש מקבל ערך pass שהוא המינימלי מבין כל התהליכים במערכת.", "parts": [{"label": "6.1", "q": "עבור כל אחד מאלגוריתמי התזמון FCFS, SJF, SRTF, RR, MLFQ, Lottery, Stride – האם מתאפשרת הרעבה? תנו דוגמה קצרה היכן שכן, או הוכחה היכן שלא.", "answer": "", "atable": {"headers": ["אלגוריתם", "הרעבה?", "דוגמה או הוכחה"], "rows": [["FCFS", "לא", "התהליכים מטופלים לפי הסדר, ולכן בהכרח יגיע תורו של כל תהליך. (תהליך בלולאה אינסופית לא נחשב – אין דבר כזה ב-FCFS.)"], ["SJF", "כן", "תהליך ארוך יתעכב אחרי תהליכים קצרים שעלולים להגיע כל הזמן."], ["SRTF", "כן", "כמו SJF."], ["RR", "לא", "תמיד יגיע תורו של כל תהליך לרוץ, לפי סדר התור."], ["MLFQ", "לא", "בזכות ה-priority boost, כל תהליך יקבל זמן ריצה בסופו של דבר."], ["Lottery", "כן", "ייתכן שתהליך מסוים לא יוגרל שוב ושוב."], ["Stride", "כן", "אם תהליכים חדשים מגיעים כל הזמן, ה-pass שלהם קטן מכל הקיימים."]]}}, {"label": "6.2", "q": "עבור כל אחד מאותם אלגוריתמים – האם ייתכן אפקט השיירה? תנו דוגמה קצרה היכן שכן, או הוכחה היכן שלא.", "answer": "", "atable": {"headers": ["אלגוריתם", "שיירה?", "דוגמה או הוכחה"], "rows": [["FCFS", "כן", "תהליך ארוך שמגיע ראשון גורם לתהליכים הקצרים להתעכב אחריו."], ["SJF", "כן", "אם תהליכים קצרים מגיעים רגע אחרי תהליך ארוך, הם מתעכבים אחריו (אין הפקעה)."], ["SRTF", "לא", "תהליכים קצרים תמיד יטופלו לפני ארוכים."], ["RR", "לא", "כל תהליך מקבל קוונטום קבוע לפי סדר התור, בלי קשר לזמן הריצה שלו."], ["MLFQ", "לא", "כמו RR, ובנוסף תהליך ארוך יורד בעדיפות ומקבל פחות זמן מעבד."], ["Lottery", "כן", "תהליך ארוך עם הרבה כרטיסים עלול להשתלט על המעבד, כי אחרים לא יוגרלו."], ["Stride", "כן", "תהליך ארוך עם stride נמוך ישתלט על המעבד לזמן רב, ואחרים יתעכבו אחריו."]]}}, {"label": "6.3", "q": "סטודנט כתב תוכנית שבה כתיבות לקבצים נאגרות בחוצץ (buffer) בזיכרון, ונכתבות בבת אחת ובאופן רציף כשהסגמנט מתמלא. בהתחלה הביצועים השתפרו ככל שגודל הסגמנט גדל, אבל מגודל מסוים ביצועי התוכנית הידרדרו משמעותית (למרות שביצועי הכתיבה לדיסק המשיכו להשתפר). מה הסיבה?", "answer": "החוצץ גדל מעבר לגודל הזיכרון שעומד לרשות התוכנית (ה-cache או המסגרות הפיזיות). מעבר לסף הזה, בגלל השימוש ב-LRU (או קירוב שלו), הגישה הסדרתית לחוצץ גורמת לפינוי דווקא של הדפים שנצטרך בקרוב, וכמעט כל גישה הופכת להחטאה – בדיוק כמו בדוגמה של loop.c מהשיעור."}, {"label": "6.4", "q": "הציעו דרך לטפל בבעיה מהסעיף הקודם.", "answer": "להגביל את הגודל המקסימלי של הסגמנט כך שיתאים לגודל ה-cache (הזיכרון הזמין), או להחליף את מדיניות הפינוי לאלגוריתם שאין לו את הבעיה הזו של LRU בגישה סדרתית מחזורית (למשל אקראי, או MRU)."}], "official": "כמו בטבלאות ובתשובות כאן.", "expl": "הסבר ל-6.3: LRU בלולאה סדרתית על N דפים, כשיש רק פחות מ-N מסגרות, מחטיא בכל גישה – הדף שפונה הוא תמיד זה שיידרש הכי מוקדם. זה הגרף של loop workload מההרצאה.", "check": "לפי הפתרון הרשמי וההגדרות שבשאלה", "exam": "23AA", "examLabel": "סמסטר א' תשפ\"ג מועד א'", "date": "30.01.2023", "id": "23AA-6"}, {"num": "7", "type": "open", "topic": "deadlock", "sub": "סמפורים וקיפאון", "intro": "נתונה מערכת שמנהלת N \"מחסנים\" שונים, ובכל אחד פעולות של יצרן-צרכן. לשם כך הוגדר מערך של N מכל סמפור בפתרון שנלמד בשיעור.\nהפרמטר t הוא אינדקס המחסן. add_item / remove_item מוסיפות ומסירות מוצר ממחסן t, אבל הן לא בטוחות לשימוש במקביל.\nנדרשה פעולה חדשה, consume_several, שצורכת מוצרים מכמה מחסנים בו-זמנית (באופן אטומי, ולא יותר ממוצר אחד מכל מחסן). היא מקבלת מערך בוליאני items[N], והתא i מציין האם לצרוך ממחסן i.\nסטודנט טען שבפעולה הזו תפיסת המשאבים נעשית תמיד בסדר קבוע, ולכן מופר תנאי הקיפאון של המתנה מעגלית. למרות טענתו, אפשר להגיע לקיפאון.", "code": "sem_t empty[N];   // init all to MAX\nsem_t full[N];    // init all to 0\nsem_t mutex[N];   // init all to 1\n\nvoid produce(int t) {             void consume(int t) {\n    sem_wait(&empty[t]);              sem_wait(&full[t]);\n    sem_wait(&mutex[t]);              sem_wait(&mutex[t]);\n    add_item(t);                      remove_item(t);\n    sem_post(&mutex[t]);              sem_post(&mutex[t]);\n    sem_post(&full[t]);               sem_post(&empty[t]);\n}                                 }\n\n 1 void consume_several(int items[N]) {\n 2     for (int i = 0; i < N; ++i) {\n 3         if (items[i]) {\n 4             sem_wait(&full[i]);\n 5         }\n 6     }\n 7     for (int i = 0; i < N; ++i) {\n 8         if (items[i]) {\n 9             sem_wait(&mutex[i]);\n10             remove_item(i);\n11             sem_post(&mutex[i]);\n12             sem_post(&empty[i]);\n13         }\n14     }\n15 }", "parts": [{"label": "7.1", "q": "תארו ריצה שמובילה לקיפאון.", "answer": "נניח MAX = 1 ושהמחסנים ריקים.\n\nחוט 1 מייצר מוצר למחסן 0 (full[0] = 1, כל השאר 0).\nחוט 2 מפעיל consume_several כדי לצרוך ממחסנים 0 ו-1. הוא מוריד את full[0] ל-0, ונחסם על full[1].\nחוט 3 מפעיל consume(0) – נחסם, כי full[0] = 0.\nחוט 4 מפעיל produce(0) – נחסם, כי empty[0] = 0 (המחסן מלא). אחר כך הוא היה אמור לייצר גם למחסן 1.\n\nעכשיו אף חוט לא יכול להתקדם: חוט 4 מחכה שמישהו יוציא את המוצר ממחסן 0, חוט 2 \"הזמין\" את המוצר אבל לא יוציא אותו עד שיהיה מוצר במחסן 1, והמוצר למחסן 1 יגיע רק מחוט 4.\n\nמחסן 0 נמצא במצב בלתי אפשרי: הוא \"ריק\" מבחינת הצרכנים וגם \"מלא\" מבחינת היצרנים."}, {"label": "7.2", "q": "האם טענת הסטודנט נכונה? אם כן – הסבירו איך ייתכן קיפאון למרות שהופר תנאי ההמתנה המעגלית. אחרת – הסבירו מדוע הטענה שגויה. (רמז: איזו הנחה נסתרת לגבי המשאבים הנחנו כשלמדנו את 4 תנאי הקיפאון, ושלא מתקיימת כאן?)", "answer": "הסטודנט צודק – אין כאן המתנה מעגלית במובן של תפיסת מנעולים בסדר קבוע.\n\nההנחה הנסתרת: 4 תנאי הקיפאון מדברים על משאבים שמתנהגים כמו מנעול – חוט מקצה אותם בתחילת הפעולה ומשחרר אותם בסוף.\n\nביצרן-צרכן זה הפוך: אין \"הקצאה ושחרור\" של משאב קיים. חוט צריך קודם \"לשחרר\" את המשאב (לייצר מוצר), ורק אז חוט אחר יכול \"לתפוס\" אותו (לצרוך). ההמתנה כאן היא למשאב שעוד לא נוצר, ולכן הסדר הקבוע לא מונע קיפאון."}, {"label": "7.3", "q": "הקריאה sem_trywait דומה ל-trylock עבור סמפורים: אם ערך הסמפור גדול מ-0 היא מורידה אותו ב-1 באופן אטומי ומחזירה 0, אחרת היא חוזרת מיד בלי לשנות את הסמפור ומחזירה 1-.\nתקנו את consume_several כך שתעבוד בלי קיפאון ובלי livelock. מותר לשנות רק את שורות 2–6. מותר להוסיף משתנים גלובליים (עם ערכי האתחול בהערה) ולהיעזר ב-sem_trywait, באובייקטי סנכרון ובפעולות אטומיות. תארו בקצרה את הפתרון וכתבו קוד ברור.", "answer": "הרעיון – כמו בפתרון לתנאי no preemption: בהקצאת המוצרים משתמשים ב-sem_trywait במקום sem_wait. אם הגענו למחסן שאין בו מוצר (trywait נכשל), מחזירים את כל ההקצאות הקודמות (sem_post לכל המחסנים הקודמים) ומתחילים מחדש. כך חוט אף פעם לא מחזיק משאב בזמן שהוא חסום – ואין קיפאון.\n\nכדי למנוע livelock, תופסים מנעול גלובלי הוגן master בתחילת כל ניסיון ומשחררים בסוף הניסיון (בהצלחה או בכישלון). בגלל ההוגנות, כל חוט יקבל בתורו הזדמנות לנסות לבד.\n\nsem_t master;   // init to 1 (assumed fair)\n\nvoid consume_several(int items[N]) {\n    sem_wait(&master);\n    int i = 0;\n    while (i != N) {\n        if ((!items[i]) || (!sem_trywait(&full[i]))) {\n            ++i;\n        } else {\n            // failed - give back everything and restart\n            for (int k = 0; k < i; ++k)\n                if (items[k])\n                    sem_post(&full[k]);\n            i = 0;\n            sem_post(&master);   // let other threads try\n            sem_wait(&master);\n        }\n    }\n    sem_post(&master);\n    for (int i = 0; i < N; ++i) {\n        ... // lines 7-14 unchanged\n    }\n}\n\nשימו לב: הפתרון לא מונע הרעבה – ייתכן שבכל פעם שמגיע תורו של החוט חסר לו מוצר אחר. פתרון נוסף ל-livelock הוא המתנה אקראית לפני ניסיון חוזר.\n\nפתרון שגוי נפוץ: לאפס את items[i] בכל מחסן שבו ההקצאה נכשלה. זה לא תקין – אסור לשנות את הבקשה של המשתמש. צריך לצרוך את כל המוצרים שהפעולה דורשת, ולחכות עד שזה אפשרי."}], "official": "7.1–7.3 כמו כאן.", "note": "בקוד הרשמי של 7.3, בלולאת ההחזרה כתוב if (items[i]) sem_post(&full[i]) – כלומר תמיד אותו אינדקס i במקום k. כך מחזירים את המשאב הלא נכון (ופעמים רבות), ומחסנים מתמלאים במוצרים שלא קיימים. הקוד כאן מתוקן ל-items[k] ו-full[k].", "expl": "נבדק בהרצה: התרחיש של 7.1 עם הקוד המקורי נתקע (קיפאון), ועם הקוד המתוקן כל החוטים מסיימים. בנוסף, בדיקת עומס עם 3 יצרנים ו-3 צרכנים (2 מהם עם consume_several) – בלי קיפאון, ובלי אף מחסן שעובר את MAX או יורד מתחת ל-0.", "check": "הורץ עם חוטים אמיתיים", "exam": "23AA", "examLabel": "סמסטר א' תשפ\"ג מועד א'", "date": "30.01.2023", "id": "23AA-7"}, {"num": "8", "type": "open", "topic": "disk", "sub": "ביצועי דיסק ו-VSFS", "intro": "נתון דיסק קשיח עם הנתונים הבאים:\nמהירות סיבוב: 12,000 RPM.\nגודל מצביע: 4 בתים. גודל סקטור: 1024 בתים. גודל בלוק: 4KB.\n8 משטחים (4 platters דו-צדדיים).\nצפיפות הסקטורים ברצועה לפי 4 אזורים A, B, C, D, ובכל אזור 1200 רצועות: באזור A יש 4000 סקטורים לרצועה, ב-B ‏3000, ב-C ‏2000, וב-D ‏1000.\nזמן ה-seek הממוצע הוא 7ms, ובין שתי רצועות סמוכות 1.5ms.\nיש track skew: בקריאת סקטורים עוקבים ברצועות סמוכות אין המתנה לסיבוב.\nקצב העברת המידע של הדיסק תואם להעברת רצועה אחת באזור A בזמן סיבוב אחד בדיוק.\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "8.1", "q": "מה הזמן המינימלי שתיקח קריאה של 1000 בלוקים רצופים בכל אזור, אם משתמשים במשטח אחד בלבד? הניחו שמיקום הראש לפני כל פעולה אינו ידוע.", "answer": "זמן סיבוב:\n60,000ms / 12,000 = 5ms\nהמתנה ממוצעת לסיבוב היא חצי מזה: 2.5ms\n\nזמן מיקום (seek ממוצע + המתנה לסיבוב):\n7 + 2.5 = 9.5ms\n\nכמות הנתונים:\n1000 בלוקים · 4 סקטורים = 4000 סקטורים\n\nאזור A – רצועה אחת בדיוק, סיבוב שלם:\n9.5 + 5 = 14.5ms\n\nאזור B – רצועה ושליש, ומעבר אחד לרצועה סמוכה (בלי המתנה לסיבוב, בזכות ה-track skew):\n9.5 + 5·4/3 + 1.5 = 17.67ms\n\nאזור C – 2 רצועות ומעבר אחד:\n9.5 + 10 + 1.5 = 21ms\n\nאזור D – 4 רצועות ו-3 מעברים:\n9.5 + 20 + 4.5 = 34ms\n\nזמן המעבר נדרש כי כל הקריאה היא על משטח אחד – אחרת אפשר היה לעבור למשטח הבא באותו צילינדר בלי seek."}, {"label": "8.2", "q": "נתונה גרסה חדשה של הדיסק, שבה כל הנתונים זהים מלבד קצב העברת מידע של 100 MB/s. האם הגרסה החדשה זולה יותר (פחות טובה), יקרה יותר, או שאי אפשר לדעת?", "answer": "זולה יותר.\n\nבדיסק המקורי מעבירים רצועה של אזור A בזמן סיבוב אחד:\n4000 סקטורים · 1KB / 5ms = 800 KB/ms, כלומר בערך 800 MB/s\n\nזה הרבה יותר מהיר מ-100 MB/s, ולכן הדיסק החדש פחות טוב – וזול יותר."}, {"label": "8.3", "q": "הוחלט לנהל על הדיסק מערכת קבצים VSFS, ו-99% מהבלוקים בדיסק הוגדרו להיות ה-data region. בכל inode יש 9 מצביעים ישירים ו-3 מצביעים עקיפים. כמה קבצים בגודל המקסימלי אפשר להחזיק בדיסק? אפשר להניח שאין מגבלה על כמות ה-inodes.", "answer": "7704 קבצים.\n\nסקטורים במשטח אחד:\n1200 · (4000 + 3000 + 2000 + 1000) = 12,000,000\n\nבכל 8 המשטחים:\n8 · 12,000,000 = 96,000,000 סקטורים\nכלומר 24,000,000 בלוקים (4 סקטורים לבלוק)\n\nבלוקי DATA:\n0.99 · 24,000,000 = 23,760,000\n\nמצביעים בבלוק:\n4KB / 4B = 1024\n\nגודל קובץ מקסימלי (בלוקי נתונים):\n9 + 3 · 1024 = 3081\n\nמקום שהקובץ תופס בדיסק – גם 3 הבלוקים העקיפים עצמם:\n3081 + 3 = 3084 בלוקים\n\nמספר הקבצים:\n23,760,000 / 3084 = 7704.3, כלומר 7704 קבצים"}], "official": "8.1: ‏14.5ms, ‏17.66ms, ‏21ms, ‏34ms. 8.2: זולה יותר. 8.3: ‏7704 קבצים.", "note": "בפתרון הרשמי של 8.3 כתוב 120 · (4000+3000+2000+1000) = 12 מיליון – זו טעות הקלדה: מספר הרצועות הוא 1200, וזה מה שנותן 12 מיליון.", "expl": "טעות נפוצה ב-8.3: לחשב רק לפי גודל הקובץ (3081 בלוקים) ולשכוח את 3 הבלוקים של המצביעים העקיפים – כך מקבלים 7711 קבצים במקום 7704.", "check": "חושב בסקריפט", "exam": "23AA", "examLabel": "סמסטר א' תשפ\"ג מועד א'", "date": "30.01.2023", "id": "23AA-8"}, {"num": "1", "type": "tf", "topic": "memory", "sub": "Swapping", "q": "הוכח או הפרך: אם הזיכרון המשני מלא לחלוטין, לא ניתן להקצות זיכרון נוסף לתהליכים קיימים או להריץ תהליכים חדשים.", "correct": false, "official": "לא נכון. ייתכן שעדיין יש מסגרות פנויות בזיכרון הראשי.", "expl": "הזיכרון המשני (swap) נדרש רק כשצריך לפנות דפים מהזיכרון הראשי. כל עוד יש מסגרות פנויות בזיכרון הפיזי, אפשר להקצות אותן ישירות לתהליכים – קיימים או חדשים.", "check": "לפי הפתרון הרשמי", "exam": "23AB", "examLabel": "סמסטר א' תשפ\"ג מועד ב'", "date": "20.02.2023", "id": "23AB-1"}, {"num": "2", "type": "tf", "topic": "sync", "sub": "הרעבה ומנעולים הוגנים", "q": "הוכח או הפרך: במערכת שמשתמשת במנעולים הוגנים בלבד (ללא אובייקטי סנכרון אחרים), לא תיתכן הרעבה.", "correct": false, "official": "לא נכון. בדומה לקיפאון, גם הרכבה של מנעולים הוגנים עלולה לגרום להרעבה. לדוגמה, מימוש מנעול קוראים-כותבים שנלמד בשיעור גורם להרעבת הכותב גם בשימוש במנעולים הוגנים.", "expl": "הוגנות היא תכונה של מנעול בודד. כשבונים מכמה מנעולים הוגנים מנגנון מורכב יותר, המנגנון עצמו לא בהכרח הוגן.\n\nבמנעול קוראים-כותבים מההרצאה, הקורא הראשון תופס את מנעול הכתיבה והאחרון משחרר אותו. אם קוראים חדשים מגיעים כל הזמן, תמיד יש לפחות קורא אחד בפנים – ומנעול הכתיבה לא משתחרר לעולם. הכותב מורעב, למרות ששני המנעולים הוגנים.", "check": "לפי הפתרון הרשמי", "exam": "23AB", "examLabel": "סמסטר א' תשפ\"ג מועד ב'", "date": "20.02.2023", "id": "23AB-2"}, {"num": "3", "type": "tf", "topic": "disk", "sub": "SSD", "q": "הוכח או הפרך: בכונן SSD נעדיף מערכת קבצים מבוססת לוג (כמו LFS) על פני מערכת קבצים סטנדרטית (כמו VSFS), אחרת חלקים מהדיסק יישחקו משמעותית יותר מהר.", "correct": false, "official": "לא נכון. כונן SSD דואג ברמת החומרה לפיזור הכתיבות, כך שאפשר להשתמש בו כרגיל, ללא תלות במערכת הקבצים.", "expl": "ה-FTL שבתוך הכונן ממפה כתובות לוגיות לדפים פיזיים, וכותב בעצמו בצורה של לוג עם wear leveling. כך גם כתיבות חוזרות לאותו בלוק לוגי מתפזרות על פני כל הפלאש. מערכת הקבצים לא צריכה לדאוג לשחיקה.", "check": "לפי הפתרון הרשמי", "exam": "23AB", "examLabel": "סמסטר א' תשפ\"ג מועד ב'", "date": "20.02.2023", "id": "23AB-3"}, {"num": "4", "type": "tf", "topic": "memory", "sub": "פרגמנטציה", "q": "הוכח או הפרך: בהקצאות זיכרון בגודל קבוע אין אף סוג של פרגמנטציה.", "correct": false, "official": "לא נכון. יש פרגמנטציה פנימית אם נדרש למשתמש פחות זיכרון מהגודל הקבוע.", "expl": "בהקצאות בגודל קבוע אין פרגמנטציה חיצונית – כל חור פנוי מתאים לכל בקשה. אבל אם משתמש צריך פחות מהגודל הקבוע (למשל 100 בתים מתוך יחידה של 4KB), שאר היחידה מבוזבז – זו פרגמנטציה פנימית.", "check": "לפי הפתרון הרשמי", "exam": "23AB", "examLabel": "סמסטר א' תשפ\"ג מועד ב'", "date": "20.02.2023", "id": "23AB-4"}, {"num": "5", "type": "tf", "topic": "fs", "sub": "VSFS", "q": "הוכח או הפרך: בדיסק קשיח עם מערכת קבצים VSFS, כתיבה סדרתית גדולה לקובץ תמיד תהיה מהירה או שווה במהירות למספר כתיבות אקראיות של אותה כמות מידע לאותו קובץ.", "correct": false, "official": "לא נכון. תלוי בהקצאה: ייתכן שהקובץ מפוזר על פני בלוקים בדיסק כך שכתיבה סדרתית בפועל מתורגמת לפעולות אקראיות בדיסק, בעוד שכתיבות אקראיות עלולות במקרה לפנות לבלוקים רציפים, וכך להתבצע מהר יותר.", "expl": "\"סדרתי\" ו\"אקראי\" כאן הם לפי המיקום בקובץ, לא לפי המיקום בדיסק. VSFS לא מבטיח שבלוקים עוקבים בקובץ יהיו רציפים בדיסק, ולכן אין \"תמיד\".", "check": "לפי הפתרון הרשמי", "exam": "23AB", "examLabel": "סמסטר א' תשפ\"ג מועד ב'", "date": "20.02.2023", "id": "23AB-5"}, {"num": "6", "type": "open", "topic": "memory", "sub": "Clock", "intro": "נתונה מערכת שמשתמשת באלגוריתם השעון (עם כל השדרוגים), ובה רץ תהליך יחיד עם טבלת הדפים הלינארית שבהמשך. כל שורה מייצגת רצף ביטים אחד של PTE אחד (PFN, ‏P, ‏V, ‏A, ‏D, ואז 7 ביטים של ריפוד).\nP=Present, V=Valid, A=Accessed (Reference), D=Dirty.\nעמודת \"דף\" ועמודת \"סגמנט\" הן לתיאור בלבד ואינן חלק מה-PTE. ידוע שגודל הטבלה קטן מדף אחד.\nיש להתעלם מכל הזיכרון ומבני הנתונים של הקרנל מלבד טבלאות הדפים.", "table": {"headers": ["דף", "PFN", "P", "V", "A", "D", "סגמנט"], "rows": [["0", "00100", "1", "1", "1", "0", "TEXT"], ["1", "00000", "0", "1", "0", "0", "TEXT"], ["2", "11101", "1", "1", "0", "0", "TEXT"], ["3", "00000", "0", "0", "0", "0", "TEXT"], ["4", "00010", "1", "1", "1", "0", "DATA"], ["5", "00000", "0", "0", "0", "0", "DATA"], ["6", "10011", "1", "1", "0", "1", "STACK"], ["7", "00000", "0", "1", "0", "0", "HEAP"], ["8", "10100", "1", "1", "0", "1", "HEAP"], ["9", "00000", "0", "0", "0", "0", "HEAP"], ["10", "00000", "0", "1", "0", "0", "HEAP"], ["11", "01011", "1", "1", "1", "0", "HEAP"], ["12", "01101", "1", "1", "1", "0", "HEAP"], ["13", "00000", "0", "0", "0", "0", "HEAP"], ["14", "11010", "1", "1", "1", "1", "HEAP"], ["15", "00000", "0", "1", "0", "0", "HEAP"]]}, "parts": [{"label": "6.1", "q": "איזה נתון חסר כדי לחשב את גודל הזיכרון הווירטואלי ואת גודל הזיכרון הפיזי המקסימלי? מה יהיו הגדלים אם ערך הנתון החסר הוא X?", "answer": "הנתון החסר: גודל הדף.\n\nמרחב הכתובות:\nבטבלה יש 16 כניסות, כלומר 16 דפים לתהליך.\nמרחב כתובות = 16 · X בתים\n\nזיכרון פיזי:\nה-PFN הוא 5 ביטים, כלומר 32 מסגרות.\nזיכרון פיזי = 32 · X בתים"}, {"label": "6.2", "q": "התהליך מריץ את השורה int pid1 = fork(); הקריאה הצליחה, ותהליך הבן עוד לא קיבל זמן מעבד. כמה מסגרות נוספות יהיו תפוסות מיד אחרי ביצוע כל השורה (ביחס למצב שלפניה)?", "answer": "2 מסגרות נוספות.\n\nלפני: התהליך תופס 9 מסגרות – 8 דפים עם P = 1, ועוד מסגרת אחת לטבלת הדפים (הטבלה קטנה מדף).\n\nfork: בגלל copy-on-write לא משוכפלת אף מסגרת של זיכרון התהליך. נוספת רק מסגרת אחת לטבלת הדפים של הבן.\n\nההשמה ל-pid1: האב כותב למחסנית, שמשותפת עכשיו עם הבן. copy-on-write משכפל את הדף – המחסנית היא דף אחד (דף 6), אז נוספת עוד מסגרת אחת.\n\nסך הכל: 1 + 1 = 2"}, {"label": "6.3", "q": "נניח שכל שאר המסגרות בזיכרון (שלא בשימוש התהליך) שמורות לקרנל. התהליך ניגש לכתובת בדף 10. איזה דף יפונה מהזיכרון? מה יהיה הערך החדש של ה-PTE של דף 10?", "answer": "יפונה דף 2.\n\nאין מסגרת פנויה, ולכן צריך לפנות דף. שעון עם השדרוגים מחפש קודם דף שלא ניגשו אליו לאחרונה (A = 0) וגם לא שונה (D = 0) – כי אותו אפשר לפנות בלי לכתוב לדיסק.\n\nהדפים בזיכרון (P = 1): ‏0, 2, 4, 6, 8, 11, 12, 14. מתוכם רק לדף 2 יש A = 0 ו-D = 0. כיוון שהוא היחיד, הוא ייבחר בלי קשר למיקום המחוג.\n\nדף 10 נכנס למסגרת שהתפנתה:\nPFN = 11101, ‏P = 1, ‏V = 1, ‏A = 1\nD = 0 או 1, לפי סוג הגישה (קריאה או כתיבה)"}], "official": "6.1: גודל הדף; ‏16X; ‏32X. 6.2: עוד 2 מסגרות. 6.3: דף 2; ‏PFN=11101, P=V=A=1, D לפי הפעולה.", "expl": "דף 10 הוא V = 1 ו-P = 0 – כלומר הוא חוקי אבל לא בזיכרון (נמצא ב-swap). לכן הגישה גורמת ל-page fault ולא ל-segmentation fault.", "check": "נבדק מול הטבלה", "exam": "23AB", "examLabel": "סמסטר א' תשפ\"ג מועד ב'", "date": "20.02.2023", "id": "23AB-6", "image": "img/23AB-6.png"}, {"num": "7", "type": "open", "topic": "threads", "sub": "מקביליות", "intro": "נתונה תוכנית לקידום מונה משותף counter על ידי כמה חוטים. ערכי הקבועים T ו-N לא ידועים (אבל כל אחד מהם לפחות 2). כל החוטים מריצים את אותה פונקציה – foo או bar.\nמריצים את התוכנית פעמיים: פעם כשכל החוטים שנוצרים בשורה 23 מריצים את foo, ופעם כשכולם מריצים את bar. כל קריאות המערכת הצליחו.\nיש לפרט בקצרה ובבירור את תזמוני הריצות שמובילים לכל תשובה.", "code": " 1 #define T ??   // 2 or more\n 2 #define N ??   // 2 or more\n 3 int counter = 0;\n 4\n 5 void* foo(void* arg)\n 6 {\n 7     for (int i = 0; i < N; ++i) {\n 8         ++counter;\n 9     }\n10     return NULL;\n11 }\n12\n13 void* bar(void* arg)\n14 {\n15     while (counter < N) {\n16         ++counter;\n17     }\n18     return NULL;\n19 }\n20\n21 void main() {\n22     pthread_t threads[T];\n23     for (int i = 0; i < T; ++i)\n24         pthread_create(&threads[i], NULL, ??, NULL);\n25     for (int i = 0; i < T; ++i)\n26         pthread_join(threads[i], NULL);\n27     printf(\"counter = %d\\n\", counter);\n28 }", "parts": [{"label": "7.1", "q": "מה הערך המינימלי של counter (כפונקציה של T ו-N) שיודפס בסוף, כשהחוטים מריצים את foo? (רמז: המקסימלי הוא T·N.)", "answer": "הערך המינימלי הוא 2.\n\nחוט 1 קורא 0 ונעצר לפני שהוא כותב 1.\nחוט 2 מקדם N − 1 פעמים, ונעצר לפני הקידום האחרון (עוד לפני שקרא את המונה).\nכל שאר החוטים מקדמים N פעמים ומסיימים.\nחוט 1 כותב 1 – ו\"מוחק\" את כל הקידומים שנעשו עד עכשיו.\nחוט 2 קורא 1 ונעצר לפני שהוא כותב 2.\nחוט 1 משלים את N − 1 הקידומים שנשארו לו, ומסיים.\nחוט 2 כותב 2 – זה היה הקידום ה-N שלו, והוא מסיים.\n\nלמה לא 1? הכתיבה האחרונה היא של ערך שנקרא קודם ועוד 1. כדי שהערך הסופי יהיה 1, הכתיבה האחרונה צריכה לבוא אחרי קריאה של 0 – אבל כל חוט כותב לפחות פעמיים (N ≥ 2), והכתיבה השנייה שלו באה אחרי קריאה שאחרי הכתיבה הראשונה שלו, שהיא לפחות 1."}, {"label": "7.2", "q": "מה הערך המקסימלי של counter (כפונקציה של T ו-N) שיודפס בסוף, כשהחוטים מריצים את bar? (רמז: המינימלי הוא N.)", "answer": "התשובה הצפויה במבחן: N + T − 1.\n\nחוט 1 נכנס ללולאה ומקדם את המונה עד N − 1.\nכל T החוטים בודקים את תנאי הלולאה ונכנסים (המונה קטן מ-N).\nלפי הסדר, כל חוט מקדם בנפרד פעם אחת – T קידומים.\nכולם יוצאים מהלולאה, והמונה הוא N − 1 + T.\n\nאבל זה לא המקסימום האמיתי כש-T ≥ 3. בעזרת כתיבה \"ישנה\" שמורידה את המונה מתחת ל-N, חוטים יכולים להיכנס ללולאה שוב, בזמן שחוט אחר מחזיק קידום שעוד לא כתב. דוגמה עם T = 3 ו-N = 2 (מגיעה ל-5, ולא ל-4):\n\nT0: בודק 0<2, קורא 0\nT1: בודק 0<2, קורא 0\nT0: כותב 1, בודק 1<2, קורא 1\nT2: בודק 1<2\nT0: כותב 2\nT2: קורא 2\nT1: כותב 1 (כתיבה ישנה – המונה יורד ל-1)\nT0: בודק 1<2\nT1: בודק 1<2\nT2: כותב 3\nT0: קורא 3, כותב 4, יוצא\nT1: קורא 4, כותב 5, יוצא\nT2: יוצא – המונה 5"}, {"label": "7.3", "q": "נתון T = 2 והחוטים מריצים את bar. מה המספר המקסימלי של פעמים (כפונקציה של N) שחוט כלשהו עלול להריץ את שורה 15? (רמז: המינימלי הוא 0.)", "answer": "בערך N²/2. בדיוק: חוט 2 מקדם N + (N − 1) + ... + 1 = N(N + 1)/2 פעמים, ועוד בדיקה אחת אחרונה שנכשלת – כלומר שורה 15 רצה N(N + 1)/2 + 1 פעמים.\n\nחוט 1 קורא 0 ונעצר לפני שהוא כותב 1.\nחוט 2 מקדם את המונה עד N (‏N קידומים) ונעצר לפני הבדיקה הבאה.\nחוט 1 כותב 1, בודק, קורא 1 ונעצר לפני שהוא כותב 2.\nחוט 2 מקדם מ-1 עד N (‏N − 1 קידומים) ונעצר לפני הבדיקה.\nחוט 1 כותב 2, קורא 2 ונעצר...\nוכן הלאה."}, {"label": "7.4", "q": "לכל חוט יש מזהה ייחודי בין 0 ל-T−1, והפונקציה int get_id() מחזירה את המזהה של החוט שקורא לה (זה לא ה-TID; בטוחה לשימוש במקביל).\nתקנו את foo כך שהחוטים יקדמו את המונה לסירוגין ובאופן נכון: חוט 0 פעם אחת, אז חוט 1, ..., חוט T−1, ואז שוב חוט 0, וכן הלאה, עד שכל חוט קידם N פעמים.\nמותר להגדיר משתנים גלובליים ולהשתמש בסמפורים, אבל לא בפעולות אטומיות או באובייקטי סנכרון אחרים.", "answer": "סמפור לכל חוט. הסמפור של חוט 0 מאותחל ל-1, וכל השאר ל-0. כל חוט מחכה לסמפור שלו, מקדם, ומעיר את החוט הבא (האחרון מעיר את הראשון).\n\nsem_t sems[T];   // sems[0] = 1, all others = 0\n\nvoid* foo(void* arg)\n{\n    for (int i = 0; i < N; ++i) {\n        sem_wait(&sems[get_id()]);\n        ++counter;\n        sem_post(&sems[(get_id() + 1) % T]);\n    }\n    return NULL;\n}\n\nפתרון פשוט יותר אבל לא יעיל (המתנה פעילה): כל חוט בודק את השארית של counter בחלוקה ל-T, ומקדם רק כשהיא שווה למזהה שלו.\n\nvoid* foo(void* arg)\n{\n    for (int i = 0; i < N; ++i) {\n        while (counter % T != get_id())\n            pthread_yield();\n        ++counter;\n    }\n    return NULL;\n}"}], "official": "7.1: ‏2. 7.2: ‏N+T−1. 7.3: ‏N²/2. 7.4: כמו כאן.", "note": "7.2: התשובה הרשמית N+T−1 נכונה רק עבור T = 2. בבדיקה ממוחשבת של כל התזמונים האפשריים (כל בדיקה, קריאה וכתיבה כצעד נפרד) יצא מקסימום של 5 עבור T = 3, N = 2 (במקום 4), ‏7 עבור T = 3, N = 3, ו-8 עבור T = 4, N = 2. המקסימום האמיתי גדל מהר בהרבה מ-N+T−1. במבחן כנראה תתקבל התשובה הרשמית – אבל כדאי להכיר את התזמון שבתשובה.\n7.3: התשובה הרשמית N²/2 היא קירוב; הספירה המדויקת היא N(N+1)/2 + 1 (נבדק עבור N = 2..5).\n7.4: בקוד הרשמי של הפתרון עם ההמתנה הפעילה כתוב counter % N – צריך להיות counter % T (מספר החוטים).", "expl": "", "check": "נבדק בסריקה ממוחשבת של כל התזמונים (7.1–7.3) והורץ עם חוטים אמיתיים (7.4)", "exam": "23AB", "examLabel": "סמסטר א' תשפ\"ג מועד ב'", "date": "20.02.2023", "id": "23AB-7"}, {"num": "8", "type": "open", "topic": "fs", "sub": "VSFS", "intro": "ב-VSFS נוסף שדרוג של copy-on-write, שמאפשר להתייחס לאותו בלוק DATA מכמה מקומות (למשל, להצביע אליו מכמה inodes).\nלשם כך מקצים אזור חדש בדיסק (סט בלוקים) שמכיל מספר לכל בלוק DATA – כמה הפניות יש אליו. כמות ההפניות המקסימלית לבלוק היא 255.\nבהעתקת קובץ בתוך מערכת הקבצים לא משכפלים את המידע והמצביעים, אלא רק יוצרים inode חדש עם אותם ערכי מצביעים. במחיקת קובץ (כשלא נשארו אליו hard links) מחסירים 1 מכמות ההפניות של כל הבלוקים שלו. בעדכון נתוני קובץ משכפלים את הבלוקים ששונו ומעדכנים את מספרי ההפניות (וגם את המצביעים ב-inode שעודכן).\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "8.1", "q": "גודל בלוק 4KB. במערכת VSFS רגילה (בלי השדרוג) יש מקום ל-10,000,000 בלוקים של DATA. מבצעים את השדרוג בלי לשנות שום נתון אחר של מערכת הקבצים, מלבד הקטנת ה-data region לטובת האזור החדש. לכמה בלוקי DATA יהיה מקום אחרי השדרוג?", "answer": "9,997,559 בלוקים.\n\nכל מונה הפניות דורש בית אחד (8 ביטים מייצגים 0 עד 255). לכן בבלוק של 4KB נכנסים 4096 מונים.\n\nאם אחרי השדרוג יש X בלוקי DATA, צריך X/4096 בלוקים של מונים (מעוגל למעלה). מחפשים את ה-X הגדול ביותר כך ש:\nX + ⌈X/4096⌉ ≤ 10,000,000\n\nX = 9,997,559\n9,997,559 + 2,441 = 10,000,000"}, {"label": "8.2", "q": "אחרי השדרוג, ב-inode יש 10 מצביעים ישירים, מצביע עקיף אחד ומצביע עקיף כפול אחד. גודל מצביע 4 בתים.\nמשתמש העתיק קובץ רגיל בגודל 45,040 בתים, ואז כתב 10 בתים לסוף הקובץ המקורי. כמה בלוקים צריך לקרוא ולכתוב בדיסק עבור כל אחת מהפעולות, במקרה המקסימלי?\n(אין צורך להתייחס לגישה לתיקיות או לעדכון זמני גישה. אפשר להניח שה-inode של הקובץ המקורי כבר בזיכרון, ושאף cache לא מכיל מידע רלוונטי.)", "answer": "מבנה הקובץ:\n45,040 / 4096 = 10.996, כלומר 11 בלוקי DATA\nהקובץ משתמש ב-10 המצביעים הישירים ובמצביע העקיף, ובבלוק המצביעים יש מצביע אחד.\n\nהעתקה – 14 קריאות ו-14 כתיבות:\ninode bitmap – קריאה וכתיבה (הקצאת inode חדש)\nהבלוק של ה-inode החדש – קריאה וכתיבה (המצביעים זהים למקור)\nבלוקי מונים – לכל היותר 12 לקריאה ולכתיבה: מגדילים ב-1 את המונה של 11 בלוקי ה-DATA ושל בלוק המצביעים העקיף (גם אליו יש עכשיו 2 הפניות)\n2 + 12 = 14\n\nכתיבת 10 בתים בסוף המקור – לפי הפתרון הרשמי, 6 קריאות ו-7 כתיבות:\n45,040 + 10 = 45,050 ≤ 11 · 4096, ולכן לא נוסף בלוק – כותבים לבלוק ה-11.\nהבלוק משותף, אז משכפלים אותו. בעקבות זה משתנה גם בלוק המצביעים העקיף – גם הוא משותף, ולכן גם אותו משכפלים.\nקריאה של בלוק המצביעים העקיף (כדי למצוא את בלוק ה-DATA) – 1\nבלוקי מונים – לכל היותר 2 לקריאה ולכתיבה\nבלוקי data bitmap – קריאה עד שמוצאים מקום, וכתיבה של לכל היותר 2\nכתיבת 2 הבלוקים המשוכפלים – 2 לכתיבה בלבד\ninode של קובץ המקור עם המצביע המעודכן – קריאה וכתיבה"}, {"label": "8.3", "q": "סטודנט טען שעם השדרוג אין יותר צורך ב-data bitmap. מדוע זה נכון, ומה היתרונות והחסרונות של ויתור עליו?", "answer": "הטענה נכונה: אזור ההפניות כבר אומר אם בלוק פנוי. אם לבלוק DATA יש 0 הפניות, אף קובץ לא משתמש בו – והוא פנוי.\n\nיתרון: חוסכים את המקום שתפס ה-data bitmap.\n\nחסרון: מציאת מקום פנוי דורשת יותר גישות – כל בלוק של מונים מכסה רק 4096 בלוקים (בית לכל בלוק), בעוד שבלוק bitmap מכסה 32,768 (ביט לכל בלוק)."}], "official": "8.1: ‏9,997,559. 8.2: העתקה – 14 קריאות ו-14 כתיבות; כתיבה – 6 קריאות ו-7 כתיבות. 8.3: כמו כאן.", "note": "8.2 (הכתיבה): הספירה הרשמית לא כוללת כמה גישות שבמקרה המקסימלי כנראה נדרשות: קריאה של בלוק ה-DATA הישן (כדי להעתיק את 4,080 הבתים שכבר כתובים בו לפני הוספת 10 הבתים), ועדכון המונים של 2 הבלוקים החדשים ל-1 (שעלולים להיות בבלוקי מונים אחרים – עד 4 בלוקי מונים במקום 2). מנגד, כתוב שה-inode של המקור כבר בזיכרון, אז ייתכן שאין צורך לקרוא אותו. כדאי לכתוב במבחן את ההנחות במפורש.", "expl": "בדיקה ל-8.1: עם X = 9,997,560 צריך ⌈9,997,560/4096⌉ = 2,441 בלוקי מונים, וביחד 10,000,001 – יותר מדי.", "check": "חושב בסקריפט", "exam": "23AB", "examLabel": "סמסטר א' תשפ\"ג מועד ב'", "date": "20.02.2023", "id": "23AB-8"}, {"num": "1", "type": "open", "topic": "memory", "sub": "גודל טבלת דפים", "intro": "נתונה מערכת עם זיכרון פיזי של 64KB וגודל דף של 512B. כל כניסה בטבלת הדפים (PTE) מכילה מספר מסגרת בלבד, ונדרש שכל טבלה תאוחסן בדף אחד בדיוק.", "parts": [{"label": "1.1", "q": "אם התרגום מכתובת וירטואלית לפיזית נעשה ברמה אחת בלבד, מה גודל הזיכרון הווירטואלי של תהליך?", "answer": "256KB.\n\nמספר המסגרות:\n64KB / 512B = 128 = 2^7\nכלומר ה-PFN הוא 7 ביטים, ואחרי ריפוד לחזקה של 2 – כל PTE הוא בית אחד.\n\nכניסות בטבלה (הטבלה בגודל דף בדיוק):\n512B / 1B = 512 כניסות, כלומר 512 דפים\n\nמרחב הכתובות:\n512 · 512B = 256KB"}, {"label": "1.2", "q": "משדרגים את ה-MMU כך שיתמוך בתרגום של שתי רמות. מה גודל הזיכרון הווירטואלי של תהליך?", "answer": "128MB.\n\nבכל טבלה (בכל רמה) עדיין 512 כניסות. בשתי רמות:\n512 · 512 = 2^18 = 256K דפים\n\nמרחב הכתובות:\n2^18 · 2^9 = 2^27 בתים = 128MB"}, {"label": "1.3", "q": "במערכת של סעיף 1.1, 4KB מהזיכרון הפיזי שמורים לקרנל, ויש שטח החלפה (swap) של 256KB שכרגע כולו פנוי. בהנחה שכל הזיכרון של הקרנל פנוי, כמה תהליכי משתמש יכולים לרוץ במערכת?", "answer": "8 תהליכים.\n\nהמגבלה היא הזיכרון של הקרנל, שמחזיק את טבלאות הדפים של התהליכים. לגודל ה-swap אין משמעות כאן, כי טבלאות הדפים לא נשמרות בו.\n\n4KB / 512B = 8 טבלאות, כלומר 8 תהליכים"}], "official": "1.1: ‏256KB. 1.2: ‏128MB. 1.3: ‏8 תהליכים.", "expl": "", "check": "חושב", "exam": "23AC", "examLabel": "סמסטר א' תשפ\"ג מועד ג'", "date": "28.03.2023", "id": "23AC-1"}, {"num": "2", "type": "open", "topic": "sync", "sub": "אובייקט סנכרון", "q": "בסניף דואר יש פקיד יחיד ו-2 סוגי תורים: תור רגיל ותור מהיר. הפקיד מטפל בלקוחות לפי סדר הגעתם, אבל לקוחות בתור המהיר עוקפים את התור הרגיל. כשהפקיד פנוי:\nאם יש לקוחות שמחכים בתור המהיר – הוא מטפל בבא בתור המהיר.\nאחרת, אם יש לקוחות שמחכים בתור הרגיל – הוא מטפל בבא בתור הרגיל.\nאסור להתחיל טיפול בלקוח מהתור הרגיל אם יש לקוחות שמחכים בתור המהיר, ובכל רגע מטופל לקוח אחד בלבד.\nכל לקוח מיוצג על ידי חוט. ממשו אובייקט סנכרון עם 4 פעולות:\nenter_regq / enter_fastq – כניסה לתור הרגיל / המהיר. הפעולה חוזרת רק כשהגיע תורו של הלקוח.\nexit_regq / exit_fastq – הלקוח סיים את הטיפול. רק אחרי שהקריאה הסתיימה הפקיד פנוי לבא בתור.\nהאובייקט צריך לקיים מניעה הדדית, חופש מקיפאון והוגנות. מותר להשתמש באובייקטי סנכרון ובפעולות אטומיות כרצונכם. יש לציין ערכי אתחול של משתנים גלובליים.", "answer": "int fast_wait = 0;   // customers in the fast queue (incl. in service)\nsem_t fastlock;      // init to 1 (any fair lock)\nsem_t reglock;       // init to 1 (any fair lock)\n\nvoid enter_regq() {\n    sem_wait(&reglock);              // wait until I'm first in regq\n    while (1) {\n        sem_wait(&fastlock);         // prevent fastq from entering\n        if (fast_wait == 0)          // no fast customers waiting\n            return;\n        sem_post(&fastlock);         // otherwise release and retry\n    }\n}\nvoid exit_regq() {\n    sem_post(&fastlock);             // release both locks\n    sem_post(&reglock);              // (order doesn't matter)\n}\n\nvoid enter_fastq() {\n    fetch_and_add(&fast_wait, 1);    // mark: waiting in fast queue\n    sem_wait(&fastlock);             // wait for my turn\n}\nvoid exit_fastq() {\n    fetch_and_add(&fast_wait, -1);   // no longer waiting\n    sem_post(&fastlock);             // next in line\n}\n\nfastlock הוא בעצם \"הפקיד\": מי שמחזיק אותו מטופל. לקוחות מהירים מחכים עליו לפי הסדר (מנעול הוגן).\n\nreglock מסדר את התור הרגיל: רק הראשון בתור הרגיל מתחרה על הפקיד.\n\nהלקוח הרגיל הראשון תופס את הפקיד רק אם אין אף לקוח מהיר (fast_wait == 0). אם יש – הוא משחרר ומנסה שוב, וכך הלקוחות המהירים עוקפים אותו.", "official": "כמו כאן.", "expl": "הקוד הורץ עם 3 חוטים בתור המהיר ו-3 בתור הרגיל, ‏20,000 טיפולים לכל חוט: אף פעם לא היו 2 לקוחות אצל הפקיד בו-זמנית, וכל החוטים סיימו.\n\nשימו לב שהלקוח הרגיל הראשון מבצע המתנה פעילה כל עוד יש לקוחות מהירים – זה מקובל כאן, כי הוא היחיד שמחכה כך (שאר הרגילים חסומים על reglock).", "check": "הורץ עם חוטים אמיתיים", "exam": "23AC", "examLabel": "סמסטר א' תשפ\"ג מועד ג'", "date": "28.03.2023", "id": "23AC-2"}, {"num": "3", "type": "open", "topic": "fs", "sub": "VSFS", "intro": "נתונה מערכת קבצים VSFS על דיסק עם גודל סקטור וגודל בלוק של 4KB. יש במערכת 1,000,000 בלוקי DATA פנויים ו-100,000 inodes פנויים.\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "3.1", "q": "משתמש הריץ את הסקריפט הבא. כמה בלוקי DATA וכמה inodes יהיו פנויים אחרי הרצתו?", "code": "for d in a{1..10} ; do          # iterate over a1, a2, ..., a10\n    mkdir $d                     # create dirs a1, a2, ..., a10\n    for x in b{1..10} ; do      # iterate over b1, b2, ..., b10\n        mkdir $d/$x              # create dirs $d/b1, $d/b2, ...\n        for f in h{1..10} ; do  # iterate over h1, h2, ..., h10\n            echo hello > $d/$x/$f\n        done\n    done\ndone", "answer": "פנויים: 998,890 בלוקים ו-98,890 inodes.\n\nנוצרים:\n10 תיקיות בלולאה החיצונית\n100 תיקיות בלולאה האמצעית (10 בכל תיקייה חיצונית)\n1000 קבצים בלולאה הפנימית (10 בכל תיקייה אמצעית)\nסך הכל 1110 אובייקטים\n\nכל אחד צריך inode אחד. כל קובץ (\"hello\") וכל תיקייה (מעט רשומות) נכנסים בבלוק DATA אחד – המינימום.\n\nלכן נוצלו 1110 בלוקים ו-1110 inodes:\n1,000,000 − 1110 = 998,890\n100,000 − 1110 = 98,890"}, {"label": "3.2", "q": "אחרי הסקריפט, המשתמש הריץ rm -rf a* (מחיקה רקורסיבית של כל הקבצים והתיקיות). האם כמות הבלוקים וה-inodes הפנויים חזרה בדיוק למה שהייתה לפני הסקריפט?", "answer": "כן. אחרי מחיקת כל הקבצים והתיקיות, כל הבלוקים וה-inodes שהוקצו משתחררים, ולכן הכמויות זהות למצב ההתחלתי."}, {"label": "3.3", "q": "במצב המקורי של המערכת (לפני הסעיפים הקודמים), משתמש הריץ את הסקריפט הבא. מה ההשפעה על מערכת הקבצים (מבחינת הבלוקים הפנויים)? האם הסקריפט ירוץ לנצח? אם כן – תארו איך זה ייתכן, אחרת – מדוע לא.", "code": "x=1\nwhile [ $x ] ; do      # practically, kind of infinite loop\n    echo hello > $x\n    let x=$x+1         # like x++ in C language\ndone", "answer": "ירוץ לנצח.\n\nנוצרים קבצים עד שנגמרים ה-inodes הפנויים. כל קובץ תופס inode אחד ובלוק DATA אחד, ויש יותר בלוקים (1,000,000) מ-inodes (100,000) – לכן המגבלה היא ה-inodes. אחרי 100,000 קבצים לא נשארים inodes, ובערך 900,000 בלוקים נשארים פנויים.\n\nהתנאי [ $x ] תמיד מתקיים (x אף פעם לא ריק), ולכן הלולאה ממשיכה לנצח – כל echo נכשל ומדפיס הודעת שגיאה."}], "official": "3.1: נוצלו 1110 בלוקים ו-1110 inodes. 3.2: כן, הכמות חזרה. 3.3: קבצים נוצרים עד שה-inodes נגמרים, ואז הסקריפט ממשיך בלולאה אינסופית עם הודעות שגיאה.", "note": "3.3: התיקייה שבה נוצרים הקבצים גם היא גדלה – 100,000 רשומות לא נכנסות בבלוק אחד – ולכן בפועל ייתפסו קצת יותר מ-100,000 בלוקים. הפתרון הרשמי מתעלם מזה.", "expl": "", "check": "חושב", "exam": "23AC", "examLabel": "סמסטר א' תשפ\"ג מועד ג'", "date": "28.03.2023", "id": "23AC-3"}, {"num": "1", "type": "tf", "topic": "memory", "sub": "Swapping", "q": "הוכח או הפרך: אם הזיכרון הראשי (RAM) מספיק גדול, לא נצטרך לעולם לקרוא או לכתוב נתוני תהליך מ/אל הזיכרון המשני (דיסק).", "correct": false, "official": "לא נכון. עדיין נצטרך לקרוא נתוני תהליך מהדיסק, לדוגמה את קוד התהליך. בנוסף, יש שימוש ב-swapping גם כשהזיכרון לא בהכרח מלא, בגלל high/low watermark.", "expl": "קוד התוכנית נטען מהקובץ שבדיסק (בדרך כלל בעצלות, דף אחרי דף, כשניגשים אליו). בנוסף, מערכת ההפעלה מפנה דפים ברקע כבר כשמספר המסגרות הפנויות יורד מתחת לסף ה-low watermark – לא רק כשהזיכרון מלא לגמרי.", "check": "לפי הפתרון הרשמי", "exam": "23BA", "examLabel": "סמסטר ב' תשפ\"ג מועד א'", "date": "25.06.2023", "id": "23BA-1"}, {"num": "2", "type": "tf", "topic": "sync", "sub": "הוגנות", "q": "הוכח או הפרך: מנעול הוגן אינו מבטיח שכל חוט שמנסה לתפוס את המנעול בהכרח יצליח לתפוס אותו בשלב מסוים.", "correct": true, "official": "נכון. במקרה שאף חוט לא מצליח לתפוס את המנעול (קיפאון), או שיש במערכת קיפאון/הרעבה שלא קשורים לתכונות המנעול (כמו הרעבת הכותבים במנעול קוראים-כותבים, גם עם מנעול הוגן).", "expl": "הוגנות מבטיחה שחוט שמחכה יקבל את המנעול – בתנאי שהמנעול משתחרר. אם החוט שמחזיק במנעול לעולם לא משחרר אותו (למשל, הוא תקוע בקיפאון על מנעול אחר), אף אחד מהממתינים לא יצליח. כמו כן, מנגנון שבנוי ממנעולים הוגנים יכול בעצמו לגרום להרעבה.", "check": "לפי הפתרון הרשמי", "exam": "23BA", "examLabel": "סמסטר ב' תשפ\"ג מועד א'", "date": "25.06.2023", "id": "23BA-2"}, {"num": "3", "type": "tf", "topic": "fs", "sub": "LFS", "q": "הוכח או הפרך: ב-LFS נעדיף להשתמש בסגמנט גדול ככל האפשר.", "correct": false, "official": "לא נכון. סגמנט גדול ייתן ביצועים טובים יותר, אבל סיכון גדול יותר לאיבוד נתונים.", "expl": "LFS אוסף כתיבות בזיכרון ושולח אותן לדיסק בבת אחת כשהסגמנט מתמלא. סגמנט גדול יותר מקטין את התקורה של זמן המיקום ביחס לכמות הנתונים – אבל עד שהסגמנט נכתב, הנתונים נמצאים רק בזיכרון ויאבדו בנפילת מתח. בנוסף, תשואה פוחתת: מעבר לגודל מסוים כמעט כל הזמן הוא העברה, והשיפור זניח. (וגם, כמו בשאלה 6.3 במבחן 23AA, חוצץ גדול מדי בזיכרון עלול לפגוע בביצועים.)", "check": "לפי הפתרון הרשמי", "exam": "23BA", "examLabel": "סמסטר ב' תשפ\"ג מועד א'", "date": "25.06.2023", "id": "23BA-3"}, {"num": "4", "type": "tf", "topic": "process", "sub": "מצבי תהליך", "q": "הוכח או הפרך: תהליך יכול לעבור באופן יזום (על ידי התהליך) ממצב Running למצב Ready.", "correct": true, "official": "נכון. על ידי קריאת המערכת yield.", "expl": "קריאת המערכת sched_yield מוותרת על המעבד מרצון: התהליך עובר ל-Ready (לא ל-Blocked – הוא לא מחכה לשום אירוע), והמתזמן בוחר תהליך אחר.", "check": "לפי הפתרון הרשמי", "exam": "23BA", "examLabel": "סמסטר ב' תשפ\"ג מועד א'", "date": "25.06.2023", "id": "23BA-4"}, {"num": "5", "type": "tf", "topic": "sched", "sub": "Round Robin", "q": "הוכח או הפרך: בתזמון RR, זמן התגובה הוא אופטימלי.", "correct": false, "official": "לא נכון. זמן התגובה של RR טוב אך אינו אופטימלי (וגם לא אידיאלי) אפילו עם קוונטום מינימלי, כי תהליך חדש מתווסף לסוף התור וממתין לקוונטום של כל התהליכים שלפניו.", "expl": "דוגמה: 3 תהליכים מגיעים יחד, קוונטום q. ב-RR זמני התגובה הם 0, q, 2q. אלגוריתם שמריץ תהליך חדש מיד כשהוא מגיע (למשל, מתזמן שתמיד מעדיף את מי שעוד לא רץ) ישיג בתהליך שמגיע מאוחר יותר זמן תגובה 0, ואילו ב-RR הוא יחכה לכל התור.", "check": "לפי הפתרון הרשמי", "exam": "23BA", "examLabel": "סמסטר ב' תשפ\"ג מועד א'", "date": "25.06.2023", "id": "23BA-5"}, {"num": "6", "type": "open", "topic": "memory", "sub": "טבלה היררכית", "intro": "נתונה מערכת עם זיכרון וירטואלי של 1GB וגודל דף של 4KB. בכל דף/חלק של טבלת הדפים נכנסות 1024 רשומות (PTE / PDE), וה-MMU משתמש ב-5 ביטים של סטטוס.\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "6.1", "q": "מה גודל הזיכרון הפיזי המקסימלי האפשרי במערכת?", "answer": "512GB.\n\nגודל רשומה:\n4KB / 1024 = 4 בתים = 32 ביטים\n\nבמקרה המקסימלי ה-PFN הוא כל הביטים מלבד 5 ביטי הסטטוס:\n32 − 5 = 27 ביטים, כלומר 2^27 מסגרות\n\nזיכרון פיזי:\n2^27 · 2^12 = 2^39 בתים = 512GB"}, {"label": "6.2", "q": "כמה רמות דרושות לטבלת הדפים, וכמה ביטים בכתובת הווירטואלית משמשים לכל רמה?", "answer": "2 רמות: 8 ביטים לרמה העליונה ו-10 ביטים לרמה התחתונה.\n\nמספר הדפים:\n1GB / 4KB = 2^30 / 2^12 = 2^18\n\nבכל דף של הטבלה 2^10 רשומות, כלומר רמה אחת ממפה 10 ביטים. 18 ביטים דורשים 2 רמות:\nרמה תחתונה: 10 ביטים\nרמה עליונה: 18 − 10 = 8 ביטים\n\n(ועוד 12 ביטים של offset – סך הכל 30 ביטים.)"}, {"label": "6.3", "q": "תהליך הקצה דינמית (malloc) ‏5MB. כמה מסגרות ייתפסו בזיכרון הראשי בעקבות הפקודה, במקרה המקסימלי?", "answer": "1284 מסגרות.\n\nמספר הדפים:\n5MB / 4KB = 1280 דפים רצופים\nבמקרה המקסימלי ההקצאה לא מיושרת לתחילת דף, ואז היא נפרסת על 1281 דפים.\n\nכל חלק בטבלה התחתונה ממפה 1024 דפים. 1281 דפים יכולים להתפרס על 3 חלקים שונים – למשל דף אחד בסוף חלק, 1024 בחלק הבא, ו-256 בחלק שאחריו.\n\nאם 3 החלקים האלה לא הוקצו עד עכשיו:\n1281 מסגרות לזיכרון + 3 מסגרות לחלקי הטבלה = 1284\n\nהרמה העליונה של הטבלה בהכרח כבר קיימת, ולכן היא לא נספרת."}], "official": "6.1: ‏512GB. 6.2: ‏2 רמות, 8 ו-10 ביטים. 6.3: ‏1284 מסגרות.", "expl": "בפועל malloc לרוב לא מקצה מסגרות מיד – הן מוקצות בעצלות כשניגשים לדפים. השאלה מבקשת את המקרה המקסימלי, כלומר שכל הדפים מוקצים.", "check": "חושב", "exam": "23BA", "examLabel": "סמסטר ב' תשפ\"ג מועד א'", "date": "25.06.2023", "id": "23BA-6"}, {"num": "7", "type": "open", "topic": "sync", "sub": "אובייקט סנכרון", "q": "נתונה מערכת מרובת חוטים שמנהלת N משאבים אקסקלוסיביים: מותר לגשת רק לאחד מהמשאבים בכל רגע (אבל כמה חוטים יכולים לגשת לאותו משאב במקביל).\nהמשאבים ממוספרים 0…N−1. חוט שרוצה לגשת למשאב i קורא ל-enter(i) לפני הגישה, ול-exit(i) בסיום. הקריאה enter(i) חוסמת את החוט עד שמותר לו לגשת למשאב i.\nכתבו את enter ו-exit כך ש:\nמניעה הדדית – בכל רגע לא נעשית גישה ליותר ממשאב אחד.\nחופש מקיפאון – אם חוט מנסה לגשת למשאב i ואין חוט שניגש למשאב שונה מ-i, החוט יצליח לגשת ל-i.\nלרשותכם המשתנים הגלובליים שבקוד. אסור להוסיף משתנים גלובליים או סטטיים, ואסור להשתמש בפקודות אטומיות או באובייקטי סנכרון נוספים.", "code": "int r = -1, c = 0;\nsem_t mutex;   // init to 1", "answer": "r הוא אינדקס המשאב שבשימוש כרגע, ו-c הוא מספר החוטים שמשתמשים בו (c == 0 – אף משאב לא בשימוש).\n\nvoid enter(int i) {\n    while (1) {\n        sem_wait(&mutex);\n        if ((r == i) || (c == 0)) {\n            r = i;\n            ++c;\n            sem_post(&mutex);\n            return;\n        }\n        sem_post(&mutex);\n    }\n}\n\nvoid exit(int i) {\n    sem_wait(&mutex);\n    --c;\n    sem_post(&mutex);\n}\n\nבכניסה תופסים את mutex ובודקים אם המשאב זמין: אף משאב לא בשימוש, או שהמשאב שבשימוש הוא i. אם כן – מעדכנים ויוצאים. אחרת – משחררים את mutex ומנסים שוב.\n\nהמנעול הוגן, וזה מה שמבטיח חופש מקיפאון: אחרת חוט אחד היה יכול לנסות שוב ושוב ולמנוע מחוט אחר לקרוא ל-exit ולשחרר את המשאב.\n\nשימו לב: למרות המנעול ההוגן ייתכנה הרעבה (חוטים שמשתמשים במשאב אחר יכולים להחזיק אותו לנצח), אבל הוגנות לא נדרשה בשאלה.", "official": "כמו כאן.", "expl": "הקוד הורץ עם 6 חוטים ו-3 משאבים, ‏20,000 גישות לכל חוט: אף פעם לא נעשה שימוש בשני משאבים שונים בו-זמנית, ועד 6 חוטים השתמשו באותו משאב במקביל.", "check": "הורץ עם חוטים אמיתיים", "exam": "23BA", "examLabel": "סמסטר ב' תשפ\"ג מועד א'", "date": "25.06.2023", "id": "23BA-7"}, {"num": "8", "type": "open", "topic": "disk", "sub": "ביצועי דיסק", "intro": "נתון דיסק קשיח עם הנתונים הבאים:\nמהירות סיבוב: 6,000 RPM. גודל סקטור: 1024 בתים. גודל בלוק: 4KB.\n4 משטחים (2 platters דו-צדדיים).\nצפיפות הסקטורים לפי 4 אזורים A, B, C, D. בכל אזור 50 רצועות, והאזורים מסודרים מבחוץ פנימה – A החיצוני ביותר ו-D הפנימי ביותר.\nבאזור A יש 2000 סקטורים לרצועה, ב-B ‏1500, ב-C ‏1000, וב-D ‏500.\nזמן ה-seek הממוצע 20ms, בין שתי רצועות סמוכות 2ms, וזמן ה-seek המקסימלי 40ms.\nיש track skew: בקריאת סקטורים עוקבים ברצועות סמוכות אין המתנה לסיבוב.\nהבהרה: בקורס נהגנו לחשב זמנים ממוצעים. בשאלה זו נתונים זמנים בפועל, שעלולים להיות גבוהים או נמוכים מהממוצע, עד כדי הנתונים של הדיסק.\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "8.1", "q": "קוראים קובץ של 100 בלוקים, שמפוצל על פני שתי רצועות באותו משטח (בתוך כל רצועה המידע רציף). מדדו את הפעולה וגילו שמתבצעים, לפי הסדר:\n1. השהיה של זמן לא ידוע.\n2. העברה של 300KB נתונים במשך 1.5ms.\n3. השהיה של 50ms.\n4. העברת שאר המידע של הקובץ (100KB) ברצף אחד, בלי השהיות נוספות.\nכמה זמן נמשכה העברת המידע בשלב 4?", "answer": "2ms.\n\nזמן סיבוב:\n60,000ms / 6,000 = 10ms\n\nשלב 1 הוא זמן המיקום (seek והמתנה לסיבוב).\n\nשלב 2 – קצב ההעברה:\n300KB / 1.5ms = 200 KB/ms\nזה בדיוק הקצב של אזור A:\n2000 סקטורים · 1KB / 10ms = 200 KB/ms\n\nשלב 3 – ‏50ms הם בדיוק ה-seek המקסימלי (40ms) ועוד סיבוב מלא (10ms, ההמתנה המקסימלית). כלומר עברנו את המרחק הגדול ביותר בדיסק – מרצועה באזור A לרצועה באזור D.\n\nשלב 4 – קוראים 100KB מרצועה באזור D:\nברצועה ב-D יש 500KB, ו-100KB הם חמישית ממנה – חמישית סיבוב:\n10ms / 5 = 2ms"}, {"label": "8.2", "q": "נתון קובץ של 100MB. איך כדאי למקם את נתוני הקובץ בדיסק כך שקריאה של כולו תהיה הכי מהירה (במקרה הממוצע)? כמה זמן תיקח הפעולה במקרה זה?", "answer": "561ms.\n\nהקובץ:\n100MB = 102,400 סקטורים\n\nשמים אותו ברצף באזור A – שם הקצב הגבוה ביותר. בכל רצועה של A יש 2000 סקטורים, ובצילינדר (4 רצועות, אחת בכל משטח) יש 8000 סקטורים שאפשר לקרוא ברצף בלי seek ובלי המתנה לסיבוב.\n\n12 צילינדרים מלאים:\n12 · 8000 = 96,000 סקטורים, כלומר 48 רצועות\n48 סיבובים = 480ms\n11 מעברים בין צילינדרים סמוכים: 11 · 2 = 22ms\n\nנשארו 6400 סקטורים, בצילינדר ה-13 (עדיין באזור A):\n6400 / 2000 = 3.2 סיבובים = 32ms\nועוד מעבר לצילינדר: 2ms\n\nבתחילת הפעולה – seek ממוצע והמתנה ממוצעת לסיבוב:\n20 + 5 = 25ms\n\nסך הכל:\n25 + 480 + 22 + 32 + 2 = 561ms"}, {"label": "8.3", "q": "מה שטח האחסון הכולל בדיסק (כמה בתים של נתונים אפשר לאחסן בדיסק כולו)?", "answer": "1,000,000 סקטורים של 1KB, כלומר 1,000,000KB (בערך 1GB).\n\nבמשטח אחד:\n50 · (2000 + 1500 + 1000 + 500) = 250,000 סקטורים\n\nב-4 משטחים:\n4 · 250,000 = 1,000,000 סקטורים"}], "official": "8.1: ‏2ms. 8.2: ‏561ms. 8.3: מיליון סקטורים של 1KB.", "expl": "טעות נפוצה ב-8.2: לפזר את הקובץ על משטח אחד בלבד. אז 50 הרצועות של A לא מספיקות (102,400 > 100,000), והזמן המינימלי יוצא 643ms:\n25 + 50 סיבובים ב-A (500ms) + 1.6 סיבובים ב-B (16ms) + 51 מעברים בין רצועות (102ms) = 643ms\n\nהנחה סמויה ב-8.2: מעבר בין משטחים באותו צילינדר לא דורש זמן (בלי seek ובלי המתנה לסיבוב).", "check": "חושב בסקריפט", "exam": "23BA", "examLabel": "סמסטר ב' תשפ\"ג מועד א'", "date": "25.06.2023", "id": "23BA-8"}, {"num": "1", "type": "tf", "topic": "memory", "sub": "Swapping", "q": "הוכח או הפרך: אם הזיכרון הראשי (RAM) מלא, הקצאת זיכרון של דף חדש לתהליך בהכרח גוררת כתיבה לשטח ההחלפה (swap space).", "correct": false, "official": "לא נכון. אם יש מסגרת לפינוי עם Dirty=0, אין צורך לכתוב ל-swap.", "expl": "כדי לפנות מסגרת צריך לכתוב את התוכן שלה לדיסק רק אם הוא השתנה מאז שנטען. דף נקי (D = 0) – למשל דף קוד, או דף שנטען מה-swap ולא שונה – כבר יש לו עותק עדכני בדיסק, ואפשר פשוט לדרוס אותו.", "check": "לפי הפתרון הרשמי", "exam": "23BB", "examLabel": "סמסטר ב' תשפ\"ג מועד ב'", "date": "16.07.2023", "id": "23BB-1"}, {"num": "2", "type": "tf", "topic": "sync", "sub": "הוגנות", "q": "הוכח או הפרך: כל מימוש תקין של סמפור הוא הוגן.", "correct": false, "official": "לא נכון. מימוש הסמפור המובנה בלינוקס הוא הוגן, אבל בהגדרה של אובייקט הסנכרון אין חובה לממש הוגנות.\nיש להבדיל מאובייקט כמו מנעול קוראים-כותבים שאינו הוגן בגלל אופן השימוש בסמפורים הפנימיים – זה לא מפריך את הטענה, כי הסמפורים הפנימיים כן הוגנים; רק האובייקט שנבנה מהם (שאינו סמפור) לא הוגן.", "expl": "ההגדרה של סמפור קובעת רק את הערך ואת פעולות wait ו-post. היא לא קובעת מי מבין הממתינים יתעורר. מימוש שמעיר ממתין שרירותי (או מאפשר לחוט שהגיע עכשיו \"לעקוף\") עדיין תקין – אבל לא הוגן.", "check": "לפי הפתרון הרשמי", "exam": "23BB", "examLabel": "סמסטר ב' תשפ\"ג מועד ב'", "date": "16.07.2023", "id": "23BB-2"}, {"num": "3", "type": "tf", "topic": "fs", "sub": "LFS", "q": "הוכח או הפרך: ב-LFS ניתן להוסיף מנגנון להתמודדות עם קריסות.", "correct": true, "official": "נכון. על ידי שימוש בטרנזקציות, בדומה ל-journaling, נוכל להבטיח התמודדות עם קריסות.", "expl": "LFS שומר checkpoint region עם מיקום ה-imap, ומעדכן אותו מדי פעם (עם חותמת זמן בתחילתו ובסופו, ושני עותקים לסירוגין). אחרי קריסה חוזרים ל-checkpoint האחרון התקין, ואפשר גם \"לגלגל קדימה\" את הסגמנטים שנכתבו אחריו – בדומה ל-journaling.", "check": "לפי הפתרון הרשמי", "exam": "23BB", "examLabel": "סמסטר ב' תשפ\"ג מועד ב'", "date": "16.07.2023", "id": "23BB-3"}, {"num": "4", "type": "tf", "topic": "process", "sub": "fork", "q": "הוכח או הפרך: בביצוע fork() ללא copy-on-write, ישוכפל כל הזיכרון של תהליך האב.", "correct": false, "official": "לא נכון. שטחי זיכרון שלא ניתנים לכתיבה (כמו הקוד / TEXT) עדיין ישותפו ולא ישוכפלו.", "expl": "אין סיבה לשכפל דף שאף אחד לא יכול לשנות. לכן גם בלי copy-on-write, דפי קוד (ודפים אחרים לקריאה בלבד) משותפים בין האב לבן – רק הטבלאות של שניהם מצביעות לאותן מסגרות.", "check": "לפי הפתרון הרשמי", "exam": "23BB", "examLabel": "סמסטר ב' תשפ\"ג מועד ב'", "date": "16.07.2023", "id": "23BB-4"}, {"num": "5", "type": "tf", "topic": "sched", "sub": "מנגנון ומדיניות", "q": "הוכח או הפרך: החלק של אלגוריתם התזמון שבוחר את התהליך הבא לביצוע ממומש כולו בתוכנה ולא בחומרה.", "correct": true, "official": "נכון. תהליך הוא מבנה נתונים של הקרנל, ולכן בחירת התהליך הבא לביצוע בהכרח נעשית על ידי הקרנל בלבד – בקוד של מערכת ההפעלה.", "expl": "החומרה מספקת את המנגנונים (פסיקת שעון שמחזירה שליטה לקרנל, שמירת רגיסטרים במעבר למצב קרנל), אבל המדיניות – איזה תהליך ירוץ עכשיו – היא קוד של מערכת ההפעלה, שעובד על רשימת התהליכים שלה. החומרה בכלל לא מכירה את המושג \"תהליך\".", "check": "לפי הפתרון הרשמי", "exam": "23BB", "examLabel": "סמסטר ב' תשפ\"ג מועד ב'", "date": "16.07.2023", "id": "23BB-5"}, {"num": "6", "type": "open", "topic": "process", "sub": "fork", "intro": "נתונה התוכנית הבאה. יש מעבד יחיד, אלגוריתם התזמון הוא FIFO, וכל קריאות המערכת הצליחו.", "code": " 1 int main()\n 2 {\n 3     int arr[N] = {0};   // init all to 0\n 4     char *e[] = {\"echo\", \"hello\", NULL};\n 5     setbuf(stdout, NULL);\n 6\n 7     for (int i = 0; i < N; ++i)\n 8         arr[i] = (fork() > 0);   // 0 or 1\n 9\n10     for (int i = 0; i < N; ++i)\n11         printf(\"%d \", arr[i]);\n12\n13     if (arr[0])\n14         execvp(e[0], e);\n15     else\n16         printf(\"\\n\");\n17 }", "parts": [{"label": "6.1", "q": "כתבו פלט אפשרי של התוכנית כאשר N = 3.", "answer": "1 1 1 hello\n0 1 1\n1 0 1 hello\n1 1 0 hello\n0 0 1\n0 1 0\n1 0 0 hello\n0 0 0\n\nכל תהליך מדפיס במערך arr את ערכי ההחזרה של כל קריאות ה-fork מנקודת המבט שלו: 1 אם הוא היה האב, 0 אם הוא הבן.\n\nכל תהליך שלא נמצא בתת-העץ של הבן מה-fork הראשון (כלומר arr[0] = 1) מריץ את echo ומדפיס גם hello. האחרים מדפיסים ירידת שורה.\n\nהסדר: ב-FIFO עם מעבד יחיד, כל תהליך רץ עד הסוף, והתהליכים רצים לפי סדר היצירה. התהליך הראשי (1 1 1) יוצר 3 בנים ורץ ראשון. אחריו הבן הראשון (0 1 1), שיוצר 2 בנים, ואז הבן השני (1 0 1) והשלישי (1 1 0), וכן הלאה."}, {"label": "6.2", "q": "כמה תהליכים נוצרו במהלך ריצה תקינה של התוכנית, כולל התהליך הראשי, כפונקציה של N?", "answer": "2^N. בכל קריאה ל-fork מספר התהליכים מוכפל.\n\nעץ התהליכים:\n\n[[TREE]]", "tree": ["1 1 1", "hello", [["0 1 1", "", [["0 0 1", "", [["0 0 0", "", []]]], ["0 1 0", "", []]]], ["1 0 1", "hello", [["1 0 0", "hello", []]]], ["1 1 0", "hello", []]]]}, {"label": "6.3", "q": "איך ישתנה הפלט אם אלגוריתם התזמון הוא MLFQ במקום FIFO? (תארו את השינוי במקרה הכללי, בלי לכתוב את הפלט.)", "answer": "התוכן יישאר זהה – כל תהליך ידפיס בדיוק את אותו דבר. אבל הסדר ישתנה: כל סדר של ההדפסות אפשרי, כולל ערבוב בין ההדפסות של תהליכים שונים (ה-stdout בלי חוצץ, כך שכל printf נכתב מיד ותהליך יכול להיקטע באמצע השורה שלו)."}, {"label": "6.4", "q": "איך ישתנה הפלט אם בתנאי בשורה 13 נבדוק את arr[N−1] במקום arr[0]? (תארו את השינוי במקרה הכללי.)", "answer": "אותו מספר תהליכים ידפיסו hello (חצי מהם, 2^(N−1)), אבל אלה יהיו תהליכים אחרים: כל התהליכים שאינם עלים בעץ התהליכים – כלומר מי שהיה האב בקריאה האחרונה ל-fork בלולאה.\n\nהתהליכים עם arr[N−1] = 0 הם אלה שנוצרו ב-fork האחרון – והם בדיוק העלים."}], "official": "כמו כאן.", "expl": "בהרצה אמיתית (לא FIFO) הסדר והערבוב משתנים, אבל קבוצת השורות זהה: ‏4 שורות עם arr[0] = 1 ו-hello, ו-4 שורות עם arr[0] = 0 בלי hello.", "check": "הורץ", "exam": "23BB", "examLabel": "סמסטר ב' תשפ\"ג מועד ב'", "date": "16.07.2023", "id": "23BB-6"}, {"num": "7", "type": "open", "topic": "sync", "sub": "אובייקט סנכרון", "q": "בסניף קופת חולים יש N חדרים. כל מטופל שמגיע מקבל מספר ומחכה לתורו; כשמגיע תורו הוא נכנס לחדר עד סוף הטיפול. כל מטופל יכול לקבל טיפול בכל חדר, אבל בכל חדר מטופל אחד בלבד בכל רגע.\nכל מטופל מיוצג על ידי חוט, ואובייקט הסנכרון כולל:\nget_number – נקראת כשהמטופל מגיע, ומחזירה את המספר שלו בתור: מספרים עולים, החל מ-0, בלי דילוגים או כפילויות (אין צורך לטפל ב-overflow).\nwait_for_room – נקראת מיד אחרי קבלת המספר. חוזרת רק כשהגיע תורו של המטופל, ומחזירה את מספר החדר (0 עד N−1) שאליו הוא נכנס.\nleave_room – נקראת כשהמטופל עוזב את החדר. רק אחריה החדר פנוי למטופל נוסף.\nדרישות:\nבכל רגע, בכל חדר לכל היותר מטופל אחד.\nאם יש חדר פנוי ויש מטופלים שמחכים, מטופל כלשהו ייכנס לחדר.\nמטופלים נכנסים לפי סדר המספרים: לא ייתכן שמטופל X+1 נכנס לחדר בזמן שמטופל X חסום (ואין לו חדר פנוי).\nאפשר להניח שימוש נכון באובייקט. לרשותכם המשתנים הגלובליים שבקוד; אסור להוסיף משתנים גלובליים או סטטיים. מותר להשתמש בפעולות האטומיות שנלמדו (רמז: fetch_and_add, test_and_set). תארו בקצרה את הפתרון וכתבו קוד ברור.", "code": "int r[N] = {0};   // init all to 0\nint next = 0, turn = N-1;", "answer": "הרעיון – כמו מנעול כרטיסים (ticket lock), אבל N מטופלים יכולים להיות \"בתור\" בו-זמנית. next מחלק מספרים, ו-turn הוא המספר הגדול ביותר שמותר לו להיכנס. בהתחלה turn = N − 1, כלומר N המטופלים הראשונים נכנסים מיד, וכל יציאה מקדמת את turn ב-1.\n\nr הוא מערך בוליאני שמציין אם כל חדר תפוס. כל חדר הוא בעצם מנעול TAS: מטופל שהגיע תורו מנסה פעם אחת לתפוס כל חדר. TAS נחוץ כי עד N חוטים עלולים לנסות לתפוס חדרים במקביל.\n\nint get_number() {\n    return fetch_and_add(&next);\n}\n\nint wait_for_room(int myNumber) {\n    while (myNumber > turn);\n    for (int i = 0; i < N; ++i)\n        if (!test_and_set(&r[i]))\n            return i;\n}\n\nvoid leave_room(int myRoom) {\n    r[myRoom] = 0;\n    fetch_and_add(&turn);\n}\n\nלמה תמיד יש חדר פנוי? בכל רגע עברו את ההמתנה לכל היותר turn + 1 מטופלים, ומתוכם turn − (N − 1) כבר יצאו. כלומר לכל היותר N מטופלים נמצאים בחדרים או מחפשים חדר – ויש N חדרים. וכיוון שהחדר משתחרר (r[myRoom] = 0) לפני שמקדמים את turn, המטופל הבא ימצא אותו פנוי.\n\nסדר הכניסה: מטופל X+1 עובר את ההמתנה רק כש-turn ≥ X+1, ואז גם X כבר לא חסום.", "official": "כמו כאן.", "note": "בקוד הרשמי כתוב test_and_set(r[i]) – צריך להעביר את הכתובת: test_and_set(&r[i]).", "expl": "הקוד הורץ עם 8 חוטים ו-3 חדרים, ‏160,000 טיפולים: אף פעם לא היו 2 מטופלים באותו חדר, וכל מטופל שהגיע תורו מצא חדר פנוי.", "check": "הורץ עם חוטים אמיתיים", "exam": "23BB", "examLabel": "סמסטר ב' תשפ\"ג מועד ב'", "date": "16.07.2023", "id": "23BB-7"}, {"num": "8", "type": "open", "topic": "fs", "sub": "VSFS", "intro": "נתון דיסק קשיח ועליו מערכת קבצים VSFS עם שדרוג: בכל inode יש מקום ל-128 בתים של נתוני הקובץ, בשדה בתוך ה-inode עצמו (ולא בבלוק DATA). רק כשגודל הקובץ חורג מזה, מערכת הקבצים משתמשת במצביעים להמשך הנתונים.\nכמו כן:\nגודל בלוק 4KB, גודל מצביע 4 בתים.\nגודל inode הוא 256 בתים (כולל 128 בתי הנתונים).\nבכל inode יש 5 מצביעים ישירים, 2 עקיפים, 1 עקיף כפול ו-1 עקיף משולש.\nבנתונים של תיקייה יש טבלה עם 2 עמודות; גודל כל שורה הוא מספר התווים בשם הקובץ (בית לכל תו) ועוד 8 בתים.\nגודל הנתונים של קישור סימבולי הוא בית אחד לכל תו.\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "8.1", "q": "מה הגודל המקסימלי של קובץ במערכת הקבצים, וכמה בלוקי DATA הוא יתפוס?", "answer": "מצביעים בבלוק:\n4096 / 4 = 1024\n\nבלוקי נתונים שאפשר להגיע אליהם:\n5 + 2 · 1024 + 1024² + 1024³ = 1,074,792,453\n\nגודל מקסימלי – הבלוקים ועוד 128 הבתים שב-inode:\n128B + 4KB · (5 + 2048 + 1024² + 1024³)\n= 4,402,349,887,616 בתים (בערך 4TB)\n\nבלוקים שהקובץ תופס – גם בלוקי המצביעים:\n2 עקיפים\nעקיף כפול: 1 + 1024\nעקיף משולש: 1 + 1024 + 1024²\n\nסך הכל:\n5 + (2 + 2048) + (1 + 1024 + 1024²) + (1 + 1024 + 1024² + 1024³) = 1,075,843,081 בלוקים"}, {"label": "8.2", "q": "משתמש פתח את הקובץ /home/mta/a.txt, שהוא קישור סימבולי אל /usr/local/bin/ls. אף cache לא מכיל מידע רלוונטי. כמה בלוקים צריך לקרוא ולכתוב במקרה המינימלי? אפשר להניח כל תרחיש שמוביל למינימום, כל עוד הוא עומד בנתונים.", "answer": "קריאה אחת וכתיבה אחת.\n\nבמקרה המינימלי, כל התיקיות בדרך מחזיקות את הרשומות הדרושות בתוך 128 הבתים של ה-inode שלהן, וגם התוכן של הקישור הסימבולי (\"/usr/local/bin/ls\" – 17 תווים) נמצא ב-inode. אז צריך לקרוא רק inodes:\nהשורש, home, ‏mta, ‏a.txt\nואז (השורש כבר נטען) usr, ‏local, ‏bin, ‏ls\nסך הכל 8 inodes.\n\nבבלוק אחד נכנסים 4096 / 256 = 16 inodes. במקרה המינימלי כל 8 ה-inodes נמצאים באותו בלוק – קריאה אחת.\n\nבנוסף צריך לעדכן את זמני הגישה של a.txt ושל ls – שניהם באותו בלוק, כלומר כתיבה אחת."}, {"label": "8.3", "q": "סטודנט טען שהשדרוג (128 בתים של נתונים בתוך ה-inode) צפוי להשפיע מעט מאוד על ביצועי מערכת הקבצים. הסבירו מדוע הוא צודק.", "answer": "השדרוג עוזר רק בקריאה של קבצים קטנים מאוד (עד 128 בתים) – חוסך גישה אחת לבלוק DATA. אבל כפי שלמדנו, במערכות היום רוב הנתונים שניגשים אליהם בתדירות גבוהה כבר נמצאים ב-cache, ולכן מתבצעות מעט קריאות כאלה מהדיסק. השיפור בפועל קטן מאוד."}], "official": "8.1: הגודל 128B + 4KB·(5 + 2048 + 1024² + 1024³), והבלוקים 5 + 2+2048 + 1+1024+1024² + 1+1024+1024²+1024³. 8.2: קריאה אחת וכתיבה אחת. 8.3: כמו כאן.", "expl": "", "check": "חושב בסקריפט", "exam": "23BB", "examLabel": "סמסטר ב' תשפ\"ג מועד ב'", "date": "16.07.2023", "id": "23BB-8"}, {"num": "1", "type": "tf", "topic": "fs", "sub": "VSFS", "q": "הוכח או הפרך: ב-VSFS, העתקה של קובץ בתוך אותה מערכת קבצים לרוב תהיה מהירה יותר מאותה העתקה בין מערכות קבצים שונות.", "correct": false, "official": "לא נכון. מערכות קבצים שונות יכולות לשבת על התקנים שונים, ואז אפשר לקרוא ולכתוב את הקובץ במקביל במהלך ההעתקה. מערכת קבצים אחת נמצאת לרוב על כונן אחד, ואפשר לבצע רק פעולה אחת בכל פעם.", "expl": "ב-VSFS רגיל (בלי copy-on-write) העתקה בתוך אותה מערכת קבצים היא עדיין קריאה של כל הנתונים וכתיבה שלהם מחדש. על כונן אחד הראש נע הלוך ושוב בין המקור ליעד. בין שני כוננים, אחד קורא והשני כותב במקביל.", "check": "לפי הפתרון הרשמי", "exam": "23SA", "examLabel": "סמסטר קיץ תשפ\"ג מועד א'", "date": "07.12.2023", "id": "23SA-1"}, {"num": "2", "type": "tf", "topic": "sync", "sub": "משתני תנאי", "q": "הוכח או הפרך: במשתני תנאי, שימוש ב-broadcast במקום signal פותר את בעיית ה-lost signal.", "correct": false, "official": "לא נכון. בתרחיש הראשון שנלמד ל-lost signal, לא משנה אם מתבצע broadcast.", "expl": "lost signal קורה כשה-signal נשלח לפני שהחוט הממתין הגיע ל-wait (למשל כי לא בודקים את התנאי תחת מנעול). למשתנה תנאי אין זיכרון – גם broadcast מעיר רק את מי שכבר ממתין באותו רגע. החוט שיגיע ל-wait אחר כך יחכה לנצח. הפתרון הוא משתנה מצב ובדיקה שלו תחת המנעול, לא broadcast.", "check": "לפי הפתרון הרשמי", "exam": "23SA", "examLabel": "סמסטר קיץ תשפ\"ג מועד א'", "date": "07.12.2023", "id": "23SA-2"}, {"num": "3", "type": "tf", "topic": "disk", "sub": "רמות RAID", "q": "הוכח או הפרך: יש מקרים שבהם עדיף להשתמש ב-RAID-4 על פני RAID-5.", "correct": false, "official": "לא נכון. RAID-5 עדיף על RAID-4 בכל פרמטר.", "expl": "בטבלת ההשוואה מההרצאה, RAID-5 שווה ל-RAID-4 בקיבולת ובאמינות, שווה או טוב יותר בכל מדד ביצועים, ובכתיבה אקראית טוב משמעותית – כי בלוקי הזוגיות מפוזרים בין כל הדיסקים, ואין דיסק זוגיות אחד שהופך לצוואר בקבוק.", "check": "לפי הפתרון הרשמי וטבלת ההשוואה מההרצאה", "exam": "23SA", "examLabel": "סמסטר קיץ תשפ\"ג מועד א'", "date": "07.12.2023", "id": "23SA-3"}, {"num": "4", "type": "tf", "topic": "redir", "sub": "fork וקבצים פתוחים", "q": "הוכח או הפרך: בביצוע fork(), הקבצים הפתוחים בתהליך האב נפתחים מחדש עבור תהליך הבן.", "correct": false, "official": "לא נכון. בביצוע fork טבלת הקבצים הפתוחים משתכפלת, אבל הקבצים לא נפתחים מחדש – תהליך הבן מצביע לאותם קבצים פתוחים של האב.", "expl": "הבן מקבל עותק של טבלת ה-FD, וכל FD אצלו מצביע לאותה רשומה בטבלת הקבצים הפתוחים של המערכת – כולל אותו מיקום (offset). לכן אם האב והבן כותבים לאותו FD, הכתיבות לא דורסות זו את זו, אלא נכתבות אחת אחרי השנייה.", "check": "לפי הפתרון הרשמי", "exam": "23SA", "examLabel": "סמסטר קיץ תשפ\"ג מועד א'", "date": "07.12.2023", "id": "23SA-4"}, {"num": "5", "type": "tf", "topic": "deadlock", "sub": "ארבעת התנאים", "q": "הוכח או הפרך: בהרצת תהליכים וחוטים עם אלגוריתם התזמון FCFS, לא ייתכן קיפאון.", "correct": true, "official": "נכון. בתזמון FCFS חוט אחד מסיים לפני שהשני מתחיל, ולכן לא מתקיים התנאי של hold and wait.", "note": "התשובה הרשמית מניחה FCFS \"טהור\", שבו כל עבודה רצה עד הסוף. אם חוט יכול להיחסם (למשל על I/O) בזמן שהוא מחזיק מנעול, המתזמן יריץ חוט אחר – ואז קיפאון כן אפשרי. במבחן כדאי לכתוב את ההנחה.", "expl": "קיפאון דורש שחוט יחזיק משאב ויחכה למשאב אחר שמחזיק חוט אחר (hold and wait). אם כל חוט רץ מההתחלה ועד הסוף לפני שהבא מתחיל, אף פעם אין שני חוטים שמחזיקים משאבים בו-זמנית.", "check": "לפי הפתרון הרשמי", "exam": "23SA", "examLabel": "סמסטר קיץ תשפ\"ג מועד א'", "date": "07.12.2023", "id": "23SA-5"}, {"num": "6", "type": "open", "topic": "memory", "sub": "TLB", "intro": "נתונה מערכת שבה רוחב כתובת וירטואלית הוא 32 ביט, וגודל הזיכרון הפיזי 1GB. כל כניסה בטבלת הדפים היא 3 בתים: 6 ביטים לסטטוס, ואף ביט לא משמש לריפוד.\nתהליך הריץ את הקוד הבא (M ו-N קבועים כלשהם).\nאחרי ההרצה, אלה הרשומות שנוספו ל-TLB בעקבות הגישות למערך בשורה 4 (אף מיפוי של המערך לא היה ב-TLB לפני כן). המספרים בבסיס 16.\nיש לפרט ולנמק את כל החישובים.", "code": "1 int arr[N];\n2 int step = M;\n3 for (int i = 0; i < N; i += step)\n4     arr[i] = arr[i] + 1;", "table": {"headers": ["דף", "מסגרת", "סטטוס"], "rows": [["2", "11B", "......"], ["3", "2", "......"]]}, "parts": [{"label": "6.1", "q": "מה גודל הדף והמסגרת במערכת?", "answer": "4KB.\n\nכל PTE הוא 24 ביטים, מתוכם 6 לסטטוס ואין ריפוד:\n24 − 6 = 18 ביטים למספר מסגרת\n\nהזיכרון הפיזי:\n1GB = 2^30, כלומר כתובת פיזית של 30 ביטים\n\nההיסט:\n30 − 18 = 12 ביטים\n\nגודל דף = גודל מסגרת = 2^12 = 4KB"}, {"label": "6.2", "q": "ידוע שבגישה הראשונה למערך (i = 0) התהליך פנה לכתובת 2008 (בבסיס 16). מה הכתובת הפיזית שבה מתחיל המערך arr?", "answer": "11B008 (בבסיס 16).\n\nההיסט הוא 12 ביטים – 3 הספרות האחרונות בבסיס 16:\n0x2008: דף 2, היסט 008\n\nלפי ה-TLB, דף 2 ממופה למסגרת 11B. מחברים עם אותו היסט:\n0x11B008"}, {"label": "6.3", "q": "מה הגודל המינימלי והמקסימלי של N (גודל המערך arr), אם גודל int הוא 4 בתים?", "answer": "מינימום 1023, מקסימום 4090.\n\nלפי ה-TLB, הגישות למערך נגעו בדיוק ב-2 דפים: 2 ו-3.\n\nהמערך מתחיל ב-0x2008, כלומר 8 בתים אחרי תחילת דף 2. איבר i נמצא בכתובת:\n0x2008 + 4i\n\nאיברים בדף 2: i = 0 עד 1021\nאיברים בדף 3: i = 1022 עד 2045 (0x2008 + 4·2045 = 0x3FFC)\nמ-i = 2046 כבר דף 4.\n\nמינימום: חייבת להיות גישה לאיבר 1022 לפחות (כדי לגעת בדף 3), כלומר N ≥ 1023. למשל N = 1023 ו-M = 1: ניגשים לאיברים 0 עד 1022.\n\nמקסימום: כל הגישות חייבות להיות לאיברים ≤ 2045. הכי טוב לעשות בדיוק 2 גישות: M = 2045, ניגשים לאיבר 0 (דף 2) ולאיבר 2045 (דף 3). הגישה הבאה, לאיבר 4090, לא התבצעה – כלומר N ≤ 4090.\n\n(עם יותר גישות, למשל k+1 גישות בצעד M, צריך kM ≤ 2045 ואז N ≤ (k+1)M – שזה פחות.)"}], "official": "6.1: ‏4KB. 6.2: ‏11B008. 6.3: מינימום N = 2, מקסימום N = 4093 (ו-N = 2048 אם מתעלמים מ-step).", "note": "בפתרון הרשמי של 6.3 יש בעיה: הוא מניח שהמערך יכול להתחיל בכל מקום בדף – פעם בסוף הדף (בשביל המינימום 2) ופעם בתחילת הדף (בשביל המקסימום) – בלי להתחשב בכך שבסעיף 6.2 נתון שהמערך מתחיל בכתובת 0x2008. בנוסף, גם לפי ההנחה שלו (תחילת דף, M = 2047), הגישה הבאה היא לתא 4094, ולכן המקסימום הוא 4094 ולא 4093.\nעם הנתון 0x2008 (וכך נבדק בסקריפט על כל ערכי N ו-M): מינימום 1023, מקסימום 4090. בלי הנתון הזה (מערך שמתחיל בכל מקום): מינימום 2, מקסימום 4094.", "expl": "", "check": "נבדק בסקריפט על כל ערכי N ו-M", "exam": "23SA", "examLabel": "סמסטר קיץ תשפ\"ג מועד א'", "date": "07.12.2023", "id": "23SA-6", "image": "img/23SA-6.png"}, {"num": "7", "type": "open", "topic": "threads", "sub": "מימוש מנעול", "intro": "להלן מימוש של מנעול ל-2 חוטים. לכל חוט מזהה (0 או 1) שמועבר בפרמטר i.", "code": " 1 int flag[2] = {0};\n 2 int label[2] = {0};\n 3 void lock(int i) {\n 4     int j = 1 - i;\n 5     flag[i] = 1;\n 6     label[i] = 1 + label[j];\n 7     while ((flag[j]) && (label[i] > label[j]));\n 8 }\n 9 void unlock(int i) {\n10     flag[i] = 0;\n11 }", "parts": [{"label": "7.1", "q": "הדגימו ריצה אפשרית שמוכיחה שהמנעול לא מקיים מניעה הדדית.", "answer": "שני החוטים מגיעים יחד לשורה 6. כל אחד קורא את ה-label של השני (0) לפני שהשני כותב את שלו, ושניהם כותבים label = 1.\n\nבשורה 7, אצל כל אחד מהם label[i] > label[j] הוא 1 > 1 – שקר. שניהם יוצאים מהלולאה ונכנסים לקטע הקריטי."}, {"label": "7.2", "q": "משנים את שורה 7 כך שהאופרטור > מוחלף ב->=. הדגימו ריצה אפשרית (אחרי השינוי) שמוכיחה שהמנעול לא מקיים חופש מקיפאון.", "answer": "אותה ריצה: שני החוטים מקבלים label = 1. עכשיו בשורה 7 התנאי הוא 1 >= 1 – אמת, ושני הדגלים דולקים. שניהם תקועים בלולאה לנצח – קיפאון."}, {"label": "7.3", "q": "האם המנעול הוגן? אם כן – הוכיחו, אחרת – תנו דוגמה נגדית. (רמז: התשובה זהה עם השינוי ובלעדיו.)", "answer": "המנעול הוגן.\n\nנניח בשלילה שלא: אז ייתכן שחוט 0 חסום לצמיתות, בזמן שחוט 1 תופס ומשחרר את המנעול מספר לא מוגבל של פעמים.\n\nחוט 0 יכול להיות חסום רק בשורה 7. אם הוא הגיע לשם, הוא כבר כתב label[0] ו-flag[0] = 1.\n\nבפעם הבאה שחוט 1 מריץ את שורה 6, הוא קורא את label[0] וכותב לעצמו ערך גדול ממנו. אז בשורה 7 התנאי אצלו מתקיים (flag[0] = 1 ו-label[1] > label[0]), והוא חסום – לפחות עד שחוט 0 יתפוס וישחרר.\n\nזו סתירה לכך שחוט 1 תופס ומשחרר בלי הגבלה."}, {"label": "7.4", "q": "תקנו את המנעול כך שיקיים את 3 התכונות: מניעה הדדית, חופש מקיפאון והוגנות. אסור להוסיף משתנים גלובליים או מקומיים, ואסור להשתמש בפקודות אטומיות או באובייקטי סנכרון אחרים. תארו בקצרה את השינוי וכתבו קוד ברור.", "answer": "מממשים מנעול פטרסון: מערך הדגלים נשאר כמו שהוא, ו-label[0] משמש כמשתנה turn של פטרסון.\n\nvoid lock(int i) {\n    int j = 1 - i;\n    flag[i] = 1;\n    label[0] = j;                          // turn = j\n    while ((flag[j]) && (label[0] == j));\n}\nvoid unlock(int i) {\n    flag[i] = 0;\n}\n\nכל חוט מוותר על התור לטובת השני. אם שניהם מנסים יחד, מי שכתב אחרון ל-label[0] הוא שמחכה – ולכן בדיוק אחד נכנס."}], "official": "7.1–7.4 כמו כאן.", "expl": "כל שלוש הגרסאות נבדקו בסריקה ממוחשבת של כל התזמונים (2 חוטים, כל אחד נכנס פעמיים): המקורית – יש מצב שבו שניהם בקטע הקריטי; עם ‎>=‎ – יש מצב ששניהם תקועים בלולאה; פטרסון – אין אף אחד מהם.", "check": "נבדק בסריקה ממוחשבת של כל התזמונים", "exam": "23SA", "examLabel": "סמסטר קיץ תשפ\"ג מועד א'", "date": "07.12.2023", "id": "23SA-7"}, {"num": "8", "type": "open", "topic": "fs", "sub": "LFS", "intro": "נתונה מערכת קבצים LFS עם הנתונים הבאים:\nגודל בלוק 2KB, גודל מצביע 4 בתים, גודל סגמנט 2000 בלוקים.\nבכל inode יש 6 מצביעים ישירים, מצביע עקיף אחד, מצביע עקיף כפול אחד ומצביע עקיף משולש אחד.\nבמערכת קיים קובץ XYZ בגודל 2MB. כשהוא נוצר, כל הנתונים שלו נכתבו בבת אחת, ובתחילת הכתיבה הסגמנט היה ריק.\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "8.1", "q": "לכמה בלוקים בדיסק צריך לכתוב כדי ליצור את XYZ (כולל הנתונים)? פרטו את סוגי הבלוקים ואיך הם קשורים ל-XYZ. אפשר להניח שסגמנט חלקי נכתב לדיסק בסופו של דבר, אבל התייחסו רק לבלוקים הקשורים ל-XYZ. אין צורך להתייחס להוספת הקובץ לתיקייה.", "answer": "1029 בלוקים.\n\nבלוקי נתונים:\n2MB / 2KB = 1024\n\nמצביעים בבלוק:\n2KB / 4B = 512\n\n6 ישירים + 512 דרך העקיף = 518 בלוקים. נשארו 1024 − 518 = 506, ולהם מספיק העקיף הכפול עם מצביע אחד – לבלוק עקיף אחד.\n\nבלוקי מצביעים:\nעקיף 1, עקיף כפול 1, ועקיף מתחתיו 1 – סך הכל 3\n\nועוד inode וחלק של ה-imap:\n1024 + 3 + 1 + 1 = 1029\n\nכל זה נכנס בסגמנט אחד (2000 בלוקים). צריך גם לעדכן את ה-CR, אבל זה לא נדרש בתשובה."}, {"label": "8.2", "q": "תהליך ניגש לבית האחרון ב-XYZ. כמה בלוקים צריך לקרוא ולכתוב, בהנחה שמספר ה-inode של XYZ ידוע ואף נתון רלוונטי לא נמצא ב-cache? פרטו את כל הבלוקים, הפעולה עליהם והסיבה.", "answer": "6 קריאות ו-2 כתיבות.\n\nהבית האחרון נמצא בבלוק 1024, שמגיעים אליו דרך העקיף הכפול.\n\nקריאה:\nCR – כדי למצוא את ה-imap\nimap – כדי למצוא את ה-inode\ninode\nהבלוק העקיף הכפול\nהבלוק העקיף שמתחתיו\nבלוק הנתונים\nסך הכל 6\n\nכתיבה – עדכון זמן הגישה:\ninode מעודכן (נכתב למקום חדש בלוג)\nimap מעודכן (כי ה-inode זז)\nסך הכל 2 (וצריך לעדכן גם את ה-CR, לא נדרש בתשובה)"}, {"label": "8.3", "q": "תהליך פתח את XYZ וכתב בית אחד במיקום 12,300 בקובץ. כמה בלוקים צריך לקרוא ולכתוב, באותן הנחות? פרטו את כל הבלוקים, הפעולה עליהם והסיבה.", "answer": "לפי הפתרון הרשמי: 4 קריאות ו-4 כתיבות.\n\nבאיזה בלוק?\n12,300 / 2048 = 6.0, כלומר הבלוק השביעי בקובץ (אינדקס 6) – הראשון שמגיעים אליו דרך המצביע העקיף.\n\nקריאה:\nCR, ‏imap, ‏inode, הבלוק העקיף – סך הכל 4\n\nכתיבה (ב-LFS כל בלוק שהשתנה נכתב למקום חדש):\nבלוק הנתונים המעודכן\nהבלוק העקיף – מצביע עכשיו למיקום החדש של הנתונים\nה-inode – מצביע למיקום החדש של הבלוק העקיף\nה-imap – מצביע למיקום החדש של ה-inode\nסך הכל 4"}], "official": "8.1: ‏1029. 8.2: ‏6 קריאות ו-2 כתיבות. 8.3: ‏4 קריאות ו-4 כתיבות.", "note": "8.3: כדי לשנות בית אחד בבלוק צריך גם לקרוא את בלוק הנתונים הישן (שאר 2047 הבתים שלו). הפתרון הרשמי מציין את זה אבל לא סופר אותו – בספירה מלאה יש 5 קריאות.", "expl": "", "check": "חושב", "exam": "23SA", "examLabel": "סמסטר קיץ תשפ\"ג מועד א'", "date": "07.12.2023", "id": "23SA-8"}, {"num": "1", "type": "tf", "topic": "fs", "sub": "LFS", "q": "הוכח או הפרך: ב-LFS אין inode bitmap וגם אין inode region, ולכן אין מגבלה על כמות ה-inodes במערכת הקבצים.", "correct": false, "official": "לא נכון. כמות ה-inodes ב-LFS מוגבלת בגלל ה-imap.", "expl": "ב-LFS ה-inodes מפוזרים בלוג, אבל כדי למצוא inode לפי המספר שלו צריך את ה-imap – מערך שבו כל מספר inode ממופה למיקום. גודל ה-imap (ובפרט ה-checkpoint region שמצביע לחלקים שלו) סופי, ולכן גם מספר ה-inodes מוגבל.", "check": "לפי הפתרון הרשמי", "exam": "23SB", "examLabel": "סמסטר קיץ תשפ\"ג מועד ב'", "date": "28.12.2023", "id": "23SB-1"}, {"num": "2", "type": "tf", "topic": "deadlock", "sub": "ארבעת התנאים", "q": "הוכח או הפרך: בכל קוד או מערכת שמקיימים את כל 4 תנאי הקיפאון, בהכרח קיימת ריצה כלשהי שתוביל לקיפאון.", "correct": false, "official": "לא נכון. אם אחד התנאים לא מתקיים אז לא ייתכן קיפאון, אבל ההפך לא בהכרח נכון (לדוגמה עם חוט יחיד, או בקטעי קוד שלא ייתכן שירוצו במקביל).", "expl": "4 התנאים הם תנאים הכרחיים לקיפאון, לא תנאים מספיקים. דוגמה: שני קטעי קוד שתופסים 2 מנעולים בסדר הפוך – אבל הם רצים באותו חוט, או ש-barrier מבטיח שהם אף פעם לא רצים בו-זמנית. אז אין אף ריצה עם קיפאון.", "check": "לפי הפתרון הרשמי", "exam": "23SB", "examLabel": "סמסטר קיץ תשפ\"ג מועד ב'", "date": "28.12.2023", "id": "23SB-2"}, {"num": "3", "type": "tf", "topic": "disk", "sub": "רמות RAID", "q": "הוכח או הפרך: בתרחיש של קריאות סדרתיות, הביצועים של RAID-5 (עם כל השדרוגים) זהים לביצועים של RAID-0.", "correct": true, "official": "נכון. כפי שנלמד, קריאות סדרתיות ב-RAID-5 יכולות לנצל את כל הדיסקים, בדומה ל-RAID-0.", "note": "בטבלה של OSTEP, קריאה סדרתית ב-RAID-5 מופיעה כ-(N−1)·S ולא N·S, כי בכל פס אחד הבלוקים הוא זוגיות. הקורס, לפי הפתרון הרשמי, מתייחס לגרסה עם השדרוגים שבה כל הדיסקים מנוצלים.", "expl": "ב-RAID-5 בלוקי הזוגיות מפוזרים, כך שבקריאה סדרתית ארוכה כל הדיסקים עובדים במקביל – בדומה ל-RAID-0.", "check": "לפי הפתרון הרשמי", "exam": "23SB", "examLabel": "סמסטר קיץ תשפ\"ג מועד ב'", "date": "28.12.2023", "id": "23SB-3"}, {"num": "4", "type": "tf", "topic": "redir", "sub": "fork וקבצים פתוחים", "q": "הוכח או הפרך: בביצוע fork() מיד אחרי פתיחת קובץ, סגירת הקובץ אחרי ה-fork בתהליך האב תסגור אותו גם בתהליך הבן.", "correct": false, "official": "לא נכון. סגירת הקובץ רק מוחקת את המצביע מה-FD שלו בטבלת הקבצים הפתוחים של תהליך האב, ולא משפיעה על תהליך הבן.", "expl": "לכל תהליך יש טבלת FD משלו. close מוחק רק את הרשומה בטבלה של התהליך שקרא לו. הרשומה בטבלת הקבצים הפתוחים של המערכת משתחררת רק כשאף FD בשום תהליך לא מצביע אליה – והבן עדיין מצביע.", "check": "לפי הפתרון הרשמי", "exam": "23SB", "examLabel": "סמסטר קיץ תשפ\"ג מועד ב'", "date": "28.12.2023", "id": "23SB-4"}, {"num": "5", "type": "tf", "topic": "sched", "sub": "MLFQ", "q": "הוכח או הפרך: באלגוריתם התזמון MLFQ, לא קיים תרחיש שיוביל להרעבה של תהליך.", "correct": true, "official": "נכון. בגלל ה-priority boost, כל תהליך תמיד יקבל זמן ריצה בסופו של דבר.", "expl": "כל פרק זמן S, כל התהליכים עולים לתור העליון. כך גם תהליך שירד לתור הנמוך ביותר וממתין מאחורי תהליכים אינטראקטיביים, יקבל זמן ריצה לכל המאוחר אחרי ה-boost הבא.", "check": "לפי הפתרון הרשמי", "exam": "23SB", "examLabel": "סמסטר קיץ תשפ\"ג מועד ב'", "date": "28.12.2023", "id": "23SB-5"}, {"num": "6", "type": "open", "topic": "memory", "sub": "טבלה הפוכה", "intro": "נתונה מערכת שבה אין טבלאות דפים. במקומן יש ל-MMU (בזיכרון של הרכיב עצמו) טבלת תרגום אחת ויחידה לכל התהליכים והמסגרות.\nזו טבלה הפוכה: האינדקס בטבלה הוא מספר מסגרת, ובכל תא יש מזהה תהליך ומספר הדף של התהליך שממופה למסגרת הזו, וגם ביטי סטטוס וריפוד (אם צריך).", "parts": [{"label": "6.1", "q": "לפי מה אפשר לקבוע כמה כניסות צריכות להיות בטבלה?", "answer": "לפי מספר המסגרות בזיכרון הפיזי – לכל מסגרת יש כניסה בטבלה."}, {"label": "6.2", "q": "איך מתבצע תרגום כתובות במערכת זו? תארו את כל התהליך, מהגישה לכתובת הווירטואלית ועד מציאת הכתובת הפיזית. אפשר להניח שקיים בטבלה מיפוי עבור הדף.", "answer": "התהליך ניגש לכתובת וירטואלית.\nה-MMU מפרק אותה למספר דף ולהיסט.\nה-MMU מחפש בכל הטבלה רשומה שיש בה גם מזהה התהליך הנוכחי וגם מספר הדף הזה.\nהאינדקס של הרשומה שנמצאה הוא מספר המסגרת. מחברים אותו עם ההיסט – וזו הכתובת הפיזית."}, {"label": "6.3", "q": "מה היתרון העיקרי של מערכת זו על פני מערכות עם טבלאות דפים רגילות?", "answer": "החיפוש נעשה בחומרה, ואפשר לחפש בכל הטבלה בבת אחת (במקביל) – כך מוצאים את המיפוי מהר מאוד, בלי גישות לזיכרון לטבלאות היררכיות. בנוסף, הטבלה מקלה מאוד על מימוש אלגוריתמי פינוי כמו השעון – היא כבר מסודרת לפי מסגרות, ואין צורך במבנה נתונים נוסף."}, {"label": "6.4", "q": "איזו פעולה או מנגנון קיימים במערכות עם טבלאות דפים רגילות, ואי אפשר לממש עם הטבלה הזו בלבד? מדוע?", "answer": "החלפה (swapping). אין טבלת דפים, ולכן אין שום מידע על דף של תהליך שלא ממופה כרגע למסגרת – אין איפה לרשום שהדף נמצא בדיסק ובאיזה מקום."}], "official": "כמו כאן.", "expl": "גודל הטבלה כאן תלוי בזיכרון הפיזי ולא במרחב הווירטואלי של כל תהליך – טבלה אחת לכל המערכת.", "check": "לפי הפתרון הרשמי", "exam": "23SB", "examLabel": "סמסטר קיץ תשפ\"ג מועד ב'", "date": "28.12.2023", "id": "23SB-6"}, {"num": "7", "type": "open", "topic": "sync", "sub": "סמפורים", "parts": [{"label": "7.1", "q": "להלן פתרון לבעיית יצרן-צרכן עם 3 סמפורים (full, empty, mutex) שמאותחלים כמו בפתרון מההרצאה. שימו לב: הקוד שונה מזה שנלמד בכיתה.\nItem הוא מבנה שמייצג מוצר. produce_item / consume_item יוצרות וצורכות מוצר בודד, ובטוחות לשימוש במקביל (על מוצרים שונים). add_item / remove_item מוסיפות ומסירות מוצר מהמחסן, ואינן בטוחות לשימוש במקביל.\nהאם המימוש פותר נכון את בעיית יצרן-צרכן? אם כן – הוכיחו, אחרת – תארו את התרחיש הבעייתי.", "code": "1 void produce() {                   void consume() {\n2     Item item = produce_item();        sem_wait(&full);\n3     sem_wait(&empty);                  sem_wait(&mutex);\n4     sem_wait(&mutex);                  Item item = remove_item();\n5     add_item(item);                    sem_post(&empty);\n6     sem_post(&full);                   sem_post(&mutex);\n7     sem_post(&mutex);                  consume_item(item);\n8 }                                  }", "answer": "פותר נכון.\n\nההבדל מהפתרון בכיתה הוא רק בסדר השחרור: כאן משחררים את full (או empty) לפני mutex. לסדר השחרור אין משמעות לנכונות – post אף פעם לא חוסם, וכל הסמפורים שנתפסו משוחררים מיד.\n\nאם צרכן מתעורר מ-full לפני שהיצרן שחרר את mutex, הוא פשוט יחכה רגע על mutex. מניעה הדדית על המחסן עדיין נשמרת, והמונים full ו-empty עדיין נכונים.\n\n(מה שכן חשוב הוא סדר התפיסה: אם תופסים את mutex לפני empty/full – יכול להיווצר קיפאון. כאן הסדר בתפיסה זהה לפתרון מהכיתה.)"}, {"label": "7.2", "q": "נתונה מערכת מיוחדת שבה כל שורת קוד היא אטומית. יש 2 משתנים גלובליים x, y שמאותחלים ל-0, וסמפור משותף mutex שמאותחל ל-1. שני חוטים מריצים במקביל את הקוד הבא.\nפרטו את כל זוגות הערכים האפשריים של x, y אחרי ששני החוטים מסיימים. לכל זוג הסבירו בקצרה את הריצות שמובילות אליו.", "code": "1 void* thread1(void*) {      void* thread2(void*) {\n2     x = 2;                      x = x + 1;\n3     sem_wait(&mutex);           sem_wait(&mutex);\n4     y = y + x;                  y = y - 2;\n5     x = 4;                      x = x - y;\n6     sem_post(&mutex);           sem_post(&mutex);\n7 }                           }", "answer": "5 זוגות: (5, 0), ‏(4, 0), ‏(3, 1), ‏(4, 3), ‏(4, 2).\n\nמספיק להסתכל על שורות 2, 4, 5 של כל חוט. נקרא לחוט הראשון A ולשני B. כשחוט מריץ את שורה 4, הוא בהכרח מריץ גם את שורה 5 לפני שורה 4 של החוט השני (בגלל המנעול). יש 8 ריצות אפשריות:\n\nA2 A4 A5 B2 B4 B5 → (x=5, y=0)\nA2 A4 B2 A5 B4 B5 → (x=4, y=0)\nA2 B2 A4 A5 B4 B5 → (x=3, y=1)\nA2 B2 B4 B5 A4 A5 → (x=4, y=3)\nB2 B4 B5 A2 A4 A5 → (x=4, y=0)\nB2 B4 A2 B5 A4 A5 → (x=4, y=2)\nB2 A2 B4 B5 A4 A5 → (x=4, y=2)\nB2 A2 A4 A5 B4 B5 → (x=4, y=0)\n\nלדוגמה, השורה הראשונה: A קובע x = 2, ‏y = 0 + 2 = 2, ‏x = 4. אחר כך B: ‏x = 5, ‏y = 2 − 2 = 0, ‏x = 5 − 0 = 5."}], "official": "7.1: פותר נכון. 7.2: אותן 8 ריצות ו-5 זוגות.", "expl": "כל 20 הסידורים של 6 השורות נבדקו בסקריפט, והושארו רק אלה שמכבדים את המנעול: יצאו בדיוק 8 ריצות ו-5 זוגות.", "check": "נבדק בסקריפט על כל הסידורים", "exam": "23SB", "examLabel": "סמסטר קיץ תשפ\"ג מועד ב'", "date": "28.12.2023", "id": "23SB-7"}, {"num": "8", "type": "open", "topic": "fs", "sub": "Extents", "intro": "נתונה מערכת קבצים VSFS עם שדרוג של extents: בכל inode יש extents במקום מצביעים ישירים. מצביעים עקיפים, ומצביעים בתוך בלוקים, עובדים כרגיל (בלי extents).\nנתונים:\nגודל בלוק 1024B, גודל מצביע 4B, גודל inode ‏64B.\nבכל inode יש 4 extents, מצביע עקיף אחד ומצביע עקיף כפול אחד.\nכל extent מורכב ממצביע רגיל לבלוק ועוד בית אחד שמייצג כמות בלוקים: 1 עד 256.\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "8.1", "q": "מה הגודל המקסימלי של קובץ, וכמה בלוקי DATA הוא יתפוס?", "answer": "גודל מקסימלי: 66,816KB. בלוקים: 67,074.\n\nמצביעים בבלוק:\n1024 / 4 = 256\n\nבלוקי נתונים:\nextents: ‏4 · 256 = 1024\nעקיף: 256\nעקיף כפול: 256² = 65,536\nסך הכל 66,816 בלוקים, כלומר 66,816KB\n\nבלוקים שהקובץ תופס – גם בלוקי המצביעים:\nעקיף: 1\nעקיף כפול: 1 + 256\n66,816 + 1 + 257 = 67,074"}, {"label": "8.2", "q": "סטודנט טוען שאם נשנה את גודל המצביע מ-4B ל-2B, לא נוכל ליצור קובץ בגודל המקסימלי שהמצביעים ב-inode מאפשרים. הסבירו מדוע הוא צודק.", "answer": "מצביע של 2 בתים יכול להצביע לכל היותר ל-2^16 = 65,536 בלוקים שונים בדיסק. אבל לפי מבנה ה-inode, הקובץ המקסימלי צריך יותר בלוקים מזה (וגם בלוקי מצביעים). לכן אין מספיק כתובות בלוקים."}, {"label": "8.3", "q": "מה גודל הקובץ המקסימלי בפועל עם מצביע של 2B? תנו דוגמה לערכים חוקיים לכל המצביעים ב-inode (כולל ה-extents ותוכן הבלוקים העקיפים) שמייצגים קובץ בגודל הזה. שימו לב שגודל המצביע משנה גם את כמות המצביעים בבלוק.", "answer": "65,409KB.\n\nעכשיו בבלוק יש 1024 / 2 = 512 מצביעים. בסך הכל יש 65,536 כתובות בלוקים (0 עד 65,535), וגם בלוקי המצביעים צריכים לבוא מתוכן. רוצים כמה שיותר בלוקי נתונים.\n\nextents:\n1. מבלוק 0, ‏256 בלוקים\n2. מבלוק 256, ‏256 בלוקים\n3. מבלוק 512, ‏256 בלוקים\n4. מבלוק 768, ‏256 בלוקים\n\nמצביע עקיף ← בלוק 1024. בתוכו 512 מצביעים לבלוקים 1025 עד 1536.\n\nמצביע עקיף כפול ← בלוק 1537. בתוכו 125 מצביעים לבלוקים עקיפים 1538 עד 1662.\nב-124 הבלוקים העקיפים הראשונים (1538 עד 1661) – 512 מצביעים בכל אחד, לבלוקים 1663 עד 65,150 (‏63,488 בלוקי נתונים).\nבבלוק העקיף האחרון (1662) – 385 מצביעים, לבלוקים 65,151 עד 65,535.\n\nבדיקה: השתמשנו בכל הבלוקים 0 עד 65,535.\n\nבלוקי נתונים:\n1024 + 512 + 124 · 512 + 385 = 65,409\nכלומר 65,409KB\n\nלמה 125 בלוקים עקיפים? אם k הוא מספר הבלוקים העקיפים מתחת לעקיף הכפול, בלוקי הנתונים דרכו הם 65,536 − (1024 + 1 + 512 + 1 + k) = 63,998 − k, וצריך 63,998 − k ≤ 512k. הערך הקטן ביותר הוא k = 125."}], "official": "8.1: ‏(1024 + 256 + 256²) · 1KB, ו-1024 + 256 + 256² + 1 + 1 + 256 בלוקים. 8.2: כמו כאן. 8.3: ‏(1024 + 512 + 124·512 + 385) · 1KB, עם אותם ערכי מצביעים.", "note": "ב-8.3 הפתרון (גם הרשמי) מניח שכל 65,536 כתובות הבלוקים זמינות לקובץ – כלומר מתעלם מבלוקים שתפוסים על ידי ה-superblock, ה-bitmaps וה-inodes.", "expl": "", "check": "חושב בסקריפט", "exam": "23SB", "examLabel": "סמסטר קיץ תשפ\"ג מועד ב'", "date": "28.12.2023", "id": "23SB-8"}, {"num": "1", "type": "mcq", "topic": "fs", "sub": "inode", "q": "איזה מפריטי המידע הבאים אינו נשמר ב-inode במערכת UNIX?", "options": ["שם הקובץ.", "גודל הקובץ בבתים.", "זמן השינוי האחרון (last modification time).", "מספר ה-links שמצביעים לקובץ (link count).", "כל התשובות האחרות אינן נכונות."], "correct": 0, "official": "שם הקובץ. לקובץ אין שם ב-inode, אלא רק כחלק מה-hard link המתאים בתיקייה כלשהי.", "expl": "השם נשמר ברשומה בתיקייה (שם ← מספר inode). כך לאותו inode יכולים להיות כמה שמות (hard links) בתיקיות שונות. כל השאר – גודל, זמנים, מספר ה-links – הם מטא-דאטה של הקובץ עצמו, ונשמרים ב-inode.", "check": "לפי הפתרון הרשמי", "exam": "24AA", "examLabel": "סמסטר א' תשפ\"ד מועד א'", "date": "04.03.2024", "id": "24AA-1"}, {"num": "2", "type": "mcq", "topic": "memory", "sub": "MMU", "q": "מה תפקידו של ה-MMU?", "options": ["סיוע בתרגום כתובות וירטואליות.", "העתקת מידע מ/אל התקני קלט/פלט.", "ביצוע החלפת הקשר (context switch).", "סיוע למתזמן (scheduler) בקבלת החלטה.", "כל התשובות האחרות אינן נכונות."], "correct": 0, "official": "סיוע בתרגום כתובות וירטואליות. ה-MMU הוא רכיב חומרה שמתרגם כתובת וירטואלית לכתובת פיזית.", "expl": "העתקת מידע מהתקנים בלי המעבד היא תפקיד ה-DMA. החלפת הקשר ובחירת התהליך הבא הן קוד של מערכת ההפעלה.", "check": "לפי הפתרון הרשמי", "exam": "24AA", "examLabel": "סמסטר א' תשפ\"ד מועד א'", "date": "04.03.2024", "id": "24AA-2"}, {"num": "3", "type": "mcq", "topic": "sync", "sub": "משתני תנאי", "q": "נתונה הטענה: כדי להשתמש נכון במשתנה תנאי, תמיד צריך להשתמש גם במנעול.", "options": ["הטענה נכונה.", "הטענה לא נכונה.", "הטענה לא נכונה, אלא להפך: כדי להשתמש נכון במנעול תמיד צריך להשתמש גם במשתנה תנאי.", "הטענה לא נכונה: כדי להשתמש נכון במשתנה תנאי תמיד צריך להשתמש במשתנה עזר רגיל, ולא במנעול.", "כל התשובות האחרות אינן נכונות."], "correct": 0, "official": "הטענה נכונה. כדי להימנע מ-lost signal תמיד צריך להשתמש במנעול עם משתנה תנאי, וזה גם חלק מהממשק המובנה של משתני תנאי.", "expl": "pthread_cond_wait מקבלת מנעול כפרמטר: היא משחררת אותו ונכנסת להמתנה באופן אטומי. בלי המנעול, ה-signal יכול להגיע בין בדיקת התנאי לבין הכניסה להמתנה – ואז הוא הולך לאיבוד.\n\nמשתנה עזר (משתנה מצב) גם הוא נחוץ, אבל בנוסף למנעול – לא במקומו. ומנעול לבדו אפשר להשתמש בו בלי משתני תנאי בכלל.", "check": "לפי הפתרון הרשמי", "exam": "24AA", "examLabel": "סמסטר א' תשפ\"ד מועד א'", "date": "04.03.2024", "id": "24AA-3"}, {"num": "4", "type": "mcq", "topic": "disk", "sub": "ביצועי דיסק", "q": "נתונה הטענה: מבין שני דיסקים קשיחים כלשהם, הדיסק עם מהירות הסיבוב (RPM) הגבוהה יותר יבצע קריאות מבלוק אקראי מהר יותר.", "options": ["הטענה נכונה.", "הטענה נכונה רק אם מהירות הסיבוב של הדיסק המהיר היא לפחות 7200.", "הטענה נכונה רק אם מהירות הסיבוב של הדיסק המהיר היא לכל היותר 7200.", "הטענה לא נכונה.", "כל התשובות האחרות אינן נכונות."], "correct": 3, "official": "הטענה לא נכונה. מהירות הקריאה של דיסק תלויה בעוד פרמטרים מלבד מהירות הסיבוב, כמו זמן ה-seek וקצב ההעברה.", "expl": "זמן קריאה אקראית = seek + המתנה לסיבוב + העברה. דיסק עם RPM גבוה אבל seek ארוך (או קצב העברה נמוך) יכול להיות איטי יותר. לדוגמה: דיסק של 15,000 RPM עם seek של 20ms לעומת דיסק של 7,200 RPM עם seek של 4ms.", "check": "לפי הפתרון הרשמי", "exam": "24AA", "examLabel": "סמסטר א' תשפ\"ד מועד א'", "date": "04.03.2024", "id": "24AA-4"}, {"num": "5", "type": "mcq", "topic": "memory", "sub": "מרחב כתובות", "q": "במערכת הפעלה א' כתובת וירטואלית היא 32 ביטים, ובמערכת הפעלה ב' היא 40 ביטים. איזו טענה בהכרח נכונה?", "options": ["במערכת הפעלה א' יש יותר דפים בזיכרון הווירטואלי של כל תהליך.", "במערכת הפעלה ב' יש יותר דפים בזיכרון הווירטואלי של כל תהליך.", "במערכת הפעלה א' יתבצעו יותר פסיקות דף (page faults).", "במערכת הפעלה ב' יתבצעו יותר פסיקות דף (page faults).", "כל התשובות האחרות אינן נכונות."], "correct": 4, "official": "כל התשובות האחרות אינן נכונות. גודל הכתובת הווירטואלית לא מעיד על גודל הדף או על כמות הדפים, ולכן אי אפשר לדעת באיזו מערכת יש יותר דפים. הוא גם לא מעיד על גודל הזיכרון הפיזי והשימוש בו, ולכן אי אפשר לדעת היכן יהיו יותר פסיקות דף.", "expl": "מספר הדפים = 2^(ביטים בכתובת) / גודל דף. אם במערכת ב' הדף גדול פי 2^9 או יותר (למשל דפים של 2MB לעומת 4KB), יש בה פחות דפים או אותו מספר. פסיקות דף תלויות בזיכרון הפיזי ובדפוס הגישה – לא ברוחב הכתובת.", "check": "לפי הפתרון הרשמי", "exam": "24AA", "examLabel": "סמסטר א' תשפ\"ד מועד א'", "date": "04.03.2024", "id": "24AA-5"}, {"num": "6", "type": "open", "topic": "process", "sub": "fork ו-wait", "parts": [{"label": "6.1", "q": "נתונה התוכנית הבאה. מהם כל הפלטים האפשריים, בהנחה שכל הקריאות ל-fork הצליחו? הסבירו כל פלט.\nתזכורת: באופרטור &&, אם האופרנד הראשון הוא FALSE, האופרנד השני לא נבדק ולא מבוצע.", "code": " 1 int main(int argc, char *argv[])\n 2 {\n 3     char *str = \"hello\";\n 4\n 5     if (fork() && fork()) {\n 6         wait(NULL);\n 7         printf(\"1: %s\\n\", str);\n 8         wait(NULL);\n 9         printf(\"1: %s\\n\", str);\n10     }\n11     else {\n12         wait(NULL);\n13         printf(\"0: %s\\n\", str);\n14         str = \"goodbye\";\n15         wait(NULL);\n16         printf(\"0: %s\\n\", str);\n17     }\n18 }", "answer": "יש 5 פלטים אפשריים.\n\nמי עושה מה:\nהאב: ה-fork הראשון יוצר בן 1. אצל האב הוא מחזיר ערך חיובי, אז מבוצע גם ה-fork השני – בן 2. אצל האב שניהם אמת, והוא נכנס לבלוק של \"1\".\nבן 1: ה-fork הראשון החזיר לו 0, ולכן && עוצר מיד (הוא לא יוצר אף תהליך) והוא בבלוק של \"0\".\nבן 2: ה-fork השני החזיר לו 0 – גם הוא בבלוק של \"0\".\n\nכל בן: ל-wait אין ילדים, אז הוא חוזר מיד. הבן מדפיס \"0: hello\", משנה את str אצלו בלבד, ומדפיס \"0: goodbye\".\n\nהאב: ה-wait הראשון מחכה שבן כלשהו יסתיים, ואז מדפיס \"1: hello\" (השינוי של str בבנים לא משפיע עליו). ה-wait השני מחכה לבן השני, ואז שוב \"1: hello\" – תמיד בסוף.\n\n0: hello\n0: goodbye\n0: hello\n0: goodbye\n1: hello\n1: hello\n\n0: hello\n0: hello\n0: goodbye\n0: goodbye\n1: hello\n1: hello\n\n0: hello\n0: goodbye\n1: hello\n0: hello\n0: goodbye\n1: hello\n\n0: hello\n0: goodbye\n0: hello\n1: hello\n0: goodbye\n1: hello\n\n0: hello\n0: hello\n0: goodbye\n1: hello\n0: goodbye\n1: hello\n\nה-\"1: hello\" הראשון יכול להופיע רק אחרי ש-\"0: goodbye\" אחד כבר הודפס (כלומר בן אחד סיים), והשני רק אחרי ששני הבנים סיימו."}], "official": "5 פלטים – אותם 5 כמו כאן.", "expl": "כל הסידורים האפשריים נמנו בסקריפט: 2 בנים שכל אחד מדפיס hello ואז goodbye, ואב שמדפיס אחרי כל סיום של בן. יצאו בדיוק 5 פלטים שונים.", "check": "נמנה בסקריפט על כל הסידורים", "exam": "24AA", "examLabel": "סמסטר א' תשפ\"ד מועד א'", "date": "04.03.2024", "id": "24AA-6"}, {"num": "6b", "type": "open", "topic": "memory", "sub": "תרגום כתובות", "intro": "נתונה מערכת עם זיכרון פיזי של 16GB, שבה כתובת וירטואלית היא 32 ביטים. המערכת משתמשת בטבלת דפים לינארית. כל כניסה בטבלה היא 32 ביטים, מתוכם 25 ביטים למספר המסגרת.\nבטבלת הדפים של תהליך מסוים: דף 0 ממופה למסגרת 4, דף 1 למסגרת 5, דף 2 למסגרת 6, ודף 3 למסגרת 7. כל שאר הדפים בשימוש אבל לא נוכחים (valid=1, present=0).\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "6.2", "q": "מה גודל טבלת הדפים של התהליך (בבתים)?", "answer": "32MB.\n\nכתובת פיזית:\n16GB = 2^34, כלומר 34 ביטים\n\nההיסט:\n34 − 25 = 9 ביטים, כלומר דף של 512B\n\nמספר הדף:\n32 − 9 = 23 ביטים, כלומר 2^23 = 8M דפים\n\nגודל הטבלה:\n8M · 4B = 32MB"}, {"label": "6.3", "q": "התהליך ניגש לכתובת 0BBB ואז לכתובת 1FFF (בבסיס 16). לכל גישה: האם תתרחש פסיקת דף? אם כן – הסבירו, אחרת – מה הכתובת הפיזית?", "answer": "בשתי הגישות תתרחש פסיקת דף.\n\nההיסט הוא 9 ביטים, ולכן מספר הדף הוא הכתובת חלקי 512:\n\n0x0BBB = 3003\n3003 / 512 = דף 5 (היסט 443)\nדף 5 לא נוכח – פסיקת דף.\n\n0x1FFF = 8191\n8191 / 512 = דף 15 (היסט 511)\nדף 15 לא נוכח – פסיקת דף."}], "official": "6.2: ‏32MB. 6.3: שתי הגישות – פסיקת דף (דף 5 ודף 15).", "expl": "מלכודת: עם דפים של 4KB היה נראה ש-0x0BBB בדף 0 ו-0x1FFF בדף 1 (שניהם ממופים). כאן הדף הוא 512B בלבד, ולכן ההיסט הוא רק 9 ביטים.", "check": "חושב", "exam": "24AA", "examLabel": "סמסטר א' תשפ\"ד מועד א'", "date": "04.03.2024", "id": "24AA-6b"}, {"num": "7", "type": "open", "topic": "sync", "sub": "סמפורים", "q": "במסעדת מזון מהיר יש 3 סוגי עובדים: קופאים שלוקחים הזמנות, טבחים שמכינים את האוכל, ועובדי הגשה שמוסרים את האוכל ללקוחות. כל עובד מיוצג על ידי חוט, ונתונות הפונקציות הבאות (אין צורך לממש אותן):\ntake_order() – חוסמת עד שמגיעה הזמנה חדשה, ואז חוזרת. לא בטוחה לשימוש במקביל (אסור לקרוא לה בו-זמנית מכמה חוטים).\ncook_order() – מכינה את ההזמנה הבאה לפי הסדר, וחוסמת עד שהאוכל מוכן. בטוחה לשימוש במקביל, אבל אסור לקרוא לה אם אין הזמנה שממתינה להכנה.\nserve_order() – מגישה את ההזמנה המוכנה הבאה לפי הסדר, וחוסמת עד שהיא הוגשה. בטוחה לשימוש במקביל, אבל אסור לקרוא לה אם אין הזמנה מוכנה שממתינה להגשה.\nהרצף התקין: קופאי קורא ל-take_order, וכשהיא חוזרת הוא מודיע שיש הזמנה ממתינה. אז טבח קורא ל-cook_order, וכשהיא חוזרת הוא מודיע שיש הזמנה מוכנה. אז עובד הגשה קורא ל-serve_order.\nייתכנו כמה עובדים מכל סוג, ומספרם לא ידוע מראש.\nכתבו את הפונקציה הראשית של כל עובד. מותר להשתמש בסמפורים בלבד, ואפשר להניח שהם הוגנים. תארו בקצרה את הפתרון וכתבו קוד ברור.", "answer": "mutex מבטיח שרק קופאי אחד קורא ל-take_order בכל רגע. orders סופר הזמנות שממתינות להכנה, ו-cooked סופר הזמנות מוכנות שממתינות להגשה.\n\nsem_t mutex;           // init to 1\nsem_t orders, cooked;  // init to 0\n\nvoid* cashier(void *arg) {\n    while (1) {\n        sem_wait(&mutex);\n        take_order();          // receive order exclusively\n        sem_post(&mutex);\n        sem_post(&orders);     // order received, ready to cook\n    }\n}\n\nvoid* cook(void* arg) {\n    while (1) {\n        sem_wait(&orders);\n        cook_order();\n        sem_post(&cooked);     // order cooked, ready to serve\n    }\n}\n\nvoid* serve_worker(void* arg) {\n    while (1) {\n        sem_wait(&cooked);\n        serve_order();\n    }\n}\n\nטבח קורא ל-cook_order רק אחרי שהוריד את orders – כלומר רק אם יש הזמנה שממתינה. כך גם עובד הגשה עם cooked. cook_order ו-serve_order בטוחות לשימוש במקביל, ולכן לא צריך סביבן מנעול.", "official": "כמו כאן.", "expl": "", "check": "לפי הפתרון הרשמי", "exam": "24AA", "examLabel": "סמסטר א' תשפ\"ד מועד א'", "date": "04.03.2024", "id": "24AA-7"}, {"num": "8", "type": "open", "topic": "fs", "sub": "Journaling", "intro": "נתונה מערכת קבצים VSFS עם journaling:\nגודל בלוק 4KB, גודל inode ‏256 בתים.\nבכל inode יש 6 מצביעים ישירים, 2 עקיפים, 1 עקיף כפול ו-1 עקיף משולש.\nהמערכת לא משתמשת ב-metadata journaling – כלומר גם ה-DATA של כל פעולה נכתב ל-journal.\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "8.1", "q": "משתמש יצר קובץ חדש (ריק) בנתיב /home/mta/a.txt. פרטו את כל הגישות לדיסק (כולל ה-journal) לביצוע הפעולה במלואה, לפי הסדר הנדרש, במקרה המינימלי. לכל גישה ציינו אם היא קריאה או כתיבה, לאן ניגשים ולמה, וציינו היכן ממתינים לסיום כתיבות (fsync). אין צורך במספרי בלוקים – רק סוג הבלוק.", "answer": "במקרה המינימלי, כל ה-inodes הדרושים נמצאים באותו בלוק, וגם כל ה-bitmaps.\n\nמציאת התיקייה:\n1. קריאת הבלוק עם inode 2 – השורש (יחד עם כל שאר ה-inodes הדרושים)\n2. קריאת בלוק הנתונים של /\n3. קריאת בלוק הנתונים של /home (ה-inode כבר זמין)\n4. קריאת בלוק הנתונים של /home/mta\n5. קריאת ה-inode bitmap – למציאת inode פנוי\n\nכתיבה ל-journal (בלי metadata journaling):\n6. כתיבת טרנזקציה ללוג, בלי TxE: ה-inode של הקובץ החדש, ה-inode bitmap המעודכן, ה-inode המעודכן של /home/mta, ובלוק הנתונים המעודכן של /home/mta\n7. fsync\n8. סגירת הטרנזקציה – כתיבת TxE\n9. fsync\n\ncheckpoint – כתיבה למקומות הקבועים:\n10. כתיבת ה-inode bitmap המעודכן\n11. כתיבת ה-inode של /home/mta יחד עם ה-inode של הקובץ (באותו בלוק)\n12. כתיבת בלוק הנתונים של /home/mta (עם הרשומה של הקובץ החדש)"}, {"label": "8.2", "q": "מבין הגישות בסעיף הקודם, מה הגישה הראשונה שאחריה אפשר להבטיח בוודאות שהפעולה תתבצע בהצלחה, גם אם המערכת תקרוס?", "answer": "אחרי סגירת הטרנזקציה – כתיבת ה-TxE (שלב 8).\n\nמהרגע שה-TxE בדיסק, הטרנזקציה שלמה בלוג. אם המערכת קורסת לפני ה-checkpoint או באמצעו, בזמן ההתאוששות נריץ מחדש (replay) את הטרנזקציה מהלוג. לפני ה-TxE – טרנזקציה בלי סוף נזרקת, והפעולה לא תתבצע."}], "official": "8.1: כמו כאן. (תשובות שהניחו קיום cache קיבלו את מלוא הנקודות.) 8.2: אחרי סגירת הטרנזקציה בשלב 8.", "expl": "טעות נפוצה שגררה הורדת ניקוד משמעותית: לכתוב טרנזקציה ללוג כבר בשלב הראשון. אי אפשר לעשות את זה לפני שיודעים מה הפרטים שצריך לכתוב לטרנזקציה – ובשביל זה צריך קודם לקרוא את התיקיות וה-bitmap.", "check": "לפי הפתרון הרשמי", "exam": "24AA", "examLabel": "סמסטר א' תשפ\"ד מועד א'", "date": "04.03.2024", "id": "24AA-8"}, {"num": "9", "type": "open", "topic": "disk", "sub": "RAID-5", "q": "שאלת בונוס. נתונה מערכת RAID-5 עם 6 דיסקים קשיחים (ממוספרים 1–6). בלוק ה-parity ב-stripe הראשון נמצא בדיסק 6, ב-stripe השני בדיסק 5, וכן הלאה באופן מעגלי.\nהבלוקים ממוספרים מ-0: הבלוק הלוגי הראשון במערך הוא 0, והבלוק הפיזי הראשון בכל דיסק הוא 0. לכן ה-stripe הראשון מכיל את הבלוקים הלוגיים 0–4.\nבוצעה גישה לבלוק לוגי 535. לאיזה דיסק ולאיזה בלוק בדיסק תתבצע הגישה בפועל?", "answer": "דיסק 2, בלוק 107.\n\nבכל stripe יש 5 בלוקי מידע (ועוד בלוק parity):\n535 / 5 = 107, שארית 0\nכלומר בלוק 535 הוא בלוק המידע הראשון ב-stripe מספר 107.\n\nמיקום ה-parity חוזר כל 6 stripes:\n107 mod 6 = 5\nstripe 0 – דיסק 6, ‏stripe 1 – דיסק 5, ..., ‏stripe 5 – דיסק 1. לכן ב-stripe ‏107 ה-parity בדיסק 1.\n\nבלוק המידע הראשון הוא בדיסק שאחריו – דיסק 2. ובכל דיסק, ה-stripe ה-107 הוא הבלוק הפיזי 107.", "official": "דיסק 2, בלוק 107.", "expl": "", "check": "חושב", "exam": "24AA", "examLabel": "סמסטר א' תשפ\"ד מועד א'", "date": "04.03.2024", "id": "24AA-9"}, {"num": "1", "type": "mcq", "topic": "memory", "sub": "Swapping", "q": "מהו ה-swap space?", "options": ["מקום בדיסק שמשמש לשמירת קבצים.", "מקום בזיכרון הפיזי שמשמש להחלפת תהליכים.", "מקום במחסנית (stack) שמשמש להחלפת משתנים.", "מקום בקרנל שמשמש כזיכרון מטמון לתרגום כתובות וירטואליות.", "כל התשובות האחרות אינן נכונות."], "correct": 4, "official": "כל התשובות האחרות אינן נכונות. אזור ההחלפה (swap space) הוא אזור בדיסק שמשמש לאחסון זיכרון של תהליכים.", "expl": "ה-swap space אכן נמצא בדיסק – אבל הוא לא משמש לשמירת קבצים, אלא לדפים של תהליכים שפונו מהזיכרון הפיזי. זיכרון מטמון לתרגום כתובות הוא ה-TLB, והוא בחומרה ולא בקרנל.", "check": "לפי הפתרון הרשמי", "exam": "24AB", "examLabel": "סמסטר א' תשפ\"ד מועד ב'", "date": "22.03.2024", "id": "24AB-1"}, {"num": "2", "type": "mcq", "topic": "memory", "sub": "גודל טבלת דפים", "q": "אחת הבעיות של טבלאות דפים לינאריות היא כמות הזיכרון שהן תופסות. מה יכול לעזור להתמודד עם הבעיה?", "options": ["TLB.", "הגדלת גודל הדף.", "זיכרון משני (HDD).", "זיכרון מטמון (cache).", "כל התשובות האחרות אינן נכונות."], "correct": 1, "official": "הגדלת גודל הדף. עם דפים גדולים יותר יש פחות רשומות בטבלת הדפים, ולכן כל טבלה תופסת פחות זיכרון.", "expl": "גודל טבלה לינארית = (גודל מרחב הכתובות / גודל דף) · גודל PTE. הכפלת גודל הדף מחצה את מספר הרשומות. (המחיר: יותר פרגמנטציה פנימית.) ה-TLB וה-cache משפרים את מהירות הגישה, אבל לא משנים את גודל הטבלה.", "check": "לפי הפתרון הרשמי", "exam": "24AB", "examLabel": "סמסטר א' תשפ\"ד מועד ב'", "date": "22.03.2024", "id": "24AB-2"}, {"num": "3", "type": "mcq", "topic": "threads", "sub": "מנעולים ו-spinning", "q": "נתונה הטענה: תמיד נעדיף מנעול שלא מבצע spinning.", "options": ["הטענה נכונה.", "הטענה נכונה רק במחשב עם מעבד יחיד.", "הטענה נכונה רק כשבמחשב יש כמה מעבדים.", "הטענה לא נכונה: תמיד נעדיף מנעול שכן מבצע spinning.", "כל התשובות האחרות אינן נכונות."], "correct": 1, "official": "הטענה נכונה רק במחשב עם מעבד יחיד. במעבד יחיד ה-spinning על מנעול תפוס תמיד מיותר. עם יותר מעבדים הטענה לא תמיד נכונה – למשל אם הקטע הקריטי קצר מאוד, ייתכן שעדיף להמתין בסחרור.", "expl": "במעבד יחיד, כל עוד החוט מסתחרר, החוט שמחזיק במנעול לא רץ – אז המנעול בטוח לא ישתחרר עד סוף הקוונטום. במערכת מרובת מעבדים, המחזיק רץ במקביל, ואם הוא עומד לשחרר תוך רגע, סחרור קצר זול יותר משתי החלפות הקשר (להירדם ולהתעורר).", "check": "לפי הפתרון הרשמי", "exam": "24AB", "examLabel": "סמסטר א' תשפ\"ד מועד ב'", "date": "22.03.2024", "id": "24AB-3"}, {"num": "4", "type": "mcq", "topic": "threads", "sub": "מקביליות", "intro": "להלן קוד של שני חוטים שרצים בו-זמנית במערכת עם מעבד יחיד. כל המשתנים משותפים לשני החוטים, ו-x מאותחל ל-0.", "code": "Thread 1                      Thread 2\nfor (j = 1; j <= 4; ++j)      for (i = 1; i <= 6; ++i)\n    x = x + 1;                    x = x + 1;", "q": "מהו הערך המקסימלי של x בסיום הריצה של שני החוטים?", "options": ["5", "8", "9", "10", "כל התשובות האחרות אינן נכונות."], "correct": 3, "official": "10. הערך המקסימלי מתקבל כששני החוטים מקדמים את המשתנה בלי הפרעות – 10 קידומים בסך הכל.", "expl": "אם כל הוספה (קריאה, חיבור, כתיבה) מתבצעת בלי שהחוט השני נכנס באמצע, אף קידום לא הולך לאיבוד:\n4 + 6 = 10", "check": "נבדק בסריקה ממוחשבת של כל התזמונים", "exam": "24AB", "examLabel": "סמסטר א' תשפ\"ד מועד ב'", "date": "22.03.2024", "id": "24AB-4"}, {"num": "5", "type": "mcq", "topic": "threads", "sub": "מקביליות", "intro": "להלן קוד של שני חוטים שרצים בו-זמנית במערכת עם מעבד יחיד. כל המשתנים משותפים לשני החוטים, ו-x מאותחל ל-0.", "code": "Thread 1                      Thread 2\nfor (j = 1; j <= 4; ++j)      for (i = 1; i <= 6; ++i)\n    x = x + 1;                    x = x + 1;", "q": "מהו הערך המינימלי של x בסיום הריצה של שני החוטים?", "options": ["1", "2", "4", "6", "כל התשובות האחרות אינן נכונות."], "correct": 1, "official": "במפתח הרשמי סומנה התשובה \"כל התשובות האחרות אינן נכונות\", אבל ההסבר הרשמי עצמו אומר: \"הערך המינימלי בקוד מהסוג הזה הוא תמיד 2\".", "note": "סתירה בפתרון הרשמי: האות שסומנה היא \"כל התשובות האחרות אינן נכונות\", אבל ההסבר שם אומר שהמינימום הוא 2 – וזו אחת האפשרויות. בבדיקה ממוחשבת של כל התזמונים (4 ו-6 קידומים) המינימום הוא אכן 2, ולכן התשובה הנכונה כאן היא 2.", "expl": "תזמון שמגיע ל-2:\nחוט 1 קורא 0 ונעצר לפני הכתיבה.\nחוט 2 מבצע 5 קידומים מתוך 6, ונעצר לפני האחרון.\nחוט 1 כותב 1 – ומוחק את כל הקידומים של חוט 2.\nחוט 2 קורא 1 ונעצר לפני הכתיבה.\nחוט 1 משלים את 3 הקידומים שנשארו לו.\nחוט 2 כותב 2 – ומסיים.\n\nלמה לא 1? הכתיבה האחרונה של כל חוט באה אחרי קריאה שבאה אחרי הכתיבה הקודמת שלו, שכתבה לפחות 1. לכן הערך האחרון שנכתב הוא לפחות 2. (זה אותו טיעון כמו בשאלה 7.1 במבחן 23AB.)", "check": "נבדק בסריקה ממוחשבת של כל התזמונים", "exam": "24AB", "examLabel": "סמסטר א' תשפ\"ד מועד ב'", "date": "22.03.2024", "id": "24AB-5"}, {"num": "6", "type": "open", "topic": "memory", "sub": "טבלה היררכית", "intro": "נתונה מערכת שבה כתובת וירטואלית היא 32 ביטים, כתובת פיזית 40 ביטים, וגודל דף 4KB. כל כניסה בטבלת הדפים תופסת 4 בתים.\nבמערכת יש תהליך שמשתמש ב-128KB של נתונים החל מכתובת 0, וכל גישה לכתובת גדולה או שווה ל-128K גורמת לשגיאה.\nהנתונים האלה תקפים לכל הסעיפים. נתונים שכתובים בתוך סעיף מסוים תקפים רק לאותו סעיף.\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "6.1", "q": "התהליך משתמש בטבלת דפים לינארית. כמה זיכרון (בבתים) תופסת הטבלה, וכמה כניסות בה הן valid?", "answer": "גודל הטבלה 4MB, ו-32 כניסות valid.\n\nהיסט:\n4KB = 2^12, כלומר 12 ביטים\n\nמספר דף:\n32 − 12 = 20 ביטים, כלומר 2^20 דפים\n\nגודל הטבלה:\n2^20 · 4B = 2^22 = 4MB\n\nכניסות valid:\n128KB / 4KB = 32 דפים, החל מדף 0"}, {"label": "6.2", "q": "התהליך משתמש בטבלת דפים היררכית, וגודל כל חלק בטבלה הוא דף. כמה רמות יהיו, כמה זיכרון יתפסו כל הטבלאות יחד, וכמה כניסות valid יהיו בסך הכל בכל הרמות?", "answer": "2 רמות, 8KB, ו-33 כניסות valid.\n\nכניסות בכל חלק:\n4KB / 4B = 1024 = 2^10, כלומר 10 ביטים לרמה\n\n20 ביטים של מספר דף:\n10 + 10, כלומר 2 רמות\n\n32 הדפים (0 עד 31) נכנסים כולם בחלק הראשון של הרמה התחתונה. לכן יש חלק אחד ברמה העליונה וחלק אחד ברמה התחתונה:\n2 דפים = 8KB\n\nכניסות valid:\nרמה עליונה: 1\nרמה תחתונה: 32\nסך הכל 33"}, {"label": "6.3", "q": "תהליך אחר משתמש בטבלת דפים היררכית (כל חלק בגודל דף), ובכתובות הבאות:\ncode segment בגודל 48KB, החל מכתובת 0x1000000.\ndata segment בגודל 600KB, החל מכתובת 0x8000000.\nstack segment בגודל 64KB, החל מכתובת 0xF0000000 (וגדל לכתובות הגבוהות).\nכל גישה לכתובת אחרת גורמת לשגיאה. כמה זיכרון יתפסו כל הטבלאות יחד, וכמה כניסות valid יהיו בסך הכל?", "answer": "16KB, ו-181 כניסות valid.\n\nכמו בסעיף הקודם – 2 רמות, 10 ביטים לכל רמה. 10 הביטים העליונים של הכתובת קובעים את החלק ברמה התחתונה (כל חלק מכסה 4MB).\n\ncode: ‏0x1000000 / 4MB = 4, וכל 48KB נשארים באותו חלק\nכניסות valid: ‏48K / 4K = 12\n\ndata: ‏0x8000000 / 4MB = 32, וכל 600KB נשארים באותו חלק\nכניסות valid: ‏600K / 4K = 150\n\nstack: ‏0xF0000000 / 4MB = 960, וכל 64KB נשארים באותו חלק\nכניסות valid: ‏64K / 4K = 16\n\n3 חלקים שונים ברמה התחתונה, ועוד אחד ברמה העליונה:\n4 דפים = 16KB\n\nכניסות valid:\n3 ברמה העליונה + 12 + 150 + 16 = 181"}], "official": "6.1: ‏4MB, ‏32. 6.2: ‏2 רמות, 8KB, ‏33. 6.3: ‏16KB, ‏181.", "expl": "", "check": "חושב", "exam": "24AB", "examLabel": "סמסטר א' תשפ\"ד מועד ב'", "date": "22.03.2024", "id": "24AB-6"}, {"num": "7", "type": "open", "topic": "sync", "sub": "משתני תנאי", "q": "בבנק מפתחים ארנק דיגיטלי להעברת כספים בין לקוחות. יש N לקוחות (קבוע וידוע), והמערך הגלובלי balance מחזיק את היתרה של כל לקוח: תא i הוא היתרה של לקוח i. יתרה של לקוח לעולם לא תהיה שלילית.\nהפעולות:\nint getBalance(int c) – מחזירה את היתרה הנוכחית של לקוח c.\nint transfer(int c1, int c2, int amount) – מעבירה amount מלקוח c1 ללקוח c2. הפעולה חוסמת: אם אין ל-c1 מספיק כסף, החוט מחכה עד שאפשר לבצע את ההעברה בהצלחה. היא מחזירה את היתרה של c1 מיד אחרי ההעברה.\nכל הפרמטרים תקינים (מזהים בין 0 ל-N−1, סכומים גדולים מ-0). כל פעולה צריכה להתבצע באופן אטומי, חוטים שונים יכולים לקרוא לפעולות במקביל, והפתרון צריך להיות יעיל ככל האפשר.\nמותר להשתמש במנעולים ובמשתני תנאי בלבד. תארו בקצרה את הפתרון וכתבו קוד ברור.", "code": "#define N ??          // number of clients\nint balance[N];       // balance for all clients", "answer": "מנעול לכל לקוח, כדי שהעברות בין זוגות לקוחות שונים ירוצו במקביל. כדי למנוע קיפאון, תמיד תופסים את שני המנעולים לפי סדר גלובלי – קודם את המספר הנמוך.\n\nכשאין מספיק כסף, ממתינים על משתנה תנאי של c1 (בלי לבזבז מעבד). מי שמעביר כסף ל-c2 מעיר את כל מי שמחכה על c2.\n\npthread_mutex_t locks[N];   // init all\npthread_cond_t cv[N];       // init all\n\nint getBalance(int c) {\n    pthread_mutex_lock(&locks[c]);\n    int b = balance[c];\n    pthread_mutex_unlock(&locks[c]);\n    return b;\n}\n\nint transfer(int c1, int c2, int amount) {\n    int lo = MIN(c1, c2), hi = MAX(c1, c2);\n    pthread_mutex_lock(&locks[lo]);\n    pthread_mutex_lock(&locks[hi]);\n    while (balance[c1] < amount) {\n        pthread_mutex_unlock(&locks[c2]);         // keep only c1's lock\n        pthread_cond_wait(&cv[c1], &locks[c1]);   // wait for a deposit\n        pthread_mutex_unlock(&locks[c1]);\n        pthread_mutex_lock(&locks[lo]);           // re-lock in order\n        pthread_mutex_lock(&locks[hi]);\n    }\n    balance[c1] -= amount;\n    balance[c2] += amount;\n    int res = balance[c1];\n    pthread_cond_broadcast(&cv[c2]);              // c2 got money\n    pthread_mutex_unlock(&locks[hi]);\n    pthread_mutex_unlock(&locks[lo]);\n    return res;\n}\n\nלמה משחררים ותופסים מחדש? כשמתעוררים מ-cond_wait מחזיקים רק את המנעול של c1. אם c1 > c2, תפיסת המנעול של c2 עכשיו הייתה הפרה של הסדר הגלובלי (סכנת קיפאון). לכן משחררים הכל, תופסים שוב לפי הסדר, ובודקים שוב את התנאי.\n\nלמה אין lost signal? מי שמפקיד ל-c1 חייב להחזיק את המנעול של c1, ואנחנו מחזיקים אותו עד שנכנסים ל-cond_wait (שמשחרר אותו באופן אטומי).\n\nbroadcast ולא signal – כי כמה חוטים יכולים לחכות על אותו לקוח עם סכומים שונים, ואולי רק חלקם יכולים להתקדם.", "official": "הפתרון הרשמי משתמש במנעול לכל לקוח עם תפיסה לפי סדר גלובלי (MIN ואז MAX), אבל בהמתנה פעילה: אם אין מספיק כסף, הוא משחרר את המנעולים ומנסה שוב בלולאה. getBalance שם מחזירה את balance[c] בלי מנעול.", "note": "הפתרון הרשמי עובד, אבל עם המתנה פעילה (spinning) – בזמן שאין מספיק כסף החוט שורף מעבד. כיוון שהשאלה מבקשת פתרון יעיל ומאפשרת משתני תנאי, הפתרון כאן משתמש במשתנה תנאי לכל לקוח. שתי הגרסאות נכונות מבחינת מניעה הדדית וקיפאון.", "expl": "הקוד כאן הורץ עם 8 חוטים ו-5 לקוחות, ‏800,000 העברות שחלקן נאלצו לחכות: סכום היתרות נשמר, אף יתרה לא ירדה מתחת ל-0, ואין קיפאון.", "check": "הורץ עם חוטים אמיתיים", "exam": "24AB", "examLabel": "סמסטר א' תשפ\"ד מועד ב'", "date": "22.03.2024", "id": "24AB-7"}, {"num": "8", "type": "open", "topic": "fs", "sub": "Journaling", "intro": "במערכת קבצים VSFS שמשתמשת ב-journaling כפי שנלמד (כולל metadata journaling) יש בעיה: בעדכון נתונים של בלוק DATA קיים, קריסה בתרחישים מסוימים עדיין עלולה לשבש את מערכת הקבצים.\nלהלן רצף הפעולות על הדיסק למחיקת קובץ מתיקייה, כשלקובץ יש לפחות hard link אחד נוסף, לתיקייה יש בלוק DATA יחיד, ומספרי ה-inode של התיקייה והקובץ ידועים:\n1. קריאת בלוק ה-inode שמכיל את ה-inode של התיקייה\n2. קריאת בלוק ה-inode שמכיל את ה-inode של הקובץ\n3. קריאת בלוק ה-DATA הראשון (והיחיד) של התיקייה\n4. כתיבת טרנזקציה ללוג: TxB, ה-inode של התיקייה וה-inode של הקובץ, בלי TxE\n5. כתיבה לבלוק ה-DATA של התיקייה (בלי הרשומה של הקובץ)\n6. fsync\n7. כתיבת TxE לטרנזקציה\n8. fsync\n9. עדכון ה-inode של התיקייה (כתיבה לבלוק שמכיל אותו)\n10. עדכון ה-inode של הקובץ (כתיבה לבלוק שמכיל אותו)", "parts": [{"label": "8.1", "q": "אחרי איזה שלב (1–10) קריסה עלולה לגרום לבעיה במערכת הקבצים? הסבירו בקצרה מדוע.", "answer": "אחרי שלב 5 (או 6).\n\nבלוק ה-DATA של התיקייה כבר נכתב למקום הקבוע שלו – בלי הרשומה של הקובץ – אבל הטרנזקציה עוד לא נסגרה (אין TxE). בהתאוששות הטרנזקציה נזרקת, ולכן ה-inodes לא מתעדכנים: התיקייה כבר לא מכילה את הקישור לקובץ, אבל זמן העדכון והגודל של התיקייה לא השתנו, ומספר ה-links ב-inode של הקובץ לא ירד. מערכת הקבצים לא עקבית."}, {"label": "8.2", "q": "תנו שני תרחישים של כתיבה לקובץ שלא מוסיפים לו בלוק DATA חדש: באחד קריסה עלולה לגרום לבעיה, ובשני אף קריסה לא תגרום לבעיה. אין צורך ברצף הפעולות המלא – רק תארו את התרחיש ואיפה הבעיה, או למה אין בעיה.", "answer": "תרחיש בעייתי – שכתוב של נתונים קיימים בקובץ. אם קורסים אחרי שהנתונים נכתבו (במקום) ולפני סגירת הטרנזקציה, הנתונים כבר השתנו, אבל ה-inode לא עודכן (למשל זמן השינוי האחרון).\n\nתרחיש לא בעייתי – הוספת נתונים לסוף הקובץ (בתוך הבלוק האחרון, שעוד יש בו מקום). אם קורסים לפני סגירת הטרנזקציה, ה-inode לא עודכן – גודל הקובץ לא השתנה – ולכן פשוט מתעלמים מהנתונים שנוספו. אם קורסים אחרי סגירת הטרנזקציה, ההתאוששות משלימה את העדכון ואין בעיה."}, {"label": "8.3", "q": "הציעו פתרון לבעיה. הפתרון עדיין צריך להיות metadata journaling – ה-DATA לא נכתב ללוג, ונכתב פעם אחת בלבד למיקומו הסופי – אבל קריסה בכל שלב לא תגרום לבעיה. תארו בקצרה מה הפתרון כולל, אילו פעולות דיסק נוספות הוא גורר (או עלול לגרור), ולמה הוא פותר את הבעיה.", "answer": "אף פעם לא כותבים לבלוק קיים. בכל עדכון של נתונים בבלוק קיים, מקצים בלוק חדש וכותבים אליו את הנתונים המעודכנים. כחלק מהטרנזקציה תופסים את הבלוק החדש (bitmap), מעדכנים את המצביע ב-inode, ומשחררים את הבלוק הישן.\n\nכך, אם קורסים לפני סגירת הטרנזקציה – ה-inode עדיין מצביע לבלוק הישן, שלא השתנה. אם קורסים אחריה – ההתאוששות מעדכנת את המצביע לבלוק החדש, שכבר נכתב.\n\nהמחיר: עדכון כזה עלול לגרור עדכונים של בלוקי DATA נוספים – בלוקי מצביעים (עקיפים) – ואותם מעדכנים באותה שיטה (כמו copy-on-write)."}], "official": "8.1: אחרי שלב 5 או 6. 8.2 ו-8.3: כמו כאן.", "expl": "", "check": "לפי הפתרון הרשמי", "exam": "24AB", "examLabel": "סמסטר א' תשפ\"ד מועד ב'", "date": "22.03.2024", "id": "24AB-8"}, {"num": "9", "type": "open", "topic": "disk", "sub": "RAID-4", "q": "שאלת בונוס. נתונה מערכת RAID-4 עם chunk של בלוק אחד ו-4 דיסקים (ממוספרים 1–4). לכל דיסק:\nמהירות סיבוב 7500 RPM, זמן seek ממוצע 10ms, בכל רצועה 8 בלוקים, וקצב ההעברה תוכנן כך שרצועה שלמה מועברת בזמן סיבוב אחד בדיוק.\nמשתמש ביצע פעולת כתיבה אחת לבלוקים הלוגיים 100–102 (הבלוקים הלוגיים ממוספרים מ-0), ואף cache לא מכיל מידע רלוונטי. מהו הזמן הקצר ביותר שבו הפעולה יכולה להתבצע? אפשר להניח כל תרחיש שמוביל לזמן הקצר ביותר, כל עוד הוא עומד בנתונים.", "answer": "התשובה הרשמית: 10ms (עם parity חיסורי).\n\nזמן סיבוב:\n60,000ms / 7500 = 8ms\nבלוק אחד (מתוך 8 ברצועה): 1ms\n\nנניח שדיסק הזוגיות הוא דיסק 4. יש 3 בלוקי מידע ב-stripe:\n100 / 3 = 33, שארית 1 – בלוקים 100–101 ב-stripe ‏33, בדיסקים 2 ו-3\n102 / 3 = 34, שארית 0 – בלוק 102 ב-stripe ‏34, בדיסק 1\n\nבמקרה האידיאלי הראש כבר במקום בתחילת הפעולה – בלי seek ובלי המתנה לסיבוב.\n\nעם parity חיסורי (קוראים את הישן וכותבים את החדש):\nדיסקים 1–3: קריאת בלוק (1ms), המתנה לסיבוב עד אותו בלוק (7ms), כתיבה (1ms) – 9ms\nדיסק הזוגיות: קריאת 2 בלוקים רצופים (2ms), המתנה (6ms), כתיבה של שניהם (2ms) – 10ms\nהדיסקים עובדים במקביל, ודיסק הזוגיות הוא צוואר הבקבוק: 10ms.", "official": "10ms.", "note": "הפתרון הרשמי מניח parity חיסורי (subtractive) בשני ה-stripes. אם משתמשים ב-parity חיבורי (additive) – גם הוא נלמד – אפשר להגיע ל-3ms:\nדיסק 1: קורא את הבלוק הישן של stripe ‏33 (0–1ms), ואז כותב את 102 ב-stripe ‏34 (1–2ms).\nדיסקים 2, 3: כותבים את 100/101 ב-stripe ‏33 (0–1ms), ואז קוראים את הבלוקים שלהם ב-stripe ‏34 (1–2ms).\nדיסק 4: כותב את ה-parity של stripe ‏33 (חושב מהנתונים החדשים ומהבלוק שדיסק 1 קרא) ב-1–2ms, ואת ה-parity של stripe ‏34 ב-2–3ms.\nאין אף קריאה של parity, ולכן אין המתנה לסיבוב. במבחן כנראה מצפים ל-10ms, אבל כדאי לדעת שזה לא באמת המינימום.", "expl": "", "check": "חושב", "exam": "24AB", "examLabel": "סמסטר א' תשפ\"ד מועד ב'", "date": "22.03.2024", "id": "24AB-9"}, {"num": "1", "type": "open", "topic": "redir", "sub": "exec", "intro": "נתונה התוכנית הבאה.", "code": "int main (int argc, char *argv[]) {\n    int N = 2;\n    char* args[] = {\"echo\", \"Done\", NULL};\n    pid_t pid;\n    for (int i = 0; i < N; ++i) {\n        printf (\"%d %d\\n\", getpid(), i);\n        if (!fork())\n            printf (\"1: %d [%d]\\n\", getpid(), getppid());\n        else if (!fork())\n            printf (\"2: %d [%d]\\n\", getpid(), getppid());\n        else\n            break;   // exit for-loop\n    }\n    wait(NULL);\n    wait(NULL);\n    printf (\"pid = %d \", getpid());\n    execvp(args[0], args);\n    printf(\"BYE BYE\\n\");\n    return 0;\n}", "parts": [{"label": "1.1", "q": "כתבו פלט אפשרי של התוכנית, בהנחה שכל הקריאות ל-fork הצליחו. הניחו שמזהה התהליך הראשי הוא 100, וכל תהליך שנוצר מקבל את המזהה הבא (101, 102, וכן הלאה).", "answer": "פלט אפשרי (התשובה הצפויה במבחן), כשכל בן רץ עד הסוף לפני ההורה שלו:\n\n100 0\n1: 101 [100]\n101 1\n1: 102 [101]\npid = 102 Done\n2: 103 [101]\npid = 103 Done\npid = 101 Done\n2: 104 [100]\n104 1\n1: 105 [104]\npid = 105 Done\n2: 106 [104]\npid = 106 Done\npid = 104 Done\npid = 100 Done\n\nמה קורה:\nבכל איטרציה, תהליך יוצר בן ראשון (שמדפיס \"1:\" וממשיך בלולאה), ואז בן שני (שמדפיס \"2:\" וממשיך בלולאה), ואז יוצא מהלולאה עם break.\nכל תהליך שיוצא מהלולאה מחכה ל-2 ילדים (אם יש), מדפיס \"pid = ...\" ומריץ את echo, שמדפיס \"Done\". השורה \"BYE BYE\" לא מודפסת אף פעם – exec שהצליח לא חוזר.\n\nבני האיטרציה האחרונה (i = 1) מגיעים ל-i = 2 ויוצאים מהלולאה בלי ליצור ילדים."}, {"label": "1.2", "q": "כמה תהליכים נוצרו במהלך ריצת התוכנית, כולל התהליך הראשי?", "answer": "7. התהליך הראשי יוצר 2 בנים, וכל אחד מהם יוצר 2 בנים:\n1 + 2 + 4 = 7\n\nעץ התהליכים:\n\n[[TREE]]", "tree": ["100", "", [["101", "1:", [["102", "1:", []], ["103", "2:", []]]], ["104", "2:", [["105", "1:", []], ["106", "2:", []]]]]]}, {"label": "1.3", "q": "נניח ש-N לא ידוע (אבל לפחות 0). כמה תהליכים נוצרו, כולל הראשי, כפונקציה של N?", "answer": "2^(N+1) − 1.\n\nבאיטרציה הראשונה התהליך הראשי יוצר 2 בנים. בכל איטרציה, כל התהליכים שנוצרו באיטרציה הקודמת (ורק הם) יוצרים 2 בנים כל אחד:\n1 + 2 + 4 + ... + 2^N = 2^(N+1) − 1\n\nבדיקה: N = 0 נותן 1 (רק הראשי), ו-N = 2 נותן 7."}], "official": "1.1: פלט כמו כאן (עם \"pid = X Done\" לכל תהליך). 1.2: ‏7. 1.3: ‏2^(N+1) − 1.", "note": "1.1: בפלט הרשמי המזהה 103 מופיע לשני תהליכים שונים (\"2: 103 [101]\" וגם \"2: 103 [100]\") – זו טעות; הפלט כאן מתוקן עם מזהים עוקבים.\nחשוב יותר: בהרצה אמיתית הטקסט \"pid = X \" לא יודפס בכלל. ה-printf שלו בלי ירידת שורה, אז הוא נשאר ב-buffer של stdio, ו-exec מחליף את כל הזיכרון של התהליך – כולל ה-buffer – לפני שהוא נשפך. בהרצה על מסוף מקבלים רק \"Done\" לכל תהליך. ואם הפלט מופנה לצינור (./prog | cat), נעלמות גם כל השורות שלפני כן, ונשארות רק 7 שורות \"Done\". (נבדק בהרצה.) במבחן כנראה מצפים לפלט הרשמי – אבל כדאי להכיר את ההתנהגות האמיתית.", "expl": "", "check": "הורץ (על מסוף ועם צינור)", "exam": "24AC", "examLabel": "סמסטר א' תשפ\"ד מועד ג'", "date": "30.04.2024", "id": "24AC-1"}, {"num": "2", "type": "open", "topic": "sched", "sub": "Priority inversion", "intro": "מצב של priority inversion מתרחש כשאלגוריתם התזמון גורם לקיפאון, כי תהליך ממתין בהמתנה פעילה (busy-wait) למשאב שמוחזק על ידי תהליך אחר שלעולם לא מתוזמן.", "parts": [{"label": "2.1", "q": "באילו מאלגוריתמי התזמון הבאים אפשר להגיע ל-priority inversion: ‏FCFS, ‏SRTF עם overlap, ‏RR, ‏MLFQ עם כל השיפורים?", "answer": "", "atable": {"headers": ["אלגוריתם", "אפשרי?", "הסבר"], "rows": [["FCFS", "לא", "תהליך רץ מההתחלה ועד הסוף, ולכן לא ייתכן שהוא ממתין למשאב של תהליך אחר: התהליך האחר עוד לא רץ (ולא מחזיק במשאב), או שכבר הסתיים (ושחרר אותו)."], ["SRTF", "אפשרי", "תהליך ארוך עלול להחזיק במשאב שתהליך קצר ממתין לו (בהמתנה פעילה), בזמן שתהליכים קצרים אחרים מגיעים כל הזמן – ולכן הארוך לא מתוזמן."], ["RR", "לא", "כל תהליך יקבל זמן ריצה בסופו של דבר, וישחרר את המשאב."], ["MLFQ", "לא", "בגלל ה-priority boost, כל תהליך יקבל זמן ריצה בסופו של דבר."]]}}, {"label": "2.2", "q": "נתונים 3 חוטים של אותו תהליך (בקוד), ו-S, T, U סמפורים. אין חוטים נוספים. הסמפור S אותחל ל-1 (ערכי האתחול של T ו-U לא ידועים). האם קיימת ריצה שמובילה לקיפאון?", "code": "Thread 1               Thread 2               Thread 3\nwhile (1) {            while (1) {            while (1) {\n    sem_wait(&U);          sem_wait(&S);          sem_wait(&T);\n    printf(\"3\");           printf(\"2\");           printf(\"1\");\n    sem_post(&T);          sem_post(&U);          sem_post(&S);\n}                      }                      }", "answer": "לא קיימת.\n\nהסמפורים יוצרים מעגל: S ← חוט 2 ← U ← חוט 1 ← T ← חוט 3 ← S.\n\nכיוון ש-S = 1, חוט 2 יכול לבצע לפחות איטרציה אחת. היא מעלה את U, וזה מאפשר לחוט 1 לבצע איטרציה. היא מעלה את T, וזה מאפשר לחוט 3, שמעלה שוב את S – וחוזר חלילה. תמיד יש \"אסימון\" שמסתובב במעגל, ולכן תמיד יש חוט שיכול להתקדם."}, {"label": "2.3", "q": "האם קיימים ערכי אתחול ל-S, T, U כך שהפלט יהיה תמיד 1, ואז 2, ואז 3, שוב ושוב (123123123...)? אם כן – ציינו אותם והסבירו, אחרת – הסבירו מדוע לא.", "answer": "קיימים: S = 0, ‏T = 1, ‏U = 0.\n\nרק חוט 3 יכול להתחיל (T = 1), והוא מדפיס 1 ומעלה את S. עכשיו רק חוט 2 יכול לרוץ: מדפיס 2 ומעלה את U. אז רק חוט 1: מדפיס 3 ומעלה את T. וחוזר חלילה.\n\nבכל רגע רק אחד מהסמפורים הוא 1, ולכן רק חוט אחד יכול להתקדם – והסדר קבוע."}], "official": "2.1: FCFS לא, SRTF אפשרי, RR לא, MLFQ לא. 2.2: לא קיימת. 2.3: ‏S=0, ‏T=1, ‏U=0.", "expl": "", "check": "לפי הפתרון הרשמי ובדיקת המעגל", "exam": "24AC", "examLabel": "סמסטר א' תשפ\"ד מועד ג'", "date": "30.04.2024", "id": "24AC-2"}, {"num": "3", "type": "open", "topic": "fs", "sub": "VSFS", "intro": "נתונה מערכת קבצים VSFS עם הנתונים הבאים:\nגודל בלוק 512 בתים, גודל מצביע 8 בתים, גודל inode ‏512 בתים.\nבכל inode יש 10 מצביעים ישירים, מצביע עקיף אחד, מצביע עקיף כפול אחד ומצביע עקיף משולש אחד.", "parts": [{"label": "3.1", "q": "משתמש יצר קובץ חדש בגודל 50KB. לכמה בלוקים בדיסק צריך לכתוב כדי להשלים את הפעולה, במקרה המינימלי?", "answer": "108 בלוקים.\n\nמצביעים בבלוק:\n512 / 8 = 64\n\nבלוקי נתונים:\n50KB / 512B = 100\n10 ישירים + 64 דרך העקיף = 74, ונשארו 26 – דרך העקיף הכפול (בלוק כפול אחד ובלוק עקיף אחד מתחתיו).\n\nכתיבות:\ninode bitmap – 1\ndata bitmap – 1 (כל הביטים באותו בלוק)\nה-inode של הקובץ – 1 (inode בגודל בלוק, אז בלוק משלו)\n10 בלוקים ישירים – 10\nבלוק עקיף + 64 בלוקי נתונים – 65\nבלוק עקיף כפול + בלוק עקיף + 26 בלוקי נתונים – 28\nבלוק ה-DATA של התיקייה (רשומה חדשה) – 1\nה-inode של התיקייה (זמן שינוי) – 1\n\nסך הכל:\n1 + 1 + 1 + 10 + 65 + 28 + 1 + 1 = 108\n\nה-inode של התיקייה וה-inode של הקובץ לא יכולים להיות באותו בלוק, כי בכל בלוק נכנס רק inode אחד."}, {"label": "3.2", "q": "מה הגודל המקסימלי של קובץ, וכמה בלוקי DATA הוא יתפוס?", "answer": "גודל מקסימלי:\n(10 + 64 + 64² + 64³) · 512B = 266,314 · 512 = 136,352,768 בתים (בערך 130MB)\n\nבלוקים:\n10 ישירים\nעקיף: 1 בלוק מצביעים + 64 נתונים\nעקיף כפול: 1 + 64 בלוקי מצביעים + 64² נתונים\nעקיף משולש: 1 + 64 + 64² בלוקי מצביעים + 64³ נתונים\n\nסך הכל:\n10 + (1 + 64) + (1 + 64 + 64²) + (1 + 64 + 64² + 64³) = 270,541 בלוקים\n\n(גם בלוקי המצביעים נמצאים ב-data region, ולכן נספרים.)"}, {"label": "3.3", "q": "סטודנט טען שקריאה של 4 קבצים שונים בגודל 25KB כל אחד דורשת פחות קריאות של בלוקים מהדיסק מאשר קריאה של קובץ אחד בגודל 100KB. האם הוא צודק?", "answer": "הסטודנט טועה: 208 קריאות לעומת 205.\n\nקובץ של 25KB הוא 50 בלוקים:\ninode – 1\n10 ישירים – 10\nבלוק עקיף + 40 נתונים – 41\nסך הכל 52 לקובץ, ו-208 ל-4 הקבצים\n\nקובץ של 100KB הוא 200 בלוקים:\ninode – 1\n10 ישירים – 10\nבלוק עקיף + 64 נתונים – 65\nבלוק עקיף כפול + 2 בלוקים עקיפים מתחתיו + 64 + 62 נתונים – 129\nסך הכל 205\n\nלכל קובץ קטן משלמים מחדש על ה-inode ועל הבלוק העקיף, וזה יותר ממה שעולה העקיף הכפול של הקובץ הגדול."}], "official": "3.1: ‏108. 3.2: ‏(10 + 64 + 64² + 64³) · 512B, ו-10 + 1+64 + 1+64+64² + 1+64+64²+64³ בלוקים. 3.3: הסטודנט טועה (208 לעומת 205).", "note": "בפתרון הרשמי של 3.1 כתוב בהתחלה \"כתיבה ל-inode (אותו בלוק עם התיקייה המכילה את הקובץ)\", ובסוף \"לא ייתכן שה-inodes באותו בלוק כי נכנס רק אחד בבלוק\". הספירה עצמה (108) מתאימה לגרסה השנייה – inode בבלוק נפרד לכל אחד.", "expl": "", "check": "חושב", "exam": "24AC", "examLabel": "סמסטר א' תשפ\"ד מועד ג'", "date": "30.04.2024", "id": "24AC-3"}, {"num": "4", "type": "open", "topic": "disk", "sub": "RAID-5", "q": "שאלת בונוס. נתונה מערכת RAID-5 עם chunk של בלוק אחד ו-5 דיסקים (ממוספרים 1–5). בלוק ה-parity ב-stripe הראשון נמצא בדיסק 5, בשני בדיסק 4, וכן הלאה באופן מעגלי.\nלכל דיסק: מהירות סיבוב 6000 RPM, זמן seek ממוצע 15ms, בכל רצועה 5 בלוקים, וקצב ההעברה תוכנן כך שרצועה שלמה מועברת בזמן סיבוב אחד בדיוק.\nהבלוקים ממוספרים מ-0 (הבלוק הלוגי הראשון במערך הוא 0, והבלוק הפיזי הראשון בכל דיסק הוא 0). לכן ה-stripe הראשון מכיל את הבלוקים הלוגיים 0–3.\nדיסק 2 התקלקל, ואחר כך משתמש קרא את הבלוקים הלוגיים 20–22. אף cache לא מכיל מידע רלוונטי, והפעולה הצליחה בעזרת שאר הדיסקים, לפי אופן הפעולה של RAID-5.\nמהו הזמן הקצר ביותר שבו הפעולה יכולה להתבצע? יש להזניח זמן חישובים. אפשר להניח כל תרחיש שמוביל לזמן הקצר ביותר, כל עוד הוא עומד בנתונים.", "answer": "2ms.\n\nזמן סיבוב:\n60,000ms / 6000 = 10ms\nבלוק אחד (מתוך 5 ברצועה): 2ms\n\nבכל stripe יש 4 בלוקי מידע:\n20 / 4 = 5, כלומר בלוקים 20–23 הם stripe ‏5\nה-parity חוזר כל 5 stripes: ‏5 mod 5 = 0, כלומר כמו ב-stripe הראשון – בדיסק 5. בלוקים 20–23 בדיסקים 1–4.\n\nבלוק 21 נמצא בדיסק 2, שהתקלקל. כדי לשחזר אותו קוראים את כל שאר ה-stripe – בלוקים 20, 22, 23 ואת ה-parity – ומבצעים XOR.\n\nבמקרה הטוב ביותר, בכל הדיסקים הראש כבר במקום ואין המתנה לסיבוב. דיסקים 1, 3, 4, 5 קוראים כל אחד בלוק אחד במקביל:\nזמן הפעולה = קריאה של בלוק אחד = 2ms\n\n(בלוקים 20 ו-22 עצמם נקראים כחלק מהקריאה הזו.)", "official": "2ms.", "note": "בפתרון הרשמי כתוב שבלוק 22 הוא זה שנמצא בדיסק 2. לפי הפריסה שבשאלה (ה-stripe הראשון מכיל את 0–3 בדיסקים 1–4, ו-stripe ‏5 בנוי כמו הראשון), בדיסק 2 נמצא בלוק 21. התשובה הסופית לא משתנה – בכל מקרה צריך לקרוא את כל שאר ה-stripe במקביל.", "expl": "", "check": "חושב", "exam": "24AC", "examLabel": "סמסטר א' תשפ\"ד מועד ג'", "date": "30.04.2024", "id": "24AC-4"}, {"num": "1", "type": "mcq", "topic": "deadlock", "sub": "מניעת קיפאון", "q": "איך אפשר למנוע קיפאון במערכת שמשתמשת במנעולים כדי להגן על גישה למשאבים שונים?", "options": ["תמיד לתפוס את המנעולים בסדר קבוע.", "כשצריך לתפוס כמה מנעולים, לתפוס אותם \"בבת אחת\" (לוודא שחוט אחר לא מנסה לתפוס מנעולים במקביל אלינו).", "אם לא הצלחנו לתפוס מנעול, לשחרר את כל המנעולים שאנחנו מחזיקים ולנסות מחדש.", "להימנע לגמרי משימוש במנעולים ובמניעה הדדית.", "כל התשובות נכונות."], "correct": 4, "official": "כל התשובות נכונות. כל אחת מייצגת את אחת הטכניקות שנלמדו למניעת קיפאון.", "expl": "כל טכניקה שוברת אחד מ-4 התנאים:\nסדר קבוע – שובר המתנה מעגלית (circular wait).\nתפיסה בבת אחת – שוברת hold and wait.\nשחרור הכל וניסיון מחדש (trylock) – שובר no preemption.\nוויתור על מניעה הדדית (למשל מבני נתונים lock-free) – שובר mutual exclusion.", "check": "לפי הפתרון הרשמי", "exam": "24BA", "examLabel": "סמסטר ב' תשפ\"ד מועד א'", "date": "07.07.2024", "id": "24BA-1"}, {"num": "2", "type": "mcq", "topic": "process", "sub": "פסיקת שעון", "q": "נתונה מערכת הפעלה בלי תמיכה בפסיקת שעון. איזו טענה בהכרח נכונה?", "options": ["אי אפשר לטפל בפסיקות.", "אי אפשר לבצע context switch.", "תהליכים לעולם לא יהיו במצב READY.", "תהליכים לא יכולים לבצע קריאות מערכת.", "כל התשובות האחרות אינן נכונות."], "correct": 4, "official": "כל התשובות האחרות אינן נכונות. פסיקת שעון נועדה לעצור תהליכים כל פרק זמן קבוע ולהחזיר את השליטה לקרנל. בלעדיה מערכת ההפעלה ממשיכה לעבוד כרגיל, מלבד המנגנון הזה – אי אפשר לוודא שהשליטה תחזור לקרנל.", "expl": "בלי פסיקת שעון עדיין יש פסיקות אחרות (קלט/פלט), קריאות מערכת, ו-context switch כשתהליך נחסם או קורא ל-yield. תהליך שהתעורר מהמתנה עובר ל-READY. מה שחסר הוא רק ההפקעה (preemption): תהליך בלולאה אינסופית בלי קריאות מערכת יחזיק את המעבד לנצח.", "check": "לפי הפתרון הרשמי", "exam": "24BA", "examLabel": "סמסטר ב' תשפ\"ד מועד א'", "date": "07.07.2024", "id": "24BA-2"}, {"num": "3", "type": "mcq", "topic": "memory", "sub": "טבלה היררכית", "q": "במערכת עם טבלת דפים היררכית, תהליך ניגש לדף שהטבלה שמכילה את המיפוי שלו לא הוקצתה (תת-הטבלה המתאימה ברמה התחתונה לא קיימת). איזו טענה נכונה?", "options": ["התרגום יתבצע באופן תקין, אבל יתרחש page fault.", "התרגום יתבצע באופן תקין, ולא יתרחש page fault.", "אי אפשר לבצע את התרגום – הגישה תגרום לשגיאת זיכרון בתהליך.", "אי אפשר לבצע את התרגום – הגישה תגרום לשגיאה בקרנל (תקיעה/קריסה של המחשב).", "כל התשובות האחרות אינן נכונות."], "correct": 2, "official": "אי אפשר לבצע את התרגום – הגישה תגרום לשגיאת זיכרון בתהליך. אם הטבלה המתאימה לא הוקצתה, כל הרשומות שלה הן V=0, כלומר הן מייצגות זיכרון שהתהליך לא משתמש בו, וכל גישה לכתובת כזו גורמת לשגיאה בתהליך.", "expl": "בטבלה היררכית לא מקצים תת-טבלה לאזור שאין בו אף דף בשימוש – זה כל החיסכון. ב-PDE המתאים יהיה valid = 0, והגישה תסתיים ב-segmentation fault של התהליך. המחשב לא קורס.", "check": "לפי הפתרון הרשמי", "exam": "24BA", "examLabel": "סמסטר ב' תשפ\"ד מועד א'", "date": "07.07.2024", "id": "24BA-3"}, {"num": "4", "type": "mcq", "topic": "redir", "sub": "exec", "q": "נתון הקוד של תוכנית בשם myexec. הריצו אותה, ושורת הפלט הראשונה הייתה PID: 300. כל קריאות המערכת הצליחו, לא נוצרו תהליכים בקוד אחר במערכת, וכל תהליך מקבל מזהה גדול ב-1 מהתהליך שנוצר לפניו. איזו טענה נכונה?", "code": "int main()\n{\n    char* args[] = {\"myexec\", NULL};\n    printf(\"PID: %d\\n\", getpid());\n    execvp(args[0], args);\n}", "options": ["לא יהיה פלט נוסף לתוכנית.", "המשך הפלט יהיה \"PID: 300\" אינסוף פעמים (עד שעוצרים את התוכנית).", "המשך הפלט יהיה \"PID: 301\", אחר כך \"PID: 302\", וכן הלאה (עד שעוצרים את התוכנית).", "התוכנית תקרוס בשלב מסוים בגלל יצירה של יותר מדי תהליכים.", "כל התשובות האחרות אינן נכונות."], "correct": 1, "official": "\"PID: 300\" אינסוף פעמים. הקריאה ל-execvp מריצה שוב את main באותו תהליך (execvp לא יוצר תהליך חדש), ולכן הקוד הוא מעין לולאה אינסופית.", "expl": "exec מחליף את התוכנית שרצה בתהליך – אבל התהליך עצמו, וה-PID שלו, נשארים. לכן אף פעם לא נוצר תהליך חדש: כל הרצה של myexec מדפיסה את אותו PID ומריצה את עצמה מחדש. הרצה יבשה צעד אחר צעד יש בעמוד \"הפניות וצינורות\" באתר הלמידה.", "check": "הורץ (גם בעמוד הפניות באתר הלמידה)", "exam": "24BA", "examLabel": "סמסטר ב' תשפ\"ד מועד א'", "date": "07.07.2024", "id": "24BA-4"}, {"num": "5", "type": "mcq", "topic": "fs", "sub": "Journaling", "q": "נתונה מערכת קבצים VSFS שמשתמשת ב-journaling. איזו טענה בהכרח נכונה?", "options": ["קובץ לא יכול להכיל יותר נתונים מהמקום הפנוי ב-journal.", "קריאה מקובץ באופן סדרתי מתורגמת לגישה סדרתית לדיסק.", "שימוש ב-metadata journaling תמיד יהיה מהיר יותר מ-journaling רגיל.", "אם מובטח שהכתיבות לדיסק מתבצעות לפי הסדר שבו נשלחו, לא נצטרך fsync.", "כל התשובות נכונות."], "correct": 3, "official": "אם מובטח שסדר הכתיבות בדיסק הוא לפי הסדר שבו נשלחו, לא נצטרך fsync. השימוש ב-fsync נועד להבטיח שלא מבצעים כתיבה כלשהי לפני שהכתיבות שקדמו לה הסתיימו. אם מובטח שהכתיבות מתבצעות לפי הסדר, אין צורך ב-fsync.", "expl": "ב-journaling, ה-fsync מפריד בין שלבים: קודם הטרנזקציה (בלי TxE), אחר כך TxE, ורק אז ה-checkpoint. בלעדיו הדיסק עלול לסדר מחדש את הכתיבות, ו-TxE ייכתב לפני שהטרנזקציה עצמה בדיסק. אם הדיסק מבטיח סדר, ההפרדה הזו מתקבלת בחינם.\n\nשאר הטענות: הלוג מחזיק טרנזקציות זמניות (וכתיבה גדולה מתחלקת), לא את הקובץ כולו; VSFS לא מבטיח שבלוקים עוקבים בקובץ רציפים בדיסק; ו-metadata journaling לא תמיד מהיר יותר.", "check": "לפי הפתרון הרשמי", "exam": "24BA", "examLabel": "סמסטר ב' תשפ\"ד מועד א'", "date": "07.07.2024", "id": "24BA-5"}, {"num": "6", "type": "open", "topic": "memory", "sub": "LRU", "intro": "נתונה מערכת עם גודל דף של 1KB, שבה הזיכרון הווירטואלי גדול פי 2 מהזיכרון הפיזי. כל תהליך משתמש בטבלת דפים לינארית, וכל כניסה בטבלה היא 16 ביטים.\nאלה 10 ה-PTE הראשונים בטבלת הדפים של תהליך מסוים (עמודת \"דף\" לתיאור בלבד). P=Present, V=Valid, A=Access (Reference), D=Dirty.\nיש לפרט ולנמק את כל החישובים.", "table": {"headers": ["דף", "PFN", "V", "P", "A", "D", "ריפוד"], "rows": [["0", "00000", "1", "0", "0", "0", "0000000"], ["1", "00000", "0", "0", "0", "0", "0000000"], ["2", "11101", "1", "1", "1", "1", "0000000"], ["3", "00000", "0", "0", "0", "0", "0000000"], ["4", "00010", "1", "1", "1", "1", "0000000"], ["5", "00000", "1", "0", "0", "0", "0000000"], ["6", "01011", "1", "1", "1", "1", "0000000"], ["7", "00000", "1", "1", "0", "0", "0000000"], ["8", "11111", "1", "1", "0", "0", "0000000"], ["9", "00000", "1", "1", "0", "0", "0000000"]]}, "parts": [{"label": "6.1", "q": "כמה כניסות יש בטבלת הדפים המלאה? מה גודל הטבלה המלאה בבתים?", "answer": "64 כניסות, ‏128 בתים.\n\nדף של 1KB, כלומר היסט של 10 ביטים.\nלפי הטבלה ה-PFN הוא 5 ביטים, ולכן הכתובת הפיזית היא:\n5 + 10 = 15 ביטים, כלומר זיכרון פיזי של 32KB\n\nהזיכרון הווירטואלי כפול:\n64KB, כלומר כתובת של 16 ביטים\n\nמספר הכניסות:\n64KB / 1KB = 64\n\nגודל הטבלה:\n64 · 2B = 128 בתים"}, {"label": "6.2", "q": "התהליך ניגש לכתובת 0x1960. האם תתרחש פסיקת דף? אם כן – הסבירו, אחרת – מה הכתובת הפיזית?", "answer": "אין פסיקת דף. הכתובת הפיזית: 0x2D60.\n\nהכתובת היא 16 ביטים – 6 ביטים למספר הדף ו-10 להיסט:\n0x1960 = 000110 0101100000\n\nמספר הדף:\n000110 = 6\n\nלפי הטבלה, דף 6 נוכח (P = 1) במסגרת 01011 = 11. מחליפים את מספר הדף במספר המסגרת, וההיסט נשאר:\n01011 0101100000 = 0x2D60"}, {"label": "6.3", "q": "לכל הדפים שלא מופיעים בטבלה V = 1 ו-P = 0. התהליך ניגש לדפים הבאים, לפי הסדר: 2, 7, 8, 4, 15, 16, 17, 2, 4. כמה page faults יתרחשו עם LRU? יש להניח שכל page fault מפנה רק מסגרות שבשימוש התהליך, וטוען רק אליהן.", "answer": "4 page faults.\n\nבהתחלה התהליך מחזיק 6 מסגרות – הדפים עם P = 1: ‏2, 4, 6, 7, 8, 9.\n\n4 הגישות הראשונות (2, 7, 8, 4) הן לדפים בזיכרון – בלי page fault.\n\n15, 16, 17 לא בזיכרון – 3 page faults. LRU מפנה את הדפים שהגישה האחרונה אליהם הכי ישנה: קודם 6 ו-9 (לא ניגשנו אליהם בכלל ברצף הזה), ואחריהם 2 (הראשון מבין 2, 7, 8, 4).\n\nהגישה ל-2 – כבר פונה, page fault רביעי. מפנים את 7.\n\nהגישה ל-4 – עדיין בזיכרון.\n\nהסדר בין 6 ל-9 לא ידוע, אבל זה לא משנה – שניהם מפונים."}], "official": "6.1: זיכרון פיזי 32KB, וירטואלי 64KB. 6.2: ‏0x2D60. 6.3: ‏4 page faults.", "note": "בפתרון הרשמי של 6.1 מחושבים רק גודל הזיכרון הפיזי (32KB) והווירטואלי (64KB). מכאן התשובה לשאלה עצמה: 64 כניסות ו-128 בתים.", "expl": "", "check": "חושב", "exam": "24BA", "examLabel": "סמסטר ב' תשפ\"ד מועד א'", "date": "07.07.2024", "id": "24BA-6", "image": "img/24BA-6.png"}, {"num": "7", "type": "open", "topic": "sync", "sub": "סמפורים", "intro": "נתונה מערכת שמשתמשת בפתרון לבעיית יצרן-צרכן. מוגדרים טיפוס Item ו-3 סמפורים: mutex, ‏full, ‏empty. הקבוע N הוא מספר המדפים במחסן.\nנתונות הפונקציות (אין צורך לממש אותן):\nItem produce_item() – מייצרת מוצר חדש. בטוחה לשימוש במקביל.\nvoid consume_item(Item) – צורכת מוצר קיים. בטוחה לשימוש במקביל (על מוצרים שונים). אסור לקרוא לה יותר מפעם אחת לאותו מוצר.\nvoid add_item(Item) – מוסיפה מוצר (שלא קיים במחסן) למחסן. לא בטוחה לשימוש במקביל.\nItem del_item() – מוציאה מוצר אחד מהמחסן ומחזירה אותו. לא בטוחה לשימוש במקביל.\nיש לתאר בקצרה ובבירור כל פתרון ולכתוב קוד ברור.", "parts": [{"label": "7.1", "q": "ממשו את הפתרון של יצרן-צרכן כפי שנלמד בכיתה, עם 3 הסמפורים בלבד: produce() מייצרת מוצר ומוסיפה אותו למחסן, ו-consume() מוציאה מוצר מהמחסן וצורכת אותו. ציינו את ערכי האתחול.", "answer": "ערכי אתחול: mutex = 1, ‏full = 0, ‏empty = N.\n\nvoid produce() {\n    Item item = produce_item();\n    sem_wait(&empty);\n    sem_wait(&mutex);\n    add_item(item);\n    sem_post(&mutex);\n    sem_post(&full);\n}\n\nvoid consume() {\n    sem_wait(&full);\n    sem_wait(&mutex);\n    Item item = del_item();\n    sem_post(&mutex);\n    sem_post(&empty);\n    consume_item(item);\n}\n\nהייצור והצריכה עצמם (produce_item, consume_item) נמצאים מחוץ לקטע הקריטי – הם בטוחים לשימוש במקביל, ואין סיבה לחסום בזמנם."}, {"label": "7.2", "q": "נדרשה פעולה חדשה שמייצרת ומוסיפה למחסן כמה מוצרים בבת אחת (באופן אטומי). מובטח ש-x ≤ N. הקוד שנכתב (בהמשך) אינו תקין. מה הבעיה, ואיך היא יכולה לקרות?", "code": " 1 void produce_several(int x) {\n 2     Item arr[x];   // assume this is allowed\n 3     for (int i = 0; i < x; ++i)\n 4         arr[i] = produce_item();\n 5     for (int i = 0; i < x; ++i)\n 6         sem_wait(&empty);\n 7     sem_wait(&mutex);\n 8     for (int i = 0; i < x; ++i)\n 9         add_item(arr[i]);\n10     sem_post(&mutex);\n11     for (int i = 0; i < x; ++i)\n12         sem_post(&full);\n13 }", "answer": "הבעיה: קיפאון.\n\nהפעולה תופסת מקומות פנויים אחד-אחד, ומחזיקה את מה שכבר תפסה בזמן שהיא מחכה לשאר (hold and wait).\n\nדוגמה: N = 2 והמחסן ריק. שני חוטים קוראים ל-produce_several(2), וכל אחד מצליח להוריד את empty פעם אחת. עכשיו empty = 0, ושניהם מחכים למקום נוסף. אבל המחסן עדיין ריק (שניהם עוד לא הוסיפו כלום), ולכן אף צרכן לא יכול לצרוך ולפנות מקום. כולם תקועים."}, {"label": "7.3", "q": "sem_trywait מנסה להוריד את ערך הסמפור ב-1: אם הוא גדול מ-0, היא מורידה אותו באופן אטומי ומחזירה 0; אחרת היא חוזרת מיד, בלי לחכות, ומחזירה 1-.\nתקנו את produce_several כך שתעבוד באופן תקין. מותר לשנות רק את שורות 5–6. מותר להשתמש ב-sem_trywait, אבל לא בפעולות אטומיות או באובייקטי סנכרון נוספים.", "answer": "במקום לחכות על כל מקום ולהחזיק את מה שכבר תפסנו, מנסים לתפוס את כל x המקומות עם sem_trywait. אם ניסיון נכשל – מחזירים את כל מה שתפסנו ומתחילים מחדש. כך חוט אף פעם לא מחזיק מקומות בזמן שהוא חסום, ואין קיפאון.\n\nכדי למנוע livelock (שני חוטים שתופסים חלק, משחררים, ושוב ושוב), כל ניסיון נעשה תחת mutex. בכישלון משחררים את mutex ותופסים אותו מחדש – כך צרכנים (שגם הם צריכים את mutex) יכולים לפנות מקום בינתיים.\n\nvoid produce_several(int x) {\n    Item arr[x];\n    for (int i = 0; i < x; ++i)\n        arr[i] = produce_item();\n\n    // instead of lines 5-6:\n    sem_wait(&mutex);\n    for (int i = 0; i < x; ++i) {\n        if (sem_trywait(&empty)) {         // failed\n            for (int k = 0; k < i; ++k)\n                sem_post(&empty);          // give back\n            i = -1;                        // restart (++i makes it 0)\n            sem_post(&mutex);              // let consumers run\n            sem_wait(&mutex);\n        }\n    }\n    sem_post(&mutex);\n\n    sem_wait(&mutex);                      // lines 7-12 unchanged\n    for (int i = 0; i < x; ++i)\n        add_item(arr[i]);\n    sem_post(&mutex);\n    for (int i = 0; i < x; ++i)\n        sem_post(&full);\n}"}], "official": "7.1: כמו כאן. 7.2: קיפאון. 7.3: אותו רעיון (trywait, החזרה והתחלה מחדש, ו-mutex נגד livelock).", "note": "7.1: בקוד הרשמי של consume כתוב sem_post(&full) בסוף – צריך להיות sem_post(&empty) (הצרכן מפנה מקום).\n7.2: הדוגמה הרשמית (מקום פנוי אחד, וקריאה עם x = 2 שחוסמת גם את produce) היא קיפאון רק אם אין צרכן שיכול לצרוך מוצר מהמחסן. הדוגמה כאן (שני produce_several על מחסן ריק) היא קיפאון בכל מקרה.\n7.3: בקוד הרשמי הסוגריים לא מאוזנים; הקוד כאן מסודר.", "expl": "נבדק בהרצה עם N = 2, שני חוטים שקוראים ל-produce_several(2), יצרן רגיל ושני צרכנים: הקוד המקורי נתקע (קיפאון), והקוד המתוקן מסיים, בלי שהמחסן עובר את N או יורד מתחת ל-0.", "check": "הורץ עם חוטים אמיתיים", "exam": "24BA", "examLabel": "סמסטר ב' תשפ\"ד מועד א'", "date": "07.07.2024", "id": "24BA-7"}, {"num": "8", "type": "open", "topic": "disk", "sub": "ביצועי דיסק", "intro": "נתון דיסק קשיח עם הנתונים הבאים:\nגודל סקטור 512B, גודל בלוק 8 סקטורים (4KB).\n8 משטחים (4 platters דו-צדדיים).\nצפיפות הסקטורים לפי 2 אזורים A, B, ובכל אזור 200 רצועות. באזור A יש 1024 בלוקים לרצועה, ובאזור B ‏256.\nהנתונים האלה תקפים לכל הסעיפים. נתונים שכתובים בתוך סעיף תקפים רק לאותו סעיף.\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "8.1", "q": "מה שטח האחסון הכולל בדיסק?", "answer": "8000MB.\n\n(1024 + 256) בלוקים · 200 רצועות · 8 משטחים · 4KB\n= 2,048,000 בלוקים · 4KB = 8,192,000KB = 8000MB"}, {"label": "8.2", "q": "משתמש בדק את קצב ההעברה: קריאה של 2MB רצופים לוקחת בממוצע 50ms, וקריאה של 1MB רצופים לוקחת בממוצע 40ms. מה קצב ההעברה המקסימלי של הדיסק?", "answer": "100 MB/s.\n\nבשתי הפעולות זמן המיקום (seek והמתנה לסיבוב) זהה בממוצע. לכן ההפרש ביניהן הוא רק זמן ההעברה של ה-MB הנוסף:\n50 − 40 = 10ms ל-1MB\n\n1MB / 10ms = 100 MB/s"}, {"label": "8.3", "q": "נוספו הנתונים: 6,000 RPM; זמן seek ממוצע 16ms, ובין שתי רצועות סמוכות 1ms; יש track skew (בקריאת סקטורים עוקבים ברצועות סמוכות אין המתנה לסיבוב); וקצב ההעברה תוכנן כך שרצועה של A מועברת בזמן סיבוב אחד בדיוק.\nמשתמש ביצע פעולה שמתורגמת לקריאה של 50 רצועות שלמות ורצופות באזור B. מה קצב ההעברה בפועל?", "answer": "לפי הפתרון הרשמי: בערך 256.4 MB/s.\n\nזמן סיבוב 10ms, ולכן המתנה ממוצעת לסיבוב 5ms.\n\nקצב ההעברה של הדיסק:\nרצועה של A היא 1024 · 4KB = 4MB, בסיבוב אחד – 400 MB/s\n\nרצועה של B היא 256 · 4KB = 1MB, ולכן הפעולה היא 50MB.\nזמן ההעברה ב-400 MB/s:\n50 / 400 = 0.125s = 125ms\n\nזמן מיקום:\nseek של 16ms, ועוד 49 מעברים בין רצועות סמוכות של 1ms – סך הכל 65ms\nהמתנה לסיבוב: 5ms\n\nסך הכל:\n65 + 5 + 125 = 195ms\n\nקצב בפועל:\n50MB / 0.195s ≈ 256.4 MB/s\n\nהפתרון הרשמי קיבל גם שתי דרכי חישוב נוספות:\nאם הרצועות מפוזרות בין 8 המשטחים, יש רק 6 מעברים בין צילינדרים במקום 49, וה-seek הכולל הוא 22ms.\nחישוב מדויק יותר: רצועה של B עוברת מתחת לראש בסיבוב שלם (10ms), כלומר באזור B הקצב הוא רק 100 MB/s, וזמן ההעברה 500ms במקום 125ms. אז:\n16 + 49 + 5 + 500 = 570ms, כלומר בערך 87.7 MB/s\n(ועם פיזור על המשטחים: 16 + 6 + 5 + 500 = 527ms, בערך 94.9 MB/s)"}], "official": "8.1: ‏8000MB. 8.2: ‏100 MB/s. 8.3: ‏195ms, כלומר 256.4 MB/s (התקבלו גם החישובים החלופיים).", "note": "8.3: מבחינה פיזיקלית, החישוב \"המדויק\" הוא הנכון – קריאה של רצועה שלמה לוקחת סיבוב שלם בכל אזור, ולכן באזור B אי אפשר לקרוא ב-400 MB/s. הפתרון הרשמי מציג את 256.4 MB/s כתשובה הראשית, אבל מקבל גם את החישוב לפי זמן הסיבוב.", "expl": "", "check": "חושב בסקריפט", "exam": "24BA", "examLabel": "סמסטר ב' תשפ\"ד מועד א'", "date": "07.07.2024", "id": "24BA-8"}, {"num": "9", "type": "open", "topic": "disk", "sub": "RAID-10", "intro": "שאלת בונוס. נתונה מערכת RAID-10 עם 3 עותקים (כלומר RAID-1 עם mirroring level של 3), עם 9 דיסקים (ממוספרים 1–9), ולכל אחד נפח של 8TB.", "parts": [{"label": "9.1", "q": "מה שטח האחסון הכולל הזמין למשתמש?", "answer": "24TB. יש 9 דיסקים של 8TB, אבל כל נתון משוכפל 3 פעמים:\n9 · 8TB / 3 = 24TB"}, {"label": "9.2", "q": "מה המספר המקסימלי של דיסקים שיכולים להתקלקל בלי לאבד מידע?", "answer": "6. במערך יש 3 קבוצות (RAID-0 ביניהן), ובכל קבוצה 3 דיסקים משוכפלים (RAID-1). אם בכל קבוצה מתקלקלים 2 דיסקים, עדיין נשאר עותק אחד מכל נתון. הדיסק השביעי בהכרח ישלים קבוצה שלמה – ואז נאבד מידע."}, {"label": "9.3", "q": "מה המספר המינימלי של דיסקים שצריכים להתקלקל כדי שנאבד מידע?", "answer": "3. מאבדים מידע רק כשמתקלקלים כל הדיסקים של אותה קבוצה – כל 3 העותקים של אותם נתונים."}], "official": "9.1: ‏24TB. 9.2: ‏6. 9.3: ‏3.", "expl": "", "check": "חושב", "exam": "24BA", "examLabel": "סמסטר ב' תשפ\"ד מועד א'", "date": "07.07.2024", "id": "24BA-9"}, {"num": "1", "type": "mcq", "topic": "disk", "sub": "מבנה הדיסק", "q": "מה תפקידו של ה-servo burst?", "options": ["לתקן שגיאות מיקום של הראש הקורא-כותב.", "לקשר בין קובץ לבין מיקום ה-DATA שלו בדיסק.", "לפרט את מיקומי האזורים השונים של מערכת הקבצים.", "ליידע באיזה משטח (surface) נמצא כרגע הראש הקורא-כותב.", "לאפשר לראש הקורא-כותב לדעת את כמות הסקטורים ברצועה."], "correct": 0, "official": "לתקן שגיאות מיקום. ה-servo burst הוא רצף נתונים מיוחד בדיסק שעוזר לראש הקורא-כותב לוודא את המיקום שלו ולתקן שגיאות מיקום שהצטברו כתוצאה מהתנועה.", "expl": "ה-servo bursts צרובים ברצועות במרווחים קבועים, והבקר משתמש באות שלהם כדי לשמור את הראש בדיוק במרכז הרצועה (track following). זה מנגנון חומרה – לא קשור למערכת הקבצים.", "check": "לפי הפתרון הרשמי", "exam": "24BB", "examLabel": "סמסטר ב' תשפ\"ד מועד ב'", "date": "30.07.2024", "id": "24BB-1"}, {"num": "2", "type": "mcq", "topic": "fs", "sub": "ניהול שטח פנוי", "q": "נתונה מערכת קבצים VSFS שמשתמשת ב-free list כדי למצוא שטח פנוי. איזו טענה נכונה לגביה, בהשוואה ל-bitmap?", "options": ["אפשר לנצל יותר שטח בדיסק.", "מציאת שטח פנוי רצוף תהיה קלה יותר.", "נוכל להשתמש באותו בלוק DATA עבור קבצים שונים.", "נוכל לנצל פחות מכל בלוק DATA שבשימוש, כי צריך לשמור בו מצביע לבלוק הבא.", "כל התשובות נכונות."], "correct": 0, "official": "אפשר לנצל יותר שטח בדיסק. עם free list לא צריך שטח ייעודי בדיסק במקום ה-bitmap. המצביעים בתוך הבלוקים נמצאים רק בבלוקים שאינם בשימוש – ולכן לא מבזבזים נפח בכלל.", "expl": "ב-free list כל בלוק פנוי מחזיק מצביע לבלוק הפנוי הבא – כלומר המידע על השטח הפנוי נשמר בתוך השטח הפנוי עצמו. בלוק שבשימוש לא מכיל מצביע כזה, אז אין הפסד בבלוקים שבשימוש.\n\nמציאת שטח רצוף דווקא קשה יותר (צריך לעבור על הרשימה), ושיתוף בלוק בין קבצים לא קשור לשיטת ניהול השטח הפנוי.", "check": "לפי הפתרון הרשמי", "exam": "24BB", "examLabel": "סמסטר ב' תשפ\"ד מועד ב'", "date": "30.07.2024", "id": "24BB-2"}, {"num": "3", "type": "mcq", "topic": "threads", "sub": "מקביליות", "q": "מהו מרוץ / מצב מרוץ (race condition)?", "options": ["קוד שרץ במקביל בחוטים שונים.", "קוד שנכונות התוצאה שלו תלויה במתזמן.", "קוד שבו כמה חוטים ניגשים לאותו משאב משותף.", "קוד קריטי שמחייב שימוש במנעול לצורך מניעה הדדית.", "כל התשובות נכונות."], "correct": 1, "official": "קוד שנכונות התוצאה שלו תלויה במתזמן – כלומר בתזמון החוטים או התהליכים.", "expl": "כמה חוטים שניגשים לאותו משאב (למשל רק קוראים) לא בהכרח יוצרים מרוץ. מרוץ קיים כשתזמונים שונים מובילים לתוצאות שונות, וחלק מהן שגויות – כמו ++counter משני חוטים.", "check": "לפי הפתרון הרשמי", "exam": "24BB", "examLabel": "סמסטר ב' תשפ\"ד מועד ב'", "date": "30.07.2024", "id": "24BB-3"}, {"num": "4", "type": "mcq", "topic": "redir", "sub": "exec", "q": "נתון הקוד של תוכנית בשם execme. הריצו אותה, והתהליך שנוצר קיבל את המזהה 300. כל קריאות המערכת הצליחו, לא נוצרו תהליכים בקוד אחר, וכל תהליך מקבל מזהה גדול ב-1 מהתהליך שנוצר לפניו. איזו טענה בהכרח נכונה?", "code": "int main()\n{\n    char* args[] = {\"execme\", NULL};\n    if (!fork()) {\n        execvp(args[0], args);\n        printf(\"PID: %d\\n\", getpid());\n    }\n}", "options": ["לא יהיה פלט לתוכנית.", "הפלט יהיה \"PID: 300\" אינסוף פעמים (עד שעוצרים את התוכנית).", "הפלט יהיה \"PID: 301\", אחר כך \"PID: 302\", וכן הלאה (עד שעוצרים את התוכנית).", "התוכנית תקרוס בשלב מסוים בגלל יצירה של יותר מדי תהליכים.", "כל התשובות האחרות אינן נכונות."], "correct": 0, "official": "לא יהיה פלט. התוכנית קוראת לעצמה במעין לולאה אינסופית: בכל פעם נוצר תהליך בן שמריץ את התוכנית מההתחלה, ותהליך האב מסתיים. execvp לא חוזר, ולכן התוכנית ממשיכה לרוץ אבל לא מדפיסה שום דבר.", "expl": "ה-printf נמצא אחרי execvp – והוא רץ רק אם exec נכשל. בכל רגע חיים לכל היותר 2 תהליכים (האב מסתיים מיד), ולכן גם אין קריסה מריבוי תהליכים. הרצה יבשה צעד אחר צעד יש בעמוד \"הפניות וצינורות\" באתר הלמידה.", "check": "הורץ (גם בעמוד הפניות באתר הלמידה)", "exam": "24BB", "examLabel": "סמסטר ב' תשפ\"ד מועד ב'", "date": "30.07.2024", "id": "24BB-4"}, {"num": "5", "type": "mcq", "topic": "threads", "sub": "Cache coherence", "q": "נתון תהליך מרובה חוטים שמשתמש במשתנה משותף. איזו טענה בהכרח נכונה?", "options": ["כל כתיבה למשתנה תגרור הודעה לגביו ב-bus.", "לכל מעבד תמיד יהיה עותק משלו של המשתנה (ב-cache שלו).", "בכל רגע יהיה רק עותק אחד של המשתנה (ב-cache של אחד המעבדים).", "אם הגישה למשתנה היא לקריאה בלבד, לעולם לא תעבור הודעה לגביו ב-bus.", "כל התשובות האחרות אינן נכונות."], "correct": 4, "official": "כל התשובות האחרות אינן נכונות. כשניגשים למשתנה משותף, תמיד ייתכן שתעבור לגביו הודעה ב-bus – גם בגישה לקריאה בלבד (כדי לקבל את הערך ולהכניס ל-cache). כתיבה לא תמיד גוררת הודעה, אלא רק אם צריך גישה בלעדית (invalidate). משתנה משותף יכול להיות ב-cache של כל מעבד, או של אף אחד.", "expl": "אם למעבד כבר יש את השורה במצב בלעדי (Modified/Exclusive), הוא יכול לכתוב שוב ושוב בלי הודעות. וקריאה ראשונה של משתנה שלא נמצא ב-cache דורשת להביא אותו – דרך ה-bus.", "check": "לפי הפתרון הרשמי", "exam": "24BB", "examLabel": "סמסטר ב' תשפ\"ד מועד ב'", "date": "30.07.2024", "id": "24BB-5"}, {"num": "6", "type": "open", "topic": "memory", "sub": "טבלה היררכית", "intro": "נתונה מערכת שבה כל תהליך משתמש בטבלת דפים היררכית עם 3 רמות. לכל טבלה מוקצית מסגרת (כל חלק בטבלה הוא דף אחד בדיוק), וכל כניסה בטבלה היא 16 ביטים.\nזה החלק הראשון ברמה התחתונה של טבלת הדפים של תהליך מסוים – תת-הטבלה PT0 המלאה, עם המיפויים לדפים 0 והלאה. בכל PTE יש גם 4 ביטים של ריפוד (0000). P=Present, V=Valid, A=Access (Reference), D=Dirty.\nיש לפרט ולנמק את כל החישובים.", "table": {"headers": ["דף", "PFN", "V", "P", "A", "D"], "rows": [["0", "00000000", "0", "0", "0", "0"], ["1", "00100010", "1", "0", "0", "0"], ["2", "00011101", "1", "1", "1", "1"], ["3", "00000000", "0", "0", "0", "0"], ["4", "00000010", "1", "1", "1", "1"], ["5", "00000000", "1", "0", "0", "0"], ["6", "00001011", "1", "1", "1", "1"], ["7", "00000000", "1", "1", "0", "0"], ["8", "00011111", "1", "1", "0", "0"], ["9", "00000000", "1", "1", "0", "0"], ["10", "11010110", "1", "0", "0", "0"], ["11", "01100110", "1", "1", "1", "1"], ["12", "01111111", "1", "1", "1", "1"], ["13", "11100000", "1", "1", "1", "1"], ["14", "00000000", "0", "0", "0", "0"], ["15", "00001111", "1", "1", "1", "0"]]}, "parts": [{"label": "6.1", "q": "מה גודל הזיכרון הפיזי המקסימלי במערכת?", "answer": "8KB.\n\nהטבלה היא בגודל דף, ויש בה 16 רשומות של 16 ביטים:\n16 · 2B = 32B – זה גודל הדף\n\nה-PFN הוא 8 ביטים, כלומר 256 מסגרות:\n256 · 32B = 8KB"}, {"label": "6.2", "q": "מה גודל הזיכרון הווירטואלי של תהליך?", "answer": "128KB.\n\nבכל טבלה (בכל רמה) 16 רשומות, ויש 3 רמות:\n16 · 16 · 16 = 4096 דפים\n\n4096 · 32B = 128KB"}, {"label": "6.3", "q": "מלבד הטבלה הנתונה, התהליך משתמש ב-15 דפים נוספים, ו-3 מהם רצופים בזיכרון הווירטואלי (לכולם P = 0). כמה זיכרון פיזי תתפוס כל טבלת הדפים (כל הרמות יחד) במקרה המינימלי ובמקרה המקסימלי, וכמה כניסות valid יהיו בסך הכל בכל מקרה? יש לכלול גם את החלק הנתון.", "answer": "בטבלה הנתונה יש 13 כניסות valid.\n\nמינימום – 128B, ‏31 כניסות valid:\nכל 15 הדפים הנוספים באותה טבלה ברמה התחתונה (טבלה אחרת מ-PT0, כי ב-PT0 יש רק 3 מקומות פנויים), וההצבעה אליה מאותה טבלה ברמה האמצעית.\nרמה עליונה: טבלה 1, ‏1 valid\nרמה אמצעית: טבלה 1, ‏2 valid\nרמה תחתונה: 2 טבלאות, ‏13 + 15 valid\nסך הכל 4 מסגרות = 128B, ו-1 + 2 + 13 + 15 = 31\n\nמקסימום – 992B, ‏58 כניסות valid:\nרוצים כל דף נוסף בטבלה נפרדת, גם ברמה התחתונה וגם באמצעית. אבל 3 הדפים הרצופים יכולים להתפרס רק על 2 טבלאות (סוף של אחת ותחילת הבאה), ולכן 15 הדפים יהיו ב-14 טבלאות נפרדות.\nרמה עליונה: טבלה 1, ‏15 valid\nרמה אמצעית: 15 טבלאות, ‏1 valid בכל אחת\nרמה תחתונה: 15 טבלאות – PT0 עם 13 valid, ועוד 15 הדפים הנוספים\nסך הכל 1 + 15 + 15 = 31 מסגרות = 992B, ו-15 + 15 + 13 + 15 = 58"}], "official": "6.1: ‏8KB. 6.2: ‏128KB. 6.3: מינימום 128B עם 31 valid; מקסימום 992B עם 58 valid.", "expl": "", "check": "חושב", "exam": "24BB", "examLabel": "סמסטר ב' תשפ\"ד מועד ב'", "date": "30.07.2024", "id": "24BB-6", "image": "img/24BB-6.png"}, {"num": "7", "type": "open", "topic": "sync", "sub": "מנעול קוראים-כותבים", "intro": "נתונה מערכת שמשתמשת במנעול קוראים-כותבים. מוגדרים 2 משתנים משותפים מטיפוס int: ‏numReaders ו-numWriters, ו-2 סמפורים: readlock ו-writelock. המשתנים מאותחלים ל-0 והסמפורים ל-1.\nזה המימוש שנלמד (עם סמפורים בינאריים במקום מנעולים):", "code": "void acquire_writelock() {        void release_writelock() {\n    sem_wait(&writelock);             sem_post(&writelock);\n}                                 }\n\nvoid acquire_readlock() {         void release_readlock() {\n    sem_wait(&readlock);              sem_wait(&readlock);\n    if (++numReaders == 1)            if (--numReaders == 0)\n        sem_wait(&writelock);             sem_post(&writelock);\n    sem_post(&readlock);              sem_post(&readlock);\n}                                 }", "parts": [{"label": "7.1", "q": "במימוש שנלמד יש עדיפות לקוראים, שגורמת להרעבת כותבים: חוט שמנסה לתפוס את המנעול לכתיבה עלול להיות חסום לזמן לא מוגבל, בזמן שחוטים אחרים תופסים ומשחררים בהצלחה. תארו ריצה ברורה שמדגימה את הבעיה.", "answer": "חוט 1 (קורא) תופס את המנעול – מוריד את writelock ל-0.\nחוט 2 (כותב) מחכה ש-writelock יעלה ל-1.\nחוט 3 (קורא) תופס את המנעול – מדלג על writelock, כי חוט 1 בפנים.\nחוט 1 משחרר – מדלג על writelock, כי חוט 3 בפנים.\nחוט 1 תופס שוב לקריאה – מדלג על writelock, כי חוט 3 בפנים.\nחוט 3 משחרר – מדלג על writelock, כי חוט 1 בפנים.\n\nוכך הלאה עד אינסוף: תמיד יש קורא בפנים, writelock לא משתחרר, וחוט 2 לעולם לא יתפוס את המנעול."}, {"label": "7.2", "q": "נדרש לתת עדיפות לכותבים: כל עוד יש חוט שמנסה לתפוס את המנעול לכתיבה, חוט שמנסה לתפוס לקריאה לא יצליח. הקוד שנכתב (בהמשך) לא תקין. מה הבעיה, ואיך היא יכולה לקרות?", "code": "void acquire_writelock() {        void release_writelock() {\n    sem_wait(&readlock);              sem_post(&writelock);\n    ++numWriters;                     sem_wait(&readlock);\n    sem_post(&readlock);              --numWriters;\n    sem_wait(&writelock);             sem_post(&readlock);\n}                                 }\n\nvoid acquire_readlock() {         void release_readlock() {\n    sem_wait(&readlock);              sem_wait(&readlock);\n    while (numWriters > 0);           if (--numReaders == 0)\n    if (++numReaders == 1)                sem_post(&writelock);\n        sem_wait(&writelock);         sem_post(&readlock);\n    sem_post(&readlock);          }\n}", "answer": "הבעיה: קיפאון.\n\nחוט 1 (כותב) מגדיל את numWriters ותופס את המנעול.\nחוט 2 (קורא) תופס את readlock ונתקע בלולאה while (numWriters > 0) – בזמן שהוא מחזיק את readlock.\nחוט 1 מנסה לשחרר: release_writelock צריך את readlock כדי להקטין את numWriters – אבל חוט 2 מחזיק אותו.\n\nחוט 2 מחכה ש-numWriters ירד, וחוט 1 מחכה ל-readlock שחוט 2 מחזיק. אף חוט לא יכול להשתמש יותר במנעול."}, {"label": "7.3", "q": "תקנו את המימוש כך שיעבוד נכון וייתן עדיפות לכותבים. מותר להשתמש ב-fetch_and_add, אבל לא בפעולות אטומיות או באובייקטי סנכרון נוספים, ואסור להגדיר משתנים משותפים או גלובליים נוספים.", "answer": "שני שינויים:\n1. מגדילים ומקטינים את numWriters באופן אטומי עם fetch_and_add, בלי readlock – כך כותב לא צריך את readlock בכלל.\n2. קוראים ממתינים בלולאה לפני שתופסים את readlock – כך קורא שממתין לא מחזיק שום דבר שכותבים צריכים.\n(שינוי 2 לבד מספיק כדי לענות על הדרישות.)\n\nvoid acquire_writelock() {\n    fetch_and_add(&numWriters, 1);\n    sem_wait(&writelock);\n}\nvoid release_writelock() {\n    sem_post(&writelock);\n    fetch_and_add(&numWriters, -1);\n}\n\nvoid acquire_readlock() {\n    while (numWriters > 0);\n    sem_wait(&readlock);\n    if (++numReaders == 1)\n        sem_wait(&writelock);\n    sem_post(&readlock);\n}\nvoid release_readlock() {\n    sem_wait(&readlock);\n    if (--numReaders == 0)\n        sem_post(&writelock);\n    sem_post(&readlock);\n}"}], "official": "7.1: כמו כאן. 7.2: קיפאון. 7.3: כמו כאן.", "expl": "הקוד של 7.3 הורץ עם 4 קוראים ו-2 כותבים (‏800,000 קריאות ו-40,000 כתיבות): אף פעם לא היו כותב וקורא יחד, או שני כותבים יחד, וכל הכותבים סיימו.", "check": "הורץ עם חוטים אמיתיים", "exam": "24BB", "examLabel": "סמסטר ב' תשפ\"ד מועד ב'", "date": "30.07.2024", "id": "24BB-7"}, {"num": "8", "type": "open", "topic": "fs", "sub": "Journaling", "intro": "נתונה מערכת קבצים VSFS שמשתמשת ב-journaling:\nגודל בלוק 2KB, גודל inode ‏256B, גודל מצביע 4B.\nבכל inode יש 10 מצביעים ישירים, 2 עקיפים ועקיף כפול אחד.\nהמערכת משתמשת ב-metadata journaling, עם journal של 250 בלוקים.\nהנתונים האלה תקפים לכל הסעיפים. נתונים שכתובים בתוך סעיף תקפים רק לאותו סעיף.\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "8.1", "q": "נתון דיסק של 100MB שעליו מערכת הקבצים, ו-99MB מהדיסק הוגדרו כ-data region. מה המספר המקסימלי של קבצים שאפשר להחזיק?", "answer": "2048 קבצים.\n\nבלוקים בדיסק:\n100MB / 2KB = 51,200\nמתוכם DATA:\n99MB / 2KB = 50,688\n\ndata bitmap – בכל בלוק 2048 · 8 = 16,384 ביטים:\n50,688 / 16,384 = 3.09, כלומר 4 בלוקים\n\nsuperblock – 1, ‏journal – 250\n\nעד כאן:\n1 + 250 + 4 + 50,688 = 50,943\nנשארו 51,200 − 50,943 = 257 בלוקים ל-inode bitmap ול-inodes.\n\nבבלוק נכנסים 2048 / 256 = 8 inodes. ‏256 בלוקים של inodes נותנים 2048 inodes, ובלוק אחד מספיק ל-bitmap של כולם.\n\nלכן יש לכל היותר 2048 inodes – כלומר 2048 קבצים."}, {"label": "8.2", "q": "משתמש יצר קובץ חדש (ריק) בתיקייה שמספר ה-inode שלה ידוע. אף cache לא מכיל מידע רלוונטי (מלבד מספר ה-inode של התיקייה). לכמה בלוקים צריך לכתוב במקרה המינימלי? פרטו את הכתיבות לפי הסדר, ציינו היכן ממתינים לכתיבות (fsync), ומהו השלב הראשון שאחריו מובטח שהפעולה תתבצע גם אם המערכת תקרוס.", "answer": "7 כתיבות.\n\nצריך לעדכן: ה-inode של התיקייה, ה-inode bitmap, ה-inode של הקובץ החדש, ובלוק ה-DATA של התיקייה. במקרה המינימלי 2 ה-inodes באותו בלוק, ובבלוק ה-DATA של התיקייה יש מקום לרשומה נוספת.\n\n1. כתיבת TxB ל-journal\n2. כתיבת ה-inode bitmap ל-journal\n3. כתיבת בלוק ה-inodes המעודכן (תיקייה + קובץ) ל-journal\n4. עדכון בלוק ה-DATA של התיקייה – הוספת רשומה (במקום, כי זו רק הוספה ולא שכתוב)\nfsync\n5. כתיבת TxE\nfsync – מכאן הפעולה תתבצע בוודאות\n6. עדכון ה-inode bitmap במקומו\n7. עדכון בלוק ה-inodes במקומו"}], "official": "8.1: ‏2048. 8.2: ‏7 כתיבות.", "note": "8.1: התיקייה הראשית (root) גם היא צורכת inode. אם סופרים רק קבצים רגילים, המקסימום הוא 2047.\n8.2: ברשימה הרשמית הכתיבה הראשונה מופיעה כ-\"TxE\" – צריך להיות TxB (התחלת הטרנזקציה).", "expl": "טעות נפוצה ב-8.1: לחשב כמה קבצים בגודל מקסימלי נכנסים ב-DATA. אבל קובץ לא חייב להיות בגודל מקסימלי (הוא יכול להיות גם ריק) – המגבלה היא מספר ה-inodes.", "check": "חושב בסקריפט", "exam": "24BB", "examLabel": "סמסטר ב' תשפ\"ד מועד ב'", "date": "30.07.2024", "id": "24BB-8"}, {"num": "9", "type": "open", "topic": "disk", "sub": "RAID-1", "intro": "שאלת בונוס. נתונה מערכת RAID-1 עם 2 עותקים (mirroring level של 2), עם 5 דיסקים, לכל אחד נפח של 2TB. הזמן הקצר ביותר לפעולה על בלוק בודד בדיסק הוא 10ms. אפשר להניח כל תרחיש שמוביל לזמן הקצר ביותר, כל עוד הוא עומד בנתונים.", "parts": [{"label": "9.1", "q": "מה הזמן הקצר ביותר של קריאה של 10 בלוקים לוגיים רצופים?", "answer": "20ms. בגלל השיקוף, לכל בלוק יש 2 עותקים, ואפשר לבחור מאיזה לקרוא. תמיד אפשר לסדר את 10 הבלוקים כך שקוראים 2 בלוקים מכל אחד מ-5 הדיסקים. כל דיסק קורא 2 בלוקים ב-20ms, והדיסקים עובדים במקביל."}, {"label": "9.2", "q": "מה הזמן הקצר ביותר של כתיבה ל-20 בלוקים לוגיים רצופים?", "answer": "80ms. כל בלוק צריך להיכתב ל-2 דיסקים שונים, כלומר 40 כתיבות של בלוקים. בגלל ה-striping הן מתחלקות שווה בשווה – 8 בלוקים לכל דיסק. הכתיבות בכל דיסק רצופות, והדיסקים עובדים במקביל:\n8 · 10ms = 80ms"}], "official": "9.1: ‏20ms. 9.2: ‏80ms.", "note": "בשאלה המקורית כתוב \"5 דיסקים קשיחים הממוספרים 1–9\" – כנראה טעות הקלדה; החישוב מתבסס על 5 דיסקים.", "expl": "", "check": "חושב", "exam": "24BB", "examLabel": "סמסטר ב' תשפ\"ד מועד ב'", "date": "30.07.2024", "id": "24BB-9"}, {"num": "1", "type": "mcq", "topic": "threads", "sub": "פעולות אטומיות", "q": "נתון מעבד שתומך בפעולה האטומית CAS, דרך הפונקציה BOOL compareAndSet(int* ptr, int expected, int new). סטודנט כתב את הפונקציה הבאה כדי לדמות את הפעולה האטומית F&A בעזרת CAS. מה נכון לגביה?", "code": "int fetchAndAddWithCAS(int* val) {\n    int tmp;\n    do {\n        tmp = *val;\n    } while (!compareAndSet(val, tmp, tmp+1));\n    return tmp;\n}", "options": ["המימוש תקין, ושקול לשימוש ב-F&A.", "המימוש תקין, אבל יהיו לו ביצועים פחות טובים מ-F&A.", "המימוש לא תקין: שימוש בו עלול לגרום לקיפאון.", "המימוש לא תקין: שימוש בו עלול לגרום להרעבה.", "המימוש לא תקין: הערך של val לא תמיד יקודם נכון."], "correct": 3, "official": "המימוש עלול לגרום להרעבה. חוט מסוים עלול להיכשל בקריאת ה-CAS שוב ושוב, ובכך להיות מורעב.", "expl": "הקידום עצמו תמיד נכון: CAS מצליח רק אם הערך לא השתנה מאז שקראנו אותו. אבל אם חוטים אחרים משנים את val כל הזמן, ייתכן שחוט מסוים ייכשל בכל ניסיון – אין שום הבטחה שהוא יצליח בזמן סופי. F&A אמיתי מסתיים תמיד בצעד אחד.", "check": "לפי הפתרון הרשמי", "exam": "24SA", "examLabel": "סמסטר קיץ תשפ\"ד מועד א'", "date": "10.10.2024", "id": "24SA-1"}, {"num": "2", "type": "mcq", "topic": "threads", "sub": "חוטים וזיכרון", "q": "נתונים 2 חוטים A, B של אותו תהליך, ושניהם עוד לא הסתיימו. איזו טענה נכונה?", "options": ["החוט A לעולם לא יכול לגשת למשתנים המקומיים של B.", "החוט A יכול לגשת למשתנים המקומיים של B רק בתיווך מערכת ההפעלה (עם קריאת מערכת).", "החוט A יכול לגשת למשתנים המקומיים של B רק אם B הגדיר אותם באופן מיוחד.", "החוט A תמיד יכול לגשת למשתנים המקומיים של B.", "החוט A תמיד יכול לגשת למשתנים המקומיים של B, גם אם החוטים לא היו באותו תהליך."], "correct": 3, "official": "החוט A תמיד יכול לגשת למשתנים המקומיים של B. חוטים של אותו תהליך (בלבד) יכולים לגשת למחסנית זה של זה ולכל הזיכרון של התהליך.", "expl": "לכל חוט מחסנית משלו, אבל כל המחסניות נמצאות באותו מרחב כתובות. אם A מקבל מצביע למשתנה מקומי של B (למשל דרך משתנה גלובלי), הוא יכול לקרוא ולכתוב בו. אין הגנת חומרה בין חוטים של אותו תהליך.", "check": "לפי הפתרון הרשמי", "exam": "24SA", "examLabel": "סמסטר קיץ תשפ\"ד מועד א'", "date": "10.10.2024", "id": "24SA-2"}, {"num": "3", "type": "mcq", "topic": "signals", "sub": "סיגנלים", "q": "מהו סיגנל (signal)?", "options": ["מנגנון למניעת זומבים במערכת.", "פסיקה שתהליך יכול לגרום במעבד.", "מנגנון לשליחת הודעות מתהליך אל מערכת ההפעלה.", "מנגנון לשליחת הודעות בין תהליכים בלי התערבות של מערכת ההפעלה.", "כל התשובות האחרות אינן נכונות."], "correct": 4, "official": "כל התשובות האחרות אינן נכונות. סיגנל הוא מנגנון לשליחת הודעות בין תהליכים, או ממערכת ההפעלה אל תהליכים – בתיווך מערכת ההפעלה.", "expl": "הכיוון הוא אל התהליך (מתהליך אחר או מהקרנל), ותמיד דרך הקרנל – kill היא קריאת מערכת, והקרנל מסמן את הסיגנל ומפעיל את ה-handler כשהתהליך חוזר ממצב קרנל.", "check": "לפי הפתרון הרשמי", "exam": "24SA", "examLabel": "סמסטר קיץ תשפ\"ד מועד א'", "date": "10.10.2024", "id": "24SA-3"}, {"num": "4", "type": "mcq", "topic": "fs", "sub": "תיקיות ו-hard links", "q": "במערכת קבצים VSFS, בתיקייה d1 יש רשומה ששמה a.txt ומספר ה-inode שלה 20. איזה מהתרחישים הבאים אינו אפשרי?", "options": ["באותה תיקייה d1 יש גם רשומה בשם a.txt עם inode ‏30.", "באותה תיקייה d1 יש גם רשומה בשם b.txt עם inode ‏20.", "בתיקייה אחרת d2 יש רשומה בשם a.txt עם inode ‏30.", "בתיקייה אחרת d2 יש רשומה בשם a.txt עם inode ‏20.", "בתיקייה אחרת d2 יש רשומה בשם b.txt עם inode ‏20."], "correct": 0, "official": "באותה תיקייה d1 יש גם רשומה a.txt עם inode ‏30. לא ייתכנו 2 קבצים עם אותו שם באותה תיקייה. כל שאר האפשרויות תקינות.", "expl": "השם הוא המפתח בתיקייה, ולכן הוא ייחודי בתוכה. לעומת זאת, אותו inode יכול להופיע בכמה רשומות (hard links) – באותה תיקייה בשם אחר, או בתיקייה אחרת בכל שם.", "check": "לפי הפתרון הרשמי", "exam": "24SA", "examLabel": "סמסטר קיץ תשפ\"ד מועד א'", "date": "10.10.2024", "id": "24SA-4"}, {"num": "5", "type": "mcq", "topic": "fs", "sub": "inode", "q": "במערכת קבצים VSFS, באיזו פעולה לא צריך לגשת ל-inode של הקובץ?", "options": ["פתיחת קובץ.", "קריאה מקובץ.", "כתיבה לקובץ.", "סגירת קובץ.", "כל התשובות האחרות אינן נכונות."], "correct": 3, "official": "סגירת קובץ. בסגירה צריך רק למחוק את אובייקט ה-FD שנוצר, ואין בהכרח צורך בגישה ל-inode (או לדיסק בכלל).", "expl": "בפתיחה קוראים את ה-inode (הרשאות, מיקום). בקריאה ובכתיבה משתמשים במצביעים שב-inode ומעדכנים זמני גישה/שינוי. בסגירה רק משחררים את הרשומה בטבלאות הקבצים הפתוחים.", "check": "לפי הפתרון הרשמי", "exam": "24SA", "examLabel": "סמסטר קיץ תשפ\"ד מועד א'", "date": "10.10.2024", "id": "24SA-5"}, {"num": "6", "type": "open", "topic": "redir", "sub": "exec", "intro": "נתונה התוכנית הבאה בשם prog1.\nתזכורת: באופרטורים && ו-||, אם התוצאה ידועה לפי האופרנד הראשון, האופרנד השני לא מבוצע.\nהריצו את התוכנית, והתהליך שנוצר קיבל את המזהה 42. התוכנית prog2 לא מדפיסה שום דבר ולא יוצרת תהליכים. כל קריאות המערכת הצליחו, לא נוצרים תהליכים בקוד אחר במערכת, וכל תהליך מקבל מזהה גדול ב-1 מהתהליך שנוצר לפניו.", "code": " 1 int main()\n 2 {\n 3     pid_t pid = getpid();\n 4\n 5     if (fork() && !fork()) {\n 6         if (!fork() || fork()) {\n 7             fork();\n 8         }\n 9     }\n10\n11     while (wait(NULL) != -1);\n12     if (pid != getpid()) {\n13         char* args[] = { \"prog2\", NULL };\n14         printf(\"%d [%d]\\n\", getpid(), getppid());\n15         execvp(args[0], args);\n16     }\n17     printf(\"Done: %d\\n\", getpid());\n18 }", "parts": [{"label": "6.1", "q": "כתבו פלט אפשרי של התוכנית, וציירו את עץ התהליכים של הריצה שמובילה אליו (עם המזהה של כל תהליך). כמה תהליכים נוצרו, כולל הראשי?", "answer": "7 תהליכים.\n\nשורה 5: תהליך 42 יוצר את 43 (ה-fork הראשון). אצל 42 הוא אמת, אז מבוצע !fork() – נוצר 44. אצל 42 זה !(44) = שקר, ואצל 44 זה !0 = אמת. אצל 43 ה-fork הראשון החזיר 0, ולכן && עוצר. רק 44 נכנס לתנאי.\n\nשורה 6: ‏44 יוצר את 45. אצל 45 !0 = אמת, ולכן || עוצר – 45 נכנס מיד. אצל 44 זה שקר, אז מבוצע fork() נוסף – נוצר 46. אצל 44 התוצאה אמת (נכנס), ואצל 46 היא 0 (לא נכנס).\n\nשורה 7: ‏44 ו-45 יוצרים כל אחד בן: 47 ו-48.\n\nעץ התהליכים:\n\n[[TREE]]\n\nהמשתנה pid קיבל 42 לפני כל ה-fork-ים, ולכן אצל כולם הוא 42. כל תהליך מחכה שכל הילדים שלו יסתיימו (שורה 11), ואז: כל מי שאינו 42 מדפיס את המזהה שלו ושל ההורה, ומריץ את prog2. רק 42 מדפיס Done.\n\nפלט אפשרי:\n48 [45]\n47 [44]\n46 [44]\n45 [44]\n44 [42]\n43 [42]\nDone: 42\n\nההורה עדיין חי כשהבן מדפיס (הוא מחכה לו), ולכן getppid מחזיר את ההורה האמיתי.", "tree": ["42", "", [["43", "", []], ["44", "", [["45", "", [["48", "", []]]], ["46", "", []], ["47", "", []]]]]]}, {"label": "6.2", "q": "נניח שהכניסו את שורה 11 להערה. הקוד של prog1 ושל prog2 נכנס כל אחד בדף אחד, והמערכת משתמשת בטבלת דפים לינארית בגודל מקסימלי של 2 דפים.\nמיד אחרי שורה 3, תפוסות במערכת 30 מסגרות של זיכרון משתמש (user space).\nבודקים את המערכת ברגע שבו כל התהליכים שמגיעים לשורה 15 כבר ביצעו את execvp בהצלחה, אבל אף אחד מהם עוד לא הריץ אף פקודה של prog2, ושאר התהליכים עוד לא הסתיימו.\nכמה מסגרות של זיכרון משתמש יהיו תפוסות במקרה המינימלי ובמקרה המקסימלי? אין swapping, ואף תהליך אחר לא מקצה, משחרר או ניגש לזיכרון.", "answer": "מינימום 30, מקסימום 37.\n\nהתהליכים שמגיעים לשורה 15 הם כל התהליכים מלבד 42 – כלומר 6 תהליכים. כשהם מבצעים exec, הזיכרון הקודם שלהם (שהיה משותף עם 42 ב-copy-on-write) משתחרר. טבלאות הדפים הן זיכרון של הקרנל, ולא נספרות.\n\nמינימום – 30: אם prog2 כבר רץ בתהליך אחר במערכת (והדף של הקוד שלו כבר בזיכרון ומשותף), והמחסנית של התהליכים החדשים עוד ריקה או לא נוצרה. (התקבלה גם תשובה של 36, בנימוק שגם מחסנית ריקה מקבלת דף.)\n\nמקסימום – 37: מסגרת אחת לקוד של prog2 (משותפת לכל 6 התהליכים), ועוד מסגרת אחת למחסנית של כל אחד מ-6 התהליכים:\n30 + 1 + 6 = 37"}], "official": "6.1: ‏7 תהליכים, עם הפלט והעץ כמו כאן. 6.2: מינימום 30 (התקבל גם 36), מקסימום 37.", "expl": "", "check": "נבדק בהרצה יבשה", "exam": "24SA", "examLabel": "סמסטר קיץ תשפ\"ד מועד א'", "date": "10.10.2024", "id": "24SA-6"}, {"num": "7", "type": "open", "topic": "threads", "sub": "מימוש מנעול", "intro": "נתונה מערכת בלי תמיכה בפעולה האטומית F&A, שבה המנעול המובנה לא הוגן: הוא מקיים מניעה הדדית וחופש מקיפאון, אבל עלול לגרום להרעבה.\nמתכנת מימש מנעול בהשראת Ticket Lock, עם ++ במקום F&A. כיוון ש-++ לא אטומי וחוטים שונים עלולים לקבל את אותו מספר, הקוד משתמש גם במנעול המובנה כדי להבטיח מניעה הדדית. בנוסף, אם חוט רואה שהתור התקדם מעבר למספר שלו (כפי שעלול לקרות), הוא מחזיר את התור אחורה.\nהשדה unfair הוא המנעול המובנה (הלא הוגן). הפרמטר myturn של unlock הוא ערך ההחזרה של lock.", "code": "typedef struct {\n    int ticket;   // init to 0\n    int turn;     // init to 0\n    mutex_t unfair;\n} Lock1;\n\nint lock(Lock1* lock) {\n    int myturn = lock->ticket++;\n    while (lock->turn != myturn) {\n        if (lock->turn > myturn)\n            lock->turn = myturn;\n    }\n    mutex_lock(&lock->unfair);\n    return myturn;\n}\n\nvoid unlock(Lock1* lock, int myturn) {\n    lock->turn = myturn + 1;\n    mutex_unlock(&lock->unfair);\n}", "parts": [{"label": "7.1", "q": "האם המנעול מקיים מניעה הדדית? הוכיחו.", "answer": "כן. כל חוט תופס את המנעול unfair לפני הכניסה לקטע הקריטי, ומשחרר אותו רק ביציאה. אם 2 חוטים בקטע הקריטי בו-זמנית, שניהם מחזיקים ב-unfair – בסתירה לכך שהוא מקיים מניעה הדדית."}, {"label": "7.2", "q": "האם המנעול מקיים חופש מקיפאון? הוכיחו.", "answer": "לא. דוגמה נגדית:\n\nחוט 1 וחוט 2 קוראים יחד את ticket = 0, ושניהם כותבים 1. לשניהם myturn = 0.\nחוט 1 עובר את הלולאה (turn = 0) ותופס את unfair. חוט 2 גם עובר את הלולאה, ומחכה על unfair.\nחוט 1 משחרר: turn = 1.\nחוט 1 נועל שוב: myturn = 1 (ticket = 2), ‏turn = 1 – הוא עובר את הלולאה, ועוקף את חוט 2 ב-unfair (המנעול לא הוגן). הוא משחרר: turn = 2, ומסיים.\nחוט 2 תופס את unfair ומשחרר: turn = 0 + 1 = 1.\n\nעכשיו turn = 1 ו-ticket = 2. כל חוט שינסה לתפוס את המנעול יקבל מספר 2 ומעלה, אבל אף חוט לא מחזיק את המספר 1 – ולכן turn לעולם לא יתקדם. כולם חסומים, למרות שהמנעול פנוי."}, {"label": "7.3", "q": "האם המנעול מקיים הוגנות (bounded waiting)? הוכיחו.", "answer": "לא. דוגמה נגדית:\n\nחוט 1 מנסה לתפוס, קורא ticket = 0 ועוד לא כותב 1.\nחוט 2 תופס: קורא 0, כותב 1, משחרר (turn = 1).\nחוט 1 ממשיך: כותב ticket = 1, רואה שהתור התקדם (1 > 0), ועומד לכתוב turn = 0 – אבל עוד לא כותב.\nחוט 2 תופס שוב: קורא 1, כותב 2, נכנס (turn = 1), ונעצר בדיוק לפני ההשמה turn = 2 ב-unlock.\nחוט 1 כותב turn = 0.\nחוט 2 כותב turn = 2 ומשחרר את unfair.\nחוט 1 בודק שוב: התור התקדם (2 > 0), ועומד לכתוב turn = 0 – אבל עוד לא כותב.\nחוט 2 תופס שוב: קורא 2, כותב 3, נכנס, ונעצר לפני turn = 3.\nחוט 1 כותב turn = 0.\nחוט 2 כותב turn = 3.\nוחוזר חלילה – חוט 2 נכנס שוב ושוב, וחוט 1 אף פעם לא."}], "official": "7.1: כן. 7.2: לא. 7.3: לא (עם הדוגמה כמו כאן).", "note": "7.2: הדוגמה הנגדית שבפתרון הרשמי לא מובילה לקיפאון. בסופה ticket = 1 ו-turn = 1 – ולכן החוט הבא יקבל את המספר 1 וייכנס. (בפתרון הרשמי כתוב שכל חוט הבא יקבל 2 ומעלה, אבל זה לא נכון לפי הריצה שתוארה.) התשובה עצמה – \"לא מקיים\" – נכונה. הדוגמה כאן נמצאה בסריקה ממוחשבת של כל התזמונים, ובה באמת אף חוט לא יכול להתקדם.\nהדוגמה של 7.3 (מהפתרון הרשמי) נבדקה בסימולציה: 50 סיבובים – חוט 2 נכנס בכל סיבוב, וחוט 1 אף פעם.", "expl": "", "check": "נבדק בסריקה ממוחשבת של כל התזמונים ובסימולציה", "exam": "24SA", "examLabel": "סמסטר קיץ תשפ\"ד מועד א'", "date": "10.10.2024", "id": "24SA-7"}, {"num": "8", "type": "open", "topic": "fs", "sub": "VSFS", "intro": "ב-VSFS נוסף שדרוג של copy-on-write, שמאפשר להתייחס לאותו בלוק DATA מכמה מקומות (למשל, להצביע אליו מכמה inodes).\nלשם כך מקצים אזור חדש בדיסק שמכיל מספר לכל בלוק DATA – כמה הפניות יש אליו. כמות ההפניות המקסימלית לבלוק היא 65,535.\nבהעתקת קובץ לא משכפלים את המידע והמצביעים, אלא רק יוצרים inode חדש עם אותם מצביעים. במחיקה מוחלטת של קובץ מחסירים 1 מכמות ההפניות של כל הבלוקים שלו. בעדכון נתוני קובץ משכפלים את הבלוקים ששונו ומעדכנים את מספרי ההפניות (ואת המצביעים ב-inode שעודכן).\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "8.1", "q": "גודל בלוק 4KB. ב-VSFS רגיל (בלי השדרוג) יש מקום ל-2,000,000 בלוקי DATA. מבצעים את השדרוג בלי לשנות שום נתון אחר, מלבד הקטנת ה-data region לטובת האזור החדש. לכמה בלוקי DATA יהיה מקום?", "answer": "1,999,023 בלוקים.\n\nכל מונה דורש 2 בתים (16 ביטים מייצגים 0 עד 65,535). בבלוק של 4KB נכנסים 2048 מונים.\n\nאם יש X בלוקי DATA, צריך ⌈X/2048⌉ בלוקי מונים. מחפשים את ה-X הגדול ביותר כך ש:\nX + ⌈X/2048⌉ ≤ 2,000,000\n\nX = 1,999,023\n1,999,023 + 977 = 2,000,000"}, {"label": "8.2", "q": "בכל inode יש 8 מצביעים ישירים, 2 עקיפים ו-2 עקיפים כפולים. גודל מצביע 4B. משתמש כתב בית אחד לקובץ כלשהו, כשהנתון היחיד שידוע הוא מספר ה-inode (אף cache לא מכיל מידע רלוונטי). מה המספר המקסימלי של בלוקי DATA שצריך לכתוב אליהם? תארו את הפעולה שמביאה למקסימום, ואת כל בלוקי ה-DATA שנכתבים. אין לתאר קריאות.", "answer": "3 בלוקי DATA.\n\nהמקסימום מתקבל בכתיבה לבלוק קיים שגורמת לשכפול המקסימלי – שלו ושל כל בלוקי המצביעים בדרך אליו. למשל: כתיבה לבית האחרון של קובץ בגודל מקסימלי, שחולק את הבלוק הזה – וגם את בלוקי המצביעים – עם קובץ אחר (העתק שלו).\n\nלבלוק האחרון מגיעים מה-inode דרך מצביע עקיף כפול, ולכן כותבים:\n1. בלוק חדש – שכפול של בלוק ה-DATA שכתבנו אליו (כי הוא משותף)\n2. בלוק חדש – שכפול של בלוק המצביעים שמצביע לבלוק ה-DATA\n3. בלוק חדש – שכפול של הבלוק העקיף הכפול שמצביע לבלוק המצביעים\n\nצריך לעדכן גם את ה-inode, את המונים ואת ה-bitmap – אבל הם לא בלוקי DATA."}, {"label": "8.3", "q": "סטודנט טען שעם השדרוג אין צורך ביותר מ-hard link אחד לכל inode, כי אפשר לשתף מידע בין קבצים וזה שקול ל-hard links. האם הוא צודק?", "answer": "הסטודנט טועה. קבצים שונים אמנם יכולים לחלוק מידע, אבל שינוי של קובץ אחד לא משפיע על האחרים (הבלוק משוכפל). hard link, לעומת זאת, הוא שם נוסף לאותו קובץ – שינוי דרך שם אחד נראה דרך כל השמות, כי זה אותו קובץ ולא רק אותו תוכן ברגע מסוים."}], "official": "8.1: ‏1,999,023. 8.2: ‏3. 8.3: הסטודנט טועה.", "expl": "", "check": "חושב בסקריפט", "exam": "24SA", "examLabel": "סמסטר קיץ תשפ\"ד מועד א'", "date": "10.10.2024", "id": "24SA-8"}, {"num": "9", "type": "open", "topic": "disk", "sub": "רמות RAID", "intro": "שאלת בונוס. נתונות 2 מערכות RAID, ובכל אחת 4 דיסקים (ממוספרים 1–4). כל 8 הדיסקים זהים לגמרי. השתמשו ב-2 המערכות באותו אופן בדיוק – אותן פעולות קריאה וכתיבה לאותם בלוקים לוגיים לאורך זמן.", "parts": [{"label": "9.1", "q": "במערכת הראשונה RAID-5 ובשנייה RAID-4. משתמש ביצע כתיבה זהה בשתי המערכות – לבלוקים של 2 שורות רצופות (stripes) – וגם קריאה זהה של הבלוקים של 2 שורות רצופות. בשני המקרים הוא הופתע לגלות שהזמנים במערכת השנייה (RAID-4) היו קצרים יותר. איך זה ייתכן?", "answer": "הפעולות זהות, אבל זה לא אומר שמיקום הראש הקורא-כותב או מצב הסיבוב זהים בשתי המערכות. הסבר אפשרי: במהלך הפעולה, ההמתנה לסיבוב (או ה-seek) במערכת השנייה הייתה קצרה יותר, ולכן היא הסתיימה מהר יותר.\n\n(בכתיבה של stripes שלמים וקריאה של stripes שלמים, ל-RAID-5 אין יתרון מובנה על RAID-4 – אז ההבדל יכול לנבוע ממיקום הראשים.)"}, {"label": "9.2", "q": "במערכת הראשונה RAID-0 ובשנייה RAID-1 עם mirroring level של 2. בו-זמנית קרסו דיסקים 1 ו-2 בשתי המערכות. המשתמש הופתע לגלות שרק במערכת השנייה (RAID-1) אבדו נתונים, ובמערכת הראשונה (RAID-0) לא אבד אף נתון. איך זה ייתכן?", "answer": "RAID-1 מספק גיבוי, אבל אם נפלו 2 הדיסקים שמחזיקים את שני העותקים של אותם נתונים – הנתונים אבדו.\n\nב-RAID-0 נתונים אובדים רק אם היו מאוחסנים על הדיסקים שנפלו. ייתכן שהמשתמש אחסן נתונים רק בבלוקים שבמערכת הראשונה נמצאים על דיסקים 3–4. לדוגמה, בלוק לוגי 3 נמצא בדיסק 4 ב-RAID-0, אבל בדיסקים 1–2 ב-RAID-1 (שם כל זוג דיסקים מחזיק את אותם בלוקים). אם רק בו היו נתונים – בדיוק התרחיש שתואר."}], "official": "9.1 ו-9.2: כמו כאן.", "note": "9.2: בפתרון הרשמי כתוב \"בלוק לוגי 3 נמצא בדיסק 3 במערכת הראשונה\" – לפי מספור מ-0 ודיסקים 1–4, בלוק 3 ב-RAID-0 נמצא בדיסק 4. הרעיון לא משתנה.", "expl": "", "check": "לפי הפתרון הרשמי", "exam": "24SA", "examLabel": "סמסטר קיץ תשפ\"ד מועד א'", "date": "10.10.2024", "id": "24SA-9"}, {"num": "1", "type": "mcq", "topic": "threads", "sub": "פעולות אטומיות", "q": "נתון מעבד שתומך בפעולה האטומית F&A, דרך הפונקציה int fetchAndAdd(int* ptr). סטודנט כתב את הפונקציה הבאה כדי לדמות את הפעולה האטומית CAS בעזרת F&A. מה נכון לגביה?", "code": "int compareAndSetWithFA(int* val, int expected, int new) {\n    static int ticket = 0;\n    static int turn = 0;\n    // static vars are shared among threads (like global)\n    int res = 0;\n    int myturn = fetchAndAdd(&ticket);\n    while (myturn != turn);\n    if (*val == expected) {\n        *val = new;\n        res = 1;\n    }\n    ++turn;\n    return res;\n}", "options": ["המימוש תקין, ושקול לשימוש ב-CAS.", "המימוש תקין, אבל יהיו לו ביצועים פחות טובים מ-CAS.", "המימוש לא תקין: שימוש בו עלול לגרום לקיפאון.", "המימוש לא תקין: שימוש בו עלול לגרום להרעבה.", "המימוש לא תקין: הערך של val לא תמיד יעודכן נכון."], "correct": 1, "official": "המימוש תקין, אבל עם ביצועים פחות טובים. הוא מכיל מנעול ticket lock מובנה שמבטיח נכונות, אבל המנעול פוגע בביצועים: הפעולה לא מתבצעת במקביל (אפילו לא כשניגשים לכתובות שונות בזיכרון), ולא באופן אטומי במעבד.", "expl": "הקוד הוא בעצם ticket lock סביב ההשוואה וההשמה: רק חוט אחד בכל פעם מבצע אותן, ולפי סדר הכרטיסים (אין הרעבה וגם אין קיפאון). אבל כל הקריאות – לכל משתנה – עוברות דרך אותו מנעול ומחכות בתור, במקום פקודת מעבד אחת.", "check": "לפי הפתרון הרשמי", "exam": "24SB", "examLabel": "סמסטר קיץ תשפ\"ד מועד ב'", "date": "04.11.2024", "id": "24SB-1"}, {"num": "2", "type": "mcq", "topic": "threads", "sub": "החלפת הקשר", "q": "נתונים 2 חוטים A, B של 2 תהליכים שונים, ושניהם עוד לא הסתיימו. איזו טענה נכונה?", "options": ["החוט A יכול למנוע החלפת הקשר על ידי ביטול הפסיקות במערכת.", "החלפת הקשר בין A ל-B יכולה לקרות רק בעקבות קריאת מערכת.", "החלפת הקשר בין A ל-B יכולה לקרות רק בעקבות פסיקת שעון.", "החלפת הקשר בין A ל-B לרוב תהיה איטית יותר מאשר אם היו באותו תהליך.", "החלפת הקשר בין A ל-B לרוב תהיה מהירה יותר מאשר אם היו באותו תהליך."], "correct": 3, "official": "איטית יותר מאשר אם היו באותו תהליך. החלפת הקשר בין חוטים באותו תהליך מהירה יותר מאשר בין חוטים בתהליכים שונים.", "expl": "במעבר בין תהליכים צריך גם להחליף מרחב כתובות: לטעון טבלת דפים אחרת, ולרוב לרוקן את ה-TLB (והמטמונים \"מתקררים\"). בין חוטים של אותו תהליך מחליפים רק רגיסטרים ומחסנית.\n\nביטול פסיקות הוא פקודה מוגנת – תהליך משתמש לא יכול לבצע אותה. והחלפת הקשר יכולה לקרות גם בגלל קריאת מערכת וגם בגלל פסיקה.", "check": "לפי הפתרון הרשמי", "exam": "24SB", "examLabel": "סמסטר קיץ תשפ\"ד מועד ב'", "date": "04.11.2024", "id": "24SB-2"}, {"num": "3", "type": "mcq", "topic": "intro", "sub": "פסיקות", "q": "מהי פסיקה (interrupt)?", "options": ["מנגנון לעצירת תהליכים כל פרק זמן קבוע.", "קטע קוד שתהליך מריץ כדי לטפל באירוע כלשהו.", "הודעה שנשלחת ממערכת ההפעלה אל תהליך.", "הודעה שנשלחת בין תהליכים בתיווך מערכת ההפעלה.", "כל התשובות האחרות אינן נכונות."], "correct": 4, "official": "כל התשובות האחרות אינן נכונות. פסיקה היא הודעה שנשלחת אל המעבד/הקרנל מרכיבי חומרה או מתהליכים (באמצעות trap). פסיקת השעון משמשת לעצירת תהליכים כל פרק זמן קבוע – אבל זה שימוש של סוג אחד של פסיקה, ולא ההגדרה.", "expl": "הודעה ממערכת ההפעלה אל תהליך, או בין תהליכים בתיווך מערכת ההפעלה – זה סיגנל. הקוד שמטפל בפסיקה הוא interrupt handler של הקרנל, לא של התהליך.", "check": "לפי הפתרון הרשמי", "exam": "24SB", "examLabel": "סמסטר קיץ תשפ\"ד מועד ב'", "date": "04.11.2024", "id": "24SB-3"}, {"num": "4", "type": "mcq", "topic": "fs", "sub": "תיקיות ו-hard links", "q": "במערכת קבצים VSFS יש 2 קבצי משתמש A, B ששניהם hard links לאותו inode, ו-2 קבצי משתמש C, D ששניהם symbolic links: ‏C מצביע ל-A, ו-D מצביע ל-B. מה נכון?", "options": ["אם נמחק את A, משתמש עדיין יוכל לפתוח את C, כי B עדיין קיים.", "לא ייתכן ש-A ו-B באותה תיקייה, כי הם קישורים לאותו inode.", "לא ייתכן ש-C ו-D באותה תיקייה, כי הם קישורים לאותו inode.", "ה-inode של C זהה ל-inode של D.", "כל התשובות האחרות אינן נכונות."], "correct": 4, "official": "כל התשובות האחרות אינן נכונות – כל האפשרויות המתוארות לא אפשריות.", "expl": "C שומר את הנתיב של A, לא את ה-inode. אם מוחקים את A, הנתיב לא קיים – ו-C שבור, גם אם B עדיין מצביע לאותו inode.\nשני hard links לאותו inode יכולים להיות באותה תיקייה, בשמות שונים.\nלכל קישור סימבולי יש inode משלו (שבו שמור הנתיב), ולכן ל-C ול-D יש inodes שונים – והם גם יכולים להיות באותה תיקייה.", "check": "לפי הפתרון הרשמי", "exam": "24SB", "examLabel": "סמסטר קיץ תשפ\"ד מועד ב'", "date": "04.11.2024", "id": "24SB-4"}, {"num": "5", "type": "mcq", "topic": "intro", "sub": "Limited direct execution", "q": "נתונה הטענה: שינוי ערכי האוגרים במעבד מתבצע רק במצב קרנל (kernel mode).", "options": ["הטענה נכונה: ערכי האוגרים נשמרים ב-PCB, וזה מבנה נתונים של הקרנל.", "הטענה נכונה: האוגרים נמצאים במעבד, ורק לקרנל יש גישה לחומרה.", "הטענה לא נכונה: תהליך תמיד יכול לשנות חלק מערכי האוגרים במעבד (ב-user mode).", "הטענה לא נכונה: תהליך יכול לקבל הרשאה זמנית לשנות ערכים של חלק מהאוגרים (ב-user mode).", "כל התשובות האחרות אינן נכונות."], "correct": 2, "official": "הטענה לא נכונה: תהליך תמיד יכול לשנות חלק מערכי האוגרים. הגישה לאוגרים היא חלק מפעולת המעבד הרגילה גם ב-user mode – זו המשמעות של direct execution (גם ב-limited direct execution). תהליך ניגש לאוגרים בכל ריצה רגילה.", "expl": "כל פקודה כמו add או mov משנה אוגרים כלליים – בלי שום קשר לקרנל. רק אוגרים מיוחדים (למשל זה שמצביע לטבלת הדפים, או זה שמפעיל/מבטל פסיקות) מוגנים, ואפשר לשנות אותם רק במצב קרנל. ה-PCB הוא רק המקום שבו הקרנל שומר עותק של האוגרים בהחלפת הקשר.", "check": "לפי הפתרון הרשמי", "exam": "24SB", "examLabel": "סמסטר קיץ תשפ\"ד מועד ב'", "date": "04.11.2024", "id": "24SB-5"}, {"num": "6", "type": "open", "topic": "sched", "sub": "MLFQ", "intro": "נתון אלגוריתם חדש בשם RMLFQ, שמבוסס על MLFQ מלבד השינויים הבאים:\nתהליך חדש נכנס לתור בעדיפות הנמוכה ביותר (במקום הגבוהה ביותר).\nתהליך שלא ניצל את כל הקוונטום עולה תור אחד בעדיפות. תהליכים עדיין יורדים בעדיפות לפי אותם כללים.\nב-priority boost כל התהליכים יורדים לתור בעדיפות הנמוכה ביותר (במקום לעלות לגבוהה ביותר).", "parts": [{"label": "6.1", "q": "היפוך עדיפויות (priority inversion) הוא מצב שבו אלגוריתם התזמון גורם לקיפאון של תהליך, כי הוא ממתין למשאב שמוחזק על ידי תהליך אחר שלא יתוזמן לעולם. באילו מהאלגוריתמים FCFS, ‏SRTF (בלי overlap), ‏RMLFQ זה אפשרי?", "answer": "", "atable": {"headers": ["אלגוריתם", "היפוך עדיפויות?", "נימוק"], "rows": [["FCFS", "לא אפשרי", "כדי להחזיק משאב תהליך צריך לרוץ, ותהליך רץ מההתחלה ועד הסוף. לכן לא ייתכן שתהליך אחר ממתין למשאב שלו."], ["SRTF", "אפשרי", "תהליך ארוך שמחזיק במשאב עלול להיקטע על ידי תהליכים קצרים שמגיעים כל הזמן, ולעולם לא לרוץ כדי לשחרר אותו."], ["RMLFQ", "לא אפשרי", "אחרי priority boost כל התהליכים באותה עדיפות (נמוכה), וכולם יתוזמנו – כולל התהליך שמחזיק במשאב, שבסוף ישחרר אותו. תהליכים חדשים מגיעים בעדיפות הנמוכה ביותר, ויקבלו קוונטום רק אחריו."]]}}, {"label": "6.2", "q": "הרעבה מוגדרת כמצב שבו ייתכן שתהליך מסוים לעולם לא יסתיים. באילו מהאלגוריתמים FCFS, ‏SRTF (בלי overlap), ‏RMLFQ מתאפשרת הרעבה? תנו דוגמה קצרה היכן שכן, או הוכחה היכן שלא.", "answer": "", "atable": {"headers": ["אלגוריתם", "הרעבה?", "נימוק"], "rows": [["FCFS", "אין", "כל תהליך מתוזמן בתורו, ולפני התהליכים שהגיעו אחריו."], ["SRTF", "יש", "תהליך ארוך עלול להיות מורעב על ידי תהליכים קצרים שמגיעים כל הזמן."], ["RMLFQ", "אין", "כל תהליך ירוץ בסופו של דבר בגלל ה-priority boost. תהליכים חדשים מגיעים בעדיפות נמוכה, ולכן ירוצו רק אחרי קוונטום של כל השאר."]]}}, {"label": "6.3", "q": "אפקט השיירה מוגדר כמצב שבו ייתכן שתהליכים קצרים יתעכבו זמן רב בגלל תהליך ארוך. באילו מהאלגוריתמים FCFS, ‏SRTF (בלי overlap), ‏RMLFQ ייתכן אפקט השיירה? תנו דוגמה קצרה היכן שכן, או הוכחה היכן שלא.", "answer": "", "atable": {"headers": ["אלגוריתם", "שיירה?", "נימוק"], "rows": [["FCFS", "ייתכן", "כל תהליך מחכה לתהליכים שהגיעו לפניו – גם תהליך קצר שלפניו תהליך ארוך מאוד."], ["SRTF", "לא ייתכן", "תהליך קצר תמיד יתוזמן לפני תהליך ארוך."], ["RMLFQ", "לא ייתכן", "אחרי priority boost כל התהליכים מקבלים קוונטום, ותהליכים ארוכים נשארים בעדיפות נמוכה ולא ירוצו לפני קצרים."]]}}], "official": "כמו בטבלאות.", "expl": "בקוד הפתרון הרשמי SRTF מופיע \"בלי overlap\" – הכוונה היא שהתהליכים לא מבצעים קלט/פלט, כך שתהליך רץ רק כשהוא בעל הזמן הנותר הקצר ביותר.", "check": "לפי הפתרון הרשמי", "exam": "24SB", "examLabel": "סמסטר קיץ תשפ\"ד מועד ב'", "date": "04.11.2024", "id": "24SB-6"}, {"num": "7", "type": "open", "topic": "threads", "sub": "מימוש מנעול", "intro": "נתונה מערכת שבה המנעול המובנה לא הוגן: הוא מקיים מניעה הדדית וחופש מקיפאון, אבל עלול לגרום להרעבה.\nמתכנת מימש מנעול ל-N חוטים (N ידוע) בהשראת מנעול הדגלים: לכל חוט דגל (תא במערך) ומזהה i בין 0 ל-N−1.\nכשחוט רוצה את המנעול, הוא מרים את הדגל על ידי כתיבה של 1 או 2 לסירוגין: בפעם הראשונה 1, בשנייה 2, בשלישית 1, וכן הלאה. כל ערך אחר מציין שהדגל למטה.\nכדי להימנע מקיפאון ומהרעבה, ננסה להבטיח שחוט לא יעקוף חוט אחר יותר מפעם אחת: אם הדגל הוא 1 – עדיפות לחוטים עם מזהה נמוך יותר; אם הדגל הוא 2 – עדיפות לחוטים עם מזהה גבוה יותר.\nהשדה unfair הוא המנעול המובנה (הלא הוגן). תוכן השורות AAA ו-BBB מפורט בכל סעיף בנפרד.", "code": "#define N ??\ntypedef struct {\n    int flags[N];   // init to -2\n    mutex_t unfair;\n} Lock2;\n\nvoid lock(Lock2* lock, int i) {\n    lock->flags[i] = 3 + lock->flags[i];\n    if (lock->flags[i] == 1) {\n        for (int k = 0; k < i; ++k)\n            AAA;\n    } else {   // lock->flags[i] == 2\n        for (int k = N-1; k > i; --k)\n            BBB;\n    }\n    mutex_lock(&lock->unfair);\n}\n\nvoid unlock(Lock2* lock, int i) {\n    lock->flags[i] = -(lock->flags[i]);\n    mutex_unlock(&lock->unfair);\n}", "parts": [{"label": "7.1", "q": "הוכיחו שהמנעול מקיים מניעה הדדית בלי קשר לתוכן השורות AAA ו-BBB, אם ידוע שאין בהן return.", "answer": "בלי קשר ל-AAA ו-BBB, כל חוט תופס את unfair לפני הכניסה לקטע הקריטי, ומשחרר אותו רק ביציאה. אם 2 חוטים בקטע הקריטי בו-זמנית, שניהם מחזיקים ב-unfair – בסתירה לכך שהוא מקיים מניעה הדדית."}, {"label": "7.2", "q": "AAA: while (lock->flags[k] == 1);\nBBB: while (lock->flags[k] == 2);\nידוע שהמימוש הזה מקיים רק אחת מהתכונות: חופש מקיפאון או הוגנות. איזו תכונה הוא לא מקיים? הוכיחו.", "answer": "לא מקיים הוגנות. דוגמה:\n\nחוט 0 מעדכן flags[0] = 1 (אין לו חוטים עם מזהה נמוך יותר) ונכנס לקטע הקריטי.\nחוט 1 מעדכן flags[1] = 1 וממתין בלולאה על flags[0] == 1.\nחוט 0 משחרר (flags[0] = −1), ומנסה שוב: flags[0] = 2. הוא בודק רק חוטים עם מזהה גבוה ממנו, על הערך 2 – אבל flags[1] = 1 – אז הוא לא ממתין ונכנס. הוא משחרר (‏−2) ומנסה שוב: flags[0] = 1 – ונכנס.\nחוט 1 חוזר לרוץ – ובודק בדיוק כש-flags[0] = 1, אז נשאר חסום.\nוחוזר חלילה – חוט 0 תופס ומשחרר שוב ושוב, וחוט 1 חסום לעד.\n\nהמימוש כן מקיים חופש מקיפאון (לא נדרש להוכיח): נניח בשלילה שיש קיפאון. המנעול המובנה מקיים חופש מקיפאון, ולכן כל החוטים תקועים בלולאות. אם יש חוטים תקועים עם דגל 1 – החוט עם המזהה הקטן ביותר מביניהם לא יכול להיות תקוע, כי אין חוט עם מזהה קטן ממנו שהדגל שלו 1. באותו אופן, החוט עם המזהה הגדול ביותר מבין התקועים עם דגל 2 לא יכול להיות תקוע. אלה הערכים היחידים האפשריים – סתירה."}, {"label": "7.3", "q": "AAA: while (lock->flags[k] > 0);\nBBB: while (lock->flags[k] > 0);\nידוע שהמימוש הזה מקיים רק אחת מהתכונות: חופש מקיפאון או הוגנות. איזו תכונה הוא לא מקיים? הוכיחו.", "answer": "לא מקיים חופש מקיפאון. דוגמה:\n\nחוט 0 מעדכן flags[0] = 1, תופס את המנעול ומשחרר אותו (‏−1).\nחוט 0 מנסה שוב: מעדכן flags[0] = 2 – ומתעכב (לפני הלולאה).\nחוט 1 מעדכן flags[1] = 1 וממתין על flags[0] > 0.\nחוט 0 חוזר, עובר על מערך הדגלים, וממתין על flags[1] > 0.\nאף חוט לא יכול להתקדם – קיפאון.\n\nהמימוש כן מקיים הוגנות (לא נדרש להוכיח): נניח בשלילה שחוט X לא מצליח לעולם, בזמן שאחרים מצליחים בלי הגבלה. ניקח חוט Y שמצליח פעמיים, ובלי הגבלת הכלליות Y > X. באחת משתי הפעמים Y מרים דגל 1, ואז הוא ממתין על התא של X (שהדגל שלו מורם) עד ש-X יתפוס וישחרר – בסתירה לכך ש-Y הצליח פעמיים."}], "official": "7.1: כמו כאן. 7.2: לא מקיים הוגנות. 7.3: לא מקיים חופש מקיפאון.", "note": "בשאלה המקורית שני הסעיפים האחרונים ממוספרים 7.2, ושתי השורות החסרות בכל סעיף מסומנות AAA (השנייה היא BBB).", "expl": "שתי הגרסאות נבדקו בסריקה ממוחשבת של כל התזמונים, עם 2 ועם 3 חוטים: בגרסה של 7.2 אין מצב קיפאון, ובגרסה של 7.3 יש – בדיוק המצב שבדוגמה.", "check": "נבדק בסריקה ממוחשבת של כל התזמונים", "exam": "24SB", "examLabel": "סמסטר קיץ תשפ\"ד מועד ב'", "date": "04.11.2024", "id": "24SB-7"}, {"num": "8", "type": "open", "topic": "fs", "sub": "VSFS", "intro": "נתונה מערכת קבצים VSFS עם גודל בלוק 4KB וגודל מצביע 4B. בכל inode יש 4 מצביעים: 2 ישירים, אחד עקיף ואחד עקיף כפול.\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "8.1", "q": "משתמש טוען שבקובץ מסוים, הגישה לבית במיקום A מהירה יותר מהגישה לבית A+1, והגישה לבית B זהה במהירות לגישה לבית A+1 אבל מהירה יותר מהגישה לבית B+1. האם הטענה אפשרית? אם כן – תנו ערכים אפשריים ל-A ו-B, אחרת – הוכיחו.", "answer": "המשתמש צודק: A = 8191, ‏B = 4,202,495.\n\nA הוא הבית האחרון בבלוק שמגיעים אליו מהמצביע הישיר האחרון. הבית שאחריו (A+1) כבר דורש מעבר דרך בלוק עקיף. יש 2 מצביעים ישירים:\nA = 2 · 4KB − 1 = 8191\n\nB הוא הבית האחרון בבלוק האחרון שמגיעים אליו דרך המצביע העקיף. הגישה אליו זהה ל-A+1 (שניהם דרך בלוק עקיף אחד), אבל הבית שאחריו (B+1) דורש מעבר דרך העקיף הכפול.\nאחרי 2 הבלוקים הישירים יש 1024 בלוקים דרך העקיף:\nB = 1026 · 4KB − 1 = 4,202,495"}, {"label": "8.2", "q": "משתמש החליט שזמן הגישה הממוצע לבית אקראי בקובץ של 8MB איטי מדי, ורצה לחלק את המידע לכמה קבצים נפרדים כך שזמן הגישה הממוצע לבית אקראי יהיה הכי מהיר. האם יש חלוקה כזו? אם כן – לכמה קבצים לכל הפחות צריך לחלק?", "answer": "החלוקה אפשרית: מינימום 1024 קבצים.\n\nבקובץ של 8MB רוב הגישות לבית אקראי עוברות דרך מצביע עקיף או עקיף כפול. הזמן הממוצע הכי טוב מתקבל כשכל הגישות הן דרך מצביעים ישירים בלבד.\n\nלכן כל קובץ קטן צריך להשתמש רק במצביעים ישירים – לכל היותר 2 בלוקים. המספר המינימלי של קבצים מתקבל כשכל קובץ בגודל המקסימלי הזה:\n8MB / 4KB = 2048 בלוקים\n2048 / 2 = 1024 קבצים"}, {"label": "8.3", "q": "בדיסק כלשהו זמן המיקום (seek + wait) הוא 20ms. בדיקות הראו:\nקריאה/כתיבה של 48MB רצופים לוקחת בממוצע 820ms.\nקריאה/כתיבה של X MB רצופים לוקחת בממוצע 320ms.\nקריאה/כתיבה חוזרת של X MB באותו מיקום שוב ושוב (בלי פעולה אחרת בין לבין) לוקחת בממוצע 310ms.\nמה הערך של X, ומה נתוני הדיסק המלאים (קצב העברה מקסימלי, זמן seek, ‏RPM)?", "answer": "X = 18MB, קצב 60 MB/s, ‏seek של 10ms, ‏3000 RPM.\n\nקצב העברה – מהנתון הראשון, בלי זמן המיקום:\n820 − 20 = 800ms ל-48MB\n48MB / 0.8s = 60 MB/s\n\nX – מהנתון השני:\n320 − 20 = 300ms\n60 MB/s · 0.3s = 18MB\n\nseek ו-RPM – מהנתון השלישי: פעולות חוזרות באותו מיקום מהירות ב-10ms. כשחוזרים על פעולה באותו מקום, חוסכים את ה-seek (הראש כבר ברצועה הנכונה). לכן:\nseek = 10ms\nהמתנה ממוצעת לסיבוב = 20 − 10 = 10ms\nסיבוב שלם = 20ms\n60,000 / 20 = 3000 RPM"}], "official": "8.1: ‏A = 8191, ‏B = 4,202,495. 8.2: ‏1024 קבצים. 8.3: ‏X = 18MB, ‏60 MB/s, ‏seek 10ms, ‏3000 RPM.", "note": "8.3: ההנחה ש\"פעולה חוזרת חוסכת בדיוק את ה-seek\" היא פישוט – 18MB מתפרסים על הרבה רצועות, והראש צריך לחזור לרצועה הראשונה. גם אם מניחים שהחיסכון הוא דווקא ההמתנה לסיבוב, יוצאים אותם מספרים (10ms ו-10ms), אז התשובה לא משתנה.", "expl": "", "check": "חושב", "exam": "24SB", "examLabel": "סמסטר קיץ תשפ\"ד מועד ב'", "date": "04.11.2024", "id": "24SB-8"}, {"num": "9", "type": "open", "topic": "disk", "sub": "רמות RAID", "intro": "שאלת בונוס. נתונות 2 מערכות RAID, ובכל אחת 2 דיסקים (ממוספרים 1–2). כל 4 הדיסקים זהים לגמרי. בשאלות על ביצועים יש להתייחס לממוצע הכללי (ולא לפעולה ספציפית).", "parts": [{"label": "9.1", "q": "במערכת הראשונה RAID-4 ובשנייה RAID-5. סטודנט א' טען: אין הבדל – הדיסקים יכילו את אותם נתונים, ולא יהיה הבדל בביצועים. סטודנט ב' טען: ייתכן הבדל (בנתונים או בביצועים), כי בלוק ה-parity קבוע בדיסק אחד במערכת הראשונה ומתחלף בשנייה. מי צודק?", "answer": "סטודנט א'. עם 2 דיסקים, ה-parity של בלוק אחד הוא פשוט עותק שלו (XOR של בלוק אחד). לכן בשתי המערכות שני הדיסקים מכילים בדיוק את אותם נתונים (כמו RAID-1), ואין שום הבדל ביניהן."}, {"label": "9.2", "q": "במערכת הראשונה RAID-4 ובשנייה RAID-0. סטודנט א' טען: בשנייה הביצועים יהיו טובים יותר גם בקריאה וגם בכתיבה. סטודנט ב': בשנייה הביצועים יהיו טובים יותר בקריאה או בכתיבה, אבל לא בשתיהן. סטודנט ג': בשנייה הביצועים לא יהיו טובים יותר לא בקריאה ולא בכתיבה. מי צודק?", "answer": "סטודנט ב'. בכתיבה, RAID-0 טוב יותר: כותבים לשני הדיסקים במקביל, נתונים שונים – פי 2 מהר יותר. ב-RAID-4 עם 2 דיסקים כל נתון נכתב פעמיים (בגלל ה-parity). בקריאה הביצועים זהים, כי בשתי המערכות אפשר לנצל את 2 הדיסקים במקביל (ב-RAID-4 כאן ה-parity הוא עותק)."}], "official": "9.1: סטודנט א'. 9.2: סטודנט ב'.", "expl": "", "check": "לפי הפתרון הרשמי", "exam": "24SB", "examLabel": "סמסטר קיץ תשפ\"ד מועד ב'", "date": "04.11.2024", "id": "24SB-9"}, {"num": "1", "type": "mcq", "topic": "threads", "sub": "פעולות אטומיות", "q": "נתון מעבד שתומך בפעולה האטומית TAS, דרך הפונקציה int testAndSet(int* ptr, int val). סטודנט כתב את הפונקציה הבאה לקידום ב-1 באופן אטומי (בלי ערך החזרה) בעזרת TAS. מה נכון לגביה?", "code": "int incrementWithTAS(int* val) {\n    // repeat until old val is different than new val\n    // i.e., until *this thread* increments val\n    while (*val != testAndSet(val, *val+1));\n}", "options": ["המימוש תקין: הערך של val תמיד יקודם נכון.", "המימוש תקין, אבל יהיו לו ביצועים פחות טובים מ-F&A.", "המימוש לא תקין: שימוש בו עלול לגרום לקיפאון.", "המימוש לא תקין: שימוש בו עלול לגרום להרעבה.", "המימוש לא תקין: הערך של val לא תמיד יקודם נכון."], "correct": 4, "official": "הערך של val לא תמיד יקודם נכון. חוט יכול לקרוא את val (ב-*val) ואז להתעכב זמן רב לפני ה-TAS, בזמן שחוטים אחרים קידמו את הערך – וכך להחזיר את val לערך קודם. TAS תמיד מבצע את הכתיבה; החלק האטומי בו הוא רק החזרת הערך הקודם.", "expl": "דוגמה: val = 5. חוט 1 מחשב *val+1 = 6 ונעצר. חוט 2 מקדם ל-6, ‏7, ‏8. חוט 1 מבצע testAndSet(val, 6) – הערך יורד ל-6, ו-3 קידומים הלכו לאיבוד. בניגוד ל-CAS, ‏TAS לא בודק שהערך לא השתנה לפני שהוא כותב.", "check": "לפי הפתרון הרשמי", "exam": "24SC", "examLabel": "סמסטר קיץ תשפ\"ד מועד ג'", "date": "02.12.2024", "id": "24SC-1"}, {"num": "2", "type": "mcq", "topic": "threads", "sub": "חוטים", "q": "נתון תהליך מרובה חוטים כלשהו. איזו טענה בהכרח נכונה לגבי החוטים שלו?", "options": ["אם החוט הראשי מסתיים, כל שאר החוטים ייעצרו מיד.", "אם החוט הראשי מסתיים, שאר החוטים ימשיכו לרוץ עד שיסתיימו.", "אם החוט הראשי מסתיים, חלק מהחוטים ייעצרו מיד ואחרים ימשיכו לרוץ.", "אם החוט הראשי מסתיים, התהליך יסתיים מיד, אבל ייתכן ששאר החוטים ימשיכו לרוץ.", "כל התשובות האחרות אינן נכונות."], "correct": 4, "official": "כל התשובות האחרות אינן נכונות. זה תלוי איך החוט הראשי מסתיים: ייתכן שכל שאר החוטים ייעצרו מיד, וייתכן שכולם ימשיכו לרוץ עד שיסתיימו.", "expl": "אם main חוזר (או קורא ל-exit), כל התהליך מסתיים – כולל כל החוטים. אם החוט הראשי קורא ל-pthread_exit, רק הוא מסתיים, ושאר החוטים ממשיכים. לכן אף טענה לא נכונה \"בהכרח\".", "check": "לפי הפתרון הרשמי", "exam": "24SC", "examLabel": "סמסטר קיץ תשפ\"ד מועד ג'", "date": "02.12.2024", "id": "24SC-2"}, {"num": "3", "type": "mcq", "topic": "process", "sub": "החלפת הקשר", "q": "מהי החלפת הקשר (context switch)?", "options": ["מנגנון לעצירת תהליכים כל פרק זמן קבוע.", "מנגנון להחזרת השליטה למערכת ההפעלה.", "מנגנון שמאפשר לשנות את התהליך הנוכחי שהמעבד מריץ.", "פסיקה שמתרחשת כל זמן קבוע לצורך החלפה בין תהליכים.", "כל התשובות האחרות אינן נכונות."], "correct": 2, "official": "המנגנון שמאפשר להחליף את התהליך הנוכחי שרץ על המעבד.", "expl": "החלפת הקשר שומרת את האוגרים של התהליך הנוכחי ב-PCB שלו, וטוענת את האוגרים של התהליך הבא. עצירה כל פרק זמן קבוע היא פסיקת השעון, והחזרת השליטה למערכת ההפעלה היא trap/פסיקה – אלה מה שמוביל להחלפת הקשר, לא ההחלפה עצמה.", "check": "לפי הפתרון הרשמי", "exam": "24SC", "examLabel": "סמסטר קיץ תשפ\"ד מועד ג'", "date": "02.12.2024", "id": "24SC-3"}, {"num": "4", "type": "mcq", "topic": "fs", "sub": "inode", "q": "סטודנט טען שאפשר לשפר את VSFS כך: אם בכתיבה לקובץ יודעים בוודאות שהתוכן לא משתנה (למשל, כי ה-DATA העדכני ב-cache מפעולה קודמת) – כלומר תוכן הקובץ זהה לגמרי לפני ואחרי הכתיבה – אין צורך לבצע כתיבות לדיסק עבור הפעולה.", "options": ["הסטודנט צודק, וזה ישפר את ביצועי מערכת הקבצים.", "הסטודנט צודק, אבל לא תהיה לזה השפעה על הביצועים (או השפעה זניחה).", "הסטודנט טועה: יש מידע נוסף שצריך לכתוב לדיסק מלבד ה-DATA.", "הסטודנט טועה: חייבים לכתוב את ה-DATA, גם אם הוא זהה ל-DATA הקיים.", "כל התשובות האחרות אינן נכונות."], "correct": 2, "official": "הסטודנט טועה: יש מידע נוסף שצריך לכתוב. אם ה-DATA לא השתנה אין טעם לכתוב ערך זהה, אבל צריך לעדכן את ה-inode עם זמן השינוי האחרון של הקובץ.", "expl": "כל כתיבה לקובץ מעדכנת את mtime (וגם ctime) ב-inode – גם אם התוכן נשאר זהה. לכן לפחות בלוק ה-inode צריך להיכתב.", "check": "לפי הפתרון הרשמי", "exam": "24SC", "examLabel": "סמסטר קיץ תשפ\"ד מועד ג'", "date": "02.12.2024", "id": "24SC-4"}, {"num": "5", "type": "mcq", "topic": "threads", "sub": "ALock", "q": "נתון מנעול ALock עם מערך בגודל N. איזו טענה בהכרח נכונה?", "options": ["אם בתהליך יש N חוטים, חוט שתפס את המנעול יצליח לתפוס אותו שוב רק אחרי שכל N−1 החוטים האחרים תפסו ושחררו אותו.", "אם N+1 חוטים מנסים לתפוס את המנעול, הוא יקיים מניעה הדדית.", "אם N+1 חוטים מנסים לתפוס את המנעול, הוא יקיים חופש מקיפאון.", "אם N+1 חוטים מנסים לתפוס את המנעול, הוא יקיים הוגנות.", "כל התשובות האחרות אינן נכונות."], "correct": 4, "official": "כל התשובות האחרות אינן נכונות. אם יש N+1 חוטים ורק N תאים במערך, המנעול לא יקיים אף אחת מהתכונות.", "expl": "עם N+1 חוטים, שני חוטים מקבלים את אותו תא (המיקום הוא modulo N) – ושניהם יכולים להיכנס יחד כשהתא נדלק.\n\nולגבי הטענה הראשונה: ההוגנות של ALock היא לפי סדר ההגעה, אבל אם החוטים האחרים בכלל לא מנסים לתפוס את המנעול – החוט יכול לתפוס אותו שוב מיד.", "check": "לפי הפתרון הרשמי", "exam": "24SC", "examLabel": "סמסטר קיץ תשפ\"ד מועד ג'", "date": "02.12.2024", "id": "24SC-5"}, {"num": "6", "type": "open", "topic": "memory", "sub": "טבלה הפוכה", "intro": "נתונה מערכת שבה אין טבלאות דפים. במקומן יש ל-MMU (בזיכרון של הרכיב עצמו) טבלת תרגום אחת ויחידה לכל התהליכים והמסגרות.\nזו טבלה הפוכה: האינדקס בטבלה הוא מספר מסגרת, ובכל תא יש מזהה תהליך, מספר הדף של התהליך שממופה למסגרת הזו, ביטי סטטוס וריפוד (אם צריך).\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "6.1", "q": "במערכת עם טבלה הפוכה, גודל דף 8KB, והזיכרון הפיזי המקסימלי 4GB. גודל הטבלה ההפוכה 4MB, ובכל רשומה חצי מהביטים משמשים למספר הדף, והחצי השני למזהה התהליך, לביטי הסטטוס ולריפוד. מה גודל הזיכרון הווירטואלי של תהליך?", "answer": "32TB.\n\nמסגרות בזיכרון הפיזי:\n4GB / 8KB = 512K\nבטבלה ההפוכה רשומה לכל מסגרת – 512K רשומות.\n\nגודל רשומה:\n4MB / 512K = 8B\n\nמספר הדף הוא חצי מהרשומה:\n4B = 32 ביטים, כלומר 2^32 = 4G דפים לכל תהליך\n\nזיכרון וירטואלי:\n4G · 8KB = 2^45 = 32TB"}, {"label": "6.2", "q": "במערכת עם טבלה הפוכה, גודל דף 8KB, והזיכרון הווירטואלי 1GB. גודל הטבלה ההפוכה 16MB, וכל רשומה 4B. הזיכרון של הקרנל תופס לפחות 2 מסגרות. כמה תהליכים עם זיכרון מקסימלי אפשר להריץ?", "answer": "31 תהליכים.\n\nרשומות בטבלה – כלומר מסגרות בזיכרון הפיזי:\n16MB / 4B = 4M\n\nדפים לכל תהליך (בזיכרון מקסימלי הוא משתמש בכולם):\n1GB / 8KB = 128K\n\n4M / 128K = 32 תהליכים\n\nאבל צריך גם זיכרון לקרנל – לפחות 2 מסגרות – ולכן לכל היותר 31 תהליכים."}], "official": "6.1: ‏32TB. 6.2: ‏31.", "expl": "בטבלה הפוכה אין swap (אין איפה לרשום דף שלא בזיכרון), ולכן כל דף של כל תהליך חייב להיות במסגרת.", "check": "חושב", "exam": "24SC", "examLabel": "סמסטר קיץ תשפ\"ד מועד ג'", "date": "02.12.2024", "id": "24SC-6"}, {"num": "7", "type": "open", "topic": "threads", "sub": "מימוש מנעול", "intro": "מנעול חד-פעמי הוא מנעול שאפשר לנעול פעם אחת בלבד: ברגע שחוט תפס אותו בהצלחה, אף חוט לא יכול לתפוס אותו יותר עד סוף התוכנית. פונקציית הנעילה מחזירה 0 לחוטים שנכשלו – בלי לחסום אותם (כמו trylock) – ו-1 לחוט שהצליח. גם אם המנעול \"פנוי\", אחרי שחוט קיבל 1 כל קריאה עתידית בכל חוט תחזיר 0.\nבמנעול חד-פעמי ל-N חוטים מובטח שפונקציית הנעילה לא נקראת יותר מ-N פעמים בכל ריצה.\nלרשותנו פקודת חומרה אטומית Flip, שהופכת ערך לוגי (כמו NOT) ומחזירה את הערך שלפני ההיפוך (התיאור בקוד C הוא להסבר בלבד – הפקודה אטומית).\nאסור להשתמש באובייקטי סנכרון או בפעולות אטומיות מלבד Flip, ויש להבטיח מניעה הדדית וחופש מקיפאון.", "code": "int flip(int* val) {\n    *val = !*val;\n    return !*val;\n}", "parts": [{"label": "7.1", "q": "ממשו מנעול חד-פעמי ל-2 חוטים עם תא זיכרון יחיד (משתנה x שמתקבל כפרמטר): init2 ו-lock2.", "answer": "Flip מבדיל בין החוט הראשון שמנסה לתפוס לבין השני. הראשון צריך לנצח (ולא השני – אחרת, אם רק חוט אחד ינסה, אף אחד לא יתפוס).\n\nvoid init2(int* x) {\n    *x = 1;\n}\nint lock2(int* x) {\n    return flip(x);\n}\n\nהקורא הראשון מקבל 1 (הערך הקודם) והופך ל-0. השני מקבל 0."}, {"label": "7.2", "q": "ממשו מנעול חד-פעמי ל-3 חוטים עם 2 תאי זיכרון (x, y שמתקבלים כפרמטר): init3 ו-lock3.", "answer": "עם x לבד, הקורא הראשון והשלישי היו מקבלים את אותו ערך. אי אפשר לתת לשני לנצח – אולי רק חוט אחד ינסה. לכן משתמשים ב-y כדי \"לפסול\" את החוט השני: רק מי שקיבל 1 מ-y (הראשון והשלישי) ממשיך, ואז x מכריע ביניהם כמו בסעיף הקודם.\n\nvoid init3(int* x, int* y) {\n    *x = *y = 1;\n}\nint lock3(int* x, int* y) {\n    if (flip(y))\n        return flip(x);\n    else\n        return 0;\n}"}, {"label": "7.3", "q": "ממשו מנעול חד-פעמי ל-N חוטים (N פרמטר של פונקציית האתחול): הגדירו את המבנה FlipLock וממשו init, ‏lock, ‏destroy.", "answer": "טורניר: סדרה של משתנים, ובכל אחד נפסלים חלק מהחוטים. כל משתנה מאותחל ל-0. בכל שלב, מי שמקבל 0 מ-flip (הראשון, השלישי, החמישי...) ממשיך לשלב הבא, ומי שמקבל 1 נכשל. כך בכל שלב ממשיכים חצי מהחוטים (מעוגל למעלה), עד שבסוף נשאר רק חוט אחד.\n\ntypedef struct __fliplock {\n    int *arr;\n    int size;\n} FlipLock;\n\nvoid init(FlipLock *lock, int N) {\n    lock->size = ceil(log2(N)) + 1;   // enough levels\n    lock->arr = (int*) calloc(lock->size, sizeof(int));\n}\n\nint lock(FlipLock *lock) {\n    for (int i = 0; i < lock->size; ++i) {\n        if (flip(&lock->arr[i]))\n            return 0;\n    }\n    return 1;\n}\n\nvoid destroy(FlipLock *lock) {\n    free(lock->arr);\n}\n\nלמה בדיוק מנצח אחד? אם k חוטים מגיעים לשלב מסוים, בדיוק ⌈k/2⌉ ממשיכים – בלי קשר לסדר. בשלב הראשון יש לכל היותר N, ואחרי ⌈log2(N)⌉ שלבים נשאר לכל היותר 1. ובכל שלב לפחות אחד ממשיך (הראשון שמגיע), אז אם מישהו ניסה – מישהו ינצח."}], "official": "כמו כאן.", "note": "7.3: בקוד הרשמי כתוב flip(lock->arr[i]) – צריך להעביר את הכתובת: flip(&lock->arr[i]).", "expl": "הטורניר של 7.3 נבדק בסימולציה עם N = 1 עד 16, מספר קריאות 1 עד N, ומאות סדרי ריצה אקראיים: בכל ריצה היה בדיוק מנצח אחד – גם עם ⌈log2 N⌉ שלבים בלבד, וגם עם שלב נוסף.", "check": "נבדק בסימולציה", "exam": "24SC", "examLabel": "סמסטר קיץ תשפ\"ד מועד ג'", "date": "02.12.2024", "id": "24SC-7"}, {"num": "8", "type": "open", "topic": "disk", "sub": "ביצועי דיסק", "intro": "נתונה מערכת עם workload אקראי של 1MB וסדרתי של 50MB.\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "8.1", "q": "פרטו נתונים של 3 דיסקים לבחירתכם, כך ש:\nדיסק א' הוא המהיר ביותר בתרחיש הסדרתי.\nדיסק ב' הוא המהיר ביותר בתרחיש האקראי.\nדיסק ג' אינו האיטי ביותר באף אחד מהתרחישים.\nלכל דיסק פרטו קצב העברה מקסימלי, זמן seek ו-RPM.", "answer": "נותנים לכל הדיסקים אותו RPM (למשל 7200), כך שההמתנה הממוצעת לסיבוב (4.17ms) זהה ולא משפיעה על ההשוואה.\n\nהרעיון: א' – קצב העברה גבוה ו-seek איטי. ב' – seek מהיר מאוד. ג' – באמצע בשניהם.\n\nדיסק א': ‏200 MB/s, ‏seek של 30ms\nדיסק ב': ‏100 MB/s, ‏seek של 0ms (כמעט)\nדיסק ג': ‏150 MB/s, ‏seek של 15ms\n\nזמן = seek + 4.17 + גודל/קצב\n\nסדרתי (50MB):\nא': ‏30 + 4.17 + 250 = 284.2ms – המהיר ביותר\nב': ‏0 + 4.17 + 500 = 504.2ms\nג': ‏15 + 4.17 + 333.3 = 352.5ms – לא האיטי\n\nאקראי (1MB):\nא': ‏30 + 4.17 + 5 = 39.2ms\nב': ‏0 + 4.17 + 10 = 14.2ms – המהיר ביותר\nג': ‏15 + 4.17 + 6.7 = 25.8ms – לא האיטי"}, {"label": "8.2", "q": "משתמש הופתע לגלות שבדיסק מסוים, הקצב הממוצע בתרחיש הסדרתי (50MB) זהה לקצב הממוצע בתרחיש האקראי (1MB). מה יכולים להיות מאפייני הדיסק שמסבירים את זה?", "answer": "בתרחיש האקראי כל 1MB משלם זמן מיקום (seek והמתנה לסיבוב). כדי שהקצב בתרחיש הסדרתי יהיה זהה, גם בו צריך לשלם זמן דומה על כל 1MB – כלומר הקריאה ה\"סדרתית\" לא באמת רציפה מבחינת הדיסק.\n\nהסבר אפשרי (מהפתרון הרשמי): בדיסק אין track skew, וכמות הנתונים הרציפה בצילינדר היא כ-512KB. כל מעבר לצילינדר הבא דורש seek קצר והמתנה ארוכה לסיבוב, ולכן גם הקריאה הסדרתית \"נשברת\" לקטעים קטנים שכל אחד מהם משלם זמן מיקום.\n\nהסבר נוסף: זמן מיקום זניח (כמעט 0) – אז שני התרחישים מגיעים לקצב ההעברה המקסימלי."}], "official": "8.1: דיסק א' 25 MB/s עם seek של 1s, דיסק ב' 1 MB/s עם seek של 0.01s, דיסק ג' 10 MB/s עם seek של 0.5s, כולם באותו RPM. 8.2: אין track skew, ו-512KB רציפים בצילינדר.", "note": "8.1: הדוגמה שבפתרון הרשמי לא עומדת בתנאים, והחישובים שם שגויים. בחישוב נכון:\nסדרתי: א' 1 + 50/25 = 3s; ב' 0.01 + 50/1 = 50.01s; ג' 0.5 + 50/10 = 5.5s\nאקראי: א' 1 + 1/25 = 1.04s; ב' 0.01 + 1/1 = 1.01s; ג' 0.5 + 1/10 = 0.6s\nבאקראי דווקא דיסק ג' הוא המהיר ביותר – לא ב'. (בפתרון הרשמי כתוב 2s, ‏25.01s, ‏3s ו-1.02s, ‏0.51s, ‏0.55s.) הדוגמה כאן נבדקה בסקריפט.", "expl": "", "check": "חושב בסקריפט", "exam": "24SC", "examLabel": "סמסטר קיץ תשפ\"ד מועד ג'", "date": "02.12.2024", "id": "24SC-8"}, {"num": "1", "type": "mcq", "topic": "disk", "sub": "רמות RAID", "q": "בקורס למדנו כמה רמות של RAID. חוו דעתכם על הטענה: ככל שרמת ה-RAID גבוהה יותר, כך היא טובה יותר.", "options": ["הטענה נכונה.", "הטענה לא נכונה.", "לא למדנו מספיק רמות RAID כדי לענות על הטענה.", "RAID-0 לא מספק אמינות, ולכן אי אפשר להשוות אותו לרמות האחרות.", "כל התשובות האחרות אינן נכונות."], "correct": 1, "official": "הטענה לא נכונה. לכל רמת RAID יתרונות וחסרונות, ואין רמה שטובה מרמה אחרת – זה תלוי בדרישות (מלבד RAID-5, שטובה מ-RAID-4). הטענה לא נכונה גם אם מסתכלים רק על ביצועים או רק על אמינות.", "expl": "לדוגמה, RAID-1 אמין יותר מ-RAID-4/5 (שורד יותר כשלים במקרה הטוב), אבל מנצל רק חצי מהקיבולת. ו-RAID-0 מהיר בכתיבה יותר מכולם, אבל לא שורד אף כשל.", "check": "לפי הפתרון הרשמי", "exam": "25AA", "examLabel": "סמסטר א' תשפ\"ה מועד א'", "date": "04.02.2025", "id": "25AA-1"}, {"num": "2", "type": "mcq", "topic": "sched", "sub": "MLFQ", "q": "באלגוריתם התזמון MLFQ, זמן המחזור (turnaround time) הוא אופטימלי.", "options": ["הטענה נכונה, בתנאי שהקוונטום קצר מספיק.", "הטענה נכונה, בתנאי שהקוונטום ארוך מספיק.", "הטענה לא נכונה.", "MLFQ אינו אלגוריתם תזמון.", "כל התשובות האחרות אינן נכונות."], "correct": 2, "official": "הטענה לא נכונה. זמן המחזור האופטימלי הוא באלגוריתם SRTF. ב-MLFQ ייתכן זמן מחזור לא אופטימלי, בלי קשר לקוונטום.", "expl": "MLFQ לא יודע מראש כמה זמן כל תהליך צריך – הוא רק מנחש לפי ההתנהגות. למשל, תהליך קצר שמגיע כשתהליך ארוך עוד בתור העליון יחלוק איתו את המעבד, בעוד ש-SRTF היה מריץ אותו קודם עד הסוף.", "check": "לפי הפתרון הרשמי", "exam": "25AA", "examLabel": "סמסטר א' תשפ\"ה מועד א'", "date": "04.02.2025", "id": "25AA-2"}, {"num": "3", "type": "mcq", "topic": "memory", "sub": "אלגוריתמי החלפה", "q": "מערכת ההפעלה הקצתה לתהליך 3 מסגרות בלבד (לכל אורך הריצה), ובהתחלה כולן פנויות. התהליך פנה לדפים הבאים, לפי הסדר: 0, 1, 3, 2, 4, 0, 4, 2, 1, 3, 3, 4. כמה page faults יהיו עם האלגוריתם האופטימלי (OPT)?", "options": ["6", "7", "8", "9", "כל התשובות האחרות אינן נכונות."], "correct": 1, "official": "7. חמש הגישות הראשונות הן החטאות (הגישה הראשונה לכל דף). אחר כך הגישות 9 ו-10 (לדפים 1 ו-3) הן החטאות.", "expl": "הרצה:\n0, 1, 3 – מילוי המסגרות (3 החטאות): [0, 1, 3]\n2 – החטאה. OPT מפנה את הדף שהשימוש הבא בו הכי רחוק: 0 (גישה 6), 1 (גישה 9), 3 (גישה 10) – מפנים את 3: [0, 1, 2]\n4 – החטאה. 0 (גישה 6), 1 (גישה 9), 2 (גישה 8) – מפנים את 1: [0, 4, 2]\n0, 4, 2 – פגיעות\n1 – החטאה. 0 (לא בשימוש שוב), 4 (גישה 12), 2 (לא בשימוש שוב) – מפנים את 0: [1, 4, 2]\n3 – החטאה. מפנים את 1 או 2 (לא בשימוש שוב): [3, 4, 2]\n3, 4 – פגיעות\n\nסך הכל 7.", "check": "נבדק בסימולציה", "exam": "25AA", "examLabel": "סמסטר א' תשפ\"ה מועד א'", "date": "04.02.2025", "id": "25AA-3"}, {"num": "4", "type": "mcq", "topic": "fs", "sub": "מערכות קבצים", "q": "דיסק קשיח עם מערכת קבצים נפוצה כלשהי (לא VSFS) מחובר למחשב. משתמש ניתק אותו וחיבר למחשב אחר, עם מערכת הפעלה שונה. במחשב האחר:", "options": ["נוכל להשתמש בדיסק ולראות את הקבצים שבו.", "נוכל להשתמש בדיסק, אבל לא נראה את הקבצים שהיו בו לפני החלפת המחשב.", "לא נוכל להשתמש בדיסק בלי למחוק קודם את כל הקבצים שבו.", "לא נוכל להשתמש בדיסק בלי להחליף את מערכת הקבצים שלו (למשל ל-VSFS).", "לא נוכל להשתמש בדיסק בכלל."], "correct": 0, "official": "נוכל להשתמש בדיסק ולראות את הקבצים. מערכת קבצים לא ספציפית למערכת הפעלה, וגם לא הקבצים בה – בכל מערכת הפעלה נוכל להשתמש בדיסק ולראות את הקבצים, בתנאי שמערכת הקבצים הזו נתמכת בה.", "expl": "כל המבנה של מערכת הקבצים (superblock, ‏inodes, תיקיות) שמור על הדיסק עצמו. מערכת הפעלה שמכירה את הפורמט (למשל FAT או NTFS) יכולה לקרוא אותו – כמו בהעברת דיסק-און-קי בין מחשבים.", "check": "לפי הפתרון הרשמי", "exam": "25AA", "examLabel": "סמסטר א' תשפ\"ה מועד א'", "date": "04.02.2025", "id": "25AA-4"}, {"num": "5", "type": "mcq", "topic": "threads", "sub": "מקביליות", "q": "איזו מהטענות הבאות נכונה לגבי מקביליות?", "options": ["הגדלת מספר החוטים בתוכנית תמיד תשפר את הביצועים.", "מקביליות מייתרת את הצורך באובייקטי סנכרון כמו מנעולים וסמפורים.", "מקביליות משפרת את הביצועים על ידי הרצת כמה חוטים במקביל על אותו מעבד/ליבה.", "שימוש במקביליות לא רלוונטי במערכות עם מעבד יחיד (ליבה אחת).", "אפשר לנצל מקביליות לשיפור ביצועים גם עם מעבד יחיד (ליבה אחת)."], "correct": 4, "official": "אפשר לנצל מקביליות לשיפור ביצועים גם עם מעבד יחיד – למשל על ידי חפיפה (overlap). הבלבול עם parallelism לא משנה את התשובה, כפי שלמדנו למשל עם ריבוי תהליכים לשיפור זמן המחזור.", "expl": "עם ליבה אחת, כשחוט אחד חסום על קלט/פלט (דיסק, רשת), חוט אחר יכול להשתמש במעבד. כך הזמן הכולל קצר יותר, למרות שבכל רגע רץ רק חוט אחד.", "check": "לפי הפתרון הרשמי", "exam": "25AA", "examLabel": "סמסטר א' תשפ\"ה מועד א'", "date": "04.02.2025", "id": "25AA-5"}, {"num": "6", "type": "open", "topic": "memory", "sub": "טבלה היררכית", "intro": "נתונה מערכת עם דף של 4KB וטבלת דפים היררכית. כל PTE מכיל מספר מסגרת, 14 ביטים של סטטוס ו-20 ביטים של ריפוד. ה-PTE וה-PDE באותו גודל, וכל טבלה מאוחסנת בדף אחד בדיוק.\nהנתונים האלה תקפים לכל הסעיפים. נתונים שכתובים בתוך סעיף תקפים רק לאותו סעיף.\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "6.1", "q": "טבלת הדפים של תהליך שמשתמש בכל הדפים במרחב הכתובות שלו תופסת 1 + 512 + 512² מסגרות. כמה רמות יש בטבלה, מה מרחב הכתובות של תהליך, ומה גודל הזיכרון הפיזי המקסימלי?", "answer": "3 רמות, מרחב כתובות של 2^39 בתים (512GB), זיכרון פיזי מקסימלי של 2^42 בתים (4TB).\n\nאם בכל טבלה X רשומות, בכל רמה יש פי X טבלאות מהרמה שמעליה, וברמה העליונה תמיד טבלה אחת. לפי 1 + 512 + 512²: ‏X = 512 ו-3 רמות.\n\nמרחב הכתובות:\nברמה התחתונה 512² טבלאות עם 512 רשומות – 512³ = 2^27 דפים\n2^27 · 4KB = 2^39 בתים\n\nזיכרון פיזי:\nגודל רשומה: 4KB / 512 = 8 בתים = 64 ביטים\nPFN: ‏64 − 14 − 20 = 30 ביטים\n2^30 · 4KB = 2^42 בתים"}, {"label": "6.2", "q": "תהליך משתמש ב-30 דפים, ב-4 סגמנטים נפרדים: קוד – 5 דפים רצופים, נתונים – 5 דפים רצופים, ערימה – 10 דפים רצופים, מחסנית – 10 דפים רצופים. כל גישה לכתובת אחרת גורמת לשגיאה. הזיכרון שתופסת טבלת הדפים שלו הוא 100KB במקרה המקסימלי. כמה רמות יש, וכמה כניסות valid יש בסך הכל בכל הרמות?", "answer": "4 רמות, ‏54 כניסות valid.\n\n100KB הם 25 דפים (טבלאות).\n\nכל סגמנט רציף יכול להתפרס לכל היותר על 2 טבלאות ברמה התחתונה – כלומר לכל היותר 8 טבלאות ברמה התחתונה. במקרה המקסימלי לכל אחת מהן הורה משלה ברמה שמעל (עם מצביע אחד), וכן הלאה עד הרמה העליונה, שבה תמיד טבלה אחת.\n\n1 + 8 · (מספר הרמות − 1) = 25\nמספר הרמות − 1 = 3, כלומר 4 רמות\n\nכניסות valid:\nרמה תחתונה: 30 (אחת לכל דף)\nבכל אחת מ-3 הרמות שמעל: 8\n30 + 3 · 8 = 54"}, {"label": "6.3", "q": "טבלת הדפים במערכת היא בת 3 רמות, והתהליך זהה לזה של הסעיף הקודם. כמה זיכרון תתפוס הטבלה במקרה המינימלי, וכמה כניסות valid יהיו בסך הכל?", "answer": "12KB, ‏32 כניסות valid.\n\nבמקרה המינימלי כל 30 הדפים ממופים באותה טבלה ברמה התחתונה. עם 3 רמות – טבלה אחת בכל רמה:\n3 מסגרות = 12KB\n\nכניסות valid:\nרמה תחתונה: 30\nועוד כניסה אחת בכל אחת מ-2 הרמות שמעל\n30 + 2 = 32"}], "official": "6.1: ‏3 רמות, 2^39, ‏2^42. 6.2: ‏4 רמות, 54. 6.3: ‏12KB, ‏32.", "expl": "", "check": "חושב", "exam": "25AA", "examLabel": "סמסטר א' תשפ\"ה מועד א'", "date": "04.02.2025", "id": "25AA-6"}, {"num": "7", "type": "open", "topic": "sync", "sub": "סמפורים", "intro": "נתונה מערכת מרובת חוטים שמנהלת מחסן בפתרון יצרן-צרכן, עם תוספת: כל מוצר צריך לעבור עיבוד לפני שאפשר לצרוך אותו.\nהפעולות:\nvoid produce() – מייצרת מוצר לא מעובד ומוסיפה אותו למחסן.\nvoid process() – מוציאה מוצר לא מעובד מהמחסן, מעבדת אותו, ומחזירה את המוצר המעובד למחסן.\nvoid consume() – מוציאה מוצר מעובד מהמחסן וצורכת אותו.\nעיבוד עלול לקחת זמן רב, ולכן בזמן העיבוד process לא תופסת מקום במחסן (היא מפנה את המדף, ואחרי העיבוד מקצה מדף מחדש).\nהטיפוס Item מייצג מוצר (מעובד או לא), והקבוע N הוא מספר המדפים במחסן (מעובדים ולא מעובדים יחד).\nפונקציות נתונות (אין צורך לממש):\nItem produce_item() – מייצרת מוצר לא מעובד. בטוחה לשימוש במקביל.\nvoid consume_item(Item) – צורכת מוצר מעובד. בטוחה לשימוש במקביל (על מוצרים שונים). אסור לקרוא לה עם מוצר לא מעובד, או פעמיים לאותו מוצר.\nvoid add_item(Item) – מוסיפה מוצר למחסן. לא בטוחה לשימוש במקביל, ואסור לקרוא לה כשיש במחסן N מוצרים.\nItem del_item() – מוציאה מוצר אחד מהמחסן (מעובד או לא) ומחזירה אותו. לא בטוחה לשימוש במקביל, ואסור לקרוא לה כשהמחסן ריק.\nItem process_item(Item) – מקבלת מוצר לא מעובד ומחזירה את המוצר המעובד. בטוחה לשימוש במקביל. אסור להשתמש במוצר המקורי אחרי העיבוד.\nBOOL is_processed(Item) – מחזירה TRUE אם המוצר מעובד.\nהמחסן מתנהג כמו תור FIFO (המוצר הראשון שנוסף הוא הראשון שיוצא).", "parts": [{"label": "7.1", "q": "לפי הגדרת המחסן, בכל מימוש ייתכן תרחיש דומה לקיפאון: יש חוט (אחד או יותר) שעיבד מוצר, ויש חוט (אחד או יותר) שרוצה לצרוך מוצר מעובד – אבל אי אפשר לצרוך. תארו תרחיש כזה (שלא תלוי במימוש).", "answer": "חוט 1 מבצע produce עד שהמחסן מלא (N פעמים).\nחוט 2 מבצע process: מוציא מוצר לא מעובד ומתחיל לעבד אותו.\nחוט 1 מבצע עוד produce לפני שחוט 2 סיים – המחסן שוב מלא.\nחוט 2 מסיים את העיבוד – ולא יכול להחזיר את המוצר, כי המחסן מלא.\nחוט 3 מבצע consume – אין במחסן אף מוצר מעובד.\n\nהמוצר המעובד היחיד תקוע אצל חוט 2, והמחסן מלא במוצרים לא מעובדים."}, {"label": "7.2", "q": "ממשו את פעולות המחסן עם אובייקטי סנכרון בלבד (מנעולים, סמפורים, משתני תנאי). הפתרון צריך להיות יעיל ככל האפשר, בלי spinning. אין צורך לפתור את הבעיה מהסעיף הקודם. ציינו ערכי אתחול של משתנים גלובליים.", "answer": "מפרידים את הסמפור full לשני משאבים נפרדים: מוצרים לא מעובדים ומוצרים מעובדים. כשמוציאים מוצר מסוג מסוים, מוציאים מוצרים מהמחסן ומחזירים אותם לסוף התור, עד שמגיעים למוצר מהסוג הנכון.\n\nsem_t empty;     // # free spots, init to N\nsem_t unprocd;   // # unprocessed items, init to 0\nsem_t procd;     // # processed items, init to 0\nsem_t mutex;     // protect access to warehouse, init to 1\n\nvoid produce() {\n    Item i = produce_item();\n    sem_wait(&empty);\n    sem_wait(&mutex);\n    add_item(i);\n    sem_post(&mutex);\n    sem_post(&unprocd);\n}\n\nvoid consume() {\n    sem_wait(&procd);\n    sem_wait(&mutex);\n    Item i = del_item();\n    while (!is_processed(i)) {\n        add_item(i);\n        i = del_item();\n    }\n    sem_post(&mutex);\n    sem_post(&empty);\n    consume_item(i);\n}\n\nvoid process() {\n    sem_wait(&unprocd);\n    sem_wait(&mutex);\n    Item i = del_item();\n    while (is_processed(i)) {\n        add_item(i);\n        i = del_item();\n    }\n    sem_post(&mutex);\n    sem_post(&empty);          // free the shelf while processing\n    i = process_item(i);\n    sem_wait(&empty);          // take a shelf again\n    sem_wait(&mutex);\n    add_item(i);\n    sem_post(&mutex);\n    sem_post(&procd);\n}\n\nלמה הלולאה תמיד מוצאת מוצר מתאים? מי שעבר את sem_wait(&procd) \"שריין\" מוצר מעובד שנמצא במחסן, ורק הוא מוציא אותו (תחת mutex). כך גם עם unprocd. וכל del_item שאחריו add_item מיד לא משנה את כמות המוצרים – אז אף פעם לא מוסיפים למחסן מלא."}], "official": "כמו כאן.", "expl": "הקוד של 7.2 הורץ עם 2 יצרנים, 2 מעבדים ו-2 צרכנים: 20,000 מוצרים עברו את כל השלבים, אף מוצר לא נצרך לפני עיבוד ולא עובד פעמיים, והמחסן לא חרג מהגבולות. (כשמחסן קטן מתמלא, הריצה נתקעת בדיוק בתרחיש של 7.1 – זה צפוי, ולא באג במימוש.)", "check": "הורץ עם חוטים אמיתיים", "exam": "25AA", "examLabel": "סמסטר א' תשפ\"ה מועד א'", "date": "04.02.2025", "id": "25AA-7"}, {"num": "8", "type": "open", "topic": "disk", "sub": "SSD", "intro": "נתון כונן SSD עם דף של 6KB ובלוק של 6MB. על הכונן יש מערכת קבצים VSFS עם מצביע של 4 בתים, ובכל inode יש 10 מצביעים ישירים, עקיף אחד, עקיף כפול אחד ועקיף משולש אחד.\nכל התייחסות של מערכת הקבצים ל\"בלוק\" בדיסק קשיח מוחלפת כאן בדף של ה-SSD (לא בבלוק SSD). למשל, ה-inode מכיל מצביעים לדפים.\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "8.1", "q": "מה הגודל המקסימלי של קובץ, וכמה דפים של DATA הוא יתפוס בכונן?", "answer": "מצביעים בדף:\n6KB / 4B = 1536\n\nדפי נתונים:\nישירים: 10\nעקיף: 1536\nעקיף כפול: 1536²\nעקיף משולש: 1536³\n\nגודל מקסימלי:\n(10 + 1536 + 1536² + 1536³) · 6KB = 22,279,615,475,712 בתים (בערך 20TB)\n\nדפים בכונן – גם דפי המצביעים:\n10 + (1 + 1536) + (1 + 1536 + 1536²) + (1 + 1536 + 1536² + 1536³) = 3,628,601,869 דפים"}, {"label": "8.2", "q": "רוצים לקרוא מקובץ את הדף שמספרו 17,425 (מספור מ-0). מספר ה-inode ידוע, ואף cache לא מכיל מידע רלוונטי. טבלאות המיפוי (log table + data table) זמינות בזיכרון של הכונן, וזמן הגישה אליהן זניח. פרטו בקצרה ובדיוק איך המערכת מאתרת את הדף, ואת כל קריאות וכתיבות הדפים הנדרשות.", "answer": "איתור הדף:\nמדלגים על 10 הדפים הישירים: 17,425 − 10 = 17,415\nמדלגים על 1536 הדפים של העקיף: 17,415 − 1536 = 15,879\nנשארנו בעקיף הכפול. כל מצביע בדף העקיף הכפול מכסה 1536 דפים:\n15,879 = 10 · 1536 + 519\nכלומר המצביע ה-11 (אינדקס 10) בדף העקיף הכפול, ובדף העקיף שהוא מצביע אליו – המצביע ה-520 (אינדקס 519).\n\nקריאות:\n1. הדף שמכיל את ה-inode\n2. דף העקיף הכפול\n3. דף המצביעים שכתובתו במצביע ה-11 בדף העקיף הכפול\n4. דף הנתונים שכתובתו במצביע ה-520 בדף המצביעים\n\nבכל גישה לכונן מחפשים קודם את הדף בטבלת המיפוי log table, ואם הוא לא שם – בטבלת המיפוי data table.\n\nכתיבה: עדכון זמן הגישה האחרון ב-inode (ב-SSD הכתיבה הולכת לדף חדש בלוג, ומעדכנים את טבלת המיפוי)."}, {"label": "8.3", "q": "סטודנט טען שכתיבה של קובץ גדול בבת אחת תהיה מהירה משמעותית מכתיבה שלו בחלקים – דף שלם אחד של נתונים (6KB) בכל פעם. האם הוא צודק?", "answer": "הסטודנט טועה. כל עוד כותבים דף שלם בכל פעם, אין הבדל משמעותי בין כתיבה בבת אחת לכתיבה בחלקים, כי ה-FTL הוא log structured: כל כתיבה של דף הולכת לדף הפנוי הבא בבלוק הפתוח, בלי קשר לשאר הכתיבות."}], "official": "8.1: הגודל (10 + 1536 + 1536² + 1536³) · 6KB, והדפים כמו כאן. 8.2: כמו כאן. 8.3: הסטודנט טועה.", "expl": "טעויות נפוצות ב-8.2: לא לפרט לאיזה מצביע ולאיזה דף ניגשים, או לא לפרט איך מחפשים כל דף בכונן (דרך טבלאות המיפוי).", "check": "חושב בסקריפט", "exam": "25AA", "examLabel": "סמסטר א' תשפ\"ה מועד א'", "date": "04.02.2025", "id": "25AA-8"}, {"num": "1", "type": "mcq", "topic": "disk", "sub": "SSD", "q": "נתונים שני כונני SSD ריקים עם נתונים טכניים זהים, ובוצעו עליהם בדיוק אותן פעולות: אותן קריאות/כתיבות, עם אותם נתונים, לאותם דפים לוגיים, באותו סדר. איזו טענה בהכרח נכונה?", "options": ["המיפוי מדפים לוגיים לפיזיים יהיה זהה בין הכוננים, והדפים יכילו את אותם נתונים.", "המיפוי מדפים לוגיים לפיזיים עלול להיות שונה בין הכוננים, אבל הדפים יכילו את אותם נתונים.", "המיפוי מדפים לוגיים לפיזיים יהיה זהה בין הכוננים, אבל ייתכן שחלק מהדפים (או כולם) יכילו נתונים שונים.", "המיפוי מדפים לוגיים לפיזיים עלול להיות שונה בין הכוננים, וייתכן שחלק מהדפים (או כולם) יכילו נתונים שונים.", "אי אפשר לבצע את אותן פעולות על 2 הכוננים."], "correct": 3, "official": "המיפוי עלול להיות שונה, וייתכן שחלק מהדפים יכילו נתונים שונים. השחיקה אקראית, ולכן אותם דפים לוגיים עלולים להיות ממופים לדפים פיזיים שונים (גם עם אותן גישות). בגלל הפרעות קריאה/כתיבה (read disturbs / program disturbs) ייתכן גם שדפים ישתבשו ויכילו נתונים שונים (בכונני SSD זה מטופל במנגנונים לזיהוי ותיקון שגיאות).", "expl": "המילה \"בהכרח\" חשובה: תאי הפלאש לא זהים פיזית בין שני כוננים. תא שנשחק או בלוק פגום בכונן אחד ישנו את החלטות ה-FTL (לאן לכתוב, מתי לעשות garbage collection), ושגיאות ביטים אקראיות יכולות לשבש נתונים.", "check": "לפי הפתרון הרשמי", "exam": "25AB", "examLabel": "סמסטר א' תשפ\"ה מועד ב'", "date": "25.02.2025", "id": "25AB-1"}, {"num": "2", "type": "mcq", "topic": "memory", "sub": "אלגוריתמי החלפה", "q": "מערכת ההפעלה הקצתה לתהליך 3 מסגרות בלבד (לכל אורך הריצה), ובהתחלה כולן פנויות. התהליך פנה לדפים הבאים, לפי הסדר: 0, 1, 3, 2, 4, 0, 4, 2, 1, 3, 3, 4. כמה page faults יהיו עם MRU (Most Recently Used – ההפך מ-LRU)?", "options": ["6", "7", "8", "9", "כל התשובות האחרות אינן נכונות."], "correct": 2, "official": "8. חמש הגישות הראשונות הן החטאות (הגישה הראשונה לכל דף). אחר כך הגישות 8, 10, 12 (לדפים 2, 3, 4) הן החטאות.", "expl": "MRU מפנה את הדף שניגשו אליו הכי לאחרונה.\n0, 1, 3 – מילוי (3 החטאות): [0, 1, 3]\n2 – החטאה, מפנים את 3: [0, 1, 2]\n4 – החטאה, מפנים את 2: [0, 1, 4]\n0, 4 – פגיעות\n2 – החטאה, מפנים את 4 (הגישה האחרונה): [0, 1, 2]\n1 – פגיעה\n3 – החטאה, מפנים את 1: [0, 3, 2]\n3 – פגיעה\n4 – החטאה, מפנים את 3: [0, 4, 2]\n\nסך הכל 8.", "check": "נבדק בסימולציה", "exam": "25AB", "examLabel": "סמסטר א' תשפ\"ה מועד ב'", "date": "25.02.2025", "id": "25AB-2"}, {"num": "3", "type": "mcq", "topic": "intro", "sub": "DMA", "q": "מה תפקידו של ה-DMA?", "options": ["סיוע בתרגום כתובות וירטואליות.", "ביצוע החלפת הקשר (context switch).", "העברת מידע בין התקני קלט-פלט לזיכרון.", "סיוע למתזמן (scheduler) בקבלת החלטה.", "כל התשובות האחרות אינן נכונות."], "correct": 2, "official": "העברת מידע בין התקני קלט-פלט לזיכרון – במקום שהמעבד יעסוק בכך.", "expl": "בלי DMA המעבד היה מעתיק כל מילה מההתקן לזיכרון בעצמו (programmed I/O). עם DMA המעבד רק מגדיר את ההעברה, ממשיך להריץ תהליכים אחרים, ומקבל פסיקה כשההעברה הסתיימה. תרגום כתובות הוא תפקיד ה-MMU.", "check": "לפי הפתרון הרשמי", "exam": "25AB", "examLabel": "סמסטר א' תשפ\"ה מועד ב'", "date": "25.02.2025", "id": "25AB-3"}, {"num": "4", "type": "mcq", "topic": "process", "sub": "fork", "q": "כמה תהליכים נוצרו במהלך הרצת התוכנית הבאה, כולל התהליך הראשי? (תזכורת: באופרטור &&, אם האופרנד הראשון הוא FALSE, השני לא מבוצע.)", "code": "int main()\n{\n    for (int i = 0; i < 3; ++i) {\n        if (!fork() && !fork()) {\n            break;\n        }\n    }\n}", "options": ["7", "8", "15", "18", "31"], "correct": 2, "official": "15. בכל איטרציה, התנאי יוצר 2 תהליכים חדשים לכל תהליך שמגיע אליה. באיטרציה הראשונה הראשי יוצר 2 בנים – אחד יוצא מהלולאה ואחד ממשיך. הראשי והבן שהמשיך יוצרים כל אחד 2 בנים, מהם 2 ממשיכים – סך הכל 7. לאיטרציה השלישית מגיעים 4 תהליכים, שכל אחד יוצר 2 בנים – עוד 8, סך הכל 15.", "expl": "בכל תהליך שמגיע לתנאי:\nה-fork הראשון יוצר בן. אצל ההורה !fork() הוא שקר – הוא ממשיך בלולאה (ולא מבצע את ה-fork השני).\nאצל הבן !fork() הוא אמת – הוא מבצע fork נוסף ויוצר נכד. אצל הבן !fork() של הנכד הוא שקר – הבן ממשיך בלולאה. אצל הנכד שניהם אמת – הוא יוצא מהלולאה.\n\nכלומר כל תהליך בלולאה יוצר 2 תהליכים, ומספר התהליכים שממשיכים מוכפל בכל איטרציה:\n1 + 2 + 4 + 8 = 15\n\n(נבדק גם בהרצה.)", "check": "הורץ", "exam": "25AB", "examLabel": "סמסטר א' תשפ\"ה מועד ב'", "date": "25.02.2025", "id": "25AB-4"}, {"num": "5", "type": "mcq", "topic": "threads", "sub": "ALock", "q": "נתונה מערכת עם N+1 חוטים, שמשתמשת במנעול Anderson (ALock) עם מערך בגודל N. מה נכון?", "options": ["המנעול עובד באופן תקין.", "המנעול מקיים מניעה הדדית.", "המנעול מקיים חופש מקיפאון והוגנות.", "תתקבל שגיאת קומפילציה או ריצה: אי אפשר לממש מנעול עם מערך בגודל N במערכת עם N+1 חוטים.", "כל התשובות האחרות אינן נכונות."], "correct": 4, "official": "כל התשובות האחרות אינן נכונות. אם משתמשים במנעול אנדרסון עם מערך בגודל N במערכת עם N+1 חוטים, המנעול לא יקיים אף אחת מהתכונות.", "expl": "החוט ה-N+1 בתור מקבל את אותו תא כמו הראשון (modulo N). כשהתא נדלק, שניהם יכולים להיכנס – והמניעה ההדדית נשברת. הקוד עצמו מתקמפל ורץ בלי שגיאה.", "check": "לפי הפתרון הרשמי", "exam": "25AB", "examLabel": "סמסטר א' תשפ\"ה מועד ב'", "date": "25.02.2025", "id": "25AB-5"}, {"num": "6", "type": "open", "topic": "memory", "sub": "TLB", "intro": "בקטע הקוד הבא מכפילים 2 מטריצות (המערך c מכיל בהתחלה רק אפסים).\nהנחות:\nגודל דף 4KB.\nהקוד של multiply מאוחסן בדף אחד, ובזמן הפעלת הפונקציה כל המחסנית בדף אחד.\nint תופס 4 בתים.\nב-TLB יש 8 כניסות, ומדיניות הפינוי שלו היא LRU. ה-TLB ריק בתחילת הפונקציה.\nכל אחד מהמערכים a, b, c מתחיל בדיוק בתחילת דף.\nבשפת C מערך דו-ממדי מאוחסן \"לפי שורות\": קודם כל איברי השורה הראשונה, אחר כך השנייה, וכן הלאה.", "code": "int a[1024][1024], b[1024][1024], c[1024][1024];\nvoid multiply() {\n    for (int i = 0; i < 1024; i++)\n        for (int j = 0; j < 1024; j++)\n            for (int k = 0; k < 1024; k++)\n                c[i][j] += a[i][k] * b[k][j];\n}", "parts": [{"label": "6.1", "q": "כמה החטאות TLB יהיו בזמן ביצוע הקוד?", "answer": "2 + 1024 + 1024 + 1024³.\n\nשורה של מטריצה היא 1024 · 4B = 4KB – בדיוק דף אחד.\n\nקוד ומחסנית: ניגשים אליהם כל הזמן, אז אחרי שנכנסו ל-TLB הם לא מפונים (LRU). החטאה אחת לכל אחד – 2.\n\na: הגישה היא לפי שורות. לאורך כל לולאות j ו-k ניגשים רק לשורה i – כלומר לדף אחד. בין שתי גישות לדף הזה ניגשים רק ל-4 דפים אחרים (דף של b, הדף של c, קוד, מחסנית), אז הוא נשאר בין 5 הדפים האחרונים – ולא מפונה (יש 8 כניסות). החטאה אחת לכל שורה – 1024.\n\nc: אותו דבר – בכל i ניגשים רק לשורה i. ‏1024.\n\nb: הגישה היא לפי עמודות – b[k][j] עם k משתנה. כל k הוא שורה אחרת, כלומר דף אחר, וכל עמודה עוברת על כל 1024 הדפים של b. עם 8 כניסות בלבד – כל גישה ל-b היא החטאה: 1024³."}, {"label": "6.2", "q": "הציעו שינוי בקוד שיוריד את מספר ההחטאות למינימום (ו-c עדיין תכיל את אותה תוצאה בסוף). אין צורך לממש, רק לפרט. כמה החטאות יהיו עם השינוי?", "answer": "2 + 1024 + 1024 + 1024².\n\nשומרים את b בצורה משוחלפת (transpose), כלומר bT[j][k] = b[k][j], ומחשבים:\nc[i][j] += a[i][k] * bT[j][k]\n\nעכשיו גם ל-b ניגשים \"לפי שורות\": בלולאת k ניגשים רק לשורה j של bT – דף אחד. לכל זוג (i, j) יש החטאה אחת ב-b, כלומר 1024 לכל שורה של c – ובסך הכל 1024².\n\n(השחלוף עצמו גורם לעוד כ-1024² החטאות, אבל זה לא נדרש בתשובה.)"}], "official": "6.1: ‏2 + 1024 + 1024 + 1024³. 6.2: שחלוף של b, ‏2 + 1024 + 1024 + 1024².", "expl": "פתרון שקול: להחליף את סדר הלולאות ל-i, k, j. אז b[k][j] נגיש לפי שורות (שורה k בלולאת j), ו-a[i][k] קבוע בלולאה הפנימית – ושוב 1024² החטאות ב-b.", "check": "חושב", "exam": "25AB", "examLabel": "סמסטר א' תשפ\"ה מועד ב'", "date": "25.02.2025", "id": "25AB-6"}, {"num": "7", "type": "open", "topic": "sync", "sub": "מימוש סמפור", "intro": "בשאלה זו יש לממש סמפור: להגדיר את שדות האובייקט ולממש את sem_wait ו-sem_post. בכל סעיף מימוש נפרד, לפי המגבלות שבו. המימוש צריך להיות יעיל ככל האפשר (בלי spinning), ולקיים הוגנות וחופש מקיפאון. מותר להשתמש בקריאת המערכת yield().", "parts": [{"label": "7.1", "q": "ממשו סמפור עם מנעולים ומשתני תנאי בלבד (pthread_mutex_t, pthread_cond_t).", "answer": "מגינים על המונה במנעול, וממתינים על משתנה תנאי כשהמונה 0.\n\ntypedef struct __sem_t1 {\n    pthread_mutex_t lock;\n    pthread_cond_t cond;\n    int counter;   // init to semaphore init value\n} sem_t1;\n\nvoid sem_wait(sem_t1 *sem) {\n    pthread_mutex_lock(&sem->lock);\n    while (sem->counter == 0)\n        pthread_cond_wait(&sem->cond, &sem->lock);\n    --sem->counter;\n    pthread_mutex_unlock(&sem->lock);\n}\n\nvoid sem_post(sem_t1 *sem) {\n    pthread_mutex_lock(&sem->lock);\n    ++sem->counter;\n    pthread_cond_signal(&sem->cond);\n    pthread_mutex_unlock(&sem->lock);\n}\n\nwhile ולא if – כי חוט אחר עלול \"לחטוף\" את הערך בין ה-signal לבין ההתעוררות."}, {"label": "7.2", "q": "ממשו סמפור עם פעולות מעבד אטומיות בלבד: testAndSet, ‏compareAndSet, ‏fetchAndAdd, ‏fetchAndSub.", "answer": "הרעיון – כמו מנעול N (מבחן 22BC): ‏wait הוא כניסה לתור, ו-post מאפשר לעוד חוט אחד לעבור. ticket מחלק מספרים, ו-turn הוא כמה חוטים מותר להם לעבור עד עכשיו. חוט עם הכרטיס t עובר כש-t < turn. ההמתנה עם yield, כדי לא לבזבז מעבד.\n\ntypedef struct __sem_t2 {\n    int ticket;   // init to 0\n    int turn;     // init to semaphore init value\n} sem_t2;\n\nvoid sem_wait(sem_t2 *sem) {\n    int myticket = fetchAndAdd(&sem->ticket);\n    while (myticket >= sem->turn)\n        yield();\n}\n\nvoid sem_post(sem_t2 *sem) {\n    fetchAndAdd(&sem->turn);\n}\n\nהחוטים עוברים לפי סדר הכרטיסים – הוגנות.\n\nמימוש נוסף (מהפתרון הרשמי): ticket lock לגישה לערך הסמפור, עם מונה:\n\ntypedef struct {\n    int ticket;    // init to 0\n    int turn;      // init to 0\n    int counter;   // init to semaphore init value\n} sem_t2;\n\nvoid sem_wait(sem_t2 *sem) {\n    int myticket = fetchAndAdd(&sem->ticket);\n    while (myticket != sem->turn)\n        yield();\n    while (sem->counter == 0)\n        yield();\n    fetchAndSub(&sem->counter);\n    fetchAndAdd(&sem->turn);\n}\n\nvoid sem_post(sem_t2 *sem) {\n    fetchAndAdd(&sem->counter);\n}"}], "official": "7.1: כמו כאן. 7.2: שני המימושים (ticket lock עם מונה, ומימוש בדומה למנעול N).", "note": "7.2: במימוש השני שבפתרון הרשמי (בדומה למנעול N) כתוב while (myticket > sem->turn) – זה לא נכון: עם ערך התחלתי 1, גם הכרטיס 0 וגם הכרטיס 1 עוברים, ו-2 חוטים נכנסים יחד. צריך >=. נבדק בהרצה עם 6 חוטים וסמפור בינארי: עם > היו עד 2 חוטים בפנים, ועם >= רק 1. גם המימוש הראשון (עם counter) נבדק – רק חוט אחד בפנים.", "expl": "", "check": "הורץ עם חוטים אמיתיים", "exam": "25AB", "examLabel": "סמסטר א' תשפ\"ה מועד ב'", "date": "25.02.2025", "id": "25AB-7"}, {"num": "8", "type": "open", "topic": "fs", "sub": "VSFS", "intro": "נתון דיסק קשיח עם מערכת קבצים VSFS משודרגת: בכל inode יש מקום ל-256 בתים של נתוני הקובץ, בשדה בתוך ה-inode (ולא בבלוק DATA). רק כשהקובץ גדול מזה, משתמשים במצביעים להמשך.\nנתונים:\nמהירות סיבוב 7500 RPM, ‏seek ממוצע 15ms, קצב העברה מקסימלי 1 MB/s.\nגודל בלוק 4KB, גודל מצביע 8 בתים.\ninode בגודל 512 בתים (כולל 256 בתי הנתונים).\nבכל inode יש 9 מצביעים ישירים, 3 עקיפים ועקיף כפול אחד.\nבנתונים של תיקייה יש טבלה עם 2 עמודות; גודל כל שורה הוא מספר התווים בשם הקובץ (בית לכל תו) ועוד בית אחד.\nגודל הנתונים של קישור סימבולי הוא בית לכל תו.\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "8.1", "q": "מה הגודל המקסימלי של קובץ, וכמה בלוקי DATA הוא יתפוס?", "answer": "מצביעים בבלוק:\n4096 / 8 = 512\n\nגודל מקסימלי:\n256B + (9 + 3 · 512 + 512²) · 4KB = 1,080,070,400 בתים (בערך 1GB)\n\nבלוקים – גם בלוקי המצביעים:\n9 ישירים\n3 עקיפים + 3 · 512\nעקיף כפול: 1 + 512 + 512²\n9 + (3 + 1536) + (1 + 512 + 262,144) = 264,205"}, {"label": "8.2", "q": "משתמש קרא 116KB מתחילת הקובץ /home/mta/os/symlink, שהוא קישור סימבולי אל /usr/tmp/data/myfile. אף cache לא מכיל מידע רלוונטי. מה הזמן המינימלי של הפעולה? אפשר להניח כל תרחיש שמוביל לזמן הקצר ביותר, כל עוד הוא עומד בנתונים.", "answer": "125ms.\n\nקודם צריך לקרוא inode ו-DATA של 4 תיקיות (/, home, mta, os) ושל הקישור עצמו. אחר כך של 3 תיקיות בנתיב השני (usr, tmp, data – השורש כבר נקרא) ושל myfile. סך הכל 9 פעמים inode + DATA.\n\nבמקרה המינימלי, ה-DATA של כל אלה נמצא בתוך 256 הבתים של ה-inode. בבלוק נכנסים 8 inodes, אז 9 ה-inodes יושבים ב-2 בלוקים רצופים.\n\nנתוני הקובץ:\n116KB − 256B = 118,528 בתים, כלומר 29 בלוקים (מעוגל למעלה)\n9 ישירים ו-20 דרך מצביע עקיף – צריך לקרוא גם את בלוק המצביעים: 30 בלוקים\n\nבמקרה המינימלי כל הבלוקים רצופים, מיד אחרי 2 בלוקי ה-inodes, ואין seek או המתנה לסיבוב. זו קריאה רציפה של:\n2 + 30 = 32 בלוקים = 128KB\n\nבקצב של 1 MB/s:\n128KB / 1024KB/s = 0.125s = 125ms\n\nאי אפשר לקרוא רק את החלקים הנחוצים מכל בלוק – בקריאה רציפה עוברים על כל הנתונים בדרך."}, {"label": "8.3", "q": "סטודנט טען שמספר הקבצים המקסימלי שאפשר לגשת אליהם במערכת הזו חסום וקטן מאוד, למרות שאין מידע על טבלת ה-inodes (וגם אם היא גדולה). האם הוא צודק? אם כן – איזה נתון מגביל ומה המספר; אחרת – איזה נתון חסר ומה המספר כפונקציה שלו.", "answer": "הסטודנט צודק: 256 קבצים.\n\nכל רשומה בתיקייה מכילה רק בית אחד (8 ביטים) מעבר לשם הקובץ – וזה מספר ה-inode. לכן אפשר להפנות רק למספרי inode שאפשר לייצג ב-8 ביטים: 2^8 = 256."}], "official": "8.1: ‏256B + (9 + 3·512 + 512²)·4KB, ו-9 + 3+3·512 + 1+512+512² בלוקים. 8.2: ‏125ms. 8.3: הסטודנט צודק, 256 קבצים.", "expl": "ב-8.2 הפתרון הרשמי מציין שהפעולה גם מעדכנת את זמן הגישה ב-inode (תוספת של כ-3.9ms לכתיבת בלוק), אבל זה לא נדרש במקרה המינימלי.", "check": "חושב בסקריפט", "exam": "25AB", "examLabel": "סמסטר א' תשפ\"ה מועד ב'", "date": "25.02.2025", "id": "25AB-8"}, {"num": "1", "type": "mcq", "topic": "deadlock", "sub": "הרעבה וקיפאון", "q": "איזו טענה נכונה?", "options": ["בכל מנעול שבו אפשרי קיפאון, בהכרח אפשרית גם הרעבה.", "בכל מנעול שבו אפשרית הרעבה, בהכרח אפשרי גם קיפאון.", "קיים מנעול שבו אפשריים גם קיפאון וגם הרעבה, אבל לא בכל מנעול שבו אפשרי אחד מהם בהכרח אפשרי גם השני.", "לא קיים מנעול שבו אפשריים גם קיפאון וגם הרעבה.", "כל התשובות האחרות אינן נכונות."], "correct": 2, "official": "קיים מנעול שבו אפשריים שניהם, אבל לא בכל מנעול. ראינו מנעולים שלא מקיימים חופש מקיפאון אבל כן מקיימים הוגנות, וגם להפך – אבל לא כל המנעולים כאלה.", "expl": "דוגמאות: מנעול TAS פשוט – חופשי מקיפאון אבל לא הוגן (הרעבה בלי קיפאון). מנעול ה-flags עם \"while (flags[k] > 0)\" ממבחן 24SB – הוגן אבל עלול להיתקע (קיפאון בלי הרעבה). ומנעול כמו Lock1 ממבחן 24SA – גם קיפאון וגם הרעבה.", "check": "לפי הפתרון הרשמי", "exam": "25AC", "examLabel": "סמסטר א' תשפ\"ה מועד ג'", "date": "26.03.2025", "id": "25AC-1"}, {"num": "2", "type": "mcq", "topic": "memory", "sub": "TLB", "q": "אם נגדיל את ה-TLB:", "options": ["בהכרח נגדיל את ה-hit ratio.", "לא ייתכן שנקטין את ה-hit ratio.", "נתפוס יותר מקום בזיכרון הפיזי (RAM) עבור הרשומות הנוספות.", "נתפוס פחות מקום בזיכרון הפיזי (RAM), כי הרשומות יעברו ל-TLB.", "כל התשובות האחרות אינן נכונות."], "correct": 4, "official": "כל התשובות האחרות אינן נכונות. הגדלת ה-TLB יכולה להקטין את ה-hit ratio (אבל לא בהכרח). אין קשר בין גודל ה-TLB לבין כמות הזיכרון שתופסים ב-RAM – ה-TLB רק חוסך גישות לטבלאות הדפים.", "expl": "ה-TLB הוא מטמון בחומרה, בתוך המעבד – הוא לא מחזיק את טבלת הדפים ולא מחליף אותה. לגבי ה-hit ratio: עם מדיניות פינוי כמו FIFO, הגדלה יכולה דווקא להקטין אותו (אנומליית Belady).", "check": "לפי הפתרון הרשמי", "exam": "25AC", "examLabel": "סמסטר א' תשפ\"ה מועד ג'", "date": "26.03.2025", "id": "25AC-2"}, {"num": "3", "type": "mcq", "topic": "disk", "sub": "SSD", "q": "בכונן SSD יש קובץ שניגשים אליו פעמים רבות, לקריאה בלבד. איזו טענה נכונה?", "options": ["הגישות יגרמו ליותר הפרעות בדיסק ולסיכוי לשינוי הנתונים.", "הגישות יגרמו לפחות הפרעות בדיסק ולסיכוי לשינוי הנתונים.", "הגישות יאיצו את שחיקת הדיסק.", "הגישות יאטו את שחיקת הדיסק.", "כל התשובות האחרות אינן נכונות."], "correct": 0, "official": "יותר הפרעות וסיכוי לשינוי הנתונים. גישות רבות לאותם מיקומים בכונן SSD יוצרות הפרעות קריאה (read disturbs), שעלולות לשנות ביטים סמוכים.", "expl": "קריאה של דף מפעילה מתח על תאים שכנים באותו בלוק. אחרי הרבה קריאות, ביטים בתאים האלה עלולים להתהפך. הכונן מתמודד עם זה באמצעות ECC והעתקה של הבלוק מדי פעם. קריאה לא שוחקת את התאים כמו מחיקה וכתיבה.", "check": "לפי הפתרון הרשמי", "exam": "25AC", "examLabel": "סמסטר א' תשפ\"ה מועד ג'", "date": "26.03.2025", "id": "25AC-3"}, {"num": "4", "type": "mcq", "topic": "deadlock", "sub": "הרעבה וקיפאון", "q": "איזו טענה נכונה?", "options": ["בשימוש במנעולים שמקיימים חופש מקיפאון, אי אפשר להגיע לקיפאון.", "בשימוש במנעולים שמקיימים הוגנות, אי אפשר להגיע להרעבה.", "שימוש ב-DMA חוסך רק את זמן העברת הנתונים מ/אל ההתקן.", "בתזמון SCAN לעומת C-SCAN אין הבדל במרחק (בסקטורים) שהראש עובר, אלא רק בסדר הטיפול בבקשות.", "כל התשובות האחרות אינן נכונות."], "correct": 4, "official": "כל התשובות האחרות אינן נכונות. הקיפאון הקלאסי אפשרי גם עם מנעולים שמקיימים חופש מקיפאון, וכך גם הרעבה (למשל במנעול קוראים-כותבים, גם עם מנעולים הוגנים). DMA חוסך גם את זמן הטיפול בפסיקות של פעולה גדולה (שמחולקת לחלקים). וב-SCAN אפשר לעבור מרחק קצר יותר, לפי סדר הטיפול (ראו מבחן 22BB).", "expl": "כל אחת מהטענות הופיעה כשאלת \"הוכח או הפרך\" במבחן קודם: 22BB שאלה 5 (קיפאון עם מנעולים חופשיים מקיפאון), 23AB שאלה 2 (הרעבה עם מנעולים הוגנים), 22BB שאלה 1 (SCAN לעומת C-SCAN).", "check": "לפי הפתרון הרשמי", "exam": "25AC", "examLabel": "סמסטר א' תשפ\"ה מועד ג'", "date": "26.03.2025", "id": "25AC-4"}, {"num": "5", "type": "mcq", "topic": "memory", "sub": "Swapping", "q": "במערכת מסוימת כל המסגרות בזיכרון תפוסות, ושטח ההחלפה (swap) מלא לגמרי. איזו טענה בהכרח נכונה?", "options": ["אי אפשר לטפל באף page fault.", "אי אפשר להקצות זיכרון חדש לתהליכים.", "אם Dirty=1 בכל המסגרות בזיכרון, לא נוכל לבצע page out.", "אם Dirty=0 במסגרת כלשהי בזיכרון, נוכל לבצע page in.", "כל התשובות האחרות אינן נכונות."], "correct": 3, "official": "אם Dirty=0 במסגרת כלשהי, נוכל לבצע page in. אפשר לטפל ב-page fault, כי ייתכן שאפשר לפנות דף שכבר נמצא בדיסק (גם אם Dirty=1 עבורו), וכך גם להקצות זיכרון חדש. אם Dirty=0 לדף במסגרת כלשהי, בהכרח אפשר לפנות את המסגרת – ולכן אפשר לטעון אליה דף חדש.", "expl": "דף נקי (Dirty=0) כבר נמצא בדיסק בעותק עדכני, ולכן אפשר פשוט לדרוס את המסגרת שלו בלי לכתוב כלום. כך מתפנה מסגרת ל-page in, גם כשה-swap מלא.", "check": "לפי הפתרון הרשמי", "exam": "25AC", "examLabel": "סמסטר א' תשפ\"ה מועד ג'", "date": "26.03.2025", "id": "25AC-5"}, {"num": "6", "type": "open", "topic": "redir", "sub": "exec", "intro": "נתונה התוכנית הבאה.\nתזכורת: באופרטורים && ו-||, אם התוצאה ידועה לפי האופרנד הראשון, האופרנד השני לא מבוצע.\nכל הקריאות ל-fork הצליחו, והקובץ echo קיים במערכת.", "code": " 1 int main() {\n 2     int r1 = !fork() || fork();\n 3     if (r1) {\n 4         char* args[3] = {\"echo\", \"r1: TRUE\", NULL};\n 5         execvp(args[0], args);\n 6         printf(\"r1: TRUE\\n\");\n 7     } else {\n 8         printf(\"r1: FALSE\\n\");\n 9     }\n10     wait(NULL);\n11\n12     int r2 = !fork() && fork();\n13     if (r2) {\n14         char* args[3] = {\"echo\", \"r2: TRUE\", NULL};\n15         execvp(args[0], args);\n16     }\n17     else {\n18         printf(\"r2: FALSE\\n\");\n19     }\n20     if (r1 || r2)\n21         printf(\"END\\n\");\n22 }", "parts": [{"label": "6.1", "q": "כתבו פלט אפשרי של התוכנית, וציירו את עץ התהליכים של הריצה (עם מזהה לכל תהליך). כמה תהליכים נוצרו, כולל הראשי?", "answer": "5 תהליכים.\n\nנניח שהתהליך המקורי הוא 100.\n\nשורה 2: ‏100 יוצר את 101. אצל 101 ‏!0 = אמת, ולכן || עוצר: r1 = 1. אצל 100 זה שקר, אז מבוצע fork נוסף – נוצר 102. אצל 100 ‏r1 = 1, ואצל 102 ‏r1 = 0.\n\n100 ו-101 נכנסים לתנאי בשורה 3 ומריצים echo – ה-execvp לא חוזר.\n102 מדפיס \"r1: FALSE\". ב-wait אין לו ילדים, אז הוא ממשיך מיד.\n\nשורה 12: ‏102 יוצר את 103. אצל 102 ‏!(103) = שקר, ולכן && עוצר: r2 = 0. אצל 103 ‏!0 = אמת, אז מבוצע fork נוסף – נוצר 104. אצל 103 ‏r2 = 1, ואצל 104 ‏r2 = 0.\n\n103 מריץ echo. ‏102 ו-104 מדפיסים \"r2: FALSE\". אצל שניהם r1 = 0 ו-r2 = 0, ולכן אף אחד לא מדפיס END.\n\nפלט אפשרי:\nr1: TRUE\nr1: TRUE\nr1: FALSE\nr2: TRUE\nr2: FALSE\nr2: FALSE\n\nעץ התהליכים:\n\n[[TREE]]\n", "tree": ["100", "r1: TRUE", [["101", "r1: TRUE", []], ["102", "r1: FALSE, r2: FALSE", [["103", "r2: TRUE", [["104", "r2: FALSE", []]]]]]]]}, {"label": "6.2", "q": "האם ייתכנו זומבים בשלב כלשהו? אם כן – ציינו את כל הזומבים האפשריים בכל שלב, אחרת – הסבירו מדוע לא.", "answer": "ייתכנו. כל תהליך יכול להיות זומבי, מלבד התהליך הראשי (עליו לא ידוע – ההורה שלו הוא ה-shell).\n\nאין שום מנגנון שקובע סדר בין התהליכים. בכל נקודה, כל בן שמסתיים לפני ההורה שלו נשאר זומבי, עד שההורה מסתיים (ואז init מאמץ ואוסף אותו)."}, {"label": "6.3", "q": "נניח שהקובץ echo לא קיים במערכת. האם מספר התהליכים מסעיף 6.1 ישתנה? אם כן – מה התשובה החדשה, אחרת – מדוע לא.", "answer": "ישתנה: 9 תהליכים.\n\nאם echo לא קיים, כל הקריאות ל-execvp נכשלות, והתהליכים ממשיכים לשורה הבאה. 100 ו-101, שהגיעו לשורה 5, ממשיכים עד שורה 12 (100 מחכה קודם ב-wait שאחד מבניו יסתיים). כל אחד מהם יוצר שם 2 תהליכים נוספים (בן ונכד):\n5 + 4 = 9"}], "official": "6.1: ‏5 תהליכים, עם הפלט והעץ כמו כאן. 6.2: כל תהליך מלבד הראשי. 6.3: ‏9.", "expl": "זו גרסה של שאלה 6 ממבחן 22BB, עם ! בתחילת כל ביטוי. בעמוד \"הפניות וצינורות\" באתר הלמידה יש הרצה יבשה של הגרסה המקורית.", "check": "הורץ (גם בגרסה שבה echo לא קיים – 9 תהליכים)", "exam": "25AC", "examLabel": "סמסטר א' תשפ\"ה מועד ג'", "date": "26.03.2025", "id": "25AC-6"}, {"num": "7", "type": "open", "topic": "sync", "sub": "Barrier", "intro": "Barrier הוא אובייקט סנכרון ל-N חוטים (N פרמטר אתחול) עם פעולה אחת, checkin, שנועדה לסנכרן את שלב הביצוע של N החוטים. חוט שקורא ל-checkin חסום עד ש-N חוטים (כולל הוא) קראו ל-checkin. החוט ה-N (\"האחרון\") משחרר את כולם, וכולם ממשיכים לפקודה הבאה.\nהפעולה אינה חד-פעמית: אחרי שהקריאה חוזרת אפשר לקרוא שוב ולחכות שוב – עד שכל החוטים יקראו שוב, וכן הלאה.\nאפשר להתעלם מגבולות int (אין overflow), ואפשר להשתמש ב-spinning.", "code": "typedef struct {\n    int N;\n    int *arr;\n} Barrier;\n\nvoid init(Barrier *bar, int N) {\n    bar->N = N;\n    bar->arr = (int*) calloc(sizeof(int), N);\n}\nvoid destroy(Barrier *bar) {\n    free(bar->arr);\n}", "parts": [{"label": "7.1", "q": "לכל חוט יש מזהה i בין 0 ל-N−1, שמועבר כפרמטר ל-checkin. השלימו את checkin בלי פעולות אטומיות או אובייקטי סנכרון אחרים. אין להוסיף שדות או לשנות את הקוד הנתון.", "answer": "כל חוט סופר בתא שלו כמה פעמים קרא ל-checkin. רק הוא כותב לתא שלו, ולכן אפשר לקדם אותו בלי פעולה אטומית. אחר כך הוא עובר על כל המערך ומחכה שכל חוט יגיע לפחות לאותו מספר קריאות:\n\nvoid checkin(Barrier *bar, int i) {\n    ++bar->arr[i];\n    for (int t = 0; t < bar->N; ++t)\n        while (bar->arr[t] < bar->arr[i]);   // wait for t\n}\n\nבשימוש חוזר: חוט שכבר יצא וקרא שוב ל-checkin רק מגדיל את התא שלו, וחוט שעדיין מחכה בסבב הקודם בודק \"לפחות\" – אז זה לא מפריע לו."}, {"label": "7.2", "q": "אותה מערכת, אבל עכשיו כל תא במערך arr הוא טרינארי: הוא יכול להכיל רק 0, 1 או 2 (הגדלה של 2 מחזירה ל-0). תארו את השינוי הנדרש והשלימו את checkin, בלי פעולות אטומיות או אובייקטי סנכרון. אין להוסיף שדות או לשנות את הקוד הנתון.", "answer": "במימוש של הסעיף הקודם אף חוט לא יכול \"להשיג\" חוט אחר ביותר מ-1 – הוא ייחסם בסבב הבא עד שהחוט האיטי יגיע. לכן מספיק לדעת אם חוט אחר נמצא באותו סבב או בסבב אחד קדימה – ו-3 ערכים מספיקים.\n\nהשינוי היחיד הוא בתנאי ההמתנה: כל חוט מחכה שבתא של כל חוט אחר יהיה אותו ערך כמו שלו או הערך שאחריו (מודולו 3):\n\nvoid checkin(Barrier *bar, int i) {\n    int v = (bar->arr[i] + 1) % 3;\n    bar->arr[i] = v;\n    for (int t = 0; t < bar->N; ++t)\n        while (bar->arr[t] != v && bar->arr[t] != (v + 1) % 3);\n}\n\nלמה זה נכון: אחרי שחוט קידם את התא שלו ל-v, כל חוט אחר נמצא באחד משלושה מצבים: הערך הקודם (עוד לא הגיע לסבב הזה – צריך לחכות לו), v (הגיע), או הערך שאחרי v (כבר יצא מהסבב הזה ונכנס לבא – ולכן ברור שכולם הגיעו לסבב הזה)."}], "official": "7.1: כמו בשאלה 7 במבחן 22AB. 7.2: אותו קוד, ורק תנאי ההמתנה משתנה – מחכים שבכל תא יהיה הערך של החוט או הערך שאחריו.", "expl": "שתי הגרסאות הורצו עם 5 חוטים ו-20,000 סבבים כל אחד: אף חוט לא יצא מ-checkin לפני שכל השאר הגיעו לאותו סבב, ואין תקיעה.", "check": "הורץ עם חוטים אמיתיים", "exam": "25AC", "examLabel": "סמסטר א' תשפ\"ה מועד ג'", "date": "26.03.2025", "id": "25AC-7"}, {"num": "8", "type": "open", "topic": "disk", "sub": "ביצועי דיסק ו-RAID", "intro": "נתונה מערכת עם workload אקראי של 512KB וסדרתי של 100MB, ושלושה דיסקים קשיחים.\nיש לפרט ולנמק את כל החישובים.", "table": {"headers": ["דיסק", "RPM", "SEEK TIME", "TRANSFER RATE"], "rows": [["GHOST", "7200", "10ms", "200 MB/s"], ["FUSION", "15000", "10ms", "150 MB/s"], ["SENSOR", "5400", "5ms", "100 MB/s"]]}, "parts": [{"label": "8.1", "q": "איזה דיסק נעדיף עבור ה-workload האקראי, ואיזה עבור הסדרתי?", "answer": "אקראי: FUSION. סדרתי: GHOST.\n\nהמתנה ממוצעת לסיבוב (חצי סיבוב):\nGHOST: ‏60,000 / 7200 / 2 = 4.17ms\nFUSION: ‏60,000 / 15,000 / 2 = 2ms\nSENSOR: ‏60,000 / 5400 / 2 = 5.56ms\n\nזמן מיקום (seek + המתנה):\nGHOST: ‏14.17ms\nFUSION: ‏12ms\nSENSOR: ‏10.56ms\n\nאקראי (0.5MB):\nGHOST: ‏14.17 + 2.5 = 16.67ms\nFUSION: ‏12 + 3.33 = 15.33ms – הכי מהיר\nSENSOR: ‏10.56 + 5 = 15.56ms\n\nסדרתי (100MB):\nGHOST: ‏14.17 + 500 = 514.17ms – הכי מהיר\nFUSION: ‏12 + 666.67 = 678.67ms\nSENSOR: ‏10.56 + 1000 = 1010.56ms"}, {"label": "8.2", "q": "עבור ה-workload הסדרתי, מה אחוז הביצועים של כל דיסק – היחס בין המהירות בפועל למהירות המקסימלית שלו?", "answer": "GHOST: ‏97.2%\nFUSION: ‏98.2%\nSENSOR: ‏99.0%\n\nהאחוז הוא זמן ההעברה חלקי הזמן הכולל:\nGHOST: ‏500 / 514.17 = 97.2% (‏194.5 MB/s)\nFUSION: ‏666.67 / 678.67 = 98.2% (‏147.3 MB/s)\nSENSOR: ‏1000 / 1010.56 = 99.0% (‏99 MB/s)"}, {"label": "8.3", "q": "כדי לשפר את הביצועים ב-workload האקראי, הוחלט להשתמש במערך RAID-4 של דיסקים מסוג FUSION. מה המספר המינימלי של דיסקים שצריך כדי לשפר את הביצועים לעומת דיסק אחד בלי RAID? תשובה נפרדת לקריאה ולכתיבה.", "answer": "קריאה: 3 דיסקים. כתיבה: אין מספר שישפר.\n\nהקצב האקראי של דיסק FUSION אחד:\n0.5MB / 15.33ms ≈ 32.6 MB/s\n\nקריאה אקראית ב-RAID-4 עם N דיסקים: (N − 1) · R. כדי שיהיה יותר מ-R צריך N − 1 ≥ 2, כלומר N = 3.\n\nכתיבה אקראית ב-RAID-4: ‏R/2 – בלי קשר למספר הדיסקים (דיסק הזוגיות הוא צוואר הבקבוק). לכן אי אפשר לשפר את הכתיבה על פני דיסק אחד."}], "official": "8.1: אקראי FUSION, סדרתי GHOST. 8.2: ‏GHOST 97.25%, ‏FUSION 98.33%, ‏SENSOR 99%. 8.3: קריאה 3, כתיבה – אין שיפור.", "note": "8.2: בפתרון הרשמי הקצב של FUSION הוא 147.5 MB/s ו-98.33%. בחישוב מדויק: 100MB / 678.67ms = 147.35 MB/s, כלומר 98.23%. (וגם: בפתרון הרשמי כתוב ש-5400 RPM הוא \"זמן סיבוב של 10ms\" – בפועל 11.1ms; ההמתנה הממוצעת 5.5ms שם נכונה.)", "expl": "", "check": "חושב בסקריפט", "exam": "25AC", "examLabel": "סמסטר א' תשפ\"ה מועד ג'", "date": "26.03.2025", "id": "25AC-8", "image": "img/25AC-8.png"}, {"num": "1", "type": "mcq", "topic": "sched", "sub": "Round Robin", "q": "נתונה מערכת עם אלגוריתם תזמון שמבוסס על RR, עם הבדל אחד: משימה חדשה מתחילה לרוץ מיד כשהיא נוצרת. משימה שסיימה את הקוונטום שלה עדיין חוזרת לסוף התור, ואפשר להניח שלא נוצרות 2 משימות חדשות בו-זמנית. איזו טענה בהכרח נכונה?", "options": ["זמן התגובה של האלגוריתם אופטימלי.", "זמן המחזור של האלגוריתם תמיד טוב או שווה לזה של RR רגיל.", "לכל N > 1, אם בכל רגע יש בתור לכל היותר N משימות, לא תיתכן הרעבה.", "לכל N > 1, אם בכל רגע יש בתור לכל היותר N משימות, בהכרח תתרחש הרעבה.", "כל התשובות האחרות אינן נכונות."], "correct": 0, "official": "זמן התגובה אופטימלי. אם כל משימה רצה מיד כשנוצרה, זמן התגובה הוא 0 – וזה האופטימלי.", "expl": "זמן תגובה = הזמן מההגעה ועד הריצה הראשונה. כאן הוא 0 לכל משימה, ואי אפשר פחות.\n\nלגבי ההרעבה: גם אם התור קטן, משימות חדשות שמגיעות כל הזמן \"קופצות\" לראש ומעכבות את האחרות – אבל זה לא בהכרח קורה, ולכן גם הטענה שהרעבה \"בהכרח\" תתרחש לא נכונה.", "check": "לפי הפתרון הרשמי", "exam": "25BA", "examLabel": "סמסטר ב' תשפ\"ה מועד א'", "date": "15.07.2025", "id": "25BA-1"}, {"num": "2", "type": "mcq", "topic": "disk", "sub": "רמות RAID", "q": "נתון שרת עם 6 דיסקים זהים, 2TB כל אחד. איזה מהמנגנונים הבאים יאפשר להתמודד עם קלקול של לפחות דיסק אחד? מביניהם, בחרו את המנגנון שמספק את שטח האחסון המקסימלי.", "options": ["RAID-0", "RAID-1 עם mirroring level של 2", "RAID-1 עם mirroring level של 3", "RAID-5", "כל התשובות האחרות אינן נכונות."], "correct": 3, "official": "RAID-5. ‏RAID-0 לא מתמודד עם קריסה. ‏RAID-1 מתמודד עם יותר קריסות, אבל מקטין את שטח האחסון. לכן RAID-5 הוא המתאים ביותר.", "expl": "שטח האחסון:\nRAID-1 עם 2 עותקים: ‏6 · 2TB / 2 = 6TB\nRAID-1 עם 3 עותקים: ‏6 · 2TB / 3 = 4TB\nRAID-5: ‏(6 − 1) · 2TB = 10TB\nכולם שורדים כשל של דיסק אחד, ו-RAID-5 נותן הכי הרבה מקום.", "check": "חושב", "exam": "25BA", "examLabel": "סמסטר ב' תשפ\"ה מועד א'", "date": "15.07.2025", "id": "25BA-2"}, {"num": "3", "type": "mcq", "topic": "intro", "sub": "מודולי גרעין", "q": "איזו מהטענות הבאות נכונה לגבי מודול גרעין?", "options": ["המודול רץ עם מרחב זיכרון משלו, נפרד מה-kernel space.", "אין בעיה לגשת ישירות לזיכרון ב-user space באופן חופשי.", "אפשר לבצע קריאות מערכת כרגיל, כי הן רצות ב-kernel mode.", "אחרי שנטען, אי אפשר להסיר מודול גרעין בלי להפעיל מחדש את המערכת.", "כל התשובות האחרות אינן נכונות."], "correct": 4, "official": "כל התשובות האחרות אינן נכונות. מודול גרעין לא רץ במרחב זיכרון משלו אלא ב-kernel space. אסור לגשת ל-user space באופן חופשי – צריך לוודא גישה נכונה עם get_user / put_user. לא מבצעים קריאות מערכת באופן רגיל, כי כבר נמצאים במצב קרנל. ואפשר להסיר מודול גרעין באופן חופשי (rmmod), כפי שראינו במעבדות.", "expl": "", "check": "לפי הפתרון הרשמי", "exam": "25BA", "examLabel": "סמסטר ב' תשפ\"ה מועד א'", "date": "15.07.2025", "id": "25BA-3"}, {"num": "4", "type": "mcq", "topic": "threads", "sub": "Ticket lock", "q": "במערכת עם N חוטים שמשתמשת ב-ticket lock, ידוע שבנקודת זמן מסוימת הערך של turn הוא X. מה הערך המקסימלי האפשרי של ticket באותה נקודה?", "options": ["X", "X+1", "X+N−1", "X+N", "כל התשובות האחרות אינן נכונות."], "correct": 3, "official": "X+N. החוט שמחזיק במנעול קיבל כרטיס ששווה ל-turn (‏X), וקידם את ticket ל-X+1. כל חוט אחר יכול גם הוא לקדם את ticket – עוד N−1 פעמים – עד X+N.", "expl": "ticket הוא המספר הבא שיחולק. אם כל N החוטים מחזיקים כרטיסים – אחד עם X (בפנים) ו-N−1 שמחכים עם X+1 עד X+N−1 – המספר הבא הוא X+N.", "check": "לפי הפתרון הרשמי", "exam": "25BA", "examLabel": "סמסטר ב' תשפ\"ה מועד א'", "date": "15.07.2025", "id": "25BA-4"}, {"num": "5", "type": "mcq", "topic": "process", "sub": "fork", "q": "במערכת רץ תהליך משתמש יחיד שקורא ל-fork בלולאה. אחרי יצירת 100 תהליכים (כולל הראשי), הקריאות ל-fork נכשלות ולא נוצרים עוד תהליכים. איזו טענה בהכרח נכונה?", "options": ["הגענו לניצול מקסימלי של זיכרון המשתמש, ולכן אי אפשר ליצור עוד תהליכים.", "הגענו לניצול מקסימלי של זיכרון הקרנל, ולכן אי אפשר ליצור עוד תהליכים.", "אם נעצור את התהליך הראשי, נוכל להריץ בהצלחה כל תוכנית אחרת במקומו.", "אם נחכה פרק זמן מסוים, נוכל ליצור תהליכים חדשים (הקריאות ל-fork שוב יצליחו).", "כל התשובות האחרות אינן נכונות."], "correct": 4, "official": "כל התשובות האחרות אינן נכונות. אי אפשר לדעת אם המגבלה היא זיכרון המשתמש, זיכרון הקרנל או מגבלה אחרת. אין סיבה שאחרי זמן מה הקריאות יחזרו להצליח (ייתכן שלעולם לא). ועצירת תהליך אחד לא מאפשרת להריץ כל תוכנית – למשל תוכנית שדורשת יותר זיכרון ממה שפינינו.", "expl": "למשל, ייתכן שיש מגבלה על מספר התהליכים למשתמש (ulimit -u = 100) – וזה לא קשור לזיכרון בכלל.", "check": "לפי הפתרון הרשמי", "exam": "25BA", "examLabel": "סמסטר ב' תשפ\"ה מועד א'", "date": "15.07.2025", "id": "25BA-5"}, {"num": "6", "type": "open", "topic": "memory", "sub": "טבלה היררכית", "intro": "במערכת מסוימת כתובת וירטואלית מורכבת מ: היסט של 10 ביטים, PDI0 של 4 ביטים, PDI1 של 8 ביטים ו-PTI של 8 ביטים.\nכל PTE מכיל מספר מסגרת, 4 ביטים של סטטוס ו-4 ביטים של ריפוד. ה-PTE וה-PDE באותו גודל, וכל טבלה מאוחסנת בדף אחד.\nיש לפרט ולנמק את החישובים בכל סעיף.", "parts": [{"label": "6.1", "q": "כמה זיכרון פיזי יכול להיתפס בעקבות הרצת תהליך יחיד, במקרה המקסימלי?", "answer": "1GB + 4113KB.\n\nבמקרה המקסימלי התהליך משתמש בכל מרחב הכתובות שלו, ובכל החלקים של טבלת הדפים בכל הרמות.\n\nמרחב הכתובות:\n10 + 4 + 8 + 8 = 30 ביטים, כלומר 1GB\n\nטבלת הדפים – 3 רמות:\nרמה ראשונה: טבלה אחת\nרמה שנייה: 2^4 = 16 טבלאות\nרמה שלישית: 16 · 2^8 = 4096 טבלאות\nסך הכל 4113 מסגרות\n\nההיסט 10 ביטים, כלומר דף/מסגרת של 1KB:\n1GB + 4113 · 1KB"}, {"label": "6.2", "q": "מה גודל הזיכרון הפיזי המקסימלי במערכת?", "answer": "16GB.\n\nבחלק של הטבלה יש לכל היותר 2^8 = 256 רשומות (לפי PDI1 ו-PTI). הטבלה בגודל דף (1KB), ולכן כל רשומה:\n1KB / 256 = 4 בתים = 32 ביטים\n\n8 ביטים לסטטוס ולריפוד, ולכן ה-PFN הוא 24 ביטים:\n2^24 · 1KB = 2^34 = 16GB"}, {"label": "6.3", "q": "הזיכרון הפיזי המקסימלי זמין במערכת. מה המספר המינימלי של תהליכים שצריך להריץ כדי שכל הזיכרון הפיזי יהיה תפוס? אפשר להגדיר תהליכים כרצונכם. אין swapping, ולקרנל אין שימוש בזיכרון מלבד מה שנדרש לתהליכים.", "answer": "16 תהליכים.\n\nמשתמשים בתהליכים שתופסים כמה שיותר (סעיף 6.1):\n2^20 + 4113 = 1,052,689 מסגרות לתהליך\n\nהזיכרון הפיזי:\n2^24 = 16,777,216 מסגרות\n\n16,777,216 / 1,052,689 = 15.94\n\n15 תהליכים מלאים תופסים 15,790,335 מסגרות. נשארו 986,881, ותהליך נוסף שתופס בדיוק אותן משלים את הזיכרון. סך הכל 16."}], "official": "6.1: ‏1GB + 4113KB. 6.2: ‏16GB. 6.3: ‏16 (15 מלאים ועוד אחד עם 986,861 מסגרות).", "note": "6.3: בפתרון הרשמי כתוב שהתהליך האחרון תופס 986,861 מסגרות. בחישוב מדויק: 16,777,216 − 15 · 1,052,689 = 986,881. התשובה (16) לא משתנה.", "expl": "", "check": "חושב בסקריפט", "exam": "25BA", "examLabel": "סמסטר ב' תשפ\"ה מועד א'", "date": "15.07.2025", "id": "25BA-6"}, {"num": "7", "type": "open", "topic": "sync", "sub": "משתני תנאי", "q": "נתונה מערכת מרובת חוטים שמנהלת N משאבים אקסקלוסיביים: מותר לגשת רק לאחד מהמשאבים בכל רגע (אבל כמה חוטים יכולים לגשת לאותו משאב במקביל).\nהמשאבים ממוספרים 0…N−1. חוט שרוצה לגשת למשאב i קורא ל-enter(i) לפני הגישה, ול-exit(i) בסיום. enter(i) חוסמת את החוט עד שמותר לו לגשת ל-i.\nכתבו את enter ו-exit כך ש:\nמניעה הדדית – בכל רגע לא נעשית גישה ליותר ממשאב אחד.\nחופש מקיפאון – אם חוט מנסה לגשת ל-i ואין חוט שניגש למשאב שונה מ-i, החוט יצליח.\nמותר להשתמש במנעולים ובמשתני תנאי בלבד, בלי spinning. פתרון שמאפשר רק לחוט אחד לגשת למשאב בכל רגע לא עומד בדרישות.", "answer": "דומה לשאלה 7 במבחן 23BA, אבל עם מנעול ומשתנה תנאי במקום לולאת ניסיונות. r הוא המשאב שבשימוש, ו-c מספר החוטים שמשתמשים בו.\n\npthread_mutex_t lock;   // init\npthread_cond_t cv;       // init\nint r = -1, c = 0;\n\nvoid enter(int i) {\n    pthread_mutex_lock(&lock);\n    while ((r != i) && (c != 0))\n        pthread_cond_wait(&cv, &lock);\n    r = i;\n    ++c;\n    pthread_mutex_unlock(&lock);\n}\n\nvoid exit(int i) {\n    pthread_mutex_lock(&lock);\n    --c;\n    if (c == 0)\n        pthread_cond_broadcast(&cv);\n    pthread_mutex_unlock(&lock);\n}\n\nחוט נכנס אם אף משאב לא בשימוש, או שהמשאב שבשימוש הוא i. אחרת הוא ממתין על משתנה התנאי (בלי לבזבז מעבד).\n\nכשהאחרון עוזב משאב (c == 0), הוא מעיר את כולם עם broadcast – כי חוטים שמחכים לכמה משאבים שונים צריכים לבדוק מחדש, וכולם עשויים להיכנס (אם הם מחכים לאותו משאב).", "official": "כמו כאן.", "expl": "הקוד הורץ עם 6 חוטים ו-3 משאבים, ‏20,000 גישות לכל חוט: אף פעם לא נעשה שימוש בשני משאבים שונים בו-זמנית, ועד 6 חוטים השתמשו באותו משאב במקביל.", "check": "הורץ עם חוטים אמיתיים", "exam": "25BA", "examLabel": "סמסטר ב' תשפ\"ה מועד א'", "date": "15.07.2025", "id": "25BA-7"}, {"num": "8", "type": "open", "topic": "fs", "sub": "VSFS", "intro": "נתונה מערכת קבצים VSFS בלי מספרי inode ובלי inode table (ולכן גם בלי inode bitmap). במקום זה, כל רשומה בתיקייה מכילה את ה-inode עצמו במקום מספר ה-inode – כלומר הנתונים של תיקייה הם טבלה שבכל רשומה יש את שם הקובץ ואת מבנה ה-inode שלו.\nאת ה-inode של תיקיית השורש מחזיקים ב-superblock.", "parts": [{"label": "8.1", "q": "סטודנט טוען שבמערכת הזו אי אפשר ליצור hard link נוסף לקובץ קיים. האם הוא צודק?", "answer": "הסטודנט צודק. אין מספרי inode, ומבנה ה-inode עצמו נמצא בתוך נתוני התיקייה. לכן אי אפשר ששתי רשומות (באותה תיקייה או בתיקיות שונות) יפנו לאותו inode – כל inode מופיע פעם אחת, בתיקייה אחת, בהגדרה."}, {"label": "8.2", "q": "סטודנט טוען שבמערכת הזו אי אפשר ליצור symbolic link לקובץ קיים. האם הוא צודק?", "answer": "הסטודנט טועה. קישור סימבולי הוא קובץ רגיל (מבחינת האחסון) שכתוב בו נתיב של קובץ אחר. זה אפשרי כרגיל במערכת הזו – הוא פשוט מקבל רשומה משלו בתיקייה, עם inode משלו."}, {"label": "8.3", "q": "גודל בלוק 1KB, גודל inode ‏256B, ובכל inode יש 8 מצביעים ישירים, 4 עקיפים, 2 עקיפים כפולים ועקיף משולש אחד. גודל מצביע 4B.\nמשתמש ביצע כתיבה שמוסיפה 4KB לקובץ /home/os/exam/25ba, שגודלו 1030KB. אף cache לא מכיל מידע רלוונטי.\nמה המספר המינימלי של בלוקים שצריך לקרוא? תארו את כל הבלוקים שקוראים וכותבים, לפי הסדר, ונמקו. הסבירו בקצרה למה זה המינימום.", "answer": "7 קריאות.\n\nמציאת הקובץ – בגלל מבנה מערכת הקבצים צריך לקרוא את התוכן של כל התיקיות בנתיב:\n1. ה-superblock – בשביל ה-inode של השורש\n2. ה-DATA של השורש – בשביל ה-inode של home\n3. ה-DATA של home – בשביל ה-inode של os\n4. ה-DATA של os – בשביל ה-inode של exam\n5. ה-DATA של exam – בשביל ה-inode של 25ba\n(במקרה המינימלי, לכל תיקייה בלוק DATA אחד.)\n\nמבנה הקובץ:\nמצביעים בבלוק: 1KB / 4B = 256\n1030KB הם 1030 בלוקים: 8 ישירים, ו-1022 דרך 4 העקיפים (4 · 256 = 1024). בעקיף הרביעי נשארו 2 מצביעים פנויים.\n\nמוסיפים 4 בלוקים (1030–1033):\n1030–1031 – דרך 2 המצביעים הפנויים בעקיף הרביעי\n1032–1033 – צריך את העקיף הכפול הראשון: בלוק עקיף כפול חדש, שהמצביע הראשון בו מצביע לבלוק עקיף חדש, ובו 2 מצביעים\nסך הכל 4 בלוקי נתונים חדשים ו-2 בלוקי מצביעים חדשים.\n\n6. קריאת ה-data bitmap – במקרה המינימלי יש בו מקום לכל 6 הבלוקים (ואז כותבים אותו)\n7. קריאת הבלוק העקיף הרביעי – כדי להוסיף בו 2 מצביעים (ואז כותבים אותו)\n\nכתיבות:\nה-data bitmap\n4 בלוקי הנתונים\nהבלוק העקיף הרביעי (עם 2 המצביעים החדשים)\nהבלוק העקיף החדש (עם 2 מצביעים)\nהבלוק העקיף הכפול החדש (עם מצביע אחד)\nה-DATA של exam – עם ה-inode המעודכן של 25ba (המצביע לעקיף הכפול, הגודל וזמני הגישה)\n\nלמה זה המינימום: אין דרך להגיע ל-inode בלי לקרוא את כל התיקיות בנתיב; את ה-bitmap חייבים לקרוא כדי למצוא בלוקים פנויים; ואת העקיף הרביעי חייבים לקרוא כדי לעדכן אותו בלי לדרוס את 254 המצביעים הקיימים. את הבלוקים החדשים לא צריך לקרוא – כותבים אותם מאפס."}], "official": "8.1: הסטודנט צודק. 8.2: הסטודנט טועה. 8.3: ‏7 קריאות.", "expl": "", "check": "חושב", "exam": "25BA", "examLabel": "סמסטר ב' תשפ\"ה מועד א'", "date": "15.07.2025", "id": "25BA-8"}, {"num": "1", "type": "mcq", "topic": "sched", "sub": "Round Robin", "q": "נתונה מערכת עם אלגוריתם תזמון שמבוסס על RR, עם הבדל אחד: משימה חדשה נכנסת לתחילת התור (במקום לסופו), ומתחילה לרוץ אחרי סיום הקוונטום הנוכחי. משימה שסיימה את הקוונטום שלה עדיין חוזרת לסוף התור, ואפשר להניח שלא נוצרות 2 משימות חדשות בו-זמנית. איזו טענה בהכרח נכונה?", "options": ["זמן התגובה של האלגוריתם אופטימלי.", "זמן המחזור של האלגוריתם תמיד טוב או שווה לזה של RR רגיל.", "לכל N > 1, אם בכל רגע יש בתור בדיוק N משימות, בהכרח תתרחש הרעבה.", "לכל N > 1, אם בכל רגע יש בתור בדיוק N משימות, לא תיתכן הרעבה.", "כל התשובות האחרות אינן נכונות."], "correct": 4, "official": "כל התשובות האחרות אינן נכונות. זמן התגובה לא אופטימלי (פחות טוב מהאלגוריתם של מועד א' – כאן המשימה מחכה לסוף הקוונטום). זמן המחזור יכול להיות גרוע מ-RR רגיל, אם מתווספת משימה ארוכה. כשיש בתור בדיוק N משימות הרעבה אפשרית, אבל לא בהכרח תתרחש.", "expl": "הרעבה אפשרית: אם בכל פעם שמשימה מסתיימת נכנסת משימה חדשה לראש התור (כך שתמיד יש N), המשימות שבסוף התור עלולות לא להגיע לראש לעולם. אבל אם לא מגיעות משימות חדשות בתזמון כזה – אין הרעבה. לכן אף אחת מהטענות לא נכונה \"בהכרח\".", "check": "לפי הפתרון הרשמי", "exam": "25BB", "examLabel": "סמסטר ב' תשפ\"ה מועד ב'", "date": "04.08.2025", "id": "25BB-1"}, {"num": "2", "type": "mcq", "topic": "disk", "sub": "רמות RAID", "q": "נתון שרת עם 6 דיסקים זהים, 2TB כל אחד. איזה מהמנגנונים הבאים יאפשר להתמודד עם קלקול של יותר מדיסק אחד? מביניהם, בחרו את המנגנון שמספק את שטח האחסון המקסימלי.", "options": ["RAID-0", "RAID-1 עם mirroring level של 2", "RAID-1 עם mirroring level של 3", "RAID-5", "כל התשובות האחרות אינן נכונות."], "correct": 1, "official": "RAID-1 עם mirroring level של 2. שני מנגנוני ה-RAID-1 מאפשרים להתמודד עם קלקול של יותר מדיסק אחד, ומביניהם mirroring level של 2 נותן יותר שטח אחסון. (הוא אמנם לא מתמודד עם קלקול של כל 2 דיסקים, אבל זה לא נדרש בשאלה.)", "expl": "עם 6 דיסקים ו-2 עותקים יש 3 זוגות. אם נופלים 2 דיסקים מזוגות שונים – אין אובדן מידע (ואפילו 3, אחד מכל זוג). ‏RAID-5 שורד רק כשל אחד. שטח: 2 עותקים – 6TB, ‏3 עותקים – 4TB.", "note": "הניסוח \"יאפשר להתמודד עם קלקול של יותר מדיסק אחד\" דו-משמעי. הפתרון הרשמי מפרש \"יכול לשרוד במקרים מסוימים\". אם הכוונה היא לשרוד כל 2 קלקולים – רק mirroring level של 3 עומד בזה.", "check": "לפי הפתרון הרשמי", "exam": "25BB", "examLabel": "סמסטר ב' תשפ\"ה מועד ב'", "date": "04.08.2025", "id": "25BB-2"}, {"num": "3", "type": "mcq", "topic": "intro", "sub": "מודולי גרעין", "q": "רוצים לפתח מנהל התקן (דרייבר) שבו נשמר ערך פרטי לכל גישה להתקן, שלא משותף עם שאר הגישות לאותו התקן. מה הדרך הנכונה ביותר?", "options": ["להגדיר פרמטר למודול, כך שאפשר יהיה להתקין אותו עם ערך שונה לפי הצורך.", "להגדיר מערך גלובלי ולגשת אליו לפי ה-MINOR של ההתקן שעליו מתבצעת הפעולה.", "ארגומנט הקובץ (struct file) מאפשר לשמור ערך פרטי לכל גישה שונה להתקן.", "ארגומנט ההיסט (offset) בפעולות קריאה/כתיבה מאפשר לשמור ערך פרטי, נפרד מגישות אחרות.", "כל התשובות האחרות אינן נכונות."], "correct": 2, "official": "ארגומנט הקובץ (struct file). הוא מייצג את אובייקט הקובץ הפתוח עבור הגישה הנוכחית להתקן, ויש בו שדה private_data שנועד בדיוק לשמירת מידע לגישה הזו בלבד.", "expl": "כל open יוצר struct file חדש, ולכן private_data שונה בכל פתיחה. MINOR משותף לכל מי שפותח את אותו התקן, ופרמטר מודול משותף לכל ההתקנים.", "check": "לפי הפתרון הרשמי", "exam": "25BB", "examLabel": "סמסטר ב' תשפ\"ה מועד ב'", "date": "04.08.2025", "id": "25BB-3"}, {"num": "4", "type": "mcq", "topic": "threads", "sub": "Ticket lock", "q": "במערכת עם N חוטים שמשתמשת ב-ticket lock, ידוע שבנקודת זמן מסוימת הערך של ticket הוא X. מה הערך המקסימלי האפשרי של turn באותה נקודה?", "options": ["X", "X−1", "X−N", "X−N+1", "כל התשובות האחרות אינן נכונות."], "correct": 0, "official": "X. הערך של turn לא יכול להיות גדול מ-ticket, אבל יכול להיות שווה לו – ובהכרח שווה לו כשאף חוט לא משתמש במנעול כרגע.", "expl": "turn גדל רק ב-unlock, וכל unlock שייך לחוט שלקח כרטיס. לכן turn ≤ ticket תמיד. כשכל מי שלקח כרטיס כבר שחרר – turn = ticket.", "check": "לפי הפתרון הרשמי", "exam": "25BB", "examLabel": "סמסטר ב' תשפ\"ה מועד ב'", "date": "04.08.2025", "id": "25BB-4"}, {"num": "5", "type": "mcq", "topic": "memory", "sub": "גודל טבלת דפים", "q": "במערכת עם טבלת דפים לינארית, כל PTE מכיל 3 ביטים של סטטוס. כתובת פיזית מורכבת מהיסט של 13 ביטים וממספר מסגרת של 23 ביטים. במערכת רצים 2 תהליכים, A ו-B, וידוע שטבלת הדפים של A תופסת בדיוק 4 מסגרות. מהו מרחב הכתובות של B?", "options": ["8KB", "8MB", "64MB", "אין מספיק נתונים כדי לחשב את התשובה.", "כל התשובות האחרות אינן נכונות."], "correct": 2, "official": "64MB. גודל דף/מסגרת הוא 2^13 = 8192 בתים. PTE הוא 23 ביטים (PFN) + 3 (סטטוס) + 6 ריפוד (לעיגול ל-32) – כלומר 4 בתים. ב-4 מסגרות נכנסות בדיוק 8192 רשומות. לכל תהליך טבלה לינארית באותו גודל, כלומר 8192 דפים של 8192 בתים – 64MB.", "expl": "החישוב:\n4 · 8KB / 4B = 8192 רשומות, כלומר 8192 דפים\n8192 · 8KB = 2^13 · 2^13 = 2^26 = 64MB\n\nהנקודה: בטבלה לינארית הגודל תלוי רק במרחב הכתובות, וכל התהליכים חולקים את אותו מבנה כתובת – ולכן הטבלה של B באותו גודל כמו של A.", "note": "בפתרון הרשמי כתוב \"8096 רשומות\" – טעות הקלדה, צריך 8192.", "check": "חושב", "exam": "25BB", "examLabel": "סמסטר ב' תשפ\"ה מועד ב'", "date": "04.08.2025", "id": "25BB-5"}, {"num": "6", "type": "open", "topic": "redir", "sub": "pipe בין תהליכים", "intro": "נתונה התוכנית הבאה. הריצו אותה, והתהליך שנוצר קיבל את המזהה 42.\nבמערכת:\nגודל דף 1KB.\nטבלת הדפים של כל תהליך תופסת תמיד דף אחד בדיוק.\nתהליך 42 משתמש ב-2 דפים של TEXT, ‏2 דפים של DATA, דף אחד של מחסנית ודף אחד של ערימה.\nכל pipe משתמש בחוצץ בגודל דף אחד.\nכל קריאות המערכת שיכולות להצליח הצליחו, לא נוצרים תהליכים בקוד אחר, וכל תהליך מקבל מזהה גדול ב-1 מהקודם.\nכל הדפסה לפלט הסטנדרטי מתבצעת מיד, בלי חוצץ ובלי לחכות לירידת שורה.", "code": " 1 char buf[1024];   // 1024 bytes\n 2\n 3 int main() {\n 4     int rc;\n 5     int pipefd[2];   // 0-read end, 1-write end\n 6     pipe(pipefd);\n 7\n 8     if (fork() > 0) {\n 9         close(pipefd[0]);\n10\n11         for (int i = 0; i < 3; ++i) {\n12             buf[0] = 'A'+i;   // i=0->'A', i=1->'B', etc.\n13\n14             // write 1024 bytes into pipe\n15             write(pipefd[1], buf, 1024);\n16             printf(\"%c\", buf[0]);\n17         }\n18         close(pipefd[1]);\n19         wait(NULL);\n20     }\n21     else {\n22         close(pipefd[1]);\n23\n24         // read 1024 bytes from pipe\n25         while ((rc = read(pipefd[0], buf, 1024)) != 0)\n26             printf(\"%c\", buf[0]);\n27     }\n28 }", "parts": [{"label": "6.1", "q": "כתבו את כל הפלטים האפשריים של התוכנית, והסבירו כל פלט.", "answer": "4 פלטים: AABBCC, ‏ABABCC, ‏ABACBC, ‏AABCBC.\n\nקריאה מ-pipe חוסמת עד שיש נתונים, וכתיבה חוסמת כל עוד ה-pipe מלא. כל כתיבה היא 1024 בתים – בדיוק גודל החוצץ – ולכן אי אפשר לכתוב שוב עד שהבן קרא. כלומר, רק אחרי כל כתיבה של האב אפשרית קריאה של הבן, ולא תיתכן כתיבה נוספת לפני הקריאה.\n\nהמגבלות: כל תהליך מדפיס A, B, C לפי הסדר. האב לא יכול להדפיס C לפני שהבן הדפיס A. הבן לא יכול להדפיס אות לפני שהאב הדפיס את הקודמת לה.\n\nAABBCC – האב כותב ומדפיס A, הבן קורא ומדפיס A, וכן הלאה לסירוגין.\nABABCC – האב כותב ומדפיס A. הבן קורא, אבל לפני שהוא מדפיס – האב כותב ומדפיס B. הבן מדפיס A, קורא ומדפיס B. אחר כך C ו-C.\nABACBC – כמו הקודם, אבל גם אחרי שהבן קרא את B, לפני שהוא מדפיס – האב כותב ומדפיס C. הבן מדפיס B, קורא ומדפיס C.\nAABCBC – A ו-A לסירוגין. אחר כך האב כותב ומדפיס B, הבן קורא, ולפני שהוא מדפיס – האב כותב ומדפיס C. הבן מדפיס B, קורא ומדפיס C.\n\nכל פלט אחר בלתי אפשרי בגלל החסימות של ה-pipe."}, {"label": "6.2", "q": "מה יקרה אם נמחק (או נכניס להערה) את שורה 18? פרטו את התופעה והסבירו.", "answer": "קיפאון: אף תהליך לא יסתיים.\n\nבלי שורה 18 האב לא סוגר את הצד הכותב של ה-pipe. אחרי שהבן קרא את 3 החלקים, read לא יחזיר 0 (EOF) – כי עדיין קיים FD פתוח לכתיבה – ולכן הבן חסום ב-read לנצח. והאב חסום ב-wait, כי הבן לא מסתיים.\n\n(הבן סגר את הצד הכותב שלו בשורה 22, ולכן הצד הכותב היחיד שנשאר פתוח הוא של האב – והוא בדיוק זה שלא נסגר.)"}, {"label": "6.3", "q": "מה המספר המקסימלי של מסגרות של מרחב המשתמש (user space) שיכולות להיות בשימוש של תהליכים 42 ו-43 במהלך הריצה? פרטו את הריצה והנקודה שמובילה למקסימום, ואת כל המסגרות. אפשר להניח כל תרחיש שעומד בנתונים.", "answer": "9 מסגרות.\n\nה-pipe נמצא בזיכרון הקרנל, ולכן לא תופס מסגרת של מרחב המשתמש. גם טבלאות הדפים בזיכרון הקרנל.\n\nתהליך 42 משתמש ב-6 דפים – 6 מסגרות אם כולם בזיכרון.\n\nתהליך 43 יכול להוסיף לכל היותר 3 מסגרות (copy-on-write):\nTEXT – זהה, ולכן בהכרח משותף.\nערימה – הקוד לא משנה אותה, ולכן לא משוכפלת.\nמחסנית – בלולאת ה-while יש קריאות לפונקציות וכתיבה למשתנה מקומי (rc), ולכן הדף משוכפל: מסגרת 1.\nbuf – משתנה גלובלי ב-DATA. הוא בגודל דף, אבל אם הוא לא מיושר לתחילת דף, הנתונים שלו מתפרסים על 2 דפים. read כותב לכל 1024 הבתים, ולכן שני הדפים משוכפלים: 2 מסגרות.\n\n6 + 3 = 9"}], "official": "6.1: ‏4 פלטים – AABBCC, ‏ABABCC, ‏ABACBC, ‏AABCBC. 6.2: קיפאון / לולאה אינסופית. 6.3: ‏9 מסגרות.", "note": "6.2: בפתרון הרשמי כתוב \"האב לא יסגור את הצד הקורא של ה-pipe\" – הכוונה לצד הכותב (שורה 18 סוגרת את pipefd[1]).", "expl": "כל הסידורים של 6.1 נמנו בסקריפט (מודל: ה-pipe ריק או מלא, האב כותב רק כשהוא ריק, והבן קורא רק כשהוא מלא) – יצאו בדיוק 4 הפלטים.", "check": "נמנה בסקריפט על כל הסידורים", "exam": "25BB", "examLabel": "סמסטר ב' תשפ\"ה מועד ב'", "date": "04.08.2025", "id": "25BB-6"}, {"num": "7", "type": "open", "topic": "threads", "sub": "מימוש מנעול", "q": "בסניף קופת חולים יש N חדרים. כל מטופל שמגיע ממתין לתורו, וכשמגיע תורו הוא נכנס לחדר עד סוף הטיפול. כל מטופל יכול לקבל טיפול בכל חדר, אבל בכל חדר מטופל אחד בלבד בכל רגע.\nכל מטופל מיוצג על ידי חוט. מטופל שמגיע קורא ל-enter() כדי לחכות לתורו, ול-leave(i) אחרי שסיים את הטיפול בחדר i (ואז החדר פנוי). enter חוסמת עד שהגיע התור, ומחזירה את מספר החדר (0 עד N−1).\nדרישות:\nבכל רגע, בכל חדר לכל היותר מטופל אחד.\nאם יש חדר פנוי ויש מטופלים שמחכים, מטופל כלשהו ייכנס.\nהוגנות: לא ייתכן שמטופל ממתין לצמיתות בזמן שאחרים נכנסים ויוצאים בלי הגבלה.\nמותר להשתמש רק בפעולות האטומיות F&A ו-CAS, בלי אובייקטי סנכרון ופקודות אטומיות אחרות. יש להימנע מ-spinning באמצעות pthread_yield().\nלרשותכם המשתנים הגלובליים שבקוד – אסור להוסיף משתנים או לשנות את האתחול. פתרון שמאפשר רק למטופל אחד לקבל טיפול בכל רגע לא יקבל ניקוד.", "code": "int r[N] = {0};   // init all to 0\nint next = 0, turn = 0;", "answer": "דומה לשאלה 7 במבחן 23BB, אבל עם CAS במקום TAS ובלי פעולה נפרדת לקבלת מספר. next מחלק מספרים בתור, ו-turn סופר כמה מטופלים כבר יצאו. מטופל עם המספר t נכנס כש-t < turn + N – כלומר הוא בין N הבאים בתור. אחר כך הוא תופס חדר פנוי עם CAS.\n\nint enter() {\n    int myturn = fetch_and_add(&next);\n    while (myturn >= turn + N)\n        pthread_yield();\n    for (int i = 0; i < N; ++i) {\n        if (compare_and_set(&r[i], 0, 1))   // success: was 0, now 1\n            return i;\n    }\n}\n\nvoid leave(int i) {\n    r[i] = 0;\n    fetch_and_add(&turn);\n}\n\nבכל רגע לכל היותר N מטופלים עברו את ההמתנה ולא יצאו, ולכן תמיד יש חדר פנוי למי שעבר. החדר משתחרר לפני שמקדמים את turn, אז המטופל הבא ימצא אותו. הכניסה לפי סדר המספרים – הוגנות.", "official": "כמו כאן.", "note": "בקוד הרשמי: compare_and_set(r[i], 0, 1) == 0 – צריך להעביר את הכתובת (&r[i]), וערך ההחזרה תלוי בהגדרה של CAS (כאן הצלחה = ערך שאינו 0, כמו compareAndSet שבשאר המבחנים). בנוסף, בקוד הרשמי לולאת ההמתנה ריקה – לפי דרישות השאלה צריך לקרוא בה ל-pthread_yield().", "expl": "אותו מבנה (עם turn שמתחיל ב-N−1 והתנאי my > turn) נבדק בהרצה במבחן 23BB: 8 חוטים, 3 חדרים, 160,000 טיפולים – אף פעם 2 מטופלים באותו חדר, ותמיד נמצא חדר.", "check": "הורץ עם חוטים אמיתיים (מבנה זהה)", "exam": "25BB", "examLabel": "סמסטר ב' תשפ\"ה מועד ב'", "date": "04.08.2025", "id": "25BB-7"}, {"num": "8", "type": "open", "topic": "fs", "sub": "Journaling", "intro": "השאלה מתייחסת למערכת קבצים VSFS עם journaling (לא metadata journaling). כמה סטודנטים התווכחו על הצורך בטרנזקציות:\nסטודנט א': לכל פעולה שדורשת כתיבה לבלוק אחד בלבד אין צורך בטרנזקציה – אפשר לכתוב ישירות ועדיין להתמודד עם קריסה.\nסטודנט ב': א' צודק, וגם לפעולות שדורשות כתיבה ל-2 בלוקים אין צורך בטרנזקציה – בתנאי שלפחות אחד מהם ב-DATA region.\nסטודנט ג': ב' צודק, אבל זה נכון לכל פעולה שדורשת כתיבה ל-2 בלוקים לכל היותר, גם אם אף אחד מהם לא ב-DATA region.\nסטודנט ד': כולם טועים – צריך טרנזקציה לכל פעולה שכותבת לבלוק כלשהו.\n\"בלוקים של פעולה\" הם הבלוקים שהפעולה צריכה ב-VSFS, בלי כתיבת הטרנזקציה. אין מגבלה על מספר הבלוקים לקריאה.", "parts": [{"label": "8.1", "q": "תארו פעולה ב-VSFS (בלי journaling) שדורשת כתיבה לבלוק אחד בלבד. פרטו את כל הבלוקים שניגשים אליהם, לקריאה ולכתיבה, לפי הסדר. אף cache לא מכיל מידע רלוונטי.", "answer": "קריאה מקובץ.\n\nכשקוראים מקובץ צריך לעדכן את זמן הגישה ב-inode (כתיבה לבלוק שמכיל אותו). אין שום כתיבה אחרת.\n\nקריאת בלוק ה-inode\nקריאת בלוק ה-DATA הראשון\nכתיבה לבלוק ה-inode (עדכון זמן הגישה האחרון)"}, {"label": "8.2", "q": "תארו פעולה ב-VSFS (בלי journaling) שדורשת כתיבה ל-2 בלוקים בדיוק, ולפחות אחד מהם ב-DATA region. פרטו את כל הבלוקים לפי הסדר. אף cache לא מכיל מידע רלוונטי.", "answer": "עדכון נתונים קיימים בקובץ (בלי להוסיף בלוק DATA).\n\nצריך לכתוב לבלוק ה-DATA שהשתנה, ולעדכן את זמני הגישה והשינוי ב-inode. אין שום כתיבה אחרת.\n\nקריאת בלוק ה-inode\nקריאת בלוק ה-DATA הראשון\nכתיבה לבלוק ה-DATA (הנתונים המעודכנים)\nכתיבה לבלוק ה-inode (זמן גישה וזמן שינוי)"}, {"label": "8.3", "q": "מי מהסטודנטים צודק? בחרו את הטענה הנכונה ביותר, והסבירו למה היא נכונה ולמה האחרות שגויות.", "answer": "סטודנט א'.\n\nאם הפעולה כותבת לבלוק אחד, הכתיבה הזו ממילא אטומית – הדיסק מבטיח שכתיבה של בלוק מתבצעת במלואה או לא מתבצעת בכלל. לכן אין צורך בטרנזקציה, וסטודנט ד' טועה.\n\nסטודנט ב' טועה (ולכן גם ג'): ייתכן שהכתיבה לבלוק ה-DATA היא עדכון של נתונים קיימים (כמו ב-8.2). אם קורסים אחרי הכתיבה ל-DATA ולפני עדכון ה-inode, מערכת הקבצים נשארת במצב לא עקבי – וכך גם להפך, אם מעדכנים קודם את ה-inode וקורסים לפני ה-DATA."}], "official": "8.1: קריאה מקובץ. 8.2: עדכון נתוני קובץ. 8.3: סטודנט א'.", "expl": "", "check": "לפי הפתרון הרשמי", "exam": "25BB", "examLabel": "סמסטר ב' תשפ\"ה מועד ב'", "date": "04.08.2025", "id": "25BB-8"}, {"num": "1", "type": "mcq", "topic": "sched", "sub": "Round Robin", "q": "נתונה מערכת עם אלגוריתם תזמון שמבוסס על RR, עם הבדל: משימה חדשה מתחילה לרוץ מיד כשהיא נוצרת. משימה שסיימה את הקוונטום שלה עדיין חוזרת לסוף התור, ואפשר להניח שלא נוצרות 2 משימות חדשות בו-זמנית.\nבנוסף, אי אפשר לעצור משימה במהלך הקוונטום הראשון שלה: היא מסיימת אותו גם אם מגיעה משימה חדשה, והמשימה החדשה מתחילה מיד בסוף הקוונטום הנוכחי. בכל מקרה אחר, המשימה החדשה מתחילה לרוץ מיד כשהיא נוצרת. איזו טענה בהכרח נכונה?", "options": ["זמן התגובה של האלגוריתם אופטימלי.", "זמן המחזור של האלגוריתם תמיד טוב או שווה לזה של RR רגיל.", "לכל N > 1, אם בכל רגע יש בתור לכל היותר N משימות, לא תיתכן הרעבה.", "לכל N > 1, אם בכל רגע יש בתור לכל היותר N משימות, בהכרח תתרחש הרעבה.", "כל התשובות האחרות אינן נכונות."], "correct": 4, "official": "כל התשובות האחרות אינן נכונות – בדומה לשאלה מהמועד הקודם, אף אחת מהטענות לא נכונה.", "expl": "בגלל הקוונטום הראשון שאי אפשר להפסיק, משימה חדשה שמגיעה בזמן שמשימה אחרת בקוונטום הראשון שלה מחכה – כלומר זמן התגובה כבר לא 0, ולא אופטימלי. משימות חדשות שמגיעות שוב ושוב יכולות לעכב את הישנות בלי הגבלה (הרעבה אפשרית), אבל זה לא בהכרח קורה. וזמן המחזור יכול להיות גרוע מ-RR.", "check": "לפי הפתרון הרשמי", "exam": "25BC", "examLabel": "סמסטר ב' תשפ\"ה מועד ג'", "date": "04.09.2025", "id": "25BC-1"}, {"num": "2", "type": "mcq", "topic": "memory", "sub": "טבלה היררכית", "q": "במערכת עם טבלת דפים היררכית, כל PTE מכיל 3 ביטים של סטטוס. כתובת פיזית מורכבת מהיסט של 13 ביטים וממספר מסגרת של 23 ביטים. במערכת רצים 2 תהליכים, A ו-B, וידוע שטבלת הדפים של A תופסת בדיוק 4 מסגרות. מהו מרחב הכתובות של B?", "options": ["8KB", "8MB", "64MB", "אין מספיק נתונים כדי לחשב את התשובה.", "כל התשובות האחרות אינן נכונות."], "correct": 3, "official": "אין מספיק נתונים. זו טבלת דפים היררכית, ולכן הגודל של הטבלה של A לא מעיד על B, ואין מספיק נתונים כדי לדעת כמה דפים יש לכל תהליך במרחב הכתובות.", "expl": "השוו לשאלה 5 במבחן 25BB: שם הטבלה לינארית, ולכן גודלה קבוע ונגזר ממרחב הכתובות. בטבלה היררכית הגודל תלוי בכמה דפים התהליך משתמש בפועל (ובכמה רמות יש) – 4 מסגרות יכולות להיות 2 רמות או 3 או 4, עם מספר שונה של חלקים בכל רמה.", "check": "לפי הפתרון הרשמי", "exam": "25BC", "examLabel": "סמסטר ב' תשפ\"ה מועד ג'", "date": "04.09.2025", "id": "25BC-2"}, {"num": "3", "type": "open", "topic": "redir", "sub": "pipe בין תהליכים", "intro": "נתונה התוכנית הבאה. הריצו אותה, והתהליך שנוצר קיבל את המזהה 42. כל קריאות המערכת שיכולות להצליח הצליחו, לא נוצרים תהליכים בקוד אחר, וכל תהליך מקבל מזהה גדול ב-1 מהקודם. כל הדפסה לפלט הסטנדרטי מתבצעת מיד, בלי חוצץ ובלי לחכות לירידת שורה.", "code": " 1 void foo(int p_read[2], int p_write[2]) {\n 2     unsigned int num;\n 3     int ret;\n 4     close(p_read[1]);\n 5     close(p_write[0]);\n 6\n 7     while (1) {\n 8         ret = read(p_read[0], &num, sizeof(int));\n 9         if (ret == 0)\n10             exit(0);\n11         printf(\"%d \", num);\n12         if (num == 1)\n13             exit(0);\n14         usleep(50 * 1000);   // sleep for 50*1000us\n15         num = (num%2 == 0) ? num/2 : num*3+1;\n16         write(p_write[1], &num, sizeof(int));\n17     }\n18 }\n19\n20 int main() {\n21     int pipe1[2], pipe2[2];\n22     const int NUM = 3;\n23     pipe(pipe1);\n24     pipe(pipe2);\n25     if (!fork())\n26         foo(pipe1, pipe2);\n27     if (!fork())\n28         foo(pipe2, pipe1);\n29     write(pipe1[1], &NUM, sizeof(int));\n30     // while (wait(NULL) > 0); // commented out!\n31     exit(0);\n32 }", "parts": [{"label": "3.1", "q": "כתבו את כל הפלטים האפשריים של התוכנית, והסבירו כל פלט.", "answer": "פלט אפשרי אחד בלבד:\n3 10 5 16 8 4 2 1\n\nהאב כותב 3 ל-pipe1. הבן הראשון קורא מ-pipe1 וכותב ל-pipe2, והבן השני קורא מ-pipe2 וכותב ל-pipe1 – כך הם מעבירים את המספר הלוך ושוב. כל אחד מדפיס את המספר שקיבל ומחשב את הבא: אם זוגי – חצי, אחרת 3n + 1 (סדרת קולץ). כשמגיעים ל-1, מי שקיבל אותו יוצא.\n\nהפלט דטרמיניסטי: רק הבן הראשון קורא מ-pipe1 ורק הבן השני קורא מ-pipe2, וכל אחד חסום ב-read עד שהשני כותב – אז בכל רגע רק אחד מהם מדפיס, והסדר קבוע."}, {"label": "3.2", "q": "מה יקרה אם נוציא את שורה 30 מההערה? פרטו את התופעה והסבירו. (השינוי הוא רק בקוד הנתון.)", "answer": "קיפאון – התוכנית תיתקע. הבן שמקבל את 1 יוצא, אבל הבן השני חסום ב-read ומחכה למספר הבא. הוא היה מקבל EOF רק אם כל הצדדים הכותבים של ה-pipe שלו היו סגורים – אבל האב עדיין מחזיק אותם פתוחים, והאב עצמו תקוע ב-wait ומחכה לאותו בן. זה מעגל המתנה.\n\nכדי שזה יעבוד, האב צריך לסגור את קצוות ה-pipe שלו – בפרט את הצדדים הכותבים – לפני ה-wait."}, {"label": "3.3", "q": "אם נכניס את שורה 14 להערה, האם עלול להיווצר מרוץ (race condition)? (השינוי הוא רק בקוד הנתון.)", "answer": "לא. הבנים מסונכרנים על ידי ה-pipe עצמו: כל אחד חסום ב-read עד שהשני כותב, כך שבכל רגע רק אחד מהם \"פעיל\". ההדפסות בלי buffer, וכל תהליך עובד בזיכרון הפרטי שלו. ה-usleep רק מאט – הוא לא זה שמסנכרן."}], "official": "התשובות זהות לשאלה 6 במבחן 22AB.", "expl": "בלי שורה 30 התוכנית מסתיימת תקין: הבן שמקבל 1 יוצא, ואז לבן השני אין יותר כותבים פתוחים ל-pipe שלו (האב כבר יצא) – read מחזיר 0 והוא יוצא.", "check": "הורץ (במבחן 22AB)", "exam": "25BC", "examLabel": "סמסטר ב' תשפ\"ה מועד ג'", "date": "04.09.2025", "id": "25BC-3"}, {"num": "4", "type": "open", "topic": "threads", "sub": "מימוש מנעול", "parts": [{"label": "4.1", "q": "במנעול TTAS שנלמד מימשנו רק lock ו-unlock. במנעול המובנה של לינוקס יש גם trylock ו-timedlock.\nממשו מנעול TTAS שתומך גם ב-trylock וב-timedlock, ושומר על כל התכונות של TTAS (מניעה הדדית, חופש מקיפאון, הוגנות, ביצועים). הפעולות מחזירות 0 בהצלחה (המנעול נתפס), ומספר אחר בכישלון או ב-timeout.\nמותר להשתמש רק בפעולה האטומית TAS, ויש להימנע מ-spinning באמצעות pthread_yield(). ל-timedlock אפשר להשתמש בפונקציה time(), שמחזירה מספר שהולך וגדל ומייצג את הזמן הנוכחי. הפרמטר limit הוא הזמן שעד אליו מנסים לתפוס.\nפתרון שלא שומר על כל התכונות של TTAS (כולל הביצועים) לא עומד בדרישות.", "answer": "ב-TTAS חשוב שהניסיון לתפוס (TAS) יתבצע רק אחרי שקוראים את המנעול ורואים שהוא פנוי – אחרת הביצועים לא כמו של TTAS (כל TAS יוצר תעבורה על ה-bus). ב-trylock וב-timedlock צריך גם לוודא שבדיקת המנעול מוגבלת ולא רצה לנצח. ובכל לולאת המתנה קוראים ל-pthread_yield.\n\ntypedef struct {\n    int state;   // init to 0\n} TTASLock;\n\nvoid lock(TTASLock *lock) {\n    while (1) {\n        while (lock->state)\n            pthread_yield();\n        if (!testAndSet(&lock->state, 1))\n            return;\n    }\n}\n\nvoid unlock(TTASLock *lock) {\n    lock->state = 0;\n}\n\nint trylock(TTASLock *lock) {\n    if ((lock->state) || (testAndSet(&lock->state, 1)))\n        return 1;   // failed\n    return 0;       // acquired\n}\n\nint timedlock(TTASLock *lock, int limit) {\n    while (1) {\n        while (lock->state) {\n            if (time() >= limit)\n                return 1;   // timeout\n            pthread_yield();\n        }\n        if (!testAndSet(&lock->state, 1))\n            return 0;\n    }\n}"}, {"label": "4.2", "q": "נתון קטע הקוד הבא למימוש מנעול עבור N חוטים, כאשר לכל חוט מזהה ייחודי (בין 0 ל-N − 1) המועבר כפרמטר me לפונקציית lock. האם המנעול מקיים מניעה הדדית? חופש מקיפאון? הוגנות?", "code": "typedef struct {\n    int turn;\n    int busy;\n} FlakyLock;\nvoid init(FlakyLock *lock) {\n    lock->busy = 0;\n}\nvoid lock(FlakyLock *lock, int me) {\n    do {\n        do {\n            lock->turn = me;\n        } while (lock->busy);\n        lock->busy = 1;\n    } while (lock->turn != me);\n}\nvoid unlock(FlakyLock *lock) {\n    lock->busy = 0;\n}", "answer": "מניעה הדדית – מתקיימת. נניח בשלילה ששני חוטים בקטע הקריטי. כל אחד יצא מהלולאה החיצונית כשראה turn שווה למזהה שלו – ורק הוא עצמו כותב את המזהה שלו ל-turn. נסתכל על החוט שיצא שני: הוא כתב turn אחרי שהראשון יצא (אחרת הראשון היה רואה turn לא שלו). אבל הראשון כתב busy = 1 לפני שיצא, ולכן כשהשני בודק את busy אחרי שכתב turn, הוא רואה 1 ותקוע בלולאה הפנימית – סתירה.\n\nחופש מקיפאון – לא מתקיים. דוגמה נגדית: חוט 0 כותב turn = 0 ו-busy = 1. לפני שהוא בודק את התנאי החיצוני, חוט 1 כותב turn = 1 ונתקע בלולאה הפנימית (busy = 1). חוט 0 רואה ש-turn לא שלו, חוזר ללולאה הפנימית, כותב turn = 0 – ונתקע גם הוא, כי busy = 1. אף חוט לא בקטע הקריטי, אף אחד לא יאפס את busy – שני החוטים תקועים לנצח.\n\nהוגנות – לא מתקיימת. דוגמה נגדית: חוט 0 כותב turn = 0 ונעצר לפני busy = 1. חוט 1 כותב turn = 1, עובר ונכנס לקטע הקריטי. חוט 0 ממשיך, רואה שזה לא התור שלו ונתקע בלולאה הפנימית. חוט 1 משחרר (busy = 0), ולפני שחוט 0 רואה את זה – חוט 1 תופס שוב: turn = 1, busy = 1, ונכנס. וכך שוב ושוב."}], "official": "4.1: כמו כאן. 4.2: התשובה זהה לשאלה 7 במבחן 22AC – מניעה הדדית מתקיימת, חופש מקיפאון והוגנות לא.", "expl": "4.2 נבדק בסריקה ממוחשבת של כל השזירות (עם 2 ו-3 חוטים): אין מצב עם 2 חוטים בקטע הקריטי, ויש מצבים ישיגים שמהם אף חוט לא יכול להיכנס לעולם.", "check": "model checking (4.2)", "exam": "25BC", "examLabel": "סמסטר ב' תשפ\"ה מועד ג'", "date": "04.09.2025", "id": "25BC-4"}, {"num": "5", "type": "open", "topic": "fs", "sub": "VSFS", "intro": "נתון דיסק קשיח עם הנתונים הבאים:\nמהירות סיבוב 10,000 RPM.\nגודל מצביע 4 בתים, גודל סקטור 1024 בתים, גודל בלוק 4KB.\n8 משטחים (4 platters דו-צדדיים).\nצפיפות הסקטורים לפי 2 אזורים A, B, ובכל אזור 500 רצועות. באזור A יש 4000 סקטורים לרצועה, וב-B ‏2000.\nזמן seek ממוצע 8ms, ובין 2 רצועות סמוכות 2ms.\nיש track skew: בקריאת סקטורים עוקבים ברצועות סמוכות אין המתנה לסיבוב.\nעל כל הדיסק יש מערכת קבצים VSFS: ה-superblock בבלוק 0, ושאר מערכת הקבצים מבלוק 1 והלאה, בסדר האזורים הסטנדרטי שנלמד. כל הבלוקים בדיסק בשימוש של מערכת הקבצים.\ninode בגודל 512 בתים, ובכל inode יש 6 מצביעים ישירים, 3 עקיפים ו-2 עקיפים כפולים.\nיש לפרט ולנמק את הפעולות והחישובים בכל סעיף.", "parts": [{"label": "5.1", "q": "לכל אחד מהנתונים הבאים, ציינו אם אפשר לדעת את הערך המקסימלי שלו. אם כן – מה הוא, אחרת – מה הנתון החסר: בלוק ה-inode הראשון, בלוק ה-data הראשון, בלוק ה-inode bitmap הראשון, בלוק ה-data bitmap הראשון.", "answer": "inode bitmap ראשון: 1. ‏data bitmap ראשון: 1466. ‏inode ראשון: 1467. ‏data ראשון: 5,999,999.\n\nחישובים מקדימים:\nבכל משטח: 500 · 4000 + 500 · 2000 = 3,000,000 סקטורים\nב-8 משטחים: 24,000,000 סקטורים, כלומר 6,000,000 בלוקים\nבבלוק נכנסים 8 inodes ו-32,768 ביטים.\n\ninode bitmap – תמיד מיד אחרי ה-superblock (בסדר הסטנדרטי), ולכן תמיד בלוק 1.\n\ndata bitmap – הבלוק הראשון שלו הכי רחוק כשה-inode bitmap הכי גדול, כלומר כשכמה שיותר בלוקים הולכים ל-inodes. מורידים 1 ל-superblock, ‏1 ל-DATA ו-1 ל-data bitmap – נשארים 5,999,997 ל-inode bitmap ול-inodes. כל בלוק של inode bitmap מכסה 32,768 inodes, כלומר 4096 בלוקי inodes:\n5,999,997 / 4097 = 1464.49\nכלומר לכל היותר 1465 בלוקים של inode bitmap (האחרון בשימוש חלקי). הם בבלוקים 1–1465, ולכן ה-data bitmap מתחיל לכל היותר ב-1466.\n\ninode – מקסימלי כשה-inode bitmap מקסימלי וה-data bitmap בבלוק אחד (ה-inode bitmap \"יקר\" יותר לאותו מספר בלוקים). לכן לכל היותר 1467.\n\ndata – אזור ה-DATA הוא האחרון. הבלוק הראשון שלו הכי רחוק כשיש בלוק DATA יחיד – ואז הוא הבלוק האחרון בדיסק: 5,999,999."}, {"label": "5.2", "q": "במערכת יש קובץ בגודל 20MB. מה הזמן המינימלי לקריאת כל הקובץ? אפשר להניח כל תרחיש שמוביל לזמן המינימלי. הקובץ כבר נפתח, ומלבד זה אף cache לא מכיל מידע רלוונטי. פרטו את הפעולה, כולל כל הבלוקים לקריאה ולכתיבה.", "answer": "36ms (ליתר דיוק 36.006ms).\n\nשמים את כל הנתונים ברצף באזור A – שם יש יותר סקטורים ברצועה, אז קוראים יותר בכל סיבוב.\n\nבלוקים לקריאה:\n20MB / 4KB = 5120 בלוקי נתונים\nמצביעים בבלוק: 4KB / 4B = 1024\n6 ישירים + 3 · 1024 עקיפים = 3078; נשארו 2042 – דרך העקיף הכפול הראשון\nבלוקי מצביעים: 3 עקיפים, העקיף הכפול, ו-2 בלוקים עקיפים מתחתיו (1024 + 1018)\nועוד ה-inode\n\nצריך לקרוא את ה-inode וגם לכתוב אליו (עדכון זמן הגישה). אלה 2 גישות לאותו בלוק, ואי אפשר לעשות אותן ברצף – בין הקריאה לכתיבה צריך לחכות שהבלוק יחזור מתחת לראש.\n\nברצועה של A יש 4000KB / 4KB = 1000 בלוקים. זמן סיבוב: 60,000 / 10,000 = 6ms.\n\nבמקרה הטוב אין seek ואין המתנה לסיבוב בהתחלה, וכל הרצועות על אותו צילינדר (משטחים שונים), כך שאין מעבר בין רצועות. קוראים כ-5.13 רצועות (כ-5,130 בלוקים) ברצף, ואז מחכים עד שבלוק ה-inode חוזר מתחת לראש וכותבים אותו – בסך הכל 6 סיבובים שלמים ועוד בלוק אחד:\n6.001 · 6ms ≈ 36ms"}, {"label": "5.3", "q": "בסעיף זה בלבד, מערכת הקבצים שודרגה ל-metadata journaling. בשיעור נלמד שעם metadata journaling, אם פעולה כותבת נתונים לבלוק DATA קיים, צריך לשכפל את הבלוק עם השינויים ולא לעדכן אותו במקום, כדי להמשיך להתמודד עם קריסות.\nסטודנט א': כשמוסיפים נתונים לסוף קובץ קיים, אפשר לכתוב את הנתונים בשלב כתיבת ה-DATA כרגיל, בלי לשכפל את הבלוק (גם אם הבלוק האחרון לא היה מנוצל עד הסוף).\nסטודנט ב': א' צודק רק לפעולות שבהן הכתיבה לא מוסיפה בלוק DATA חדש לקובץ.\nסטודנט ג': א' צודק, אבל זה נכון לכל כתיבה שמוסיפה נתונים לקובץ קיים, לא דווקא בסופו.\nסטודנט ד': כולם טועים – צריך לשכפל את בלוק ה-DATA בכל טרנזקציה שכוללת כתיבה לבלוק DATA קיים.\nמי צודק? בחרו את הטענה הנכונה ביותר והסבירו למה היא נכונה ולמה האחרות שגויות.", "answer": "סטודנט א'.\n\nכשמוסיפים נתונים לקובץ וכותבים קודם את ה-DATA: אם קורסים, הנתונים פשוט לא נוספו – ה-inode עוד לא עודכן עם הגודל החדש, ולכן הבתים שנכתבו אחרי סוף הקובץ הישן לא נחשבים חלק ממנו. אין בעיה.\n\nסטודנט ב' טועה: לא משנה אם נוסף בלוק DATA חדש – כתיבה לבלוקים חדשים ממילא לא דורשת שכפול.\nסטודנט ג' טועה: אין דבר כזה \"להוסיף נתונים לקובץ שלא בסופו\". אפשר לשכתב/לעדכן נתונים קיימים, או להוסיף לסוף. כל שינוי שלא בסוף הקובץ הוא עדכון – ודורש שכפול.\nסטודנט ד' טועה, כי סטודנט א' צודק."}], "official": "5.1: ‏inode bitmap – 1, ‏data bitmap – 1466, ‏inode – 1467, ‏data – 5,999,999. 5.2: ‏36ms. 5.3: סטודנט א'.", "note": "5.2: בפתרון הרשמי כתוב שהקובץ משתמש בעקיף הכפול ובבלוק עקיף אחד מתחתיו (5125 בלוקים). בפועל דרך העקיף הכפול עוברים 2042 בלוקים, ולכן צריך 2 בלוקים עקיפים מתחתיו (5126 בלוקים). התשובה לא משתנה: בכל מקרה הקריאה ועוד ההמתנה לחזרת ה-inode מסתכמות ב-6.001 סיבובים.\nבנוסף, הקובץ \"כבר נפתח\" – ייתכן שה-inode כבר בזיכרון ואין צורך לקרוא אותו. אז אפשר לשים את בלוק ה-inode מיד אחרי הנתונים ולכתוב אותו בלי לחכות לסיבוב, ולקבל כ-5.13 סיבובים (כ-30.8ms). הפתרון הרשמי מניח שקוראים את ה-inode.", "expl": "", "check": "חושב בסקריפט", "exam": "25BC", "examLabel": "סמסטר ב' תשפ\"ה מועד ג'", "date": "04.09.2025", "id": "25BC-5"}, {"num": "1", "type": "mcq", "topic": "disk", "sub": "RAID-5", "q": "בתרחיש של כתיבות אקראיות קטנות ל-RAID-5 עם N דיסקים (N זוגי), מספר הכתיבות המקסימלי שאפשר לבצע במקביל הוא N/2.", "options": ["הטענה נכונה.", "הטענה נכונה רק אם כל הכתיבות הן לאותו stripe.", "הטענה לא נכונה: אפשר לבצע עד N−1 כתיבות במקביל.", "הטענה לא נכונה, כי חישוב parity לא דורש גישה לדיסק נוסף.", "כל התשובות האחרות אינן נכונות."], "correct": 0, "official": "הטענה נכונה. כל כתיבה \"תופסת\" לפחות 2 דיסקים – הדיסק עם בלוק הנתונים ודיסק ה-parity של אותו stripe – ולכן מספר הכתיבות המקסימלי במקביל הוא אכן N/2.", "expl": "כתיבה קטנה ב-RAID-5 (parity חיסורי) קוראת וכותבת גם את בלוק הנתונים וגם את בלוק ה-parity, שנמצאים בשני דיסקים שונים. במקרה הטוב, כל זוג כתיבות משתמש בזוג דיסקים נפרד – N/2 כתיבות במקביל. זו הסיבה שבטבלה של OSTEP הקצב של כתיבות אקראיות ב-RAID-5 הוא N/4 · R (כל כתיבה היא 4 פעולות, על 2 דיסקים).", "check": "לפי הפתרון הרשמי", "exam": "26AA", "examLabel": "סמסטר א' תשפ\"ו מועד א'", "date": "27.01.2026", "id": "26AA-1"}, {"num": "2", "type": "mcq", "topic": "disk", "sub": "SSD", "q": "איזו מהטענות הבאות נכונה לגבי זיכרון Flash?", "options": ["כל הפעולות מתבצעות ברמת דף, וכך מתאפשרת גישה אקראית מהירה.", "מחיקה היא הפעולה המהירה ביותר, כי היא מעדכנת לערך קבוע.", "מחיקה מתבצעת ברמת בלוק, והיא הפעולה האיטית ביותר.", "כתיבה לדף במצב VALID מהירה יותר מכתיבה לדף במצב ERASED, כי לא צריך לשנות מצב.", "כל התשובות האחרות אינן נכונות."], "correct": 2, "official": "מחיקה מתבצעת ברמת בלוק, והיא הפעולה האיטית ביותר – כפי שנלמד על כונני SSD.", "expl": "בפלאש: קריאה ברמת דף (עשרות מיקרו-שניות), כתיבה (program) ברמת דף (מאות מיקרו-שניות), ומחיקה ברמת בלוק שלם (מילי-שניות). ואי אפשר לכתוב לדף VALID בכלל – צריך קודם למחוק את כל הבלוק שלו.", "check": "לפי הפתרון הרשמי", "exam": "26AA", "examLabel": "סמסטר א' תשפ\"ו מועד א'", "date": "27.01.2026", "id": "26AA-2"}, {"num": "3", "type": "mcq", "topic": "memory", "sub": "טבלה היררכית", "q": "במערכת עם טבלת דפים לינארית הוחלט לעבור לטבלת דפים היררכית עם 3 רמות. איזו טענה נכונה?", "options": ["צריכת הזיכרון תקטן בממוצע, והגישה לזיכרון אחרי TLB miss תהיה איטית יותר.", "צריכת הזיכרון תקטן בממוצע, והגישה לזיכרון אחרי TLB miss תהיה מהירה יותר.", "צריכת הזיכרון תגדל בממוצע, והגישה לזיכרון אחרי TLB miss תהיה איטית יותר.", "צריכת הזיכרון תגדל בממוצע, והגישה לזיכרון אחרי TLB miss תהיה מהירה יותר.", "חסרים נתונים כדי לענות."], "correct": 0, "official": "צריכת הזיכרון תקטן בממוצע, והגישה אחרי TLB miss תהיה איטית יותר. טבלה היררכית נועדה להקטין את צריכת הזיכרון של הטבלה, אבל גורמת ליותר גישות לזיכרון אחרי TLB miss – צריך לעבור על כל הרמות.", "expl": "בטבלה לינארית TLB miss דורש גישה אחת לטבלה. עם 3 רמות – 3 גישות. בתמורה, מקצים רק את חלקי הטבלה שבשימוש, ולכן תהליך טיפוסי (שמשתמש במעט מאוד ממרחב הכתובות) חוסך הרבה זיכרון.", "check": "לפי הפתרון הרשמי", "exam": "26AA", "examLabel": "סמסטר א' תשפ\"ו מועד א'", "date": "27.01.2026", "id": "26AA-3"}, {"num": "4", "type": "mcq", "topic": "threads", "sub": "מקביליות", "intro": "להלן קוד של שני חוטים שרצים בו-זמנית במערכת עם מעבד יחיד. כל המשתנים משותפים לשני החוטים – כולל האינדקס i. המשתנה x מאותחל ל-0.", "code": "Thread 1                       Thread 2\nfor (i=1; i<=14; ++i)          for (i=1; i<=16; ++i)\n    x = x + 1;                     x = x + 1;", "q": "מהו הערך המקסימלי של x בסיום הריצה של שני החוטים?", "options": ["30", "31", "32", "33", "כל התשובות האחרות אינן נכונות."], "correct": 4, "official": "כל התשובות האחרות אינן נכונות. האינדקס i משותף, ולכן חוט 1 יכול לקרוא 1, ולפני שכתב i = 2 – החוט השני יקדם את המונה 16 פעמים. אחר כך החוט הראשון מחזיר את i ל-2, ולפני שכתב i = 3 החוט השני מקדם את המונה 15 פעמים, וכן הלאה – עד שהמונה גדול מכל התשובות.", "expl": "כתיבה \"ישנה\" של i מחזירה את הלולאה אחורה, ואז החוט השני מבצע שוב עוד איטרציות. כך מספר הקידומים הכולל יכול להיות הרבה יותר מ-14 + 16 = 30.\n\nבסריקה ממוחשבת של כל התזמונים (כל קריאה וכתיבה של x ו-i כצעד נפרד) נמצאו ריצות שמסתיימות עם x = 80 ויותר – כלומר אין חסם קטן.", "check": "נבדק בסריקה ממוחשבת של כל התזמונים", "exam": "26AA", "examLabel": "סמסטר א' תשפ\"ו מועד א'", "date": "27.01.2026", "id": "26AA-4"}, {"num": "5", "type": "mcq", "topic": "threads", "sub": "מקביליות", "intro": "להלן קוד של שני חוטים שרצים בו-זמנית במערכת עם מעבד יחיד. כל המשתנים משותפים לשני החוטים – כולל האינדקס i. המשתנה x מאותחל ל-0.", "code": "Thread 1                       Thread 2\nfor (i=1; i<=14; ++i)          for (i=1; i<=16; ++i)\n    x = x + 1;                     x = x + 1;", "q": "מהו הערך המינימלי של x בסיום הריצה של שני החוטים?", "options": ["0", "1", "2", "14", "כל התשובות האחרות אינן נכונות."], "correct": 1, "official": "1. כיוון שהאינדקס i משותף, ייתכן שחוט 1 קורא x == 0, ולפני שהוא כותב x = 1 החוט השני מקדם את המונה עד הסוף – וגם את i עד 16 (ומעבר). חוט 1 חוזר, כותב x = 1, ויוצא מהלולאה כי i כבר גדול מ-14.", "expl": "השוו לשאלה 5 במבחן 24AB, שם המינימום הוא 2: שם לכל חוט יש אינדקס משלו, ולכן כל חוט חייב לבצע את כל האיטרציות שלו, והכתיבה האחרונה היא לפחות 2. כאן i משותף – והחוט השני יכול \"לגמור\" את הלולאה של הראשון, כך שהראשון מבצע כתיבה אחת בלבד.\n\nמינימום 1 נבדק גם בסריקה ממוחשבת של כל התזמונים.", "check": "נבדק בסריקה ממוחשבת של כל התזמונים", "exam": "26AA", "examLabel": "סמסטר א' תשפ\"ו מועד א'", "date": "27.01.2026", "id": "26AA-5"}, {"num": "6", "type": "open", "topic": "sched", "sub": "FIFO ו-SJF", "intro": "נתונה התוכנית הבאה. יש מעבד יחיד, וכל קריאות המערכת הצליחו. לצורך התזמון יש להניח שכל שורת קוד רצה בזמן קבוע וזהה.", "code": " 1 int main()\n 2 {\n 3     int arr[N];\n 4     char *e[] = { \"echo\", \" hello\", NULL };\n 5     setbuf(stdout, NULL);\n 6\n 7     for (int i = 0; i < N; ++i)\n 8         arr[i] = (fork() > 0);   // FALSE is 0, TRUE is 1\n 9\n10     for (int i = 0; i < N; ++i)\n11         printf(\"%d\", arr[i]);\n12\n13     if (arr[0])\n14         execvp(e[0], e);\n15     else\n16         printf(\"\\n\");\n17 }", "parts": [{"label": "6.1", "q": "כתבו פלט אפשרי של התוכנית כאשר N = 3 ואלגוריתם התזמון הוא FIFO.", "answer": "111 hello\n011\n101 hello\n110 hello\n001\n010\n100 hello\n000\n\nכל תהליך כותב 3 ספרות – ערכי ההחזרה של ה-fork-ים מנקודת המבט שלו (1 אם היה האב). הוא נכנס לתנאי בשורה 13 (ומריץ echo) אם הוא התהליך הראשי או צאצא שלו שאינו בתת-העץ של הבן הראשון – כלומר arr[0] = 1.\n\nב-FIFO התהליכים רצים לפי סדר היצירה, וכל אחד רץ עד הסוף. הראשי יוצר 3 בנים ורץ ראשון; אחריו הבן הראשון (011), שיוצר 2 בנים, ואז השני (101) והשלישי (110), וכן הלאה.\n\nעץ התהליכים:\n\n[[TREE]]", "tree": ["111", "hello", [["011", "", [["001", "", [["000", "", []]]], ["010", "", []]]], ["101", "hello", [["100", "hello", []]]], ["110", "hello", []]]]}, {"label": "6.2", "q": "כתבו פלט אפשרי כאשר N = 3 ואלגוריתם התזמון הוא SJF.", "answer": "111 hello\n110 hello\n101 hello\n100 hello\n011\n010\n001\n000\n\nהפלט של כל תהליך זהה, אבל סדר הריצה משתנה: בכל נקודת החלטה רץ התהליך הקצר ביותר מבין אלה שכבר נוצרו, וכל תהליך רץ עד הסוף (SJF אינו מפקיע).\n\nתהליך קצר יותר הוא תהליך שנשארו לו פחות איטרציות של fork – כלומר שנוצר באיטרציה מאוחרת יותר. אחרי הראשי, מבין 011, ‏101 ו-110 – הקצר ביותר הוא 110 (נוצר באיטרציה האחרונה). אחר כך 101, שיוצר את 100 – ו-100 קצר יותר מ-011. ורק אז 011 וצאצאיו.\n\nשימו לב: זה לא אומר שכל הקצרים רצים קודם, אלא רק מבין אלה שכבר נוצרו בכל נקודת החלטה."}, {"label": "6.3", "q": "טבלת הדפים של כל תהליך נכנסת בדף אחד, והתהליך הראשי משתמש ב-5 דפים: 2 של קוד, אחד של מחסנית, אחד של ערימה ואחד של DATA. נניח שאף תהליך עוד לא קרא ל-execvp. לכל N, כמה מסגרות של מרחב המשתמש יהיו תפוסות על ידי כל התהליכים יחד בנקודה כלשהי בריצה, במקרה המינימלי והמקסימלי? יש להתייחס למערכת הפעלה רגילה עם כל המאפיינים שנלמדו.", "answer": "מינימום 0, מקסימום 5 + 2^N − 1.\n\nמינימום – 0 מסגרות: ייתכן שברגע מסוים כל הדפים ב-swap, ולא תופסים זיכרון בכלל. (התקבלה חלקית התשובה 5 – הראשי לבד לפני שהאחרים נוצרו, או N = 0.)\n\nמקסימום: יש 2^N תהליכים (כולל הראשי). הראשי משתמש ב-5 מסגרות. לכל תהליך נוסף משוכפלת רק המחסנית – הקוד משותף, ובגלל copy-on-write שאר הדפים לא משתנים. המחסנית משתנה כי arr הוא מערך מקומי. כלומר מסגרת אחת לכל תהליך נוסף:\n5 + (2^N − 1)"}], "official": "6.1 ו-6.2: כמו כאן. 6.3: מינימום 0 (התקבל חלקית 5), מקסימום 5 + 2^N − 1.", "expl": "זו גרסה של שאלה 6 ממבחן 23BB (שם עם רווחים בין הספרות). המילה hello מודפסת עם רווח לפניה, כי הארגומנט של echo הוא \" hello\".\n\nטבלאות הדפים הן זיכרון של הקרנל, ולכן לא נספרות ב-6.3.", "check": "נבדק בהרצה יבשה (ובהרצה של הגרסה במבחן 23BB)", "exam": "26AA", "examLabel": "סמסטר א' תשפ\"ו מועד א'", "date": "27.01.2026", "id": "26AA-6"}, {"num": "7", "type": "open", "topic": "sync", "sub": "משתני תנאי", "intro": "בלינוקס, המימוש המובנה של משתנה תנאי (pthread_cond_t) תומך רק במנעול רגיל (pthread_mutex_t), ולא במנעול קוראים-כותבים.\nבשאלה זו נממש אובייקט סנכרון חדש: \"תנאי קוראים-כותבים\" (RWCond), שמממש את הפעולות של משתנה תנאי עבור מנעול קוראים-כותבים:\nrwcond_wait_read – משחררת את המנעול לקריאה (של החוט הנוכחי בלבד) וחוסמת את החוט. נקראת רק על ידי חוט שמחזיק במנעול לקריאה, בתוך לולאה שבודקת את התנאי.\nrwcond_wait_write – משחררת את המנעול לכתיבה וחוסמת את החוט. נקראת רק על ידי חוט שמחזיק במנעול לכתיבה, בתוך לולאה שבודקת את התנאי.\nrwcond_signal – מעירה חוט יחיד שחסום על התנאי. נקראת רק כשהחוט מחזיק את המנעול לכתיבה.\nrwcond_broadcast – מעירה את כל החוטים שחסומים על התנאי. נקראת רק כשהחוט מחזיק את המנעול לכתיבה.\nזה המימוש של מנעול קוראים-כותבים שנלמד, עם המנעולים של לינוקס:", "code": "typedef struct {\n    pthread_mutex_t writelock;\n    pthread_mutex_t readlock;\n    int numReaders;\n} RWLock;\n\nvoid acquire_writelock(RWLock *lock) {\n    pthread_mutex_lock(&lock->writelock);\n}\nvoid release_writelock(RWLock *lock) {\n    pthread_mutex_unlock(&lock->writelock);\n}\nvoid acquire_readlock(RWLock *lock) {\n    pthread_mutex_lock(&lock->readlock);\n    if (++lock->numReaders == 1)\n        pthread_mutex_lock(&lock->writelock);\n    pthread_mutex_unlock(&lock->readlock);\n}\nvoid release_readlock(RWLock *lock) {\n    pthread_mutex_lock(&lock->readlock);\n    if (--lock->numReaders == 0)\n        pthread_mutex_unlock(&lock->writelock);\n    pthread_mutex_unlock(&lock->readlock);\n}", "parts": [{"label": "7.1", "q": "סטודנט הציע את המימוש הבא: משתנה תנאי רגיל, וכל הפעולות מומרות לפעולות עליו, עם המנעול writelock כפרמטר (היכן שצריך מנעול). הציגו תרחיש (ריצה אפשרית עם שימוש תקין) שמוכיח שהמימוש לא תקין.", "code": "typedef struct {\n    pthread_cond_t cond;\n} RWCond;\n\nvoid rwcond_wait_read(RWCond *cond, RWLock *lock) {\n    pthread_cond_wait(&cond->cond, &lock->writelock);\n}\nvoid rwcond_wait_write(RWCond *cond, RWLock *lock) {\n    pthread_cond_wait(&cond->cond, &lock->writelock);\n}\nvoid rwcond_broadcast(RWCond *cond) {\n    pthread_cond_broadcast(&cond->cond);\n}\nvoid rwcond_signal(RWCond *cond) {\n    pthread_cond_signal(&cond->cond);\n}", "answer": "חוט A תופס את המנעול לקריאה ונכנס לקטע הקריטי.\nחוט B גם תופס את המנעול לקריאה.\nחוט A קורא ל-rwcond_wait_read – זה משחרר את writelock, ו-A נחסם.\nחוט C מנסה לתפוס את המנעול לכתיבה – ומצליח, כי writelock שוחרר.\n\nעכשיו C (כותב) ו-B (קורא) בקטע הקריטי בו-זמנית – הופרה המניעה ההדדית בזמן כתיבה.\n\nהבעיה: writelock מוחזק בשם כל הקוראים יחד. קורא אחד לא יכול לשחרר אותו כשיש עוד קוראים – צריך לשחרר רק את \"החלק\" שלו (release_readlock)."}, {"label": "7.2", "q": "ממשו \"תנאי קוראים-כותבים\" עם המבנה הבא (משתנה תנאי ומנעול עזר). אסור לשנות או להוסיף להגדרות, או לשנות את מימוש המנעול. רמז: תכונה חשובה של משתנה תנאי היא ששחרור המנעול והכניסה להמתנה מתבצעים יחד באופן אטומי – חשבו איך לשמר אותה.", "code": "typedef struct {\n    pthread_cond_t cond;    // helper cond-var\n    pthread_mutex_t lock;   // helper mutex\n} RWCond;", "answer": "משתמשים במנעול העזר כדי ליצור את האטומיות הנדרשת: תופסים אותו לפני ששחררים את מנעול הקוראים-כותבים, ומשחררים אותו רק דרך pthread_cond_wait – שמשחרר ונכנס להמתנה באופן אטומי. מי שמעיר (signal/broadcast) תופס קודם את מנעול העזר, ולכן הוא לא יכול \"לפספס\" חוט שנמצא בין שחרור המנעול לכניסה להמתנה.\n\nכשהחוט מתעורר, חשוב לשחרר את מנעול העזר לפני שמנסים לתפוס מחדש את מנעול הקוראים-כותבים – אחרת ייתכן קיפאון.\n\nvoid rwcond_wait_read(RWCond *cond, RWLock *lock) {\n    pthread_mutex_lock(&cond->lock);\n    release_readlock(lock);\n    pthread_cond_wait(&cond->cond, &cond->lock);   // atomic unlock+wait\n    pthread_mutex_unlock(&cond->lock);\n    acquire_readlock(lock);\n}\n\nvoid rwcond_wait_write(RWCond *cond, RWLock *lock) {\n    pthread_mutex_lock(&cond->lock);\n    release_writelock(lock);\n    pthread_cond_wait(&cond->cond, &cond->lock);\n    pthread_mutex_unlock(&cond->lock);\n    acquire_writelock(lock);\n}\n\nvoid rwcond_signal(RWCond *cond) {\n    pthread_mutex_lock(&cond->lock);     // avoid lost signal\n    pthread_cond_signal(&cond->cond);\n    pthread_mutex_unlock(&cond->lock);\n}\n\nvoid rwcond_broadcast(RWCond *cond) {\n    pthread_mutex_lock(&cond->lock);     // avoid lost signal\n    pthread_cond_broadcast(&cond->cond);\n    pthread_mutex_unlock(&cond->lock);\n}\n\nבפתרון הרשמי, rwcond_wait_write נשאר כמו בסעיף 7.1 – pthread_cond_wait(&cond->cond, &lock->writelock) – בנימוק שכותב מחזיק רק את writelock, וכל שאר הפעולות דורשות להיות בקטע הקריטי, כך שאף חוט לא יכול לפעול עד שהוא משוחרר."}], "official": "7.1: כמו כאן. 7.2: כמו כאן, מלבד rwcond_wait_write, שבפתרון הרשמי מחכה ישירות עם writelock.", "note": "7.2: בגרסה הרשמית, אותו משתנה תנאי משמש פעם עם cond->lock (קוראים) ופעם עם writelock (כותבים). לפי תקן POSIX זה \"התנהגות לא מוגדרת\" – כל החוטים שממתינים בו-זמנית על אותו משתנה תנאי צריכים להשתמש באותו mutex. בפועל, בלינוקס זה עובד. הגרסה כאן עקבית – כל ההמתנות עם cond->lock. שתי הגרסאות הורצו: 2 כותבים ו-3 קוראים עם תנאים תלויים זה בזה – בלי הפרות של המנעול ובלי תקיעה.", "expl": "", "check": "הורץ עם חוטים אמיתיים", "exam": "26AA", "examLabel": "סמסטר א' תשפ\"ו מועד א'", "date": "27.01.2026", "id": "26AA-7"}, {"num": "8", "type": "open", "topic": "fs", "sub": "FAT", "intro": "נתונה מערכת קבצים VSFS שמשתמשת בשיטת ההקצאה FAT: בכל inode יש מצביע יחיד לבלוק ה-DATA הראשון של הקובץ, ולמערכת הקבצים נוסף אזור לטבלת ההקצאות (FAT), שמכילה לכל בלוק DATA מצביע לבלוק הבא.\nגודל בלוק 4KB, גודל מצביע 4B.\nטבלת ההקצאות בגודל 10 בלוקים.\nאין ערך מיוחד למצביע \"ריק\" (כמו 1-, ‏0 או NULL) – כלומר אין ערך שמייצג כתובת לא חוקית.\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "8.1", "q": "כמה בלוקים יש ב-data region, במקרה המינימלי והמקסימלי?", "answer": "מינימום 9217, מקסימום 10,240.\n\nמצביעים בבלוק:\n4KB / 4B = 1024\n\nמקסימום – הטבלה בשימוש מלא:\n10 · 1024 = 10,240\n\nמינימום – הטבלה עדיין תופסת 10 בלוקים, אז כולם בשימוש, אבל בבלוק האחרון יש שימוש במצביע אחד בלבד:\n9 · 1024 + 1 = 9217\n\n(התקבלה חלקית התשובה 8194 – אם גם בחלק הראשון של הטבלה יש מצביע אחד.)"}, {"label": "8.2", "q": "מה הגודל המינימלי והמקסימלי של קובץ, וכמה בלוקי DATA יתפוס כל אחד?", "answer": "מינימום: 0 בתים, 0 בלוקים. מקסימום: 40MB, ‏10,240 בלוקים.\n\nמינימום – קובץ יכול תמיד להיות בגודל 0 (שדה ה-size ב-inode הוא 0, והמצביע חסר משמעות).\n\nמקסימום – כמו ברשימה מקושרת, ב-FAT אין מגבלה מהמצביעים שב-inode, וקובץ יכול לתפוס את כל בלוקי ה-DATA:\n10,240 · 4KB = 40MB"}, {"label": "8.3", "q": "שלושה סטודנטים התווכחו אם אפשר לוותר על ה-data bitmap:\nסטודנט א': אפשר לוותר עליו ולהשתמש במקומו בטבלת ההקצאות – גם בלי ערך מיוחד למצביע ריק, אפשר לייצג מצביע ריק.\nסטודנט ב': אי אפשר להשתמש בטבלה במקום ה-bitmap, בגלל שאין ערך מיוחד למצביע ריק.\nסטודנט ג': אי אפשר להשתמש בטבלה במקום ה-bitmap בכלל, גם בלי המגבלה.\nמי צודק?", "answer": "סטודנט א'.\n\nגם בלי ערך מיוחד, אפשר לסמן בלוק פנוי בכך שהרשומה שלו בטבלה מצביעה לעצמו. בלוק תפוס מצביע לבלוק הבא בקובץ – או, אם הוא האחרון בקובץ, לכל ערך אחר חוץ מעצמו (ממילא לא נמשיך לבלוק הבא, בגלל שדה ה-size ב-inode – העיקר שנדע שהבלוק תפוס). בלוק בקובץ לא יכול להצביע לעצמו (זה היה מעגל), ולכן הסימון חד-משמעי.\n\n(תשובה חלופית: לסמן בלוק פנוי במצביע למספר בלוק שלא קיים – 10,240 ומעלה, אם הטבלה לא מלאה.)"}], "official": "8.1: מינימום 9217, מקסימום 10,240. 8.2: ‏0 בתים / 0 בלוקים, ו-40MB / ‏10,240 בלוקים. 8.3: סטודנט א'.", "expl": "", "check": "חושב", "exam": "26AA", "examLabel": "סמסטר א' תשפ\"ו מועד א'", "date": "27.01.2026", "id": "26AA-8"}, {"num": "1", "type": "mcq", "topic": "disk", "sub": "RAID-5", "q": "ב-RAID-5, ככל שיש יותר דיסקים, המהירות הממוצעת של פעולות סדרתיות מתקרבת למהירות הממוצעת של פעולות סדרתיות ב-RAID-0 (על אותם דיסקים).", "options": ["הטענה נכונה, כי דיסקים רבים מפחיתים את ההשפעה השלילית של ה-parity על הביצועים.", "הטענה נכונה רק לקריאה סדרתית, ולא לכתיבה.", "הטענה נכונה רק לכתיבה סדרתית, ולא לקריאה.", "הטענה לא נכונה: פעולות סדרתיות ב-RAID-5 תמיד איטיות משמעותית מ-RAID-0.", "הטענה לא נכונה: כמות הדיסקים לא משפיעה על ביצועי פעולות סדרתיות."], "correct": 0, "official": "הטענה נכונה. המהירות של פעולות סדרתיות ב-RAID-5 היא (N−1) כפול דיסק רגיל, לעומת N ב-RAID-0. ככל שיש יותר דיסקים, הפער מצטמצם באופן יחסי.", "expl": "היחס בין RAID-5 ל-RAID-0 בפעולות סדרתיות (קריאה וכתיבה) הוא (N−1)/N: עם 3 דיסקים – 67%, עם 10 – 90%, ועם 100 – 99%.", "check": "לפי הפתרון הרשמי", "exam": "26AB", "examLabel": "סמסטר א' תשפ\"ו מועד ב'", "date": "17.02.2026", "id": "26AB-1"}, {"num": "2", "type": "mcq", "topic": "process", "sub": "זומבים", "q": "נתונה הטענה: תהליך במצב זומבי (defunct) יכול להריץ קוד.", "options": ["הטענה נכונה, אם יתקבל סיגנל SIGCHLD.", "הטענה נכונה, כשהתהליך יקבל עוד זמן מעבד.", "הטענה נכונה, כשההורה של התהליך יאסוף אותו או יסתיים.", "הטענה לא נכונה: תהליך לא יכול להיות זומבי.", "הטענה לא נכונה: תהליך זומבי כבר סיים לרוץ."], "correct": 4, "official": "הטענה לא נכונה: תהליך זומבי הוא תהליך שסיים לרוץ ומחכה שיאספו אותו – הוא לא יכול להריץ עוד קוד.", "expl": "מתהליך זומבי נשארה רק רשומה בטבלת התהליכים (PID וסטטוס היציאה), כדי שההורה יוכל לקרוא אותה עם wait. הזיכרון שלו כבר שוחרר, והוא לא יתוזמן לעולם.", "check": "לפי הפתרון הרשמי", "exam": "26AB", "examLabel": "סמסטר א' תשפ\"ו מועד ב'", "date": "17.02.2026", "id": "26AB-2"}, {"num": "3", "type": "mcq", "topic": "memory", "sub": "טבלה היררכית", "q": "במערכת עם טבלת דפים לינארית בגודל 2 דפים בדיוק לכל תהליך, הוחלט לעבור לטבלת דפים היררכית. מה הטענה הנכונה ביותר אחרי המעבר?", "options": ["כל גישה לטבלה ההיררכית דורשת בדיוק 2 גישות לזיכרון.", "כל גישה לטבלה ההיררכית דורשת לכל היותר 2 גישות לזיכרון.", "כל גישה לטבלה ההיררכית דורשת בדיוק 3 גישות לזיכרון.", "כל גישה לטבלה ההיררכית דורשת לכל היותר 3 גישות לזיכרון.", "אין חסם על כמות הגישות לזיכרון, כי מספר הרמות לא ידוע."], "correct": 1, "official": "לכל היותר 2 גישות. טבלה לינארית בגודל 2 דפים תהיה טבלה היררכית עם 2 רמות (ברמה העליונה 2 רשומות). כל גישה לטבלה היא לכל היותר 2 גישות לזיכרון – ולא בדיוק, כי ייתכן שניגשים לזיכרון עם valid=0 כבר ברמה העליונה.", "expl": "דף של הטבלה מכסה ביט \"מספר דף\" אחד פחות מכל המרחב: 2 דפים = פעמיים מספר הרשומות שנכנסות בדף. לכן ברמה התחתונה כל דף מכסה חצי מהמרחב, ומעליה מספיקה רמה אחת עם 2 רשומות.", "check": "לפי הפתרון הרשמי", "exam": "26AB", "examLabel": "סמסטר א' תשפ\"ו מועד ב'", "date": "17.02.2026", "id": "26AB-3"}, {"num": "4", "type": "mcq", "topic": "disk", "sub": "SSD", "q": "בכונני SSD, איזה יתרון יש לשכבת תרגום (FTL) מבוססת לוג על פני מיפוי ישיר של דפים?", "options": ["הקטנת השחיקה על ידי פיזור הכתיבות על פני כל הבלוקים.", "האצת הקריאות, כי אין צורך לחפש בטבלאות מיפוי.", "מניעה מוחלטת של שחיקה, כי הנתונים נכתבים תמיד למקומות פנויים.", "אין צורך ב-garbage collection, כי העדכונים מתבצעים במקום שבו הנתונים נמצאים.", "כל התשובות האחרות אינן נכונות."], "correct": 0, "official": "הקטנת השחיקה על ידי פיזור הכתיבות. כפי שנלמד, אחד היתרונות של FTL מבוסס לוג הוא פיזור הכתיבות על פני הבלוקים כדי לאזן את השחיקה.", "expl": "במיפוי ישיר, כל עדכון של דף לוגי דורש למחוק ולכתוב מחדש את אותו בלוק פיזי – בלוקים \"חמים\" נשחקים מהר. בלוג, כל כתיבה הולכת לדף הפנוי הבא. החיסרון: צריך טבלת מיפוי ו-garbage collection – ושחיקה עדיין קיימת, רק מאוזנת.", "check": "לפי הפתרון הרשמי", "exam": "26AB", "examLabel": "סמסטר א' תשפ\"ו מועד ב'", "date": "17.02.2026", "id": "26AB-4"}, {"num": "5", "type": "mcq", "topic": "deadlock", "sub": "ארבעת התנאים", "q": "איזה מתנאי הקיפאון אפשר למנוע על ידי תפיסת כל המנעולים בבת אחת (באופן אטומי)?", "options": ["Circular wait", "Hold and wait", "No preemption", "Mutual exclusion", "כל התשובות נכונות."], "correct": 1, "official": "Hold and wait. הפתרון ל-hold and wait הוא תפיסת כל המנעולים \"בבת אחת\".", "expl": "אם חוט תופס את כל המנעולים שהוא צריך באופן אטומי (למשל תחת מנעול גלובלי), הוא אף פעם לא מחזיק חלק מהם בזמן שהוא מחכה לאחרים.", "check": "לפי הפתרון הרשמי", "exam": "26AB", "examLabel": "סמסטר א' תשפ\"ו מועד ב'", "date": "17.02.2026", "id": "26AB-5"}, {"num": "6", "type": "open", "topic": "memory", "sub": "טבלה היררכית", "intro": "נתונה התוכנית הבאה בשם prog1.\nתזכורת: באופרטורים && ו-||, אם התוצאה ידועה לפי האופרנד הראשון, האופרנד השני לא מבוצע.\nהריצו את התוכנית, והתהליך שנוצר קיבל את המזהה 42. התוכנית prog2 לא מדפיסה שום דבר ולא יוצרת תהליכים. כל קריאות המערכת הצליחו, לא נוצרים תהליכים בקוד אחר במערכת, וכל תהליך מקבל מזהה גדול ב-1 מהתהליך שנוצר לפניו.\nבמערכת נתון גם: כתובת וירטואלית של 32 ביטים, כתובת פיזית של 40 ביטים, דף של 4KB, ו-PTE/PDE של 4B. המערכת משתמשת בטבלת דפים היררכית. תהליך 42 משתמש בסגמנטים: TEXT של 48KB, ‏DATA של 600KB, מחסנית של 64KB וערימה של 64KB.", "code": " 1 int main()\n 2 {\n 3     pid_t pid = getpid();\n 4\n 5     if (fork() && !fork()) {\n 6         if (!fork() || fork()) {\n 7             fork();\n 8         }\n 9     }\n10\n11     while (wait(NULL) != -1);\n12     if (pid != getpid()) {\n13         char* args[] = { \"prog2\", NULL };\n14         printf(\"%d [%d]\\n\", getpid(), getppid());\n15         execvp(args[0], args);\n16     }\n17     printf(\"Done: %d\\n\", getpid());\n18 }", "parts": [{"label": "6.1", "q": "כתבו פלט אפשרי של התוכנית, וציירו את עץ התהליכים של הריצה שמובילה אליו (עם המזהה של כל תהליך). כמה תהליכים נוצרו, כולל הראשי?", "answer": "7 תהליכים.\n\nשורה 5: תהליך 42 יוצר את 43 (ה-fork הראשון). אצל 42 הוא אמת, אז מבוצע !fork() – נוצר 44. אצל 42 זה !(44) = שקר, ואצל 44 זה !0 = אמת. אצל 43 ה-fork הראשון החזיר 0, ולכן && עוצר. רק 44 נכנס לתנאי.\n\nשורה 6: ‏44 יוצר את 45. אצל 45 !0 = אמת, ולכן || עוצר – 45 נכנס מיד. אצל 44 זה שקר, אז מבוצע fork() נוסף – נוצר 46. אצל 44 התוצאה אמת (נכנס), ואצל 46 היא 0 (לא נכנס).\n\nשורה 7: ‏44 ו-45 יוצרים כל אחד בן: 47 ו-48.\n\nעץ התהליכים:\n\n[[TREE]]\n\nהמשתנה pid קיבל 42 לפני כל ה-fork-ים, ולכן אצל כולם הוא 42. כל תהליך מחכה שכל הילדים שלו יסתיימו (שורה 11), ואז: כל מי שאינו 42 מדפיס את המזהה שלו ושל ההורה, ומריץ את prog2. רק 42 מדפיס Done.\n\nפלט אפשרי:\n48 [45]\n47 [44]\n46 [44]\n45 [44]\n44 [42]\n43 [42]\nDone: 42\n\nההורה עדיין חי כשהבן מדפיס (הוא מחכה לו), ולכן getppid מחזיר את ההורה האמיתי.", "tree": ["42", "", [["43", "", []], ["44", "", [["45", "", [["48", "", []]]], ["46", "", []], ["47", "", []]]]]]}, {"label": "6.2", "q": "כמה זיכרון (בבתים) יתפסו טבלאות הדפים של תהליך 42 (כל הרמות יחד), וכמה כניסות valid יהיו בסך הכל, במקרה המינימלי?", "answer": "8KB, ‏195 כניסות valid.\n\nהיסט: 4KB = 12 ביטים, ונשארים 20 ביטים למספר הדף.\nכניסות בכל דף של הטבלה: 4KB / 4B = 1024, כלומר 10 ביטים לרמה – 2 רמות (10 + 10).\n\nכל סגמנט הוא כפולה של 4KB. במקרה המינימלי כולם מתחילים בתחילת דף:\n12 + 150 + 16 + 16 = 194 דפים\n\nבמקרה המינימלי כל הדפים באותה טבלה ברמה התחתונה – 2 מסגרות (אחת בכל רמה):\n8KB\n\nכניסות valid:\n194 ברמה התחתונה + 1 ברמה העליונה = 195"}, {"label": "6.3", "q": "נניח שאף תהליך שנוצר עוד לא קרא ל-execvp. במקרה המקסימלי, כמה מסגרות יתפסו טבלאות הדפים של כל התהליכים שנוצרו (כולל 42), וכמה כניסות valid יהיו בסך הכל (כל הרמות, כל התהליכים)?", "answer": "63 מסגרות, ‏1442 כניסות valid.\n\nקודם תהליך אחד במקרה המקסימלי:\nכל סגמנט הוא בדיוק כפולה של 4KB, ולכן אם הוא לא מתחיל בתחילת דף הוא תופס דף נוסף אחד:\n194 + 4 = 198 דפים\n\nכל סגמנט יכול להתפרס על 2 טבלאות שונות ברמה התחתונה – 8 מסגרות ברמה התחתונה, ועוד אחת ברמה העליונה (עם 8 כניסות valid):\n9 מסגרות\n198 + 8 = 206 כניסות valid\n\nכל תהליך שנוצר (לפני exec) מקבל עותק של אותו מרחב כתובות – כלומר אותו מקרה מקסימלי. יש 7 תהליכים (סעיף 6.1):\n7 · 9 = 63 מסגרות\n7 · 206 = 1442 כניסות valid"}], "official": "6.1: זהה לשאלה 6.1 במבחן 24SA. 6.2: ‏8KB, ‏195. 6.3: ‏64 מסגרות, ‏1442 כניסות valid.", "note": "6.3: בפתרון הרשמי כתוב 64 מסגרות. לפי החישוב שם עצמו (9 מסגרות לתהליך, כפול 7 תהליכים) יוצא 63 – והכניסות (206 · 7 = 1442) תואמות ל-7 תהליכים.", "expl": "", "check": "חושב", "exam": "26AB", "examLabel": "סמסטר א' תשפ\"ו מועד ב'", "date": "17.02.2026", "id": "26AB-6"}, {"num": "7", "type": "open", "topic": "sync", "sub": "מימוש סמפור", "intro": "בכיתה ראינו את המימוש הבא לסמפור (zemaphore), עם מנעול, משתנה תנאי וערך פנימי מטיפוס int.\nבשאלה זו נוסיף פעולה חדשה, numwait, שמחזירה את מספר החוטים שממתינים לסמפור (חסומים ב-wait). ערך ההחזרה צריך להיות ערך שהיה נכון בזמן כלשהו במהלך הקריאה. הפעולה לא חוסמת, וכל חוט יכול לקרוא לה בכל זמן. אפשר להתעלם מגבולות int.", "code": "typedef struct {                       void zem_init(zem_t *s, int value) {\n    int value;                             s->value = value;\n    pthread_cond_t cond;                   pthread_mutex_init(&s->lock, NULL);\n    pthread_mutex_t lock;                  pthread_cond_init(&s->cond, NULL);\n} zem_t;                               }\n\nvoid zem_post(zem_t *s) {              void zem_wait(zem_t *s) {\n    pthread_mutex_lock(&s->lock);          pthread_mutex_lock(&s->lock);\n    ++s->value;                            while (s->value == 0)\n    pthread_cond_signal(&s->cond);             pthread_cond_wait(&s->cond, &s->lock);\n    pthread_mutex_unlock(&s->lock);        --s->value;\n}                                          pthread_mutex_unlock(&s->lock);\n                                       }", "parts": [{"label": "7.1", "q": "להלן מימוש שמוסיף ל-zem_t מונה של חוטים ממתינים (zem_post לא השתנה). הציגו תרחיש (ריצה עם שימוש תקין) שמוכיח שהמימוש לא תקין, ותקנו אותו על ידי שינוי של פעולה אחת בלבד. אין להוסיף שדות (מלבד waitcount).", "code": "typedef struct {\n    int value;\n    pthread_cond_t cond;\n    pthread_mutex_t lock;\n    int waitcount;\n} zem_t;\n\nvoid zem_init(zem_t *s, int value) {\n    s->value = value;\n    pthread_mutex_init(&s->lock, NULL);\n    pthread_cond_init(&s->cond, NULL);\n    s->waitcount = 0;\n}\n\nint zem_numwait(zem_t *s) {\n    return s->waitcount;\n}\n\nvoid zem_wait(zem_t *s) {\n    pthread_mutex_lock(&s->lock);\n    ++s->waitcount;\n    while (s->value == 0)\n        pthread_cond_wait(&s->cond, &s->lock);\n    --s->waitcount;\n    --s->value;\n    pthread_mutex_unlock(&s->lock);\n}", "answer": "תרחיש:\nמאתחלים את הסמפור ל-10.\nחוט A קורא ל-wait, תופס את המנעול ומגדיל את waitcount ל-1 – ועוד לא יצא מהלולאה.\nחוט B קורא ל-numwait ומקבל 1 – למרות שאף חוט לא חסום (הערך הפנימי גדול מ-0, אז A לא יחכה בכלל).\n\nתיקון – בפעולה zem_wait: מגדילים את waitcount רק כשהחוט באמת עומד לחכות:\n\nvoid zem_wait(zem_t *s) {\n    pthread_mutex_lock(&s->lock);\n    if (s->value == 0) {\n        ++s->waitcount;\n        while (s->value == 0)\n            pthread_cond_wait(&s->cond, &s->lock);\n        --s->waitcount;\n    }\n    --s->value;\n    pthread_mutex_unlock(&s->lock);\n}"}, {"label": "7.2", "q": "מימוש אחר (נפרד לגמרי), בלי שדות נוספים: משתמשים בשדה value כך שכשהוא שלילי, הוא מסמן את מספר החוטים הממתינים (שאר הפעולות בלי שינוי). הערך הפנימי לא חייב להיות תמיד ≥ 0, כל עוד ההתנהגות של wait ו-post נשמרת.\nהציגו תרחיש שמוכיח שהמימוש לא תקין, ותקנו אותו על ידי שינוי של 2 פעולות בלבד (אחת מהפעולות שבסעיף, ואחת שלא שונתה). אין להוסיף שדות. רמז: באחת הפעולות חשבו איזה כלל אצבע שנלמד לא תקף כאן, וצריך להפר אותו.", "code": "int zem_numwait(zem_t *s) {\n    int val = s->value;\n    if (val >= 0)\n        return 0;\n    else\n        return -val;\n}\n\nvoid zem_wait(zem_t *s) {\n    pthread_mutex_lock(&s->lock);\n    --s->value;\n    while (s->value < 0)\n        pthread_cond_wait(&s->cond, &s->lock);\n    pthread_mutex_unlock(&s->lock);\n}", "answer": "תרחיש:\nמאתחלים את הסמפור ל-0.\nחוט A קורא ל-wait: הערך יורד ל-1- והוא נחסם.\nחוט B קורא ל-wait: הערך יורד ל-2- והוא נחסם.\nחוט C קורא ל-post: הערך עולה ל-1- ומעיר את A או את B.\nהחוט שהתעורר רואה שהערך עדיין שלילי – וחוזר להמתנה.\nאף חוט לא מתקדם, למרות שהתבצע post (עם ערך התחלתי 0, כל post צריך לשחרר חוט אחד).\n\nתיקון:\nzem_post – שולח signal רק כשהערך (אחרי ההגדלה) ≤ 0, כלומר כשיש חוט שממתין.\nzem_wait – ממתין עם if ולא עם while. ברגע שחוט מתעורר הוא יכול להמשיך: הערך השלילי כבר \"שריין\" לו את המשאב, וחוטים אחרים לא יכולים \"לגנוב\" אותו. זה הכלל שמופר כאן – \"תמיד להמתין על משתנה תנאי בתוך while\".\n\nvoid zem_wait(zem_t *s) {\n    pthread_mutex_lock(&s->lock);\n    --s->value;\n    if (s->value < 0)\n        pthread_cond_wait(&s->cond, &s->lock);\n    pthread_mutex_unlock(&s->lock);\n}\n\nvoid zem_post(zem_t *s) {\n    pthread_mutex_lock(&s->lock);\n    ++s->value;\n    if (s->value <= 0)\n        pthread_cond_signal(&s->cond);\n    pthread_mutex_unlock(&s->lock);\n}"}], "official": "7.1 ו-7.2: כמו כאן.", "note": "7.2: הפתרון עם if מניח שאין \"התעוררויות שווא\" (spurious wakeups). התקן של POSIX מתיר אותן, ולכן במערכת אמיתית זה מימוש לא בטוח לגמרי. זו התשובה שהשאלה מכוונת אליה (הרמז מדבר במפורש על הפרת הכלל).", "expl": "התיקון של 7.2 הורץ כסמפור בינארי עם 6 חוטים ו-120,000 כניסות: אף פעם לא היו 2 חוטים בפנים, numwait החזיר עד 5 ממתינים, וכל החוטים סיימו.", "check": "הורץ עם חוטים אמיתיים", "exam": "26AB", "examLabel": "סמסטר א' תשפ\"ו מועד ב'", "date": "17.02.2026", "id": "26AB-7"}, {"num": "8", "type": "open", "topic": "disk", "sub": "ביצועי דיסק", "intro": "נתון דיסק קשיח עם הנתונים הבאים:\nמהירות סיבוב 6,000 RPM. גודל סקטור 512B, גודל בלוק 8 סקטורים.\n8 משטחים (4 platters דו-צדדיים).\nצפיפות הסקטורים לפי 4 אזורים A, B, C, D, ובכל אזור 50 רצועות. האזורים מסודרים מבחוץ פנימה – A החיצוני ביותר ו-D הפנימי ביותר.\nבאזור A יש 4096 סקטורים לרצועה, ב-B ‏3072, ב-C ‏2048, וב-D ‏1024.\nזמן seek ממוצע 15ms, בין שתי רצועות סמוכות 2ms, ו-seek מקסימלי של 30ms.\nיש track skew: בקריאת סקטורים עוקבים ברצועות סמוכות אין המתנה לסיבוב.\nיש לפרט ולנמק את כל החישובים.", "parts": [{"label": "8.1", "q": "מה שטח האחסון הכולל בדיסק?", "answer": "2,097,152,000 בתים (2000MB).\n\nרצועה אחת מכל אזור:\n4096 + 3072 + 2048 + 1024 = 10,240 סקטורים\n\nבמשטח (50 רצועות בכל אזור):\n50 · 10,240 = 512,000 סקטורים\n\nב-8 משטחים:\n4,096,000 סקטורים\n\n4,096,000 · 512B = 2,097,152,000 בתים = 2000MB"}, {"label": "8.2", "q": "משתמש ביצע פעולה על רצועה שלמה באזור C. מה צריך להיות זמן ה-seek המדויק כך שבממוצע הפעולה תתבצע בקצב העברה בפועל של 50MB/s?", "answer": "5ms.\n\nרצועה ב-C: 2048 · 512B = 1MB.\nבקצב של 50MB/s הפעולה צריכה לקחת 20ms.\n\nזמן סיבוב: 10ms, כלומר המתנה ממוצעת של 5ms. קריאת רצועה שלמה – סיבוב שלם, 10ms.\n5 + 10 = 15ms\n\nחסרים 5ms – זה זמן ה-seek."}, {"label": "8.3", "q": "הראש הקורא-כותב נמצא כרגע ברצועה הפנימית ביותר. מה הגודל המינימלי של נתונים רצופים שצריך לקרוא, כך שקריאה של הכמות הזו מהרצועה החיצונית ביותר תהיה מהירה יותר מקריאה של אותה כמות מהרצועה הפנימית ביותר?", "answer": "4097 סקטורים.\n\nההמתנה לסיבוב (5ms) זהה בשתי הפעולות, ואפשר להתעלם ממנה.\n\nבקריאה מבחוץ צריך seek מקסימלי (30ms) – אבל קוראים 4096 סקטורים בסיבוב. בקריאה מבפנים אין seek – אבל קוראים רק 1024 סקטורים בסיבוב (רבע).\n\nקריאה של 4096 סקטורים מבחוץ:\n30 + 5 + 10 = 45ms\nקריאה של אותה כמות מבפנים – 4 רצועות, כלומר 4 סיבובים:\n0 + 5 + 40 = 45ms\n(אין seek בין הרצועות, כי יש 8 משטחים שאפשר לקרוא מהם ברצף באותו צילינדר.)\n\nב-4096 סקטורים הזמנים שווים. כל סקטור נוסף נקרא מבחוץ מהר יותר, ולכן המינימום הוא 4097 סקטורים. (התקבלה חלקית התשובה 4096, שעבורה הזמנים שווים.)"}], "official": "8.1: ‏2,097,152,000 בתים (2000MB). 8.2: ‏5ms. 8.3: ‏4097 סקטורים.", "expl": "טעות נפוצה ב-8.3: להוסיף מעבר בין רצועות (2ms) בקריאה מבפנים, כאילו כל הנתונים על משטח אחד. אז יוצא 3277 סקטורים – וזה לא נכון, כי אפשר לקרוא ברצף מ-8 המשטחים של אותו צילינדר.", "check": "חושב בסקריפט", "exam": "26AB", "examLabel": "סמסטר א' תשפ\"ו מועד ב'", "date": "17.02.2026", "id": "26AB-8"}]};